var QUESTOES_LEI_11892_2008 = [{"id":42482,"enunciado":"Compete à Divisão de Análise e Processamento receber, registrar, analisar e classificar reclamações, sugestões, denúncias e elogios, encaminhá-los às áreas competentes e responder ao cidadão.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":42483,"enunciado":"Compete à Assessoria de Assuntos Parlamentares, que integra a estrutura organizacional do gabinete do ministro, supervisionar, orientar e controlar as atividades relacionadas ao acompanhamento de matérias legislativas e outros assuntos de interesse do MPS Congresso Nacional.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":42484,"enunciado":"Os casos omissos e as dúvidas surgidas na aplicação do regimento interno do gabinete do ministro são solucionados pelo chefe de gabinete do ministro.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":42485,"enunciado":"A Secretaria-Executiva é dirigida pelo coordenador-geral.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":42486,"enunciado":"A Divisão de Apoio Logístico da Secretaria-Executiva tem competência para acompanhar a gestão dos contratos até sua conclusão.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":42487,"enunciado":"A Divisão de Análise e Processamento e a Divisão de Apoio ao Cidadão integram a organização do gabinete do ministro.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":42488,"enunciado":"A Secretaria-Executiva exerce, entre outros, o papel de órgão setorial dos sistemas de pessoal civil da administração federal.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":42489,"enunciado":"A Assessoria de Gestão de Educação Continuada integra a estrutura do gabinete do ministro.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":42490,"enunciado":"O gabinete do ministro, dirigido pelo chefe de gabinete, cuida de definir políticas, metodologias, controles e normas de segurança e coordenar esforços para o gerenciamento de riscos de fraudes.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":42491,"enunciado":"A Consultoria Jurídica é órgão setorial da Advocacia-Geral da União.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":42492,"enunciado":"A Coordenação de Licitações, Contratos e Pessoal integra a estrutura organizacional da Secretaria de Políticas da Previdência Social.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":42493,"enunciado":"Os processos e as consultas são encaminhados à Consultoria Jurídica somente pelos titulares dos órgãos do ministério.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":42494,"enunciado":"A consulta que for encaminhada à Consultoria Jurídica deve ser instruída com o pronunciamento da área técnica, de forma fundamentada e conclusiva, bem como do órgão ou da autoridade interessada, e deve evidenciar a dúvida ou a controvérsia a ser dirimida, sob pena de restituição.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":42495,"enunciado":"À Secretaria de Políticas de Previdência Social compete gerenciar o relacionamento e a afiliação do MPS junto aos organismos nacionais, estando fora de sua área de competência o relacionamento desse ministério com os organismos internacionais.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":42496,"enunciado":"A Ouvidoria-Geral da Previdência Social integra a estrutura organizacional da Secretaria-Executiva.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":91088,"enunciado":"As exigências dessa portaria não serão aplicadas aos convênios e contratos que tenham por objeto a delegação de competência ou a autorização a órgãos ou entidades de outras esferas de governo para a execução de atribuições determinadas em lei, regulamento ou regimento interno, com geração de receita compartilhada.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":91089,"enunciado":"Quando as disposições de tratados, acordos e convenções internacionais específicas conflitarem com essa portaria e os projetos deles decorrentes forem financiados com recursos integralmente oriundos de fonte externa de financiamento, homologados pelo Congresso Nacional ou autorizados pelo Senado Federal, prevalecerá o disposto nas normas internacionais.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":91090,"enunciado":"Essa portaria deve ser aplicada aos convênios e contratos de repasse destinados à execução descentralizada de programas federais de atendimento direto ao público, nas áreas de assistência social, médica e educacional, exceto os convênios em que tenha sido prevista a antecipação de recursos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":105728,"enunciado":"A oferta de educação profissional e tecnológica nos institutos federais ocorre por meio da conjugação de conhecimentos técnicos e tecnológicos com práticas pedagógicas.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":105729,"enunciado":"Um dos objetivos dos institutos federais é desenvolver atividades de extensão em conformidade com os princípios da educação profissional e tecnológica, ou seja, capacitação para suprir as carências e necessidades do mercado.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":105730,"enunciado":"Os institutos federais têm por finalidade ofertar educação profissional e tecnológica apenas para o nível médio de ensino e na modalidade presencial.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":105731,"enunciado":"A lei em questão dispõe que as instituições federais de educação profissional e tecnológica devem observar os parâmetros e as normas definidas pelo Ministério da Educação e seguir o modelo de instituto federal.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":105732,"enunciado":"Uma das finalidades do instituto federal é a de tornar-se centro de referência no apoio à oferta do ensino de ciências nas instituições públicas de ensino, oferecendo capacitação técnica e atualização pedagógica aos docentes das redes públicas de ensino.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":105733,"enunciado":"Cabe aos institutos federais realizar e estimular pesquisa aplicada, produção cultural, empreendedorismo, cooperativismo, desenvolvimento científico e tecnológico.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":277609,"enunciado":"Compete à ANATEL aprovar o plano geral de metas para universalização dos serviços de telecomunicações.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":277610,"enunciado":"A concorrência e a universalização são princípios básicos que norteiam a LGT.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":277611,"enunciado":"A ANATEL poderá decretar a intervenção em concessionária, caso as metas de universalização não sejam atingidas.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":277612,"enunciado":"Compete a cada unidade da Federação organizar a exploração dos serviços de telecomunicação em seu território.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":277613,"enunciado":"A ANATEL, criada como agência reguladora das telecomunicações, é subordinada hierarquicamente ao presidente da República.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":277614,"enunciado":"O indicado para conselheiro, antes da nomeação, passa por sabatina na Câmara dos Deputados.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":277615,"enunciado":"Se um conselheiro assumiu o cargo em 1.º/1/2009 e, por motivos pessoais, renunciou ao cargo um ano depois, então, nesse caso, o mandato de seu substituto terminará em 31/12/2014.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":277616,"enunciado":"É composto por cinco conselheiros, todos indicados pelo presidente da República.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":323646,"enunciado":"Acerca da criação de carreiras e organização de cargos efetivos nas autarquias especiais, denominadas agências reguladoras, julgue os itens seguintes.\n\nA distribuição de cargos de procurador federal nas procuradorias das agências reguladoras é atribuição do procurador-geral federal.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":323649,"enunciado":"Acerca da criação de carreiras e organização de cargos efetivos nas autarquias especiais, denominadas agências reguladoras, julgue os itens seguintes.\n\nA orientação aos agentes do mercado regulado e ao público em geral é uma atribuição do cargo de analista administrativo nas agências reguladoras.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":326185,"enunciado":"De acordo com a Lei nº 11.892/2008, constituem a Rede Federal de Educação Profissional, Científica e Tecnológica as seguintes instituições:","opcoes":["Os Institutos Federais de Educação, Ciência e Tecnologia, a Universidade Tecnológica Federal do Paraná – UTFPR e os Centros Federais de Educação Tecnológica Celso Suckow da Fonseca, CEFET- RJ e o de Minas Gerais, CEFET-MG.","Os Institutos Federais de Educação, todas as Universidades Federais e escolas técnicas a elas vinculadas, os Centros Federais de Educação Tecnológica e o Colégio Pedro II.","Os Institutos Federais de Educação, Ciência e Tecnologia, a Universidade Tecnológica Federal do Paraná – UTFPR, os Centros Federais de Educação Tecnológica Celso Suckow da Fonseca e o de Minas Gerais (CEFET-MG), as escolas técnicas vinculadas às universidades federais e o Colégio Pedro II.","As universidades federais, os Institutos Federais, os CEFET’s e o Colégio Pedro II.","Os Institutos Federais, os CEFET’s e o Colégio Pedro II."],"correta":2,"explicacao":"Gabarito: <strong>Os Institutos Federais de Educação, Ciência e Tecnologia, a Universidade Tecnológica Federal do Paraná – UTFPR, os Centros Federais de Educação Tecnológica Celso Suckow da Fonseca e o de Minas Gerais (CEFET-MG), as escolas técnicas vinculadas às universidades federais e o Colégio Pedro II.</strong>.","banca":"IF-SP","ano":2012,"temas_relacionados":["lei_11892_2008"]},{"id":330421,"enunciado":"Está correto o que se afirma em:","opcoes":["I, II e VI, apenas.","I, III e VII, apenas.","II, III, IV e VII, apenas.","II, IV, V e VIII, apenas.","III, V, VII e VIII, apenas."],"correta":1,"explicacao":"Gabarito: <strong>I, III e VII, apenas.</strong>.","banca":"IF-PI","ano":2012,"temas_relacionados":["lei_11892_2008"]},{"id":330471,"enunciado":"O inciso VI, do art. 7º, da Le nº 11.892/2008, que instituiu a Rede Federal de Educação Profissional, Científica e Tecnológica e criou os Institutos Federais de Educação,Ciência e Tecnologia,dispõe sobre o seguinte: observadas suas finalidades e características,os Institutos Federais têm como um de seus objetivos ministrar cursos em nível de educação superior.Sendo assim,responda:conforme o dispositivo legal acima,em relação aos cursos de nível de educação superior, ministrados pelos Institutos Federais,NÃO podemos afirmar que são cursos.","opcoes":["Superiores de tecnologia visando à formação de profissionais para os diferentes setores da economia.","De licenciatura, com vistas à formação de professores para a educação básica, sobretudo nas áreas de ciências humanas e sociais.","De bacharelado e engenharia, visando à formação de profissionais para os diferentes setores da economia e áreas do conhecimento.","De pós-graduação lato sensu de aperfeiçoamento e especialização, visando à formação de especialistas nas diferentes áreas do conhecimento.","De pós-graduação stricto sensu que contribuam para promover o estabelecimento de bases sólidas em educação, ciência e tecnologia."],"correta":1,"explicacao":"Gabarito: <strong>De licenciatura, com vistas à formação de professores para a educação básica, sobretudo nas áreas de ciências humanas e sociais.</strong>.","banca":"IF-PI","ano":2012,"temas_relacionados":["lei_11892_2008"]},{"id":331094,"enunciado":"Segundo o previsto pela lei 11892/2008, assinale a alternativa INCORRETA sobre os Institutos Federais:","opcoes":["Trata-se de instituições de educação superior, básica e profissional, pluridisciplinar e multicampi.","Os Institutos Federais terão autonomia para criar e extinguir cursos, nos limites de sua área de atuação territorial.","No âmbito de sua atuação, os Institutos Federais exercerão o papel de instituições acreditadoras e certificadoras de competências profissionais.","Possuem autonomia para registrar diplomas dos cursos por eles oferecidos, mediante autorização do seu Conselho Superior, aplicando-se, no caso da oferta de cursos a distância, a legislação específica.","São especializados na oferta de educação profissional e tecnológica nas diferentes modalidades de ensino, fundamentando-se na conjugação de conhecimentos técnicos e tecnológicos com as suas práticas pedagógicas, nos termos da respectiva Lei."],"correta":0,"explicacao":"Gabarito: <strong>Trata-se de instituições de educação superior, básica e profissional, pluridisciplinar e multicampi.</strong>.","banca":"Makiyama","ano":2013,"temas_relacionados":["lei_11892_2008"]},{"id":331096,"enunciado":"Considerando as finalidades e características dos Institutos Federais conforme descritas na lei 11892/2008, podemos considerar que a educação profissional e tecnológica está","opcoes":["voltada para o trabalho em seu aspecto operacional.","empenhada em separar a educação geral da profissional.","centrada na dicotomia trabalho manual/trabalho intelectual.","comprometida em superar o sentido ontológico do trabalho.","fundamentada na ideia da oferta de uma formação integrada."],"correta":4,"explicacao":"Gabarito: <strong>fundamentada na ideia da oferta de uma formação integrada.</strong>.","banca":"Makiyama","ano":2013,"temas_relacionados":["lei_11892_2008"]},{"id":345908,"enunciado":"Conforme a Lei n.º 11.892/2008, os institutos federais têm por finalidades e características","opcoes":["promover a integração e a verticalização da educação média à educação profissional e à educação superior, otimizando a infraestrutura física, os quadros de pessoal e os recursos de gestão.","desenvolver a educação profissional e tecnológica como processo educativo e investigativo de geração e adaptação de soluções técnicas e tecnológicas às demandas sociais e às peculiaridades regionais.","orientar sua oferta formativa em benefício da consolidação e do fortalecimento dos arranjos produtivos, sociais e culturais nacionais, identificados com base no mapeamento das potencialidades de desenvolvimento socioeconômico e cultural no âmbito de atuação de cada instituto federal.","serem centros de excelência na oferta do ensino de ciências, em geral, e de ciências humanas, em particular, estimulando o desenvolvimento do espírito crítico, voltado à investigação teórica.","serem centros de referência no apoio à oferta do ensino de ciências nas instituições públicas e privadas de ensino, oferecendo capacitação técnica e atualização pedagógica aos docentes da rede pública e da privada de ensino."],"correta":1,"explicacao":"Gabarito: <strong>desenvolver a educação profissional e tecnológica como processo educativo e investigativo de geração e adaptação de soluções técnicas e tecnológicas às demandas sociais e às peculiaridades regionais.</strong>.","banca":"FUNIVERSA","ano":2012,"temas_relacionados":["lei_11892_2008"]},{"id":345909,"enunciado":"Tendo em vista o disposto na Lei n.º 11.892/2008, com relação ao cargo de reitor, assinale a alternativa correta.","opcoes":["O docente poderá candidatar-se desde que pertença ao quadro de pessoal ativo permanente de qualquer dos campi que integram o instituto federal e possua o mínimo de cinco anos de efetivo exercício em instituição federal de educação profissional e tecnológica e tenha título de mestre.","O docente poderá candidatar-se desde que pertença ao quadro de pessoal ativo ou inativo permanente de qualquer dos campi que integram o instituto federal, possua o mínimo de cinco anos de efetivo exercício em instituição federal de educação profissional e tecnológica e tenha título de doutor.","O docente poderá candidatar-se desde que pertença ao quadro de pessoal ativo permanente de qualquer dos campi que integram o instituto federal, possua o mínimo de cinco anos de efetivo exercício em instituição federal de educação profissional e tecnológica e que esteja posicionado nas classes DIV ou DV da carreira do magistério do ensino básico, técnico e tecnológico.","O mandato de reitor extingue-se por decurso do prazo ou, antes desse prazo, por renúncia, destituição ou vacância do cargo, não sendo por aposentadoria, voluntária ou compulsória, que é motivo de extinção do mandato.","Os pró-reitores são nomeados pelo reitor do instituto federal, após escolha pessoal."],"correta":2,"explicacao":"Gabarito: <strong>O docente poderá candidatar-se desde que pertença ao quadro de pessoal ativo permanente de qualquer dos campi que integram o instituto federal, possua o mínimo de cinco anos de efetivo exercício em instituição federal de educação profissional e tecnológica e que esteja posicionado nas classes DIV ou DV da carreira do magistério do ensino básico, técnico e tecnológico.</strong>.","banca":"FUNIVERSA","ano":2012,"temas_relacionados":["lei_11892_2008"]},{"id":345970,"enunciado":"Conforme o disposto na Lei n.º 11.892/2008, é(são) objetivo(s) dos institutos federais .","opcoes":["ministrar exclusivamente cursos de formação continuada de trabalhadores que objetivem a capacitação, o aperfeiçoamento, a especialização e a atualização de profissionais, em todos os níveis de escolaridade, nas áreas da educação profissional e tecnológica.","realizar pesquisas teóricas e aplicadas que estimulem o desenvolvimento de soluções técnicas, tecnológicas e argumentativas, estendendo seus benefícios à comunidade.","ministrar educação profissional técnica de nível médio, prioritariamente na forma de cursos integrados, para os concluintes do ensino fundamental e para o público da educação de jovens e adultos","desenvolver atividades de extensão de acordo com os princípios e as finalidades da educação tecnológica com ênfase em produção, desenvolvimento e difusão de conhecimentos práticos.","estimular e apoiar todo e qualquer processo educativo, independentemente de levar à geração de trabalho e renda e à emancipação do cidadão na perspectiva do desenvolvimento socioeconômico local e regional."],"correta":2,"explicacao":"Gabarito: <strong>ministrar educação profissional técnica de nível médio, prioritariamente na forma de cursos integrados, para os concluintes do ensino fundamental e para o público da educação de jovens e adultos</strong>.","banca":"FUNIVERSA","ano":2012,"temas_relacionados":["lei_11892_2008"]},{"id":345972,"enunciado":"Tendo em vista o disposto na Lei n.º 11.892/2008 quanto à estrutura organizacional, assinale a alternativa correta.","opcoes":["A administração de um instituto federal terá como órgãos superiores o colégio de dirigentes e o conselho superior.","A presidência do colégio de dirigentes será exercida pelo pró-reitor mais antigo, e a do conselho superior será exercida pelo reitor do instituto federal.","Cada instituto federal é organizado em estrutura multicampi, com proposta orçamentária anual identificada para cada campus e para a reitoria, incluindo, no que diz respeito a pessoal, encargos sociais e benefícios aos servidores.","O colégio de dirigentes, de caráter consultivo, será composto pelos pró-reitores e pelo diretor-geral de cada um dos campi que integram o instituto federal.","O conselho superior, de caráter consultivo, será composto por representantes dos docentes, dos estudantes, dos servidores técnico-administrativos, dos egressos da instituição, da sociedade civil, do Ministério da Educação e do colégio de dirigentes do instituto federal, assegurando-se a representação paritária dos segmentos que compõem a comunidade acadêmica."],"correta":0,"explicacao":"Gabarito: <strong>A administração de um instituto federal terá como órgãos superiores o colégio de dirigentes e o conselho superior.</strong>.","banca":"FUNIVERSA","ano":2012,"temas_relacionados":["lei_11892_2008"]},{"id":352569,"enunciado":"De acordo com a Lei 11.892, que cria os Institutos Federais de Educação, Ciência e Tecnologia, assinale V (verdadeiro) ou F (falso) para as seguintes afirmativas: ( ) Os Institutos Federais terão como órgão executivo a reitoria, composta por 1 (um) Reitor e 5 (cinco) Pró-Reitores, todos eleitos para um mandato de 4 (quatro) anos, permitida uma recondução ao cargo. ( ) É finalidade dos Institutos Federais ofertar educação profissional e tecnológica, formando e qualificando cidadãos com vistas na atuação profissional nos diversos setores da economia, com ênfase no desenvolvimento socioeconômico local, regional e nacional. ( ) É objetivo dos Institutos Federais ministrar apenas cursos de formação inicial e continuada de trabalhadores, objetivando a capacitação, o aperfeiçoamento, a especialização e a atualização de profissionais, em todos os níveis de escolaridade, nas áreas da educação profissional e tecnológica. ( ) Quanto a estrutura organizacional, os Institutos Federais terão como órgãos superiores o Conselho Superior, o Colégio de Dirigentes e o Reitor. ( ) É objetivo dos Institutos Federais ministrar em nível de educação superior cursos de licenciatura, bem como programas especiais de formação pedagógica, com vistas na formação de professores para a educação básica, sobretudo nas áreas de ciências e matemática. Assinale a alternativa que representa a seqüência correta, de cima para baixo:","opcoes":["V – F – F – F – V.","V – V – V – F – F.","F – V – F – V – V.","F – V – F – F – V.","F – F – V – V – F."],"correta":3,"explicacao":"Gabarito: <strong>F – V – F – F – V.</strong>.","banca":"IFC","ano":2012,"temas_relacionados":["lei_11892_2008"]},{"id":377412,"enunciado":"As superintendências regionais do trabalho estão diretamente subordinadas ao governador do estado onde se localizam.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":377413,"enunciado":"O MTE é um órgão da administração federal indireta.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":377414,"enunciado":"O atendimento a consultas e a requerimentos do Congresso Nacional é uma atribuição específica da Secretaria Executiva do MTE.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":377426,"enunciado":"O cadastro e a aplicação da legislação de pessoal, a capacitação, o desenvolvimento e a avaliação de desempenho dos servidores públicos são atribuições estratégicas das unidades de gestão de pessoas da administração pública.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":377434,"enunciado":"A avaliação de desempenho a que se refere o decreto é apenas uma das etapas de um processo mais amplo de gestão, que pode incluir, ainda, as etapas de planejamento, de monitoramento e de revisão do desempenho individual, grupal e organizacional.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":377435,"enunciado":"O referido decreto, tendo como referência as metas da organização e da unidade de trabalho de determinado trabalhador, compreende a avaliação de desempenho como ferramenta de apreciação transversal e pontual da atuação individual do servidor.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":377436,"enunciado":"Os critérios de avaliação de desempenho individual constantes do decreto baseiam-se na noção de competências do servidor conforme comportamentos manifestos no desempenho individual de tarefas e atividades.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":377437,"enunciado":"De acordo com o decreto em tela, a avaliação de desempenho a ser aplicada deve ser do tipo 180°, uma vez que o escore final resulta das apreciações do próprio funcionário e da respectiva chefia imediata.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":377438,"enunciado":"O decreto confere caráter estratégico à prática de avaliação de desempenho visto que determina a articulação de metas globais e intermediárias de desempenho institucional com metas de desempenho individual.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":377439,"enunciado":"Os fatores de avaliação individual estabelecidos no decreto, tais como produtividade no trabalho, conhecimentos de métodos e técnicas, trabalho em equipe e comprometimento com o trabalho, constituem descritores comportamentais precisos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":377468,"enunciado":"Em caráter excepcional, órgãos e entidades federais podem executar programas estaduais ou municipais, e os órgãos da administração direta podem executar programas a cargo de entidade da administração indireta, sob regime de mútua cooperação mediante convênio.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":377469,"enunciado":"Órgãos e entidades da administração pública federal não podem celebrar ajustes ou termos de cooperação entre si; contudo, podem firmar convênios.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":377470,"enunciado":"É vedado às entidades privadas atuar como intervenientes, manifestando consentimento ou assumindo obrigações em nome próprio, nos convênios e demais instrumentos que disciplinem a transferência de recursos financeiros de dotações da União.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":377471,"enunciado":"Contrato de repasse é um instrumento administrativo, de interesse recíproco, no qual a transferência dos recursos financeiros se processa por intermédio de instituição ou agente financeiro público federal que atua como mandatário da União.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":377479,"enunciado":"A contratação de serviços continuados de terceiros por órgão da administração pública não gera vínculo empregatício entre os empregados da contratada e a administração, ficando vedada qualquer relação que caracterize pessoalidade e subordinação direta entre o órgão administrativo e os empregados.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":377480,"enunciado":"Se a administração pública promover a contratação de serviços de cooperativas ou de instituições sem fins lucrativos, o serviço contratado deverá ser executado, obrigatoriamente, pelos cooperados, no caso de cooperativas, ou pelos profissionais pertencentes aos quadros funcionais da instituição, vedada qualquer intermediação ou subcontratação.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":377481,"enunciado":"Menor preço é o tipo de licitação que, preferencialmente, deve ser adotado na contratação de serviços. No entanto, caso a contratação seja para a prestação de serviços considerados comuns, deverá ser adotada a modalidade de licitação convite ou o pregão.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":383737,"enunciado":"De acordo com a Lei 11.892/08, analise as assertivas e assinale a alternativa que aponta a(s) correta(s). I. O Colégio Pedro II é instituição federal de ensino, pluricurricular e multicampi, vinculada ao Ministério da Educação e especializada na oferta de educação básica e de licenciaturas. II. O Colégio Pedro II possui natureza jurídica de empresa pública que, embora não seja detentora de autonomia administrativa, patrimonial, financeira, possui autonomia didático-pedagógica e disciplinar. III. O Colégio Pedro II é equiparado aos institutos federais para efeito de incidência das disposições que regem a autonomia e a utilização dos instrumentos de gestão do quadro de pessoal e de ações de regulação, avaliação e supervisão das instituições e dos cursos de educação profissional e superior. IV. As unidades escolares que atualmente compõem a estrutura organizacional do Colégio Pedro II passam de forma automática, independentemente de qualquer formalidade, à condição de campi da instituição.","opcoes":["Apenas I","Apenas II e III","Apenas I e IV","Apenas I, III e IV","I, II, III e IV"],"correta":3,"explicacao":"Gabarito: <strong>Apenas I, III e IV</strong>.","banca":"INSTITUTO AOCP","ano":2013,"temas_relacionados":["lei_11892_2008"]},{"id":383837,"enunciado":"De acordo com a Lei 11.892/2008, acerca do Colégio Pedro II, assinale a alternativa INCORRETA.","opcoes":["O Colégio Pedro II é uma instituição federal de ensino, pluricurricular e multicampi, vinculada ao Ministério da Educação e especializada na oferta de educação básica e de licenciaturas.","O Colégio Pedro II é equiparado aos institutos federais para efeito de incidência das disposições que regem a autonomia e a utilização dos instrumentos de gestão do quadro de pessoal e de ações de regulação, avaliação e supervisão das instituições e dos cursos de educação profissional e superior.","O Colégio Pedro II terá a mesma estrutura e organização dos Institutos Federais de Educação, Ciência e Tecnologia.","As unidades escolares que atualmente compõem a estrutura organizacional do Colégio Pedro II passam de forma automática, independentemente de qualquer formalidade, à condição de campi da instituição.","A criação de novos campi do Colégio Pedro II fica condicionada à expedição de autorização específica do Ministério do Planejamento."],"correta":4,"explicacao":"Gabarito: <strong>A criação de novos campi do Colégio Pedro II fica condicionada à expedição de autorização específica do Ministério do Planejamento.</strong>.","banca":"INSTITUTO AOCP","ano":2013,"temas_relacionados":["lei_11892_2008"]},{"id":385344,"enunciado":"De acordo com a Lei 11.892/2008, para efeito de incidência das disposições que regem a autonomia e a utilização dos instrumentos de gestão do quadro de pessoal e de ações de regulação, avaliação e supervisão das instituições e dos cursos de educação profssional e superior, o Colégio Pedro II é equiparado","opcoes":["aos Centros Federais de Educação Tecnológica.","às Empresas Públicas.","às Instituições Particulares.","às Universidades Tecnológicas.","aos Institutos Federais."],"correta":4,"explicacao":"Gabarito: <strong>aos Institutos Federais.</strong>.","banca":"INSTITUTO AOCP","ano":2013,"temas_relacionados":["lei_11892_2008"]},{"id":391312,"enunciado":"A Rede Federal de Educação Profissional, Científica e Tecnológica conta, atualmente, com 354 unidades e mais de 400 mil vagas em todo o país. Segundo o site do MEC, essa Rede Federal “presta um serviço à nação ao dar continuidade à sua missão de qualificar profissionais para os diversos setores da economia brasileira, realizar pesquisa e desenvolver novos processos, produtos e serviços em colaboração com o setor produtivo”. A Rede cobre todos os estados brasileiros e oferece cursos técnicos e também cursos:","opcoes":["de requalificação profissional","de ciências humanas","profissionalizantes","de doutorado"],"correta":3,"explicacao":"Gabarito: <strong>de doutorado</strong>.","banca":"FDC","ano":2014,"temas_relacionados":["lei_11892_2008"]},{"id":391459,"enunciado":"De acordo com a Lei n. 11.892/2008, modificada pela Lei n. 12.772/2012, poderão ser nomeados pró-reitores os servidores ocupantes de cargo efetivo com nível superior da carreira dos técnicos-administrativos, desde que exerçam o cargo de forma efetiva, em instituição federal de educação profissional e tecnológica, pelo período mínimo de","opcoes":["2 anos.","3 anos.","4 anos.","5 anos."],"correta":3,"explicacao":"Gabarito: <strong>5 anos.</strong>.","banca":"IV - UFG","ano":2014,"temas_relacionados":["lei_11892_2008"]},{"id":393868,"enunciado":"Acerca do que prevê o a Lei n 11.892/2008, que institui a Rede Federal de Educação Profissional, Científica e Tecnológica e cria os Institutos Federais de Educação, Ciência e Tecnologia, seguem-se quatro afirmações: I. Os Institutos Federais terão autonomia para criar e extinguir cursos, nos limites de sua área de atuação territorial, bem como para registrar diplomas dos cursos por eles oferecidos, mediante autorização do seu Colégio de Dirigentes; II. Os Institutos Federais são equiparados às universidades federais para efeito da incidência das disposições que regem a regulação, avaliação e supervisão das instituições e dos cursos de educação superior; III. A unidade de ensino que compõe a estrutura organizacional de instituição transformada ou integrada em Instituto Federal passa de forma automática, independentemente de qualquer formalidade, à condição de campus da nova instituição; IV. O Colégio Pedro II é equiparado aos institutos federais somente para efeito de incidência das disposições que regem as ações de regulação, avaliação e supervisão das instituições e dos cursos de educação profissional e superior; Está correto apenas o que se afirma em :","opcoes":["I e II.","II e IV.","III e IV.","I, III e IV.","II e III."],"correta":4,"explicacao":"Gabarito: <strong>II e III.</strong>.","banca":"FUNRIO","ano":2014,"temas_relacionados":["lei_11892_2008"]},{"id":393869,"enunciado":"Considerando as finalidades e características dos Institutos Federais, conforme previsto na Lei nº 11.892/2008, pode-se afirmar que eles têm como objetivos: I. Promover a integração e a horizontalização da educação básica à educação profissional e educação superior, otimizando a infraestrutura física, os quadros de pessoal e os recursos de gestão; II. Estimular e apoiar processos educativos que levem à geração de trabalho e renda e à emancipação do cidadão na perspectiva do desenvolvimento socioeconômico local e regional; III. Ministrar cursos de formação inicial e continuada de trabalhadores, objetivando a capacitação, o aperfeiçoamento, a especialização e a atualização de profissionais, em todos os níveis de escolaridade, nas áreas da educação profissional e tecnológica; IV. Ministrar educação profissional técnica de nível médio, prioritariamente na forma de cursos integrados, para os concluintes do ensino fundamental e para o público da educação de jovens e adultos. Está correto apenas o que se afirma em :","opcoes":["I e II.","I, II e IV.","III e IV.","II, III e IV.","II e III."],"correta":3,"explicacao":"Gabarito: <strong>II, III e IV.</strong>.","banca":"FUNRIO","ano":2014,"temas_relacionados":["lei_11892_2008"]},{"id":393870,"enunciado":"Acerca do que prevê a Lei nº 11.892/2008 sobre a estrutura organizacional dos Institutos Federais, seguem-se quatro afirmações: I. A reitoria, como órgão de administração central, poderá ser instalada em espaço físico distinto de qualquer dos campi que integram o Instituto Federal, desde que previsto em seu estatuto e aprovado pelo Ministério da Educação. II. Os Reitores serão nomeados pelo Presidente da República, para mandato de 4 (quatro) anos, permitida uma recondução, após processo de consulta à comunidade escolar do respectivo Instituto Federal. III. O Conselho Superior, de caráter consultivo, será composto pelo Reitor, pelos Pró-Reitores e pelo Diretor-Geral de cada um dos campi que integram o Instituto Federal. IV. A administração dos Institutos Federais terá como órgãos superiores o Colégio de Dirigentes e a Reitoria. Está correto apenas o que se afirma em :","opcoes":["I e II.","II e IV.","III e IV.","I, III e IV.","II e III."],"correta":0,"explicacao":"Gabarito: <strong>I e II.</strong>.","banca":"FUNRIO","ano":2014,"temas_relacionados":["lei_11892_2008"]},{"id":396071,"enunciado":"Nos termos da Lei no 11.892/2008, dentre as abaixo relacionadas, qual a instituição que participa da Rede Federal de Educação Profissional, Científica e Tecnológica, vinculada ao Ministério da Educação?","opcoes":["Colégio Tecnológico da Universidade de São Paulo","Colégio Federal de Brasília","Colégio de Aplicação da UFRJ","Colégio Militar do Rio de Janeiro","Colégio Pedro II"],"correta":4,"explicacao":"Gabarito: <strong>Colégio Pedro II</strong>.","banca":"CESGRANRIO","ano":2014,"temas_relacionados":["lei_11892_2008"]},{"id":396987,"enunciado":"Acerca das finalidades e características dos Institutos Federais, a Lei nº 11.892/2008 prevê as seguintes: I. Desenvolver a educação profissional e tecnológica como processo educativo e investigativo de geração e adaptação de soluções técnicas e tecnológicas às demandas sociais e peculiaridades regionais; II. Constituir-se em centro de excelência na oferta do ensino de ciências, em geral, estimulando o desenvolvimento do corpo discente, voltado à investigação teórica; III. Ofertar educação profissional e tecnológica, em todos os seus níveis e modalidades, formando e qualificando cidadãos com vistas na atuação profissional nos diversos setores da economia, com ênfase no desenvolvimento socioambiental local; IV. Orientar sua oferta formativa em benefício da consolidação e fortalecimento dos arranjos produtivos, sociais e culturais locais, identificados com base no mapeamento das potencialidades de desenvolvimento socioeconômico e cultural no âmbito de atuação do Instituto Federal. Está correto apenas o que se afirma em :","opcoes":["I e III.","II e IV.","I e IV.","II, III e IV.","I, II e III."],"correta":2,"explicacao":"Gabarito: <strong>I e IV.</strong>.","banca":"FUNRIO","ano":2014,"temas_relacionados":["lei_11892_2008"]},{"id":396988,"enunciado":"Considerando o que prevê a Lei nº 11.892/2008, que institui a Rede Federal de Educação Profissional, Científica e Tecnológica e cria os Institutos Federais de Educação, Ciência e Tecnologia, assinale a alternativa correta.","opcoes":["Os Institutos Federais terão como órgão executivo a reitoria, composta por um Reitor e quatro Pró-Reitores.","O Colégio de Dirigentes, de caráter consultivo, será composto por representantes dos docentes, dos estudantes e dos servidores técnico-administrativos, assegurando-se a representação paritária destes segmentos.","O Conselho Superior, de caráter consultivo e deliberativo, será composto pelo Reitor, pelos Pró-Reitores e pelo Diretor- Geral de cada um dos campi que integram o Instituto Federal.","Os Reitores serão nomeados pelo Ministro da Educação, para mandato de 4 (quatro) anos, permitida uma recondução, após processo de consulta à comunidade escolar do respectivo Instituto Federal.","Os Pró-Reitores são nomeados pelo Reitor do Instituto Federal, nos termos da legislação aplicável à nomeação de cargos de direção."],"correta":4,"explicacao":"Gabarito: <strong>Os Pró-Reitores são nomeados pelo Reitor do Instituto Federal, nos termos da legislação aplicável à nomeação de cargos de direção.</strong>.","banca":"FUNRIO","ano":2014,"temas_relacionados":["lei_11892_2008"]},{"id":396989,"enunciado":"Acerca do que prevê a Lei nº 11.892/2008, seguem-se três disposições: I. Nos campi em processo de implantação, os cargos de Diretor-Geral serão providos em caráter pro tempore, após processo de consulta à comunidade do respectivo campus, atribuindo-se o peso de 1/3 (um terço) para a manifestação do corpo docente, de 1/3 (um terço) para a manifestação dos servidores técnico-administrativos e de 1/3 (um terço) para a manifestação do corpo discente; II. As unidades escolares que atualmente compõem a estrutura organizacional do Colégio Pedro II passam de forma automática, independentemente de qualquer formalidade, à condição de campi da instituição. III. A reitoria, como órgão de administração central, poderá ser instalada em espaço físico distinto de qualquer dos campi que integram o Instituto Federal, desde que previsto em seu estatuto e aprovado pelo Ministério da Educação. Está correto apenas o que se afirma em :","opcoes":["I e II.","II e III.","I e III.","I","III"],"correta":1,"explicacao":"Gabarito: <strong>II e III.</strong>.","banca":"FUNRIO","ano":2014,"temas_relacionados":["lei_11892_2008"]},{"id":398212,"enunciado":"Segundo a Lei n.º 11.892/2008, assinale a alternativa correta a respeito do patrimônio de cada um dos novos institutos federais.","opcoes":["As doações ou os legados que receber serão bens da União. Os bens e os direitos do instituto federal serão utilizados ou aplicados, exclusivamente, para a consecução de seus objetivos, não podendo ser alienados, a não ser nos casos e condições permitidos em lei.","Incorporações que resultem de serviços por ele realizado serão transferidas para a União e, posteriormente, doadas ao instituto.","Os bens e os direitos do instituto federal serão utilizados ou aplicados, exclusivamente, para a consecução de seus objetivos, não podendo ser alienados em nenhuma hipótese.","Os bens e os direitos que o instituto federal vier a adquirir integrarão o seu patrimônio.","Os bens pertencentes às entidades na época de sua criação são transferidos à União, para posterior distribuição igualitária entre os novos institutos federais."],"correta":3,"explicacao":"Gabarito: <strong>Os bens e os direitos que o instituto federal vier a adquirir integrarão o seu patrimônio.</strong>.","banca":"FUNIVERSA","ano":2012,"temas_relacionados":["lei_11892_2008"]},{"id":417607,"enunciado":"Assinale a alternativa que indique uma instituição que, segundo a Lei nº 11.892/2008, NÃO tenha a natureza jurídica de autarquia.","opcoes":["Colégio Pedro II.","Universidade Tecnológica Federal do Paraná – UTFPR.","Escolas Técnicas Vinculadas às Universidades Federais.","Institutos Federais de Educação, Ciência e Tecnologia – Institutos Federais.","Centros Federais de Educação Tecnológica Suckow da Fonseca – CEFET-RJ e de Minas Gerais – CEFET-MG."],"correta":2,"explicacao":"Gabarito: <strong>Escolas Técnicas Vinculadas às Universidades Federais.</strong>.","banca":"IDECAN","ano":2014,"temas_relacionados":["lei_11892_2008"]},{"id":417720,"enunciado":"A Lei nº 11.892/2008 dispõe que “o Colégio Pedro II terá a mesma estrutura e organização dos Institutos Federais de Educação, Ciência e Tecnologia”. A respeito da estrutura e organização dos referidos Institutos Federais, assinale a afirmativa INCORRETA.","opcoes":["O Colégio de Dirigentes, de caráter consultivo, será composto pelo Reitor, pelos Pró-Reitores e pelo Diretor-Geral de cada um dos campi que integram o Instituto Federal.","Cada Instituto Federal é organizado em estrutura multicampi, com proposta orçamentária anual identificada para cada campus e a reitoria, exceto no que diz respeito a pessoal, encargos sociais e benefícios aos servidores.","A reitoria, como órgão de administração central, poderá ser instalada em espaço físico distinto de qualquer dos campi que integram o Instituto Federal, desde que previsto em seu estatuto e aprovado pelo Ministério da Educação.","Poderão candidatar-se ao cargo de Pró-Reitor do campus os servidores ocupantes de cargo efetivo da carreira docente ou de cargo efetivo de nível superior da carreira dos técnico-administrativos do Plano de Carreira dos Cargos Técnico- Administrativos em Educação, desde que possuam o mínimo de 5 anos de efetivo exercício em instituição federal de educação profissional e tecnológica.","Os campi serão dirigidos por Diretores-Gerais, nomeados pelo Reitor para mandato de 4 anos, permitida uma recondução, após processo de consulta à comunidade do respectivo campus, atribuindo-se o peso de 1/3 para a manifestação do corpo docente, de 1/3 para a manifestação dos servidores técnico-administrativos e de 1/3 para a manifestação do corpo discente."],"correta":3,"explicacao":"Gabarito: <strong>Poderão candidatar-se ao cargo de Pró-Reitor do campus os servidores ocupantes de cargo efetivo da carreira docente ou de cargo efetivo de nível superior da carreira dos técnico-administrativos do Plano de Carreira dos Cargos Técnico- Administrativos em Educação, desde que possuam o mínimo de 5 anos de efetivo exercício em instituição federal de educação profissional e tecnológica.</strong>.","banca":"IDECAN","ano":2014,"temas_relacionados":["lei_11892_2008"]},{"id":417722,"enunciado":"O Colégio Pedro II é uma das instituições que constituem, no âmbito do sistema federal de ensino, a Rede Federal de Educação Profissional, Científica e Tecnológica, vinculada ao Ministério da Educação, conforme Lei nº 11.892/2008. Assim, nos termos da referida legislação, é correto afirmar que o Colégio Pedro II possui natureza jurídica de","opcoes":["fundação pública de caráter filantrópico, educacional e assistencial.","empresa pública, prestadora de serviço público na área específica de educação, ciência e tecnologia.","autarquia, detentoras de autonomia administrativa, patrimonial, financeira, didático-pedagógica e disciplinar.","fundação privada integralizada pelo capital público da União para desenvolvimento de trabalho na área de educação, ciência e tecnológica.","Sociedade de Economia Mista exploradora de atividade econômica na área educacional profissionalizante, cuja maior parte do capital votante pertence à União."],"correta":2,"explicacao":"Gabarito: <strong>autarquia, detentoras de autonomia administrativa, patrimonial, financeira, didático-pedagógica e disciplinar.</strong>.","banca":"IDECAN","ano":2014,"temas_relacionados":["lei_11892_2008"]},{"id":418878,"enunciado":"Considerando o que prevê a Lei nº 11.892/2008 com respeito à administração dos Institutos Federais, é correto afirmar que","opcoes":["poderão ser nomeados Pró-Reitores apenas os servidores ocupantes de cargo efetivo da Carreira docente.","os Pró-Reitores são nomeados pelo Ministro da Educação, nos termos da legislação aplicável à nomeação de cargos de direção.","poderão candidatar-se ao cargo de Diretor-Geral do campus apenas os servidores ocupantes de cargo efetivo de nível superior, da carreira dos técnico-administrativos, do Plano de Carreira dos Cargos Técnico-Administrativos em Educação.","Os Reitores serão nomeados pelo Presidente da República, para mandato de 4 (quatro) anos, permitida uma recondução, após processo de consulta à comunidade escolar do respectivo Instituto Federal.","Os campi serão dirigidos por Pró-Reitores, nomeados para mandato de 4 (quatro) anos, não sendo permitida recondução."],"correta":3,"explicacao":"Gabarito: <strong>Os Reitores serão nomeados pelo Presidente da República, para mandato de 4 (quatro) anos, permitida uma recondução, após processo de consulta à comunidade escolar do respectivo Instituto Federal.</strong>.","banca":"FUNRIO","ano":2014,"temas_relacionados":["lei_11892_2008"]},{"id":418879,"enunciado":"Acerca das finalidades e características dos Institutos Federais, conforme previsto na Lei nº 11.892/2008, pode-se afirmar que são as seguintes: I. Realizar e estimular a pesquisa aplicada, a produção cultural, o empreendedorismo, o cooperativismo e o desenvolvimento científico e tecnológico; II. Promover a produção, o desenvolvimento e a transferência de novas tecnologias, notadamente as voltadas AA manutenção do crescimento econômico. III. Promover a integração e a verticalização da educação básica à educação profissional e educação superior, otimizando a infra-estrutura física, os quadros de pessoal e os recursos de gestão. Está correto apenas o que se afirma em","opcoes":["I","II","III","I, II e III.","I e III."],"correta":4,"explicacao":"Gabarito: <strong>I e III.</strong>.","banca":"FUNRIO","ano":2014,"temas_relacionados":["lei_11892_2008"]},{"id":418880,"enunciado":"Os Institutos Federais, previstos na Lei nº 11.892/2008, têm como objetivos: I. Constituir-se em centro de excelência na oferta do ensino de ciências, em geral, e de ciências aplicadas, em particular, estimulando o desenvolvimento de espírito crítico, voltado à investigação empírica; II. Estimular e apoiar processos educativos que levem à geração de trabalho e renda e à emancipação do cidadão na perspectiva do desenvolvimento socioeconômico local e regional; III. Ministrar cursos de formação inicial e continuada de trabalhadores, objetivando a capacitação, o aperfeiçoamento, a especialização e a atualização de profissionais, em todos os níveis de escolaridade, nas áreas da educação profissional e tecnológica. Está correto apenas o que se afirma em","opcoes":["II e III.","I e III.","III.","I e II.","I, II e III."],"correta":0,"explicacao":"Gabarito: <strong>II e III.</strong>.","banca":"FUNRIO","ano":2014,"temas_relacionados":["lei_11892_2008"]},{"id":449339,"enunciado":"Com base na Lei nº 11.892/2008, sobre as finalidades, as características e os objetivos dos Institutos Federais, marque V para verdadeiro ou F para falso e, em seguida, assinale a alternativa que apresenta a sequência correta. (   ) Promover a integração e a verticalização da educação básica à educação profissional e educação superior, otimizando a infraestrutura física, os quadros de pessoal e os recursos de gestão é um dos objetivos dos Institutos Federais. (   ) Estimular e apoiar processos educativos que levem à geração de trabalho e renda e à emancipação do cidadão na perspectiva do desenvolvimento socioeconômico local e regional é uma das finalidades dos Institutos Federais. (   ) Ofertar educação profissional e tecnológica, em todos os seus níveis e modalidades, formando e qualificando cidadãos com vistas na atuação profissional nos diversos setores da economia, com ênfase no desenvolvimento socioeconômico local, regional e nacional compreende uma das finalidades e características dos Institutos Federais.","opcoes":["V/ F/ V","F/ F/ V","F/ V/ F","F/ F/ F","V/ V/ F"],"correta":1,"explicacao":"Gabarito: <strong>F/ F/ V</strong>.","banca":"CETRO","ano":2014,"temas_relacionados":["lei_11892_2008"]},{"id":449791,"enunciado":"Com relação à Lei nº 11.892/2008, que institui a Rede Federal de Educação Profissional, Científica e Tecnológica, cria os Institutos Federais de Educação, Ciência e Tecnologia, e dá outras providências, assinale a alternativa correta.","opcoes":["Servidor ocupante de cargo efetivo com nível superior da Carreira dos técnico-administrativos do Plano de Carreira dos Cargos Técnico- Administrativos em Educação poderá ser nomeado Reitor desde que possua o mínimo de 5 (cinco) anos de efetivo exercício em instituição federal de educação profissional e tecnológica.","Os reitores serão nomeados pelo Ministro da Educação para mandato de 4 (quatro) anos, permitida uma recondução.","O mandato de Reitor não poderá ser extinto antes do decurso do prazo por motivo de aposentadoria compulsória.","Cada Instituto Federal é organizado em estrutura multicampi, com proposta orçamentária anual identificada para cada campus e a reitoria, inclusive no que diz respeito a pessoal, encargos sociais e benefícios aos servidores.","Representantes dos estudantes, dos egressos da instituição e da sociedade civil comporão o Conselho Superior, um dos órgãos superiores da administração dos Institutos Federais."],"correta":4,"explicacao":"Gabarito: <strong>Representantes dos estudantes, dos egressos da instituição e da sociedade civil comporão o Conselho Superior, um dos órgãos superiores da administração dos Institutos Federais.</strong>.","banca":"CETRO","ano":2014,"temas_relacionados":["lei_11892_2008"]},{"id":452596,"enunciado":"Sobre a Lei nº 11.892 de 29 de Dezembro de 2008 que instituiu a Rede de Educação Profissional e Tecnológica e criou os Institutos Federais de Educação, Ciência e Tecnologia, numere corretamente a coluna da direita de acordo com a da esquerda. ( ) Especializado na oferta de educação básica e licenciatura; ( ) Não possui natureza jurídica de autarquia e autonomia administrativa; ( ) É equiparado às Universidades para efeito das disposições que regem a regulação, a avaliação e a supervisão das instituições de ensino superior; ( ) É configurada como instituição de ensino superior especializada na oferta de educação tecnológica. (1) Instituto Federal (2) Colégio Pedro II (3) Escola Técnica Vinculada (4) CEFET Marque a opção que contenha a sequência CORRETA de cima para baixo.","opcoes":["2, 3, 1, 4.","2, 4, 1, 3.","2, 1, 4, 3.","3, 2, 1, 4.","3, 2, 4, 1."],"correta":0,"explicacao":"Gabarito: <strong>2, 3, 1, 4.</strong>.","banca":"IF-SC","ano":2014,"temas_relacionados":["lei_11892_2008"]},{"id":459628,"enunciado":"De acordo com a Lei 11.892/08, o Colégio Pedro II","opcoes":["é instituição federal de ensino, vinculada ao Ministério da Educação.","é instituição municipal de ensino, vinculada à Secretaria Estadual de Educação","é instituição estadual de ensino, vinculada ao Município.","é instituição federal de ensino, vinculada às Universidades Federais.","é instituição municipal de ensino, vinculada ao Ministério da Educação."],"correta":0,"explicacao":"Gabarito: <strong>é instituição federal de ensino, vinculada ao Ministério da Educação.</strong>.","banca":"INSTITUTO AOCP","ano":2013,"temas_relacionados":["lei_11892_2008"]},{"id":491206,"enunciado":"Segundo a lei nº 11.892, de 29 de dezembro de 2008, que institui a Rede Federal de Educação Profissional, Científica e Tecnológica, cria os Institutos Federais de Educação, Ciência e Tecnologia e dá outras providências, afirma-se: I – O Instituto Federal deverá garantir no mínimo 50% (cinquenta por cento) de suas vagas para ministrar educação profissional técnica de nível médio. II – Terá como órgão executivo a reitoria composta por 1 (um) Reitor e 5 (cinco) Pró- Reitores. III – O colégio de dirigentes é composto pelo Reitor, pelos Pró-Reitores e pelo Diretor- Geral de cada um dos campi que integram o Instituto Federal. IV - O Instituto Federal deverá garantir no mínimo 20% (vinte por cento) de suas vagas para cursos de licenciatura, bem como programas especiais de formação pedagógica, com vistas à formação de professores. V – Os campi serão dirigidos pelo Diretor-Geral do campus, nomeados pelo Reitor para o mandato de 4 (quatro) anos, permitida uma recondução, após processo de consulta à comunidade do respectivo Instituto, atribuindo-se peso de 1/3 (um terço) para manifestação do corpo docente, de 1/3 (um terço) para manifestação dos servidores técnico-administrativos e de 1/3 (um terço) para manifestação do corpo discente. Estão CORRETAS:","opcoes":["Todas as afirmativas.","Somente quatro afirmativas","Somente duas afirmativas.","Somente três afirmativas.","Nenhuma das afirmativas."],"correta":1,"explicacao":"Gabarito: <strong>Somente quatro afirmativas</strong>.","banca":"IFC","ano":2010,"temas_relacionados":["lei_11892_2008"]},{"id":516370,"enunciado":"Conforme a Lei nº. 11.892/2008, os Institutos Federais, têm por finalidades e características, exceto:","opcoes":["desenvolver programas de extensão e de divulgação científica e tecnológica.","promover a produção, o desenvolvimento e a transferência de tecnologias sociais, notadamente as voltadas à preservação do meio ambiente.","desenvolver a educação profissional e tecnológica como processo educativo e investigativo de geração e adaptação de soluções técnicas e tecnológicas às demandas sociais e peculiaridades regionais.","organizar-se em estrutura multicampi, com proposta no que diz respeito a pessoal, encargos sociais e benefícios aos servidores."],"correta":3,"explicacao":"Gabarito: <strong>organizar-se em estrutura multicampi, com proposta no que diz respeito a pessoal, encargos sociais e benefícios aos servidores.</strong>.","banca":"EXATUS","ano":2012,"temas_relacionados":["lei_11892_2008"]},{"id":516801,"enunciado":"Sobre os Objetivos dos Institutos Federais  constantes  de  Lei  nº  11.892/2008,  analise as afirmativas: I  –  os  institutos  federais  objetivam  o  desenvolvimento  de  tecnologia  para  o  desenvolvimento de armamento nuclear; II  –  objetivam  realizar  pesquisas  aplicadas, estimulando o desenvolvimento  de  soluções  técnicas  e  tecnológicas,  estendendo  seus  benefícios  à  comunidade; III  –  objetivam  estimular  e  apoiar  processos educativos que levem à geração  de  trabalho  e  renda  e  à  emancipação  do  cidadão  na  perspectiva  do  desenvolvimento  socioeconômico  local  e  regional; IV  –  objetivam  ministrar  educação  profissional técnica de nível médio, exceto  na  forma  de  cursos  integrados  e  da  educação de jovens e adultos. À luz da legislação mencionada, marque a  alternativa correta:","opcoes":["Apenas a afirmativa I está correta.","Apenas a afirmativa II está errada.","Apenas as afirmativas I e IV estão  erradas.","Apenas as alternativas I e III estão corretas.","Apenas a afirmativa II está correta."],"correta":2,"explicacao":"Gabarito: <strong>Apenas as afirmativas I e IV estão  erradas.</strong>.","banca":"IF-TO","ano":2014,"temas_relacionados":["lei_11892_2008"]},{"id":523141,"enunciado":"Segundo o art. 2 da Lei nº 11.892, de 29/12/2008, os Institutos Federais são instituições de educação superior:","opcoes":["uniculturales e modernizantes.","multiculturales e funcionalistas.","pluricurriculares e multicampi.","tecnológicos e disciplinantes.","civilizatórios e legalistas."],"correta":2,"explicacao":"Gabarito: <strong>pluricurriculares e multicampi.</strong>.","banca":"FUNCAB","ano":2013,"temas_relacionados":["lei_11892_2008"]},{"id":532912,"enunciado":"Assinale a opção que, de acordo com a Lei n° 11.892, de 29 de dezembro de 2008, Institui a Rede Federal de Educação Profissional, Científica e Tecnológica, cria os Institutos Federais de Educação, Ciência e Tecnologia, e dá outras providências, contenha um dos objetivos dos Institutos Federais, constante na Seção III:","opcoes":["ministrar educação profissional técnica de nível médio, prioritariamente na forma de cursos integrados, para os concluintes do ensino fundamental e para o público da educação de jovens e adultos.","promover a produção, o desenvolvimento e a transferência de tecnologias sociais, notadamente as voltadas à preservação do meio ambiente.","realizar e estimular a pesquisa aplicada, a produção cultural, o empreendedorismo, o cooperativismo e o desenvolvimento científico e tecnológico.","desenvolver programas de extensão e de divulgação científica e tecnológica","qualificar-se como centro de referência no apoio à oferta do ensino de ciências nas instituições públicas de ensino, oferecendo capacitação técnica e atualização pedagógica aos docentes das redes públicas de ensino."],"correta":0,"explicacao":"Gabarito: <strong>ministrar educação profissional técnica de nível médio, prioritariamente na forma de cursos integrados, para os concluintes do ensino fundamental e para o público da educação de jovens e adultos.</strong>.","banca":"IF-PA","ano":2015,"temas_relacionados":["lei_11892_2008"]},{"id":540944,"enunciado":"Sobre as finalidades dos Institutos Federais de Educação, Ciência e Tecnologia, conforme preconiza a Lei N.º 11.892/2008, marque V para as afirmativas verdadeiras e F para as falsas. ( ) Ofertar educação profissional e tecnológica prioritariamente na educação básica e suas modalidades, considerando as necessidades imperativas de formação de profissionais para garantir o crescimento da economia. ( ) Ofertar cursos sintonizados com os arranjos locais para o incremento da produção, fortalecimento da organização social e das identidades culturais. ( ) Desenvolver programas de extensão que articulem o ensino e a pesquisa com as demandas sociais. ( ) Promover a produção, o desenvolvimento e a transferência de tecnologias sociais, com especial relevo às voltadas à preservação do meio ambiente. Assinale a sequência correta.","opcoes":["F, V, V, V","F, V, F, V","V, F, V, F","V, F, F, F"],"correta":0,"explicacao":"Gabarito: <strong>F, V, V, V</strong>.","banca":"IF-MT","ano":2014,"temas_relacionados":["lei_11892_2008"]},{"id":546205,"enunciado":"São finalidades dos institutos federais, nos termos da Lei nº 11.892/2008, exceto:","opcoes":["Promover a integração e a verticalização da educação básica à educação profissional e educação superior, otimizando a infra-estrutura física, os quadros de pessoal e os recursos de gestão.","Realizar pesquisas aplicadas, estimulando o desenvolvimento de soluções técnicas e tecnológicas, estendendo seus benefícios à comunidade.","Constituir-se em centro de excelência na oferta do ensino de ciências, em geral, e de ciências aplicadas, em particular, estimulando o desenvolvimento de espírito crítico, voltado à investigação empírica.","Desenvolver programas de extensão e de divulgação científica e tecnológica.","Promover a produção, o desenvolvimento e a transferência de tecnologias sociais, notadamente as voltadas à preservação do meio ambiente."],"correta":1,"explicacao":"Gabarito: <strong>Realizar pesquisas aplicadas, estimulando o desenvolvimento de soluções técnicas e tecnológicas, estendendo seus benefícios à comunidade.</strong>.","banca":"IF-TO","ano":2015,"temas_relacionados":["lei_11892_2008"]},{"id":546254,"enunciado":"No tocante à organização e estrutura dos institutos federais, criados pela Lei nº 11.892/2008, assinale a alternativa que aponta o tipo de estrutura adotada pelos institutos:","opcoes":["Unicampi.","Centralizada.","Multicampi.","Reitoria.","Privatizada."],"correta":2,"explicacao":"Gabarito: <strong>Multicampi.</strong>.","banca":"IF-TO","ano":2015,"temas_relacionados":["lei_11892_2008"]},{"id":549815,"enunciado":"Sobre a estrutura organizacional dos institutos federais, é correto afirmar, nos termos da Lei nº 11.892/2008, que","opcoes":["os institutos federais terão, como órgão executivo, a reitoria, composta por um reitor e quatro pró- reitores.","a administração dos institutos federais terá como órgãos superiores o Colégio de Dirigentes e o Conselho Superior.","a reitoria, como órgão de administração central, deverá ser instalada em espaço físico próprio na capital do estado.","a administração dos institutos federais será organizada em estrutura multicampi, com proposta orçamentária quadrienal."],"correta":1,"explicacao":"Gabarito: <strong>a administração dos institutos federais terá como órgãos superiores o Colégio de Dirigentes e o Conselho Superior.</strong>.","banca":"FUNCERN","ano":2015,"temas_relacionados":["lei_11892_2008"]},{"id":554290,"enunciado":"A Lei nº 11.892/2008 instituiu a Rede Federal de Educação Profissional, Científica e Tecnológica e criou os institutos federais de educação, ciência e tecnologia. Uma das finalidades e características dos institutos federais, enumeradas no art. 6º dessa Lei, é","opcoes":["promover a integração e a verticalização da educação básica à educação profissional, otimizando as plataformas virtuais e os quadros de gestão.","realizar e estimular a pesquisa social aplicada, a produção cultural, o cooperativismo e o desenvolvimento da escolaridade rural.","realizar e desenvolver programas ambientais de extensão e de divulgação científica e tecnológica, com foco nos arranjos produtivos locais.","promover a produção, o desenvolvimento e a transferência de tecnologias sociais, notadamente, as voltadas à preservação do meio ambiente."],"correta":3,"explicacao":"Gabarito: <strong>promover a produção, o desenvolvimento e a transferência de tecnologias sociais, notadamente, as voltadas à preservação do meio ambiente.</strong>.","banca":"FUNCERN","ano":2015,"temas_relacionados":["lei_11892_2008"]},{"id":560572,"enunciado":"De acordo com o Artigo 2º da Lei nº 11.892/2008,","opcoes":["os reitores dos Institutos Federais terão autonomia para criar cursos, nos limites de sua área de atuação, observadas as peculiaridades de cada Região geográfica nacional.","para efeito da avaliação e regulamentação das instituições e dos cursos de educação de nível médio, os Institutos Federais se equiparam às universidades federais.","o Ministério da Educação será responsável pela escolha de dois dos pró-reitores de cada instituto federal, que devem ser servidores efetivos.","no âmbito de sua atuação, os Institutos Federais exercerão o papel de instituições acreditadoras e certificadoras de competências profissionais."],"correta":3,"explicacao":"Gabarito: <strong>no âmbito de sua atuação, os Institutos Federais exercerão o papel de instituições acreditadoras e certificadoras de competências profissionais.</strong>.","banca":"FUNCERN","ano":2015,"temas_relacionados":["lei_11892_2008"]},{"id":584301,"enunciado":"Segundo a Lei nº 11.892 de 29 de dezembro de 2008, no desenvolvimento das suas ações acadêmicas, os Institutos Federais, em cada exercício, deverão garantir o mínimo de:","opcoes":["50% em educação profissional técnica de nível médio, prioritariamente na forma de cursos integrados e 20% em cursos de licenciatura, bem como programas especiais de formação pedagógica.","60% em educação profissional técnica de nível médio, prioritariamente na forma de cursos integrados e 30% em cursos de licenciatura, bem como programas especiais de formação pedagógica e 10% nos demais cursos.","40% em educação profissional técnica de nível médio, prioritariamente na forma de cursos integrados e 30% em cursos de licenciatura, bem como programas especiais de formação pedagógica e 30% em cursos de engenharia, bacharelado e pós-graduação lato sensu e stricto sensu.","50% em educação profissional técnica de nível médio, prioritariamente na forma de cursos integrados e 25% em cursos de licenciatura, bem como programas especiais de formação pedagógica e 25% em cursos de engenharia, bacharelado, pós-graduação lato sensu e stricto sensu e cursos superiores de tecnologia.","Proporções igualitárias entre alguns dos seguintes modelos de educação: educação profissional técnica de nível médio, prioritariamente na forma de cursos integrados, cursos de licenciatura e/ou programas especiais de formação pedagógica, cursos de engenharia, bacharelado, pós-graduação lato sensu e stricto sensu e cursos superiores de tecnologia."],"correta":0,"explicacao":"Gabarito: <strong>50% em educação profissional técnica de nível médio, prioritariamente na forma de cursos integrados e 20% em cursos de licenciatura, bem como programas especiais de formação pedagógica.</strong>.","banca":"IF-SP","ano":2015,"temas_relacionados":["lei_11892_2008"]},{"id":586415,"enunciado":"De acordo com a Lei 11.892/2008, os Institutos Federais de Educação, Ciência e Tecnologia - Institutos Federais possuem natureza jurídica de ____, detentoras de ____ administrativa, patrimonial, financeira, didático-pedagógica e disciplinar. As lacunas ficam corretamente preenchidas respectivamente por:","opcoes":["fundações públicas / autonomia.","autarquia / autonomia.","fundações públicas / dependência.","autarquia / dependência.","empresas públicas / tutela."],"correta":1,"explicacao":"Gabarito: <strong>autarquia / autonomia.</strong>.","banca":"BIO-RIO","ano":2015,"temas_relacionados":["lei_11892_2008"]},{"id":590806,"enunciado":"De acordo com a Lei 11.892/08, são objetivos dos Institutos Federais, entre outros, os a seguir listados, EXCETO UM, que está ERRADO. Assinale-o.","opcoes":["Ministrar educação profissional técnica de nível médio, prioritariamente na forma de cursos integrados, para os concluintes do ensino fundamental e para o público da educação de jovens e adultos.","Ministrar cursos de formação inicial e continuada de trabalhadores, objetivando a capacitação, o aperfeiçoamento, a especialização e a atualização de profissionais, em todos os níveis de escolaridade, nas áreas da educação profissional e tecnológica.","Realizar pesquisas aplicadas, estimulando o desenvolvimento de soluções técnicas e tecnológicas, estendendo seus benefícios à comunidade.","Apoiar processos educativos que levem à emancipação do cidadão na perspectiva do desenvolvimento socioeconômico local e regional e desestimular os que levem à geração de trabalho e renda.","Desenvolver atividades de extensão de acordo com os princípios e finalidades da educação profissional e tecnológica, em articulação com o mundo do trabalho e os segmentos sociais, e com ênfase na produção, desenvolvimento e difusão de conhecimentos científicos e tecnológicos."],"correta":3,"explicacao":"Gabarito: <strong>Apoiar processos educativos que levem à emancipação do cidadão na perspectiva do desenvolvimento socioeconômico local e regional e desestimular os que levem à geração de trabalho e renda.</strong>.","banca":"BIO-RIO","ano":2015,"temas_relacionados":["lei_11892_2008"]},{"id":590854,"enunciado":"Os Institutos Federais de Educação, Ciência e Tecnologia são instituições de:","opcoes":["educação superior, apenas.","educação básica, apenas.","educação superior e profissional, apenas.","educação básica e profissional, apenas.","educação superior, básica e profissional."],"correta":4,"explicacao":"Gabarito: <strong>educação superior, básica e profissional.</strong>.","banca":"BIO-RIO","ano":2015,"temas_relacionados":["lei_11892_2008"]},{"id":590855,"enunciado":"Os Institutos Federais têm as seguintes finalidades, EXCETO UMA, que está ERRADA. Assinale-a.","opcoes":["ofertar educação profissional e tecnológica, em todos os seus níveis e modalidades, formando e qualificando cidadãos com vistas na atuação profissional nos diversos setores da economia, com ênfase no desenvolvimento socioeconômico local, regional e nacional.","desenvolver a educação profissional e tecnológica como processo educativo e investigativo de geração e adaptação de soluções técnicas e tecnológicas às demandas sociais e peculiaridades regionais.","ser centro de excelência na oferta do ensino de ciências em geral mas não de ciências aplicadas.","desenvolver programas de extensão e de divulgação científica e tecnológica.","realizar e estimular a pesquisa aplicada, a produção cultural, o empreendedorismo, o cooperativismo e o desenvolvimento científico e tecnológico."],"correta":2,"explicacao":"Gabarito: <strong>ser centro de excelência na oferta do ensino de ciências em geral mas não de ciências aplicadas.</strong>.","banca":"BIO-RIO","ano":2015,"temas_relacionados":["lei_11892_2008"]},{"id":590907,"enunciado":"Avalie se, de acordo com a Lei 11.892/08, os Institutos Federais têm, entre outras, as seguintes finalidades e características: I. Ofertar educação profissional e tecnológica, em todos os seus níveis e modalidades, formando e qualificando cidadãos com vistas na atuação profissional nos diversos setores da economia, com ênfase no desenvolvimento socioeconômico local, regional e nacional. II. Desenvolver a educação profissional e tecnológica como processo educativo e investigativo de geração e adaptação de soluções técnicas e tecnológicas às demandas sociais e peculiaridades regionais. III. Promover a produção, o desenvolvimento e a transferência de tecnologias sociais, notadamente as voltadas à preservação do meio ambiente. Estão corretos:","opcoes":["I, apenas.","III, apenas.","II e III, apenas.","I e II, apenas.","I, II e III."],"correta":4,"explicacao":"Gabarito: <strong>I, II e III.</strong>.","banca":"BIO-RIO","ano":2015,"temas_relacionados":["lei_11892_2008"]},{"id":599633,"enunciado":"De acordo com a Lei nº 11.892/2008, os Institutos Federais de Educação, Ciência e Tecnologia são instituições que","opcoes":["priorizam a educação básica, com ênfase no ensino profissional, na modalidade a distância, visando à produção, ao desenvolvimento e à transferência de tecnologias sociais do setor público para o setor privado.","promovem programas de extensão e de divulgação científica e tecnológica, mas não têm autonomia para ministrar cursos de pós-graduação stricto sensu","realizam cursos de educação técnica e tecnológica criados pelo Conselho Nacional de Educação (CNE) em conformidade com as demandas governamentais.","ofertam educação profissional e tecnológica, em todos os seus níveis e modalidades, formando e qualificando cidadãos visando à atuação profissional nos diversos setores da economia, com ênfase no desenvolvimento socioeconômico local, regional e nacional."],"correta":3,"explicacao":"Gabarito: <strong>ofertam educação profissional e tecnológica, em todos os seus níveis e modalidades, formando e qualificando cidadãos visando à atuação profissional nos diversos setores da economia, com ênfase no desenvolvimento socioeconômico local, regional e nacional.</strong>.","banca":"UFMT","ano":2015,"temas_relacionados":["lei_11892_2008"]},{"id":623542,"enunciado":"Constituem a Rede Federal de Educação Profissional, Científica e Tecnológica, vinculada ao Ministério da Educação, as seguintes instituições, EXCETO:","opcoes":["Os Institutos Federais de Educação, Ciência e Tecnologia - Institutos Federais.","As Universidades Federais em geral.","A Universidade Tecnológica Federal do Paraná – UTFPR.","O Colégio Pedro II."],"correta":1,"explicacao":"Gabarito: <strong>As Universidades Federais em geral.</strong>.","banca":"IF-SE","ano":2016,"temas_relacionados":["lei_11892_2008"]},{"id":625307,"enunciado":"De acordo com a Lei Federal nº 11.892, de 29 de dezembro de 2008 e alterações, a administração dos Institutos Federais possui como órgãos superiores","opcoes":["a Secretaria Executiva e o Conselho de Dirigentes.","o Colégio Superior e a Secretaria Executiva.","a Secretaria Superior Estratégica e o Conselho de Dirigentes.","o Colégio de Dirigentes e o Conselho Superior.","a Secretaria Educacional Superior e o Colégio de Dirigentes."],"correta":3,"explicacao":"Gabarito: <strong>o Colégio de Dirigentes e o Conselho Superior.</strong>.","banca":"FUNRIO","ano":2016,"temas_relacionados":["lei_11892_2008"]},{"id":625308,"enunciado":"Os Institutos Federais terão como órgão executivo a reitoria, que é composta por","opcoes":["um Reitor e cinco Pró-Reitores.","um Reitor e três Pró-Reitores.","dois Reitores e dois Pró-Reitores.","um Reitor, apenas.","um Pró-Reitor e um Conselho Deliberativo."],"correta":0,"explicacao":"Gabarito: <strong>um Reitor e cinco Pró-Reitores.</strong>.","banca":"FUNRIO","ano":2016,"temas_relacionados":["lei_11892_2008"]},{"id":625371,"enunciado":"A Lei Federal nº 11.892, de 29 de dezembro de 2008 e alterações, que criou os Institutos Federais de Educação, Ciência e Tecnologia, estabelece que seus Reitores serão nomeados pelo","opcoes":["Pró-Reitor","Ministro da Educação.","Presidente do Conselho Nacional de Educação.","Presidente da República.","Diretor do Fundo Nacional de Educação."],"correta":3,"explicacao":"Gabarito: <strong>Presidente da República.</strong>.","banca":"FUNRIO","ano":2016,"temas_relacionados":["lei_11892_2008"]},{"id":627174,"enunciado":"A Lei nº 11.892, de 29 de dezembro de 2008, instituiu a Rede Federal de Educação Profissional, Científica e Tecnológica e criou os Institutos Federais de Educação, Ciência e Tecnologia. Com base nessa Lei, assinale a alternativa incorreta.","opcoes":["Os Institutos Federais têm como órgãos superiores o Colégio de Dirigentes, de caráter consultivo, e o Conselho Superior, de caráter consultivo e deliberativo.","Os Institutos Federais possuem autonomia para criar e extinguir cursos, nos limites de sua área de atuação territorial, bem como para registrar diplomas dos cursos por eles oferecidos, mediante autorização do seu Conselho Superior, aplicando-se, no caso da oferta de cursos a distância, a legislação específica.","Os Reitores são nomeados pelo Presidente da República, para mandato de 4 (quatro) anos, não sendo permitida recondução, após processo de consulta à comunidade escolar do respectivo Instituto Federal.","Os Institutos Federais, no âmbito de sua atuação, exercem o papel de instituições acreditadoras e certificadoras de competências profissionais.","O Conselho Superior será composto por representantes dos docentes, dos estudantes, dos servidores técnico-administrativos, dos egressos da instituição, da sociedade civil, do Ministério da Educação e do Colégio de Dirigentes do Instituto Federal, assegurando-se a representação paritária dos segmentos que compõem a comunidade acadêmica."],"correta":2,"explicacao":"Gabarito: <strong>Os Reitores são nomeados pelo Presidente da República, para mandato de 4 (quatro) anos, não sendo permitida recondução, após processo de consulta à comunidade escolar do respectivo Instituto Federal.</strong>.","banca":"IF-TO","ano":2015,"temas_relacionados":["lei_11892_2008"]},{"id":630503,"enunciado":"Considere as afirmativas I, II e III a respeito dos objetivos dos Institutos Federais. Assinale a alternativa que contém a(s) afirmativa(s) CORRETA(S): I. Realizar pesquisas aplicadas, estimulando o desenvolvimento de soluções técnicas e tecnológicas, estendendo seus benefícios à comunidade. II. Estimular e apoiar processos educativos que levem à geração de trabalho e renda e à emancipação do cidadão na perspectiva do desenvolvimento socioeconômico local e regional. III. Ministrar educação profissional técnica de nível médio, prioritariamente na forma de cursos integrados, para os concluintes do ensino fundamental e para o público da educação de jovens e adultos.","opcoes":["Apenas I.","Apenas I e II.","Apenas I e III.","Apenas II e III.","I, II e III."],"correta":4,"explicacao":"Gabarito: <strong>I, II e III.</strong>.","banca":"IF-RS","ano":2016,"temas_relacionados":["lei_11892_2008"]},{"id":634048,"enunciado":"A Lei n. 11.892, de 29 de dezembro de 2008, institui a Rede Federal de Educação Profissional, Científica e Tecnológica, vinculada ao Ministério da Educação. Segundo essa Lei, fazem parte da rede:","opcoes":["somente Institutos Federais de Educação, Ciência e Tecnologia.","somente os Institutos Federais de Educação, Ciência e Tecnologia e a Universidade Tecnoló­gica do Paraná.","Institutos Federais de Educação, Ciência e Tecnologia; Escolas Técnicas Vinculadas às Universidades Federais e as Escolas Municipais.","Institutos Federais de Educação, Ciência e Tecnologia; Universidade Tecnológica do Paraná e Escolas Técnicas Vinculadas às Universidades Privadas.","Institutos Federais de Educação, Ciência e Tecnologia, Universidade Tecnológica do Paraná; Escolas Técnicas Vinculadas às Universidades Federais e o Colégio Pedro II."],"correta":4,"explicacao":"Gabarito: <strong>Institutos Federais de Educação, Ciência e Tecnologia, Universidade Tecnológica do Paraná; Escolas Técnicas Vinculadas às Universidades Federais e o Colégio Pedro II.</strong>.","banca":"UFSM","ano":2015,"temas_relacionados":["lei_11892_2008"]},{"id":660898,"enunciado":"Segundo a Lei Federal n° 11.892, de 29 de dezembro de 2008 e alterações, a administração dos Institutos Federais terá como órgãos superiores o Colégio de Dirigentes e o Conselho Superior, sendo correto afirmar que","opcoes":["o Colégio de Dirigentes possui caráter executivo e deliberativo.","o Conselho Superior será composto pelo Reitor, pelos Pró-Reitores e pelo Diretor-Geral de cada um dos campi que integram o Instituto Federal.","representantes dos docentes, dos estudantes e dos servidores técnicos-administrativos integram o Colégio de Dirigentes.","as presidências do Colégio de Dirigentes e do Conselho Superior serão exercidas pelo Reitor do Instituto Federal.","as competências e as normas de funcionamento do Colégio de Dirigentes são estabelecidas por medida provisória do Ministério da Educação."],"correta":3,"explicacao":"Gabarito: <strong>as presidências do Colégio de Dirigentes e do Conselho Superior serão exercidas pelo Reitor do Instituto Federal.</strong>.","banca":"FUNRIO","ano":2016,"temas_relacionados":["lei_11892_2008"]},{"id":662114,"enunciado":"O serviço de educação oferecido pelas Universidades e Institutos Federais de Educação, Ciência e Tecnologia é um exemplo de serviço;","opcoes":["Centralizado e oferecido pela administração pública direta","Descentralizado e oferecido pela administração pública indireta","Centralizado e oferecido por autarquias e fundações do governo","Descentralizado e oferecido por qualquer organização do governo","Descentralizado e oferecido pela administração pública direta"],"correta":3,"explicacao":"Gabarito: <strong>Descentralizado e oferecido por qualquer organização do governo</strong>.","banca":"UFMA","ano":2016,"temas_relacionados":["lei_11892_2008"]},{"id":663018,"enunciado":"De acordo com a Lei Federal nº 11.892/2008, que cria os Institutos Federais, é INCORRETO afirmar que","opcoes":["o Conselho Superior, de caráter consultivo e deliberativo, será composto exclusivamente por representantes dos servidores técnico-administrativos e do Colégio de Dirigentes do Instituto Federal.","realizar pesquisas aplicadas, estimulando o desenvolvimento de soluções técnicas e tecnológicas, estendendo seus benefícios à comunidade é um dos objetivos dos Institutos Federais.","os Institutos Federais têm como uma de suas finalidades e características promover a produção, o desenvolvimento e a transferência de tecnologias sociais, notadamente as voltadas à preservação do meio ambiente.","cada Instituto Federal é organizado em estrutura multicampi, com proposta orçamentária anual identificada para cada campus e a reitoria, exceto no que diz respeito a pessoal, encargos sociais e benefícios aos servidores.","os Institutos Federais têm autonomia para criar e extinguir cursos, nos limites de sua área de atuação territorial, bem como para registrar diplomas dos cursos por eles oferecidos, mediante autorização do seu Conselho Superior, aplicando-se, no caso da oferta de cursos a distância, a legislação específica."],"correta":0,"explicacao":"Gabarito: <strong>o Conselho Superior, de caráter consultivo e deliberativo, será composto exclusivamente por representantes dos servidores técnico-administrativos e do Colégio de Dirigentes do Instituto Federal.</strong>.","banca":"FCM","ano":2016,"temas_relacionados":["lei_11892_2008"]},{"id":663270,"enunciado":"Tendo em vista a estruturação prevista na Lei 11.892/2008, a gestão dos Institutos Federais apresenta como órgãos superiores o Colégio de Dirigentes e o Conselho superior e define que:","opcoes":["As presidências do Colégio de Dirigentes e do Conselho Superior serão exercidas pelo Reitor do Instituto Federal.","O Colégio de Dirigentes, de caráter consultivo e deliberativo, será composto pelo Reitor, pelos Pró-Reitores e pelo Diretor-Geral de cada um dos campi que integram o Instituto Federal.","A presidência do Conselho Superior será exercida pelo Reitor do Instituto Federal e a do Colégio de Dirigentes pelo Diretor Geral de Campus eleito pelos pares com mandado de 02 anos.","O Conselho Superior, de caráter consultivo, será composto por representantes dos docentes, dos estudantes, dos servidores técnico-administrativos, dos egressos da instituição, da sociedade civil, do Ministério da Educação e do Colégio de Dirigentes do Instituto Federal, assegurando-se a representação paritária dos segmentos que compõem a comunidade acadêmica."],"correta":0,"explicacao":"Gabarito: <strong>As presidências do Colégio de Dirigentes e do Conselho Superior serão exercidas pelo Reitor do Instituto Federal.</strong>.","banca":"IF SUL - MG","ano":2016,"temas_relacionados":["lei_11892_2008"]},{"id":665905,"enunciado":"A administração dos Institutos Federais terá como órgãos superiores:","opcoes":["A Reitoria e as Pró-Reitorias.","O Conselho Superior e a Reitoria.","O Colégio de Dirigentes e a Reitoria.","O Colégio de Dirigentes e o Conselho Superior."],"correta":3,"explicacao":"Gabarito: <strong>O Colégio de Dirigentes e o Conselho Superior.</strong>.","banca":"IF SUL - MG","ano":2016,"temas_relacionados":["lei_11892_2008"]},{"id":671236,"enunciado":"Tendo em vista as políticas públicas voltadas para a educação implementadas pelo governo Lula na década passada, verificou-se o fortalecimento e a ampliação de toda a rede de ensino público no país. As Universidades Federais receberam incentivos financeiros que viabilizaram um crescimento extraordinário e uma ampliação considerável dos números de vagas para os cursos superiores. No tocante ao ensino tecnológico, o grande avanço se deu com a implementação dos Institutos Federais por meio da Lei nº 11.892, de 29 de dezembro de 2008. Posto isso, infere-se que:","opcoes":["Os Institutos Federais apresentam como finalidade ofertar educação profissional e tecnológica, unicamente para os níveis básicos e fundamentais, nas modalidades presenciais e à distância, formando e qualificando cidadãos com vistas na atuação técnico-profissional nos diversos setores da economia, com ênfase no desenvolvimento socioeconômico local, regional e nacional.","A Rede Federal de Educação Profissional, Científica e Tecnológica, vinculada ao Ministério da Educação, é constituída, exclusivamente, pelos Institutos Federais de Educação, Ciência e Tecnologia - Institutos Federais, pelos Centros Federais de Educação Tecnológica Celso Suckow da Fonseca - CEFET-RJ e de Minas Gerais - CEFET-MG e pelo Colégio Pedro II.","Os Institutos Federais são instituições de educação superior, básica e profissional, pluricurriculares e multicampi, especializados na oferta de educação profissional e tecnológica nas diferentes modalidades de ensino, com base na conjugação de conhecimentos técnicos e tecnológicos com as suas práticas pedagógicas, nos termos desta Lei.","Os Institutos Federais apresentam como objetivo ministrar educação profissional técnica de nível médio, apenas na forma de cursos integrados, para os concluintes do ensino fundamental e para o público da Educação de Jovens e Adultos."],"correta":2,"explicacao":"Gabarito: <strong>Os Institutos Federais são instituições de educação superior, básica e profissional, pluricurriculares e multicampi, especializados na oferta de educação profissional e tecnológica nas diferentes modalidades de ensino, com base na conjugação de conhecimentos técnicos e tecnológicos com as suas práticas pedagógicas, nos termos desta Lei.</strong>.","banca":"IF SUL - MG","ano":2016,"temas_relacionados":["lei_11892_2008"]},{"id":674628,"enunciado":"Segundo a lei 11892/2008, a administração dos Institutos Federais terá como órgãos superiores","opcoes":["o Colégio de Dirigentes e o Conselho Superior.","o Colegiado Superior e o Conselho Universitário.","a Comissão de Dirigentes e o Conselho de Classe.","o Conselho de Administração Fiscal e o Conselho Superior.","a Comissão de Enquadramento e a Comissão de Acompanhamento."],"correta":0,"explicacao":"Gabarito: <strong>o Colégio de Dirigentes e o Conselho Superior.</strong>.","banca":"Makiyama","ano":2013,"temas_relacionados":["lei_11892_2008"]},{"id":680302,"enunciado":"Nos termos da Lei nº 11.892/08, são objetivos dos Institutos Federais, EXCETO:","opcoes":["ministrar educação profissional técnica de nível médio, prioritariamente na forma de cursos integrados, para os concluintes do ensino fundamental e para o público da educação de jovens e adultos;","desenvolver a educação profissional e tecnológica como processo educativo e investigativo de geração e adaptação de soluções técnicas e tecnológicas às demandas sociais e peculiaridades regionais;","ministrar cursos de formação inicial e continuada de trabalhadores, objetivando a capacitação, o aperfeiçoamento, a especialização e a atualização de profissionais, em todos os níveis de escolaridade, nas áreas da educação profissional e tecnológica;","realizar pesquisas aplicadas, estimulando o desenvolvimento de soluções técnicas e tecnológicas, estendendo seus benefícios à comunidade;","desenvolver atividades de extensão de acordo com os princípios e finalidades da educação profissional e tecnológica, em articulação com o mundo do trabalho e os segmentos sociais, e com ênfase na produção, desenvolvimento e difusão de conhecimentos científicos e tecnológicos;"],"correta":1,"explicacao":"Gabarito: <strong>desenvolver a educação profissional e tecnológica como processo educativo e investigativo de geração e adaptação de soluções técnicas e tecnológicas às demandas sociais e peculiaridades regionais;</strong>.","banca":"IF-MG","ano":2013,"temas_relacionados":["lei_11892_2008"]},{"id":699798,"enunciado":"Sobre dispositivos contidos na Lei Federal Nº 11.892/2008, que institui a Rede Federal de Educação Profissional, Científica e Tecnológica e cria os Institutos Federais de Educação, Ciência e Tecnologia, assinale a alternativa INCORRETA.","opcoes":["A administração dos Institutos Federais terá como órgãos superiores o Colégio de Dirigentes e o Conselho Superior, cujas presidências serão exercidas pelo Reitor do Instituto Federal.","Cada Instituto Federal é organizado em estrutura multicampi, com proposta orçamentária anual identificada para cada campus e para a reitoria, exceto no que diz respeito a pessoal, encargos sociais e benefícios aos servidores.","Os Institutos Federais terão autonomia para criar e extinguir cursos, nos limites de sua área de atuação territorial, bem como para registrar diplomas dos cursos por eles oferecidos, mediante autorização do seu Conselho Superior, aplicando-se, no caso da oferta de cursos à distância, a legislação específica.","São objetivos dos Institutos Federais desenvolver programas de extensão e de divulgação científica e tecnológica e promover a produção, o desenvolvimento e a transferência de tecnologias sociais, notadamente as voltadas à preservação do meio ambiente."],"correta":3,"explicacao":"Gabarito: <strong>São objetivos dos Institutos Federais desenvolver programas de extensão e de divulgação científica e tecnológica e promover a produção, o desenvolvimento e a transferência de tecnologias sociais, notadamente as voltadas à preservação do meio ambiente.</strong>.","banca":"FUNDEP (Gestão de Concursos)","ano":2016,"temas_relacionados":["lei_11892_2008"]},{"id":702608,"enunciado":"Poderão candidatar-se ao cargo de Diretor-Geral do campus dos Institutos Federais de Educação, Ciência e Tecnologia os servidores ocupantes de cargo efetivo da carreira docente ou de cargo efetivo de nível superior da carreira dos técnico-administrativos do Plano de Carreira dos Cargos Técnico-Administrativos em Educação, desde que:","opcoes":["possuam o mínimo de dois anos de efetivo exercício em instituição federal de educação profissional e tecnológica e que tenham concluído, com aproveitamento, curso de formação para o exercício de cargo ou função de gestão em instituições da administração pública.","possuam o mínimo de três anos de efetivo exercício em instituição federal de educação profissional e tecnológica e que possuam o mínimo de um ano de exercício em cargo ou função de gestão na instituição.","possuam o mínimo de quatro anos de efetivo exercício em instituição federal de educação profissional e tecnológica e que tenham concluído, com aproveitamento, curso de formação para o exercício de cargo ou função de gestão em instituições da administração pública.","possuam o mínimo de cinco anos de efetivo exercício em instituição federal de educação profissional e tecnológica e que preencham os requisitos exigidos para a candidatura ao cargo de Reitor do Instituto Federal."],"correta":3,"explicacao":"Gabarito: <strong>possuam o mínimo de cinco anos de efetivo exercício em instituição federal de educação profissional e tecnológica e que preencham os requisitos exigidos para a candidatura ao cargo de Reitor do Instituto Federal.</strong>.","banca":"FUNDEP (Gestão de Concursos)","ano":2016,"temas_relacionados":["lei_11892_2008"]},{"id":712263,"enunciado":"De acordo com a Lei Federal nº 11.892/2008, os Institutos Federais I- são instituições de educação superior, básica e profissional, pluricurriculares e multicampi, especializados na oferta de educação profissional e tecnológica, nas diferentes modalidades de ensino, com base na conjugação de conhecimentos técnicos e tecnológicos com as suas práticas pedagógicas, nos termos desta Lei. II- possuem natureza jurídica de empresa pública. III- ministram educação em nível fundamental, médio e superior. IV- têm como uma de suas finalidades e características a realização e o estímulo à pesquisa aplicada, à produção cultural, ao empreendedorismo, ao cooperativismo e ao desenvolvimento científico e tecnológico. Estão corretas as afirmativas","opcoes":["I e III.","I e IV.","II e III.","I, II e IV.","I, II, III e IV."],"correta":1,"explicacao":"Gabarito: <strong>I e IV.</strong>.","banca":"FCM","ano":2016,"temas_relacionados":["lei_11892_2008"]},{"id":713003,"enunciado":"A Lei 11.892, publicada em 29/12/2008 cria, no âmbito do Ministério da Educação, os Institutos Federais de Educação, Ciência e Tecnologia e esses têm como foco, exceto:","opcoes":["Os institutos federais não poderão atuar em todos os níveis e modalidades da educação. Ele deverá ter seu foco no compromisso com o desenvolvimento integral do cidadão trabalhador.","A promoção do desenvolvimento sustentável com vistas à inclusão social.","A busca de soluções técnicas e geração de novas tecnologias.","Responder, de forma ágil e eficaz, as demandas crescentes por formação profissional, por difusão de conhecimentos científicos e por suporte aos arranjos produtivos locais.","A promoção da justiça social e da equidade."],"correta":0,"explicacao":"Gabarito: <strong>Os institutos federais não poderão atuar em todos os níveis e modalidades da educação. Ele deverá ter seu foco no compromisso com o desenvolvimento integral do cidadão trabalhador.</strong>.","banca":"IF-TO","ano":2015,"temas_relacionados":["lei_11892_2008"]},{"id":718298,"enunciado":"Quanto à Rede Federal de Educação Profissional, Científica e Tecnológica pode-se afirmar que: I. Os Institutos Federais de Educação, Ciência e Tecnologia constituem, exclusivamente, no âmbito do sistema federal de ensino, vinculado ao Ministério da Educação, a Rede Federal de Educação Profissional, Científica e Tecnológica. II. Os Institutos Federais de Educação, Ciência e Tecnologia são instituições de educação superior, básica e profissional, pluricurriculares e multicampi, especializados na oferta de educação profissional e tecnológica nas diferentes modalidades de ensino, com base na conjugação de conhecimentos técnicos e tecnológicos com as suas práticas pedagógicas. III. Os Institutos Federais de Educação, Ciência e Tecnologia possuem natureza jurídica de fundações públicas, detentoras de autonomia administrativa, patrimonial, financeira, didático-pedagógica e disciplinar. IV. Os Institutos Federais de Educação, Ciência e Tecnologia, no âmbito de sua atuação, exercerão o papel de instituições acreditadoras e certificadoras de competências profissionais. V. Os Institutos Federais de Educação, Ciência e Tecnologia para efeito da incidência das disposições que regem a regulação, avaliação e supervisão das instituições e dos cursos de educação superior, são equiparados às universidades federais. Assinale a alternativa em que todas as afirmativas estão CORRETAS:","opcoes":["Apenas I, II e IV.","Apenas I, II, IV e V.","Apenas I, III, IV e V.","Apenas II, IV e V.","I, II, III, IV e V."],"correta":3,"explicacao":"Gabarito: <strong>Apenas II, IV e V.</strong>.","banca":"IF-RS","ano":2016,"temas_relacionados":["lei_11892_2008"]},{"id":725283,"enunciado":"Acerca da Lei 11.892, de 29 de dezembro de 2008, que institui a Rede Federal de Educação Profissional, Científica e Tecnológica, cria os Institutos Federais de Educação, Ciência e Tecnologia, e dá outras providências, do ponto de vista da estrutura organizacional, os Institutos Federais I- dispõem da carta de serviços, que versa sobre a estruturação, as competências e as normas de funcionamento do Colégio de Dirigentes e do Conselho Superior. II- poderão ter como Reitor os docentes pertencentes ao Quadro de Pessoal Ativo Permanente de qualquer dos campi que o integram, desde que atendam aos requisitos pré-estabelecidos. III- são organizados em estrutura unicampi, com proposta orçamentária anual identificada para cada campus e a reitoria, exceto no que diz respeito a pessoal, encargos sociais e benefícios aos servidores. IV-têm o Conselho Superior composto por representantes dos docentes, dos estudantes, dos servidores técnico-administrativos, dos egressos da instituição, da sociedade civil, do MEC e do Colégio de Dirigentes. Estão corretas as afirmativas","opcoes":["I e II.","I e III.","II e III.","II e IV.","III e IV."],"correta":3,"explicacao":"Gabarito: <strong>II e IV.</strong>.","banca":"FCM","ano":2016,"temas_relacionados":["lei_11892_2008"]},{"id":728622,"enunciado":"Os campi que integram cada Instituto Federal de Educação, Ciência e Tecnologia serão dirigidos por Diretores-Gerais, nomeados pelo Reitor para mandato de","opcoes":["dois anos, permitida uma recondução.","quatro anos, proibida a recondução.","três anos, permitida uma recondução.","cinco anos, proibida a recondução.","quatro anos, permitida uma recondução."],"correta":4,"explicacao":"Gabarito: <strong>quatro anos, permitida uma recondução.</strong>.","banca":"FUNRIO","ano":2016,"temas_relacionados":["lei_11892_2008"]},{"id":734573,"enunciado":"A Lei nº 11.892, de 29 de dezembro de 2008, institui a Rede Federal de Educação Profissional, Científica e Tecnológica, cria os Institutos Federais de Educação, Ciência e Tecnologia. De acordo com o que preconiza essa lei, responda à próxima questão. Analise as alternativas e assinale a incorreta.","opcoes":["O mandato de Reitor extingue-se pelo decurso do prazo ou, antes desse prazo, pela aposentadoria, voluntária ou compulsória, pela renúncia e pela destituição ou vacância do cargo.","Os Pró-Reitores são nomeados pelo Ministro da Educação do Instituto Federal, nos termos da legislação aplicável à nomeação de cargos de direção.","A criação de novos campi fica condicionada à expedição de autorização específica do Ministério da Educação.","A mudança de lotação de servidores entre diferentes campi de um mesmo Instituto Federal deverá observar o instituto da remoção, nos termos do art. 36 da Lei nº 8.112, de 11 de dezembro de 1990."],"correta":1,"explicacao":"Gabarito: <strong>Os Pró-Reitores são nomeados pelo Ministro da Educação do Instituto Federal, nos termos da legislação aplicável à nomeação de cargos de direção.</strong>.","banca":"MSConcursos","ano":2014,"temas_relacionados":["lei_11892_2008"]},{"id":734574,"enunciado":"A Lei nº 11.892, de 29 de dezembro de 2008, institui a Rede Federal de Educação Profissional, Científica e Tecnológica, cria os Institutos Federais de Educação, Ciência e Tecnologia. De acordo com o que preconiza essa lei, responda à próxima questão. Analise as alternativas e assinale a correta.","opcoes":["Os Reitores serão nomeados pelo Presidente da República, para mandato de quatro anos, permitida uma recondução, após processo de consulta à comunidade escolar do respectivo Instituto Federal, atribuindo-se o peso de 1/3 (um terço) para a manifestação do corpo docente, de 1/3 (um terço) para a manifestação dos servidores técnico-administrativos e de 1/3 (um terço) para a manifestação do corpo discente.","Os Reitores serão nomeados pelo Presidente da República, para mandato de dois anos, permitida uma recondução, após processo de consulta à comunidade escolar do respectivo Instituto Federal, atribuindo-se o peso de 1/3 (um terço) para a manifestação do corpo docente, de 1/3 (um terço) para a manifestação dos servidores técnico-administrativos e de 1/3 (um terço) para a manifestação do corpo discente.","Os Reitores serão nomeados pelo Presidente da República, para mandato de quatro anos, permitida uma recondução, após processo de consulta à comunidade escolar do respectivo Instituto Federal, atribuindo-se o peso de 40% para a manifestação do corpo docente, de 35% para a manifestação dos servidores técnico-administrativos e de 25% para a manifestação do corpo discente.","Os Reitores serão nomeados pelo Presidente da República, para mandato de dois anos, permitida uma recondução, após processo de consulta à comunidade escolar do respectivo Instituto Federal, atribuindo-se o peso de 40% para a manifestação do corpo docente, de 35% para a manifestação dos servidores técnico-administrativos e de 25% para a manifestação do corpo discente."],"correta":0,"explicacao":"Gabarito: <strong>Os Reitores serão nomeados pelo Presidente da República, para mandato de quatro anos, permitida uma recondução, após processo de consulta à comunidade escolar do respectivo Instituto Federal, atribuindo-se o peso de 1/3 (um terço) para a manifestação do corpo docente, de 1/3 (um terço) para a manifestação dos servidores técnico-administrativos e de 1/3 (um terço) para a manifestação do corpo discente.</strong>.","banca":"MSConcursos","ano":2014,"temas_relacionados":["lei_11892_2008"]},{"id":734790,"enunciado":"O Instituto Federal de Educação, Ciência e Tecnologia do Tocantins foi criado pela Lei n.º 11.892, de 29 de dezembro de 2008. Essa norma estabeleceu os objetivos, finalidades e características dos Institutos Federais de Educação. Todas as alternativas expressam os objetivos dos Institutos Federais, exceto:","opcoes":["Constituir-se em centro de excelência na oferta do ensino de ciências, em geral, e de ciências aplicadas, em particular, desde que não estimule o desenvolvimento de espírito crítico, voltado à investigação empírica.","Estimular e apoiar processos educativos que levem à geração de trabalho e renda e à emancipação do cidadão na perspectiva do desenvolvimento socioeconômico local e regional","Realizar pesquisas aplicadas, estimulando o desenvolvimento de soluções técnicas e tecnológicas, estendendo seus benefícios à comunidade.","Ministrar educação profissional técnica de nível médio, prioritariamente na forma de cursos integrados, para os concluintes do ensino fundamental e para o público da educação de jovens e adultos.","Ministrar em nível de educação superior cursos de pós-graduação lato sensu de aperfeiçoamento e especialização, visando à formação de especialistas nas diferentes áreas do conhecimento."],"correta":0,"explicacao":"Gabarito: <strong>Constituir-se em centro de excelência na oferta do ensino de ciências, em geral, e de ciências aplicadas, em particular, desde que não estimule o desenvolvimento de espírito crítico, voltado à investigação empírica.</strong>.","banca":"IF-TO","ano":2016,"temas_relacionados":["lei_11892_2008"]},{"id":738831,"enunciado":"De acordo com a Lei N° 11.892/2008, que institui a Rede Federal de Educação Profissional, Científica e Tecnológica e cria os Institutos Federais de Educação, Ciência e Tecnologia, assinale a sequência de palavras que completam corretamente as lacunas anteriores.","opcoes":["presidente da República / 4 (quatro) anos / 1/3 (um terço) / 1/3 (um terço) / 1/3 (um terço).","ministro da Educação / 3 (três) anos / 1/3 (um terço) / de 1/3 (um terço) / de 1/3 (um terço).","presidente da República / 3 (três) anos / 2/4 (dois quartos) / 1/4 (um quarto) / 1/4 (um quarto).","ministro da Educação / 4 (quatro) anos / 2/4 (dois quartos) / 1/4 (um quarto) / 1/4 (um quarto)."],"correta":0,"explicacao":"Gabarito: <strong>presidente da República / 4 (quatro) anos / 1/3 (um terço) / 1/3 (um terço) / 1/3 (um terço).</strong>.","banca":"FUNDEP (Gestão de Concursos)","ano":2016,"temas_relacionados":["lei_11892_2008"]},{"id":740485,"enunciado":"A lei que instituiu a Rede Federal de Educação Profissional, Científica e Tecnológica (Lei n° 11.892/08 e suas alterações) dispõe que os Institutos Federais de Educação, Ciência e Tecnologia - Institutos Federais","opcoes":["possuem natureza jurídica de empresa pública e são detentores de autonomia administrativa, patrimonial, financeira, didático-pedagógica e disciplinar.","possuem natureza jurídica de fundação social e são detentores de autonomia didático-pedagógica e disciplinar, mas com dependência administrativa, patrimonial, financeira vinculadas ao Estado.","possuem natureza jurídica de autarquia e são detentores de autonomia administrativa, patrimonial, financeira, didático-pedagógica e disciplinar.","possuem natureza jurídica de fundação privada e são detentores de autonomia didático-pedagógica e disciplinar, mas com dependência administrativa, patrimonial, financeira vinculadas ao Estado.","possuem natureza jurídica de empresa pública e são detentores de autonomia didático-pedagógica e disciplinar, mas com dependência administrativa, patrimonial, financeira vinculadas ao Estado."],"correta":2,"explicacao":"Gabarito: <strong>possuem natureza jurídica de autarquia e são detentores de autonomia administrativa, patrimonial, financeira, didático-pedagógica e disciplinar.</strong>.","banca":"INSTITUTO AOCP","ano":2016,"temas_relacionados":["lei_11892_2008"]},{"id":740486,"enunciado":"De acordo com o que estabelece a lei que instituiu a Rede Federal de Educação Profissional, Científica e Tecnológica (Lei n° 11.892/08 e suas alterações), acerca da Estrutura Organizacional dos Institutos Federais, assinale a alternativa correta.","opcoes":["Cada Instituto Federal é organizado em estrutura multicampi, com proposta orçamentária anual identificada para cada campus e a reitoria, exceto no que diz respeito a pessoal, encargos sociais e benefícios aos servidores.","A administração dos Institutos Federais terá como órgãos subordinados o Colégio de Dirigentes e o Conselho Superior. As presidências do Colégio de Dirigentes e do Conselho Superior serão exercidas pelos Pró- Reitores do Instituto Federal.","O Conselho Superior, de caráter consultivo, será composto pelo Reitor, pelos Pró-Reitores e pelo Diretor-Geral de cada um dos campi que integram o Instituto Federal.","O Colégio de Dirigentes, de caráter consultivo e deliberativo, será composto por representantes dos docentes, dos estudantes, dos servidores técnico-administrativos, dos egressos da instituição, da sociedade civil, do Ministério da Educação.","Os Institutos Federais terão como órgão subordinado a reitoria, composta por 2 Reitores e 5 Pró-Reitores."],"correta":0,"explicacao":"Gabarito: <strong>Cada Instituto Federal é organizado em estrutura multicampi, com proposta orçamentária anual identificada para cada campus e a reitoria, exceto no que diz respeito a pessoal, encargos sociais e benefícios aos servidores.</strong>.","banca":"INSTITUTO AOCP","ano":2016,"temas_relacionados":["lei_11892_2008"]},{"id":740487,"enunciado":"De acordo com o que estabelece a lei que instituiu a Rede Federal de Educação Profissional, Científica e Tecnológica (Lei n° 11.892/08 e suas alterações), acerca da Estrutura Organizacional dos Institutos Federais, assinale a alternativa correta.","opcoes":["Os Reitores serão nomeados pelo Ministro da Educação, para mandato de 2 anos, permitida uma recondução, após processo de consulta à comunidade escolar do respectivo Instituto Federal, atribuindo-se o peso de 1/3 para a manifestação do corpo docente, de 1/3 para a manifestação dos servidores técnico-administrativos e de 1/3 para a manifestação do corpo discente.","Os Reitores serão nomeados pelo Presidente da República, para mandato de 2 anos, permitida uma recondução, após processo de consulta à comunidade escolar do respectivo Instituto Federal, atribuindo-se o peso de 1/3 para a manifestação do corpo docente e de 2/3 para a manifestação dos servidores técnico-administrativos.","Os Reitores serão nomeados pelo Presidente da República, para mandato de 1 ano, permitida uma recondução, após processo de consulta à comunidade escolar do respectivo Instituto Federal, atribuindo-se o peso de 2/3 para a manifestação do corpo docente e de 1/3 para a manifestação do corpo discente.","Os Reitores serão nomeados pelo Ministro da Educação, para mandato de 4 anos, permitida uma recondução, após processo de consulta à comunidade escolar do respectivo Instituto Federal, atribuindo-se o peso de 2/3 para a manifestação do corpo docente e de 1/3 para a manifestação do corpo discente.","Os Reitores serão nomeados pelo Presidente da República, para mandato de 4 anos, permitida uma recondução, após processo de consulta à comunidade escolar do respectivo Instituto Federal, atribuindo-se o peso de 1/3 para a manifestação do corpo docente, de 1/3 para a manifestação dos servidores técnico-administrativos e de 1/3 para a manifestação do corpo discente."],"correta":4,"explicacao":"Gabarito: <strong>Os Reitores serão nomeados pelo Presidente da República, para mandato de 4 anos, permitida uma recondução, após processo de consulta à comunidade escolar do respectivo Instituto Federal, atribuindo-se o peso de 1/3 para a manifestação do corpo docente, de 1/3 para a manifestação dos servidores técnico-administrativos e de 1/3 para a manifestação do corpo discente.</strong>.","banca":"INSTITUTO AOCP","ano":2016,"temas_relacionados":["lei_11892_2008"]},{"id":741891,"enunciado":"Com a fundação dos Institutos Federais, que possibilitou a instituição da Rede Federal, por meio da Lei nº 11.892/08, foram delimitadas as finalidades e características dos IFs (Institutos Federais), em seu Art 6º. Sob esses aspectos é possível afirmar que é finalidade destas instituições:","opcoes":["Direcionar as ofertas formativas em atendimento à disseminação da tecnologia, sem considerar os arranjos produtivos locais e fazer o mapeamento das potencialidades socioeconômicas da região.","Desenvolver a educação profissional e tecnológica como processo educativo e investigativo de geração e adaptação de soluções técnicas e tecnológicas às demandas sociais e peculiaridades regionais.","Ofertar educação profissional e tecnológica apenas nos níveis de ensino médio e educação superior, respeitando a modalidade integrada da educação.","Estimular a pesquisa pura, o empreendedorismo e a produção cultural.","Promover a verticalização da educação superior, independente da integralização com a educação básica e da otimização do quadro de pessoal e da infraestrutura."],"correta":1,"explicacao":"Gabarito: <strong>Desenvolver a educação profissional e tecnológica como processo educativo e investigativo de geração e adaptação de soluções técnicas e tecnológicas às demandas sociais e peculiaridades regionais.</strong>.","banca":"IF-MS","ano":2016,"temas_relacionados":["lei_11892_2008"]},{"id":741941,"enunciado":"Em seu os Artigos 7ª e 8ª da Lei nº11.892/08 que dispõe sobre a Rede Federal de Educação Profissional, Científica e Tecnológica é correto afirmar que entre os objetivos do Instituto Federal está:","opcoes":["O desenvolvimento das atividades de extensão deve ser articulado prioritariamente com as ações de ensino e se possível fazer a articulação com o mundo do trabalho.","As ações dos Institutos Federais devem priorizar as pesquisas puras, que considerem a curiosidade em saber dos estudantes, sem qualquer aplicação prática ou voltada ao desenvolvimento de soluções técnicas e tecnológicas que atendam a comunidade.","A oferta dos cursos de educação superior devem se restringir aos cursos de tecnologia que buscam formar profissionais que atendam aos diferentes setores da economia.","No desenvolvimento da sua ação acadêmica, o Instituto Federal, em cada exercício, deverá garantir o mínimo de 50% (cinqüenta por cento) de suas vagas para atender aos objetivos definidos no inciso I do caput do art. 7o desta Lei, e o mínimo de 20% (vinte por cento) de suas vagas para atender ao previsto na alínea b do inciso VI do caput do citado art. 7o..","A dispensa aos Institutos Federais em ofertar cursos de formação inicial e continuada de trabalhadores e a especialização e atualização de profissionais em todos os níveis de escolaridade."],"correta":3,"explicacao":"Gabarito: <strong>No desenvolvimento da sua ação acadêmica, o Instituto Federal, em cada exercício, deverá garantir o mínimo de 50% (cinqüenta por cento) de suas vagas para atender aos objetivos definidos no inciso I do caput do art. 7o desta Lei, e o mínimo de 20% (vinte por cento) de suas vagas para atender ao previsto na alínea b do inciso VI do caput do citado art. 7o..</strong>.","banca":"IF-MS","ano":2016,"temas_relacionados":["lei_11892_2008"]},{"id":742018,"enunciado":"Assinale a alternativa que contempla uma das finalidades dos Institutos Federais de Educação, Ciência e Tecnologia, conforme a Lei Nº. 11.892/2008, que instituiu a Rede Federal de Educação Profissional, Científica e Tecnológica e criou os Institutos Federais.","opcoes":["Assegurar a verticalização da educação básica e o acesso à educação superior, otimizando a infraestrutura física, os quadros de pessoal e os recursos de gestão.","Constituir-se como centro de excelência da educação superior, com foco nas áreas sociais e da saúde, em consonância com os recursos tecnológicos disponíveis e corpo docente especializado.","Promover a expansão da educação profissional de modo integrado à educação superior, com corpo docente, quadros de gestão e infraestrutura distintas para ambas as ações de formação.","Promover a integração e a verticalização da educação básica à educação profissional e educação superior, otimizando a infraestrutura física, os quadros de pessoal e os recursos de gestão.","Promover a verticalização da educação profissional, com amplitude de pessoal, recursos de gestão e infraestrutura."],"correta":3,"explicacao":"Gabarito: <strong>Promover a integração e a verticalização da educação básica à educação profissional e educação superior, otimizando a infraestrutura física, os quadros de pessoal e os recursos de gestão.</strong>.","banca":"IF-MS","ano":2016,"temas_relacionados":["lei_11892_2008"]},{"id":742833,"enunciado":"Assinale a alternativa CORRETA, considerando as disposições da Lei nº 11.892/08:","opcoes":["Os Institutos Federais oferecem cursos superiores de tecnologia visando à formação de profissionais das áreas de engenharias para a atuação no setor industrial.","É objetivo dos Institutos Federais desenvolver programas de pesquisa para transferência de tecnologias.","É objetivo dos Institutos Federais a ministração de cursos para jovens com vistas à capacitação para o mercado de trabalho.","O Instituto Federal deverá garantir até cinquenta por cento de suas vagas para o ensino médio técnico.","É finalidade dos Institutos Federais ser centro de referência no apoio à oferta do ensino de ciências nas instituições públicas de ensino."],"correta":4,"explicacao":"Gabarito: <strong>É finalidade dos Institutos Federais ser centro de referência no apoio à oferta do ensino de ciências nas instituições públicas de ensino.</strong>.","banca":"IFB","ano":2016,"temas_relacionados":["lei_11892_2008"]},{"id":743425,"enunciado":"Análise os itens que tratam da Lei n° 11.892/08, que institui a Rede Federal de Educação Profissional, Científica e Tecnológica, cria os Institutos Federais de Educação, Ciência e Tecnologia, julgando a assertiva CORRETA:","opcoes":["Os Institutos Federais são instituições de educação básica e profissional, pluricurriculares e multicampi, especializados na oferta de educação profissional, tecnológica e superior nas diferentes modalidades de ensino, com base na conjugação de conhecimentos técnicos, tecnológicos e superiores com as suas práticas pedagógicas, nos termos desta Lei.","Os Institutos Federais terão como órgão executivo a reitoria, composta por 1 (um) Reitor, 5 (cinco) Pró-Reitores, 1 (uma) Ouvidoria e 1 (uma) Auditoria.","A reitoria, como órgão de administração central, poderá ser instalada em espaço físico distinto de qualquer dos campi que integram o Instituto Federal, desde que previsto em seu estatuto, independente de aprovação do Ministério da Educação.","Uma finalidade e característica dos Institutos Federais é constituir-se em centro de excelência na oferta do ensino de ciências, em geral, e de ciências aplicadas, em particular, estimulando o desenvolvimento de espírito crítico, voltado à investigação empírica.","Os Reitores serão nomeados pelo Ministro da Educação, para mandato de 4 (quatro) anos, permitida uma recondução, após processo de consulta à comunidade escolar do respectivo Instituto Federal, atribuindo-se o peso de 2/3 (dois terços) para a manifestação do corpo docente, de 2/3 (dois terços) para a manifestação dos servidores técnico-administrativos e de 2/3 (dois terços) para a manifestação do corpo discente."],"correta":3,"explicacao":"Gabarito: <strong>Uma finalidade e característica dos Institutos Federais é constituir-se em centro de excelência na oferta do ensino de ciências, em geral, e de ciências aplicadas, em particular, estimulando o desenvolvimento de espírito crítico, voltado à investigação empírica.</strong>.","banca":"IF-PA","ano":2016,"temas_relacionados":["lei_11892_2008"]},{"id":743495,"enunciado":"No que tange a Estrutura Organizacional dos Institutos Federais, descrita na Lei nº 11.892, de29 de dezembro de 2008 (Lei de criação dos Institutos Federais de Educação, Ciência e Tecnologia), é INCORRETO afirmar que:","opcoes":["poderão candidatar-se ao cargo de Reitor os docentes pertencentes ao Quadro de Pessoal Ativo Permanente de quaisquer dos campi que integram o Instituto Federal, desde que possuam o mínimo de 5 (cinco) anos de efetivo exercício em instituição federal de educação profissional e tecnológica que, cumulativamente, obtenham o título de doutor e posicionado nas Classes DIV ou DV da Carreira do Magistério do Ensino Básico, Técnico e Tecnológico, ou na Classe de Professor Associado da Carreira do Magistério Superior","o Colégio de Dirigentes, de caráter consultivo, será composto pelo Reitor, pelos Pró-Reitores e pelo Diretor-Geral de cada um dos campi que integram o Instituto Federal.","os Institutos Federais terão como órgão executivo a reitoria, composta por 1 (um) Reitor e 5 (cinco) Pró-Reitores.","os Reitores serão nomeados pelo Presidente da República, para mandato de 4 (quatro) anos, permitida uma recondução, após processo de consulta à comunidade escolar do respectivo Instituto Federal, atribuindo-se o peso de 1/3 (um terço) para a manifestação do corpo docente, de 1/3 (um terço) para a manifestação dos servidores técnico-administrativos e de 1/3 (um terço) para a manifestação do corpo discente.","poderão ser nomeados Pró-Reitores os servidores ocupantes de cargo efetivo da Carreira docente ou de cargo efetivo com nível superior da Carreira dos técnico-administrativos do Plano de Carreira dos Cargos Técnico-Administrativos em Educação, desde que possuam o mínimo de 5 (cinco) anos de efetivo exercício em instituição federal de educação profissional e tecnológica."],"correta":0,"explicacao":"Gabarito: <strong>poderão candidatar-se ao cargo de Reitor os docentes pertencentes ao Quadro de Pessoal Ativo Permanente de quaisquer dos campi que integram o Instituto Federal, desde que possuam o mínimo de 5 (cinco) anos de efetivo exercício em instituição federal de educação profissional e tecnológica que, cumulativamente, obtenham o título de doutor e posicionado nas Classes DIV ou DV da Carreira do Magistério do Ensino Básico, Técnico e Tecnológico, ou na Classe de Professor Associado da Carreira do Magistério Superior</strong>.","banca":"IF-PA","ano":2016,"temas_relacionados":["lei_11892_2008"]},{"id":745181,"enunciado":"A Lei 11.892/2008 instituiu a Rede Federal de Educação Profissional, Científica e Tecnológica e criou os Institutos Federais de Educação, Ciência e Tecnologia. Com base nos assuntos disciplinados na referida lei, considere as seguintes afirmativas: 1. Os Institutos Federais são instituições de educação superior, básica e profissional, pluricurriculares e multicampi, especializados na oferta de educação profissional e tecnológica nas diferentes modalidades de ensino, com base na conjugação de conhecimentos técnicos e tecnológicos com as suas práticas pedagógicas. 2. Uma das finalidades e características dos Institutos Federais é orientar sua oferta formativa em benefício da consolidação e fortalecimento dos arranjos produtivos, sociais e culturais locais, identificados com base no mapeamento das potencialidades de desenvolvimento socioeconômico e cultural no âmbito de atuação do Instituto Federal. 3. Um dos objetivos dos Institutos Federais é desenvolver atividades de extensão de acordo com os princípios e finalidades da educação profissional e tecnológica, em articulação com o mundo do trabalho e os segmentos sociais e com ênfase na produção, desenvolvimento e difusão de conhecimentos científicos e tecnológicos. 4. Os Institutos Federais tem como órgão executivo a reitoria, composta por um Reitor e oito Pró-Reitores. A reitoria, como órgão de administração central, deverá ser instalada em espaço físico distinto de qualquer dos campi que integram o Instituto Federal. Assinale a alternativa correta.","opcoes":["Somente as afirmativas 2 e 3 são verdadeiras.","Somente as afirmativas 1 e 4 são verdadeiras.","Somente as afirmativas 2, 3 e 4 são verdadeiras.","Somente as afirmativas 1, 2 e 3 são verdadeiras.","As afirmativas 1, 2, 3 e 4 são verdadeiras."],"correta":3,"explicacao":"Gabarito: <strong>Somente as afirmativas 1, 2 e 3 são verdadeiras.</strong>.","banca":"IF-PR","ano":2013,"temas_relacionados":["lei_11892_2008"]},{"id":745896,"enunciado":"Leia as afirmativas acerca dos Institutos Federais de Educação, instituídos na Lei nº 11.892/08. I) Uma das finalidades dos Institutos Federais é a de orientar sua oferta formativa em benefício da consolidação e do fortalecimento dos arranjos produtivos, sociais e culturais locais. II) O atendimento ao percentual mínimo de oferta de vagas dos Institutos Federais na educação profissional técnica de nível médio, prioritariamente na forma de cursos integrados, é obrigatório em todos os campi. III) Uma das finalidades dos Institutos Federais é ofertar educação profissional e tecnológica, em todos os níveis e modalidades. IV) O Instituto Federal tem por finalidade prevista em lei a promoção da verticalização da educação básica à educação profissional e educação superior. Assinale a alternativa que apresenta somente as afirmativas CORRETAS:","opcoes":["I, IV","I, II, III","II, III, IV","I, III, IV","II, III"],"correta":3,"explicacao":"Gabarito: <strong>I, III, IV</strong>.","banca":"IFB","ano":2016,"temas_relacionados":["lei_11892_2008"]},{"id":753053,"enunciado":"Considerando a Lei Federal n.º 11.892/2008, os Institutos Federais I. têm autonomia para criar e extinguir cursos, nos limites de sua área de atuação territorial. II. no que se refere à criação de novas instituições, bem como à expansão das já existentes, levará em conta o modelo de Instituto Federal, sem a interferência de parâmetros e normas do Ministério da Educação. III. relativamente à sua administração, em razão de sua autonomia política e administrativa, não possui conselhos e órgãos superiores. IV. têm como uma de suas finalidades e características o desenvolvimento de programas de extensão e de divulgação científica e tecnológica. Estão corretas as afirmativas","opcoes":["I e III.","I e IV.","II e III.","I, II e IV.","I, II, III e IV."],"correta":1,"explicacao":"Gabarito: <strong>I e IV.</strong>.","banca":"FCM","ano":2016,"temas_relacionados":["lei_11892_2008"]},{"id":753174,"enunciado":"A Lei Nº 11.892/2008 que institui a Rede Federal de Educação Profissional, Científica e Tecnológica e criou os Institutos Federais de Educação, Ciência e Tecnologia- Institutos Federais, também define, no seu Art. 6º, as finalidades e características dos mencionados Institutos Federais. Sobre as referidas finalidades e características elencadas no artigo aqui mencionado, assinale a alternativa INCORRETA:","opcoes":["Ofertar educação profissional e tecnológica, em todos os seus níveis e modalidades, formando e qualificando cidadãos com vistas na atuação profissional, nos diversos setores da economia, com ênfase no desenvolvimento socioeconômico local, regional e nacional.","Desenvolver a educação básica e tecnológica como processo educativo e produtivo de geração e adaptação de soluções técnicas e tecnológicas às demandas sociais e peculiaridades locais de naturezas específicas.","Promover a integração e a verticalização da educação básica à educação profissional e educação superior, otimizando a infraestrutura física, os quadros de pessoal e os recursos de gestão.","Realizar e estimular a pesquisa aplicada, a produção cultural, o empreendedorismo, o cooperativismo e o desenvolvimento científico e tecnológico.","Promover a produção, o desenvolvimento e a transferência de tecnologias sociais, notadamente as voltadas à preservação do meio ambiente."],"correta":1,"explicacao":"Gabarito: <strong>Desenvolver a educação básica e tecnológica como processo educativo e produtivo de geração e adaptação de soluções técnicas e tecnológicas às demandas sociais e peculiaridades locais de naturezas específicas.</strong>.","banca":"IF-PI","ano":2016,"temas_relacionados":["lei_11892_2008"]},{"id":753175,"enunciado":"I - Para efeito da incidência das disposições que regem a regulação, avaliação e supervisão das instituições e dos cursos de educação superior, os Institutos Federais são equiparados às Universidades Federais. II - No âmbito de sua atuação, os Institutos Federais exercerão o papel de instituições acreditadoras e certificadoras de competências profissionais. III - Os Institutos Federais não terão autonomia para criar e extinguir cursos, nos limites de sua área de atuação territorial, bem como para registrar diplomas dos cursos por eles oferecidos, mediante autorização do seu Conselho Superior, aplicando-se, no caso da oferta de cursos à distância, a legislação específica.","opcoes":["Apenas os itens I e II estão corretos.","Apenas os itens I e III estão corretos.","Apenas os itens II e III estão corretos.","Apenas o item I esta correto.","Todos os itens estão corretos."],"correta":0,"explicacao":"Gabarito: <strong>Apenas os itens I e II estão corretos.</strong>.","banca":"IF-PI","ano":2016,"temas_relacionados":["lei_11892_2008"]},{"id":753176,"enunciado":"A sequência CORRETA é:","opcoes":["V, V, F, V, F.","V, F, V, F, V.","V, V, F, F, V.","F, V, V, F, F.","F, V, F, F, V."],"correta":2,"explicacao":"Gabarito: <strong>V, V, F, F, V.</strong>.","banca":"IF-PI","ano":2016,"temas_relacionados":["lei_11892_2008"]},{"id":753209,"enunciado":"Com base nas disposições constantes na Lei nº 11.892, de 29 de dezembro de 2008, assinale a alternativa CORRETA:","opcoes":["A administração dos Institutos Federais terá como órgãos superiores o Conselho Superior, presidido pelo Reitor, e o Colégio de Dirigentes, presidido por um dos Diretores-Gerais dos Campi, indicado pelo Reitor.","Os Institutos Federais são instituições de educação exclusivamente básica e profissional, pluricurriculares e multicampi, especializados na oferta de educação profissional e tecnológica nas diferentes modalidades de ensino, com base na conjugação de conhecimentos técnicos e tecnológicos com as suas práticas pedagógicas, nos termos desta Lei.","Somente poderão ser nomeados Pró-Reitores os servidores ocupantes de cargo efetivo da Carreira docente, desde que possuam o mínimo de 5 (cinco) anos de efetivo exercício em instituição federal de educação profissional e tecnológica.","Os Institutos Federais terão autonomia para criar e extinguir cursos, nos limites de sua área de atuação territorial, bem como para registrar diplomas dos cursos por eles oferecidos, mediante autorização do seu Conselho Superior, aplicando-se, no caso da oferta de cursos a distância, a legislação específica.","O Conselho Superior, de caráter normativo, será composto por representantes dos docentes, dos estudantes, dos servidores técnico-administrativos e da sociedade civil, assegurando-se a representação paritária dos segmentos que compõem a comunidade acadêmica."],"correta":3,"explicacao":"Gabarito: <strong>Os Institutos Federais terão autonomia para criar e extinguir cursos, nos limites de sua área de atuação territorial, bem como para registrar diplomas dos cursos por eles oferecidos, mediante autorização do seu Conselho Superior, aplicando-se, no caso da oferta de cursos a distância, a legislação específica.</strong>.","banca":"IF-RS","ano":2016,"temas_relacionados":["lei_11892_2008"]},{"id":754041,"enunciado":"Na trajetória histórica da Educação Profissional está a instituição da Rede Federal de Educação Profissional, Científica e Tecnológica e a criação dos Institutos Federais de Educação, Ciência e Tecnologia com a Lei 11.892/2008. De acordo com o artigo 2º, desta Lei, os Institutos Federais são instituições de:","opcoes":["Educação superior, básica e profissional, pluricurriculares e multicampi, especializados na oferta de educação profissional e tecnológica nas diferentes modalidades de ensino, com base na conjugação de conhecimentos técnicos e tecnológicos com as suas práticas pedagógicas, nos termos desta Lei.","Educação superior e profissional, pluricurriculares e multicampi, especializados na oferta de educação profissional e tecnológica nas diferentes modalidades de ensino, com base na conjugação de conhecimentos técnicos e tecnológicos com as suas práticas pedagógicas, nos termos desta Lei.","Educação superior, básica e profissional, pluricurriculares e multicampi, especializados na oferta de educação profissional e técnica nas diferentes modalidades de ensino, com base na conjugação de conhecimentos técnicos e tecnológicos com as suas práticas pedagógicas, nos termos desta Lei.","Educação superior e profissional, pluricurriculares e multicampi, especializados na oferta de educação profissional e tecnológica nos diferentes níveis de ensino, com base na conjugação de conhecimentos técnicos e tecnológicos com as suas práticas pedagógicas, nos termos desta Lei.","Educação superior, básica e profissional, pluricurriculares e multicampi, especializados na oferta de educação profissional e tecnológica nos diferentes níveis de ensino, com base na conjugação de conhecimentos gerais com as suas práticas pedagógicas, nos termos desta Lei."],"correta":0,"explicacao":"Gabarito: <strong>Educação superior, básica e profissional, pluricurriculares e multicampi, especializados na oferta de educação profissional e tecnológica nas diferentes modalidades de ensino, com base na conjugação de conhecimentos técnicos e tecnológicos com as suas práticas pedagógicas, nos termos desta Lei.</strong>.","banca":"IF-PB","ano":2015,"temas_relacionados":["lei_11892_2008"]},{"id":754043,"enunciado":"Na trajetória histórica da Educação Profissional, a Rede Federal de Educação Profissional, Científica e Tecnológica, de acordo com a Lei nº 11.892/2008, artigo 1º, além dos Institutos Federais de Educação, Ciência e Tecnologia, é constituída pelas seguintes instituições:","opcoes":["Universidade Tecnológica Federal do Paraná - UTFPR; Centros Federais de Educação Tecnológica Celso Suckow da Fonseca - CEFET-RJ; Escolas Técnicas vinculadas às Universidades Federais.","Universidade Tecnológica Federal do Paraná - UTFPR; Centros Federais de Educação Tecnológica Celso Suckow da Fonseca - CEFET-RJ e de Minas Gerais - CEFET-MG; Escolas Técnicas vinculadas às Universidades Federais.","Universidade Tecnológica Federal do Paraná - UTFPR; Centros Federais de Educação Tecnológica Celso Suckow da Fonseca - CEFET-RJ; Escolas Agrotécnicas vinculadas às Universidades Federais.","Universidade Tecnológica Federal do Paraná - UTFPR; Centros Federais de Educação Tecnológica Celso Suckow da Fonseca - CEFET-RJ e de Minas Gerais - CEFET-MG; Escolas Técnicas não vinculadas às Universidades Federais.","Universidade Tecnológica Federal do Paraná - UTFPR; Centros Federais de Educação Tecnológica Celso Suckow da Fonseca - CEFET-RJ e de Minas Gerais - CEFET-MG; Escolas Agrotécnicas não vinculadas às Universidades Federais."],"correta":1,"explicacao":"Gabarito: <strong>Universidade Tecnológica Federal do Paraná - UTFPR; Centros Federais de Educação Tecnológica Celso Suckow da Fonseca - CEFET-RJ e de Minas Gerais - CEFET-MG; Escolas Técnicas vinculadas às Universidades Federais.</strong>.","banca":"IF-PB","ano":2015,"temas_relacionados":["lei_11892_2008"]},{"id":755083,"enunciado":"Sobre a lei nº 11.892/2008, que institui a Rede Federal de Educação Profissional, Científica e Tecnológica, cria os Institutos Federais de Educação, Ciência e Tecnologia, e dá outras providências; assinale a alternativa FALSA.","opcoes":["Os Institutos Federais são instituições de educação superior, básica e profissional, pluricurriculares e multicampi, especializados na oferta de educação profissional e tecnológica nas diferentes modalidades de ensino, com base na conjugação de conhecimentos técnicos e tecnológicos com as suas práticas pedagógicas, nos termos da lei 11.892/2008.","Os Institutos Federais terão autonomia para criar e extinguir cursos, nos limites de sua área de atuação territorial, bem como para registrar diplomas dos cursos por eles oferecidos, mediante autorização do seu Conselho Superior, aplicando-se, no caso da oferta de cursos à distância, a legislação específica.","Os Institutos Federais têm como uma das finalidades e características ofertar educação profissional e tecnológica, em todos os seus níveis e modalidades, formando e qualificando cidadãos com vistas na atuação profissional nos diversos setores da economia, com ênfase no desenvolvimento socioeconômico local, regional e nacional;","Cada Instituto Federal é organizado em estrutura multicampi, com proposta orçamentária anual identificada para cada campus e a reitoria, exceto no que diz respeito a pessoal, encargos sociais e benefícios aos servidores.","Os Institutos Federais terão como órgão executivo a reitoria, composta por 1 (um) Reitor e 7 (sete) Pró- Reitores."],"correta":4,"explicacao":"Gabarito: <strong>Os Institutos Federais terão como órgão executivo a reitoria, composta por 1 (um) Reitor e 7 (sete) Pró- Reitores.</strong>.","banca":"IF Sertão - PE","ano":2016,"temas_relacionados":["lei_11892_2008"]},{"id":755116,"enunciado":"Acerca da estrutura dos Institutos Federais e do que dispõe a Lei nº 11.892, de 29/12/2008, assinale a alternativa correta:","opcoes":["Os Institutos Federais terão como órgão executivo a reitoria, composta por 1 (um) Reitor e 7 (sete) Pró- Reitores.","Por serem cargos de confiança e livre nomeação, os Diretores-Gerais de todos os campi serão livremente nomeados pelo Reitor para mandato de 4 (quatro) anos, permitida uma recondução, e deverão atender aos requisitos estabelecidos em lei.","A presidência do Colégio de Dirigentes será decidida por meio de eleição entre os diretores de todos os campi e a do Conselho Superior será exercida pelo Reitor do Instituto Federal.","Poderão ser nomeados Pró-Reitores os servidores ocupantes de cargo efetivo da Carreira docente ou de cargo efetivo com nível superior da Carreira dos técnico-administrativos do Plano de Carreira dos Cargos Técnico-Administrativos em Educação, desde que possuam o mínimo de 5 (cinco) anos de efetivo exercício em instituição federal de educação profissional e tecnológica.","O mandato de Reitor extingue-se pelo decurso do prazo ou, antes desse prazo, pela livre exoneração levada a feito pelo Presidente da República, aposentadoria, voluntária ou compulsória, pela renúncia e pela destituição ou vacância do cargo."],"correta":3,"explicacao":"Gabarito: <strong>Poderão ser nomeados Pró-Reitores os servidores ocupantes de cargo efetivo da Carreira docente ou de cargo efetivo com nível superior da Carreira dos técnico-administrativos do Plano de Carreira dos Cargos Técnico-Administrativos em Educação, desde que possuam o mínimo de 5 (cinco) anos de efetivo exercício em instituição federal de educação profissional e tecnológica.</strong>.","banca":"IF Sertão - PE","ano":2016,"temas_relacionados":["lei_11892_2008"]},{"id":755191,"enunciado":"NÃO é uma das finalidades e características dos Institutos Federais de Educação, Ciência e Tecnologia:","opcoes":["Contribuir para o fortalecimento das ações de cooperação institucional entre os entes federados nas relações com as organizações do segundo setor.","Desenvolver a educação profissional e tecnológica como processo educativo e investigativo de geração e adaptação de soluções técnicas e tecnológicas às demandas sociais e peculiaridades regionais.","Constituir-se em centro de excelência na oferta do ensino de ciências, em geral, e de ciências aplicadas, em particular, estimulando o desenvolvimento de espírito crítico, voltado à investigação empírica.","Qualificar-se como centro de referência no apoio à oferta do ensino de ciências nas instituições públicas de ensino, oferecendo capacitação técnica e atualização pedagógica aos docentes das redes públicas de ensino.","Ofertar educação profissional e tecnológica, em todos os seus níveis e modalidades, formando e qualificando cidadãos com vistas na atuação profissional, nos diversos setores da economia, com ênfase no desenvolvimento socioeconômico local, regional e nacional."],"correta":0,"explicacao":"Gabarito: <strong>Contribuir para o fortalecimento das ações de cooperação institucional entre os entes federados nas relações com as organizações do segundo setor.</strong>.","banca":"FCM","ano":2016,"temas_relacionados":["lei_11892_2008"]},{"id":760209,"enunciado":"No que concerne à estrutura organizacional dos Institutos Federais, prevista na Lei nº 11.892/08, podemos afirmar que:","opcoes":["O Reitor é nomeado pelo Ministro da Educação para mandato de 4 (quatro) anos, após consulta à comunidade escolar.","Apenas os servidores pertencentes a carreira docente poderão candidatar-se ao cargo de Reitor.","O Reitor do instituto Federal deve possuir o título de doutor e estar posicionado nas Classes DIV da Carreira do Magistério do Ensino Básico, Técnico e Tecnológico.","Os Pró-Reitores são nomeados pelo Reitor e serão eleitos entre os diretores gerais dos campi. nos termos da legislação.","O mandato de Reitor extingue-se pelo decurso do prazo ou, antes desse prazo, apenas pela aposentadoria ou destituição do cargo."],"correta":1,"explicacao":"Gabarito: <strong>Apenas os servidores pertencentes a carreira docente poderão candidatar-se ao cargo de Reitor.</strong>.","banca":"IF-ES","ano":2016,"temas_relacionados":["lei_11892_2008"]},{"id":760260,"enunciado":"Leia as afirmativas acerca dos Institutos Federais de Educação, instituídos na Lei nº 11.892/08. I) A oferta de curso superior de licenciatura é finalidade dos Institutos Federais, na medida em que o que se pretende é a formação de professores para a educação básica, sobretudo nas áreas de ciências e matemática, e para a educação profissional. II) É um objetivos dos Institutos Federais a ministração de cursos técnicos de nível médio prioritariamente integrados. III) Uma das finalidades dos Institutos Federais é ofertar educação profissional e tecnológica, em todos os níveis e modalidades. IV) O Instituto Federal deverá garantir até cinquenta por cento de suas vagas para o ensino médio técnico. Assinale a alternativa que apresenta somente as afirmativas CORRETAS:","opcoes":["I, IV","I, II, III","II, III, IV","I, III, IV","II, III"],"correta":4,"explicacao":"Gabarito: <strong>II, III</strong>.","banca":"IF-ES","ano":2016,"temas_relacionados":["lei_11892_2008"]},{"id":771353,"enunciado":"Com relação à estrutura organizacional dos Institutos Federais, prevista na Lei nº 11.892/08, é CORRETO afirmar que:","opcoes":["A administração do Instituto Federal é do Reitor.","A Reitoria do Instituto Federal deve ser instalada em local distinto dos seus campi, na capital do estado.","Poderá se candidatar ao cargo de Reitor do Instituto Federal qualquer um dos servidores estáveis da autarquia que tenha pelo menos cinco anos de efetivo exercício e que possua o título de doutor.","O Instituto Federal é organizado multicampi, sendo que, no que diz respeito a pessoal, encargos sociais e benefícios dos servidores, a proposta orçamentária anual não é identificada por campus.","O Colégio de Dirigentes e o Conselho Superior são órgãos consultivos do Reitor."],"correta":3,"explicacao":"Gabarito: <strong>O Instituto Federal é organizado multicampi, sendo que, no que diz respeito a pessoal, encargos sociais e benefícios dos servidores, a proposta orçamentária anual não é identificada por campus.</strong>.","banca":"IFB","ano":2017,"temas_relacionados":["lei_11892_2008"]},{"id":771354,"enunciado":"Com base na Lei nº 11.892/08, assinale a alternativa CORRETA:","opcoes":["Os Institutos Federais oferecem cursos superiores de tecnologia visando à formação de profissionais das áreas de engenharias para a atuação no setor industrial.","É objetivo dos Institutos Federais formar profissionais técnicos especializados para atender ao mercado industrial e de tecnologias.","É objetivo dos Institutos Federais a ministração de cursos para jovens com vistas à capacitação para o mercado de trabalho.","O Instituto Federal deve garantir no mínimo cinquenta por cento de suas vagas para o ensino médio técnico integrado.","É finalidade dos Institutos Federais ser centro de referência de ensino médio técnico integrado entre as instituições públicas de ensino."],"correta":3,"explicacao":"Gabarito: <strong>O Instituto Federal deve garantir no mínimo cinquenta por cento de suas vagas para o ensino médio técnico integrado.</strong>.","banca":"IFB","ano":2017,"temas_relacionados":["lei_11892_2008"]},{"id":776908,"enunciado":"A Lei n° 11.892/2008 (Institui a Rede Federal de Educação Profissional, Científica e Tecnológica) determina que","opcoes":["o Conselho Superior possui caráter consultivo e deliberativo.","os Reitores e Pró-Reitores serão nomeados pelo Presidente da República, para mandato de 2 (dois) anos.","os Institutos Federais terão como órgão executivo a Reitoria, composta por 1 (um) Reitor, 5 (cinco) Pró-Reitores e 5 (cinco) Pró-Reitores Substitutos.","poderá se candidatar ao cargo de Reitor qualquer docente pertencente ao Quadro de Pessoal Ativo Permanente de qualquer dos campi que integram o Instituto Federal.","o Colégio de Dirigentes será composto por representantes dos docentes, dos estudantes, dos servidores técnico-administrativos, dos egressos da instituição, da sociedade civil, do Ministério da Educação e do Conselho Superior do Instituto Federal."],"correta":0,"explicacao":"Gabarito: <strong>o Conselho Superior possui caráter consultivo e deliberativo.</strong>.","banca":"FCM","ano":2017,"temas_relacionados":["lei_11892_2008"]},{"id":780601,"enunciado":"É prática sustentável prevista no Plano Orientador da UFSB para alcançar melhores níveis de desempenho ambiental na gestão universitária:","opcoes":["Contratação de empresas especializadas em gestão ambiental.","Criação de um programa ambiental específico para a fase de implantação das unidades de aprendizagem.","Aproveitamento de áreas antropizadas em posse de outros órgãos públicos.","Adoção do padrão de desempenho ambiental praticado pela maioria das universidades brasileiras."],"correta":2,"explicacao":"Gabarito: <strong>Aproveitamento de áreas antropizadas em posse de outros órgãos públicos.</strong>.","banca":"UFMT","ano":2017,"temas_relacionados":["lei_11892_2008"]},{"id":801667,"enunciado":"De acordo com a Lei 11.892/08, o Colégio Pedro II possui natureza jurídica de","opcoes":["Sociedade de Economia Mista.","Empresa Pública Federal.","Sociedade Civil.","Sociedade Empresária.","Autarquia."],"correta":4,"explicacao":"Gabarito: <strong>Autarquia.</strong>.","banca":"INSTITUTO AOCP","ano":2013,"temas_relacionados":["lei_11892_2008"]},{"id":810054,"enunciado":"Sobre o processo de nomeação e os requisitos para candidatura ao cargo de Reitor e Diretor-Geral de Campus previstos na Lei nº 11.892, de 29 de dezembro de 2008, considere as seguintes afirmativas: I. Os Reitores serão nomeados pelo Presidente da República, para mandato de 4 (quatro) anos, permitida uma recondução, após processo de consulta à comunidade escolar do respectivo Instituto Federal. II. Poderão candidatar-se ao cargo de Reitor os docentes pertencentes ao Quadro de Pessoal Ativo Permanente de qualquer dos campi que integram o Instituto Federal, desde que possuam o título de Doutor e estejam posicionados na Classe DV da Carreira do Magistério do Ensino Básico, Técnico e Tecnológico. III. O mandato de Reitor extingue-se pelo decurso do prazo ou, antes desse prazo, pela aposentadoria, voluntária ou compulsória, pela renúncia e pela destituição ou vacância do cargo. IV. Os Diretores-Gerais serão nomeados pelo Reitor para mandato de 4 (quatro) anos, vedada a recondução. V. Para candidatar-se ao cargo de Diretor-Geral, o servidor Docente ou Técnico Administrativo de nível Superior deverá possuir o mínimo de 5 (cinco) anos de efetivo exercício em instituição federal de educação profissional e tecnológica e estar posicionado na última Classe da respectiva carreira. Assinale a alternativa que contém todas as afirmativas CORRETAS:","opcoes":["Apenas I, III.","Apenas II, IV.","Apenas III, V.","Apenas I, II, III.","Apenas I, IV, V."],"correta":0,"explicacao":"Gabarito: <strong>Apenas I, III.</strong>.","banca":"IF-RS","ano":2016,"temas_relacionados":["lei_11892_2008"]},{"id":810056,"enunciado":"O Instituto Federal de Educação, Ciência e Tecnologia do Rio Grande do Sul – IFRS rege-se pela Lei nº 11.892, de 29 de dezembro de 2008, pela legislação federal e, entre outros, pelos seguintes instrumentos normativos: I. Estatuto. II. Regimento Geral. III. Resoluções do Conselho Superior. IV. Resoluções do Colégio de Dirigentes. V. Resoluções do Comitê de Desenvolvimento Institucional. Assinale a alternativa em que todas as afirmativas estão CORRETAS:","opcoes":["Apenas I, II, III.","Apenas I, II, III, IV.","Apenas I, III, IV, V.","Apenas II, III, IV, V.","I, II, III, IV, V."],"correta":0,"explicacao":"Gabarito: <strong>Apenas I, II, III.</strong>.","banca":"IF-RS","ano":2016,"temas_relacionados":["lei_11892_2008"]},{"id":810094,"enunciado":"O Colégio de Dirigentes é o órgão de apoio ao processo decisório da Reitoria do Instituto Federal de Educação, Ciência e Tecnologia do Rio Grande do Sul – IFRS. A ele compete: I. apreciar e recomendar a distribuição interna de recursos. II. apreciar e recomendar as normas para celebração de acordos, convênios e contratos, bem como para elaboração de cartas de intenção ou de documentos equivalentes. III. apreciar as contas do exercício financeiro e o relatório de gestão anual, emitindo parecer conclusivo sobre a propriedade e regularidade dos registros. IV. apreciar e recomendar normas de aperfeiçoamento da gestão. V. atuar como instância máxima no âmbito do Instituto Federal de Educação, Ciência e Tecnologia do Rio Grande do Sul – IFRS. Assinale a alternativa em que todas as afirmativas estão CORRETAS:","opcoes":["Apenas I, II, V.","Apenas I, II, IV.","Apenas I, III, IV.","Apenas II, III, V.","Apenas II, IV, V."],"correta":1,"explicacao":"Gabarito: <strong>Apenas I, II, IV.</strong>.","banca":"IF-RS","ano":2016,"temas_relacionados":["lei_11892_2008"]},{"id":810096,"enunciado":"O Instituto Federal de Educação, Ciência e Tecnologia do Rio Grande do Sul – IFRS regese pela Lei nº 11.892, de 29 de dezembro de 2008, pela legislação federal e, entre outros, pelos seguintes instrumentos normativos: I. Estatuto. II. Regimento Geral. III. Resoluções do Conselho Superior. IV. Resoluções do Comitê de Desenvolvimento Institucional. V. Resoluções do Colégio de Dirigentes. Assinale a alternativa em que todas as afirmativas estão CORRETAS:","opcoes":["Apenas I, II, III.","Apenas I, II, III, IV.","Apenas I, III, IV, V.","Apenas II, III, IV, V.","I, II, III, IV, V."],"correta":0,"explicacao":"Gabarito: <strong>Apenas I, II, III.</strong>.","banca":"IF-RS","ano":2016,"temas_relacionados":["lei_11892_2008"]},{"id":816968,"enunciado":"Assinale a alternativa incorreta, em conformidade com os termos da Lei nº 11.892, de 29/12/2008:","opcoes":["O Instituto Federal do Sertão Pernambucano tem como objetivo ministrar educação profissional técnica de nível médio, na forma de cursos integrados, para os concluintes do ensino fundamental; ministrar cursos de formação inicial e continuada de trabalhadores; realizar pesquisas aplicadas e cursos superiores de tecnologia.","O Instituto Federal do IF Sertão é organizado por meio de estrutura única, sendo o seu órgão central a Reitoria, que detém o controle administrativo, financeiro e orçamentário sobre os demais órgãos da instituição.","Os Institutos Federais terão autonomia para criar e extinguir cursos, nos limites de sua área de atuação territorial, na forma da Lei.","A administração dos Institutos Federais terá como órgãos superiores o Colégio de Dirigentes e o Conselho Superior.","O Colégio de Dirigentes, de caráter consultivo, será composto pelo Reitor, pelos Pró-Reitores e pelo Diretor-Geral de cada um dos campi que integram o Instituto Federal."],"correta":1,"explicacao":"Gabarito: <strong>O Instituto Federal do IF Sertão é organizado por meio de estrutura única, sendo o seu órgão central a Reitoria, que detém o controle administrativo, financeiro e orçamentário sobre os demais órgãos da instituição.</strong>.","banca":"IF Sertão - PE","ano":2016,"temas_relacionados":["lei_11892_2008"]},{"id":818085,"enunciado":"Todos os itens abaixo são finalidades e características dos Institutos Federais e Educação, exceto:","opcoes":["Desenvolver a educação fundamental como processo educativo e investigativo de geração e adaptação de soluções técnicas e tecnológicas às demandas sociais e peculiaridades regionais;","Ofertar educação profissional e tecnológica, em todos os seus níveis e modalidades;","Promover a integração e a verticalização da educação básica à educação profissional e educação superior, otimizando a infra estrutura física, os quadros de pessoal e os recursos de gestão;","Orientar sua oferta formativa em benefício da consolidação e fortalecimento dos arranjos produtivos, sociais e culturais locais, identificando com base no mapeamento das potencialidades de desenvolvimento socioeconômico e cultural no âmbito de atuação do Instituto Federal;","Desenvolver programas de extensão e de divulgação científica e tecnológica;"],"correta":0,"explicacao":"Gabarito: <strong>Desenvolver a educação fundamental como processo educativo e investigativo de geração e adaptação de soluções técnicas e tecnológicas às demandas sociais e peculiaridades regionais;</strong>.","banca":"IF-MG","ano":2015,"temas_relacionados":["lei_11892_2008"]},{"id":818089,"enunciado":"Assinale o item abaixo que não é o objetivo dos Institutos Federais de Educação, Ciência e Tecnologia:","opcoes":["Ministrar cursos de formação inicial e continuada de trabalhadores, objetivando a capacitação, o aperfeiçoamento, a especialização e a atualização de profissionais, em todos os níveis de escolaridade, nas áreas da educação profissional e tecnológica;","Realizar pesquisas aplicadas, estimulando o desenvolvimento de soluções técnicas e tecnológicas, estendendo seus benefícios à comunidade;","Ministrar educação de nível fundamental, profissional técnica de nível médio, prioritariamente na forma de cursos integrados, para os concluintes do ensino primário e fundamental e para o público da educação de jovens e adultos;","Desenvolver atividades de extensão de acordo com os princípios e finalidades da educação profissional e tecnológica, em articulação com o mundo do trabalho e os segmentos sociais, e com ênfase na produção, desenvolvimento e difusão de conhecimentos científicos e tecnológicos;","Estimular e apoiar processos educativos que levem à geração de trabalho e renda e à emancipação do cidadão na perspectiva do desenvolvimento socioeconômico local e regional."],"correta":2,"explicacao":"Gabarito: <strong>Ministrar educação de nível fundamental, profissional técnica de nível médio, prioritariamente na forma de cursos integrados, para os concluintes do ensino primário e fundamental e para o público da educação de jovens e adultos;</strong>.","banca":"IF-MG","ano":2015,"temas_relacionados":["lei_11892_2008"]},{"id":822918,"enunciado":"Um marco importante na história da educação profissional no Brasil foi a publicação do Decreto nº 7.566, assinado pelo então presidente da república, Nilo Peçanha, em 1909, criando as Escolas de Aprendizes Artífices, destinadas ao ensino profissional, primário e gratuito em diferentes unidades federativas. Em 1942, o Decreto nº 4.127 transforma as Escolas de Aprendizes e Artífices em Escolas Industriais e Técnicas, passando a oferecer a formação profissional em nível equivalente ao do secundário. Estas, no ano de 1959, depois de transformadas em autarquias, receberam o nome de Escolas Técnicas Federais. Somente com a Lei nº 11.892/2008, deu-se a instituição da Rede Federal de Educação Profissional, Científica e Tecnológica e a criação dos Institutos Federais de Educação, Ciência e Tecnologia. Tendo como base o modelo atual de Instituições de educação profissional e tecnológica que compõem a Rede federal, julgue as alternativas a seguir, marcando V ou F: ( ) Os Institutos Federais são instituições de educação superior, básica e profissional, pluricurriculares e multicampi, tendo como órgão executivo a reitoria, composta por 1 (um) Reitor e 5 (cinco) Pró-Reitores. ( ) A Rede Federal de Educação Profissional, Científica e Tecnológica é constituída pelos Institutos Federais de Educação, Ciência e Tecnologia e pelas Universidades Tecnológicas Federais, sendo estas instituições de natureza jurídica de autarquia, detentoras de autonomia administrativa, patrimonial, financeira, didático-pedagógica e disciplinar. ( ) Orientar sua oferta formativa em benefício da consolidação e fortalecimento dos arranjos produtivos, sociais e culturais locais, identificados com base no mapeamento das potencialidades de desenvolvimento socioeconômico e cultural no âmbito de sua atuação, é uma das finalidades dos Institutos Federais. ( ) Um dos objetivos dos Institutos Federais é o de ministrar educação profissional técnica de nível médio, prioritariamente na forma de cursos integrados, garantindo, no mínimo, 50% (cinquenta por cento) de suas vagas para atender os concluintes do ensino fundamental e para o público da educação de jovens e adultos. ( ) Em nível de educação superior, os institutos federais ofertarão apenas cursos superiores de tecnologia, cursos de licenciatura, cursos de bacharelado e engenharia, visando à formação de profissionais para os diferentes setores da economia e áreas do conhecimento. Assinale a sequência correta:","opcoes":["V, V, V, F, V.","V, F, V, V, F.","F, F, F, V, F.","F, V, F, F, V.","F, F, V, V, F."],"correta":1,"explicacao":"Gabarito: <strong>V, F, V, V, F.</strong>.","banca":"IF-MS","ano":2016,"temas_relacionados":["lei_11892_2008"]},{"id":833362,"enunciado":"Nos termos da Lei 11.892/08, entre outros requisitos, poderão candidatar-se ao cargo de Reitor:","opcoes":["qualquer servidor do Quadro de Pessoal Ativo Permanente, que não esteja em estágio probatório.","apenas servidores ocupantes de cargo de nível superior.","somente servidores com mais de 10 (dez) anos no cargo e que não respondam a processo administrativo disciplinar.","os diretores gerais dos campi.","docentes do Quadro de Pessoal Ativo Permanente de qualquer um dos campi que integram o Instituto Federal, desde que possuam o mínimo de 5 (cinco) anos de efetivo exercício em instituição federal de educação profissional e tecnológica."],"correta":4,"explicacao":"Gabarito: <strong>docentes do Quadro de Pessoal Ativo Permanente de qualquer um dos campi que integram o Instituto Federal, desde que possuam o mínimo de 5 (cinco) anos de efetivo exercício em instituição federal de educação profissional e tecnológica.</strong>.","banca":"IF-ES","ano":2017,"temas_relacionados":["lei_11892_2008"]},{"id":836305,"enunciado":"Considerando as normas contidas na Lei nº 11.892/2008, em especial quanto à estrutura organizacional dos Institutos Federais, assinale a alternativa incorreta.","opcoes":["Os Institutos Federais terão como órgão executivo a reitoria, composta por 1 (um) Reitor e 5 (cinco) Pró-Reitores.","Poderão candidatar-se ao cargo de Reitor os docentes pertencentes ao Quadro de Pessoal Ativo Permanente ou de cargo efetivo com nível superior da Carreira dos técnico-administrativos do Plano de Carreira dos Cargos Técnico-Administrativos em Educação, ambos de qualquer dos campi que integram o Instituto Federal, desde que possuam o mínimo de 5 (cinco) anos de efetivo exercício em instituição federal de educação profissional e tecnológica.","Poderão ser nomeados Pró-Reitores os servidores ocupantes de cargo efetivo da carreira docente ou de cargo efetivo com nível superior da carreira dos técnico-administrativos do plano de carreira dos cargos técnico-administrativos em educação, desde que possuam o mínimo de 5 (cinco) anos de efetivo exercício em instituição federal de educação profissional e tecnológica.","Os Reitores serão nomeados pelo Presidente da República, para mandato de 4 (quatro) anos, permitida uma recondução, após processo de consulta à comunidade escolar do respectivo Instituto Federal, atribuindo-se o peso de 1/3 (um terço) para a manifestação do corpo docente, de 1/3 (um terço) para a manifestação dos servidores técnico-administrativos e de 1/3 (um terço) para a manifestação do corpo discente.","Os Pró-Reitores são nomeados pelo Reitor do Instituto Federal, nos termos da legislação aplicável à nomeação de cargos de direção."],"correta":1,"explicacao":"Gabarito: <strong>Poderão candidatar-se ao cargo de Reitor os docentes pertencentes ao Quadro de Pessoal Ativo Permanente ou de cargo efetivo com nível superior da Carreira dos técnico-administrativos do Plano de Carreira dos Cargos Técnico-Administrativos em Educação, ambos de qualquer dos campi que integram o Instituto Federal, desde que possuam o mínimo de 5 (cinco) anos de efetivo exercício em instituição federal de educação profissional e tecnológica.</strong>.","banca":"IF-TO","ano":2017,"temas_relacionados":["lei_11892_2008"]},{"id":848316,"enunciado":"Na Lei N° 11.892 de 2008, no §2° do Artigo 2° está expresso: “ § 2° No âmbito de sua atuação, os Institutos Federais exercerão o papel de instituições acreditadoras e certificadoras de competências profissionais.” Acreditação e certificação, referem-se respectivamente a:","opcoes":["Credenciar outras escolas e certificar seus próprios alunos.","Registrar os diplomas de outras instituições e emitir diplomas e certificados de seus próprios cursos.","Reconhecer a formação de outras instituições e registrar seus diplomas e certificados.","Apostilar diplomas de outras instituições e registrar seus próprios diplomas.","Emitir e registrar seus diplomas e certificados."],"correta":2,"explicacao":"Gabarito: <strong>Reconhecer a formação de outras instituições e registrar seus diplomas e certificados.</strong>.","banca":"IF-SC","ano":2017,"temas_relacionados":["lei_11892_2008"]},{"id":852162,"enunciado":"Na Lei N° 11.892 de 2008, no §2° do Artigo 2º está expresso: “§ 2º No âmbito de sua atuação, os Institutos Federais exercerão o papel de instituições acreditadoras e certificadoras de competências profissionais.” Acreditação e certificação, referem-se respectivamente a:","opcoes":["Registrar os diplomas de outras instituições e emitir diplomas e certificados de seus próprios cursos.","Reconhecer a formação de outras instituições e registrar seus diplomas e certificados.","Credenciar outras escolas e certificar seus próprios alunos.","Apostilar diplomas de outras instituições e registrar seus próprios diplomas.","Emitir e registrar seus diplomas e certificados."],"correta":1,"explicacao":"Gabarito: <strong>Reconhecer a formação de outras instituições e registrar seus diplomas e certificados.</strong>.","banca":"IF-SC","ano":2017,"temas_relacionados":["lei_11892_2008"]},{"id":857154,"enunciado":"Sobre o mandado de segurança, assinale a alternativa incorreta.","opcoes":["Não se concederá mandado de segurança quando se tratar de decisão judicial transitada em julgado.","Concedida a segurança, a sentença estará sujeita obrigatoriamente ao duplo grau de jurisdição.","Quando o direito ameaçado ou violado couber a várias pessoas, qualquer delas poderá requerer o mandado de segurança.","Os processos de mandado de segurança e os respectivos recursos terão prioridade sobre todos os atos judiciais, salvo habeas corpus, habeas data e ação popular.","Não cabe mandado de segurança contra os atos de gestão comercial praticados pelos administradores de empresas públicas, de sociedade de economia mista e de concessionárias de serviço público."],"correta":3,"explicacao":"Gabarito: <strong>Os processos de mandado de segurança e os respectivos recursos terão prioridade sobre todos os atos judiciais, salvo habeas corpus, habeas data e ação popular.</strong>.","banca":"FEPESE","ano":2017,"temas_relacionados":["lei_11892_2008"]},{"id":860357,"enunciado":"Com relação à estrutura organizacional dos Institutos Federais, de acordo com a Lei nº 11892/2008, marque (V) para as afirmativas verdadeiras e (F), para as falsas. ( ) São órgãos superiores dos Institutos Federais o Colégio de Dirigentes e o Conselho Superior. ( ) Cada Instituto Federal é organizado em estrutura multicampi e o Campus Sede é aquele instalado na capital do Estado. ( ) O Colégio de Dirigentes é composto pelo Reitor e pelos Diretores-Gerais de cada um dos campi. ( ) Os Institutos Federais terão como órgão executivo a Reitoria, composta por 1 (um) Reitor e 5 (cinco) Pró-Reitores. ( ) O Reitor, obrigatoriamente, deve possuir o título de doutor. ( ) Um servidor de cargo efetivo da carreira dos técnico-administrativos do Plano de Carreira dos Cargos Técnico-Administrativos em Educação, desde que possua 5 (cinco) anos de efetivo exercício em instituição federal de educação profissional e tecnológica, pode ser nomeado como Pró-Reitor. Assinale a alternativa que contém a sequência CORRETA de cima para baixo.","opcoes":["V, F, V, F, V, F","F, V, V, F, V, F","F, V, F, V, V, F","V, F, F, V, F, V","V, F, V, F, F, V"],"correta":3,"explicacao":"Gabarito: <strong>V, F, F, V, F, V</strong>.","banca":"IF-SC","ano":2015,"temas_relacionados":["lei_11892_2008"]},{"id":906789,"enunciado":"Sobre os requisitos necessários à nomeação de Pró-Reitores, previstos na Lei nº 11.892/2008, considere: I. Servidores ocupantes de cargo efetivo de nível superior da carreira dos técnico-administrativos do Plano de Carreira dos Cargos Técnico-Administrativos em Educação poderão ser nomeados ao cargo de Pró-Reitor. II. Servidores ocupantes de cargo efetivo de nível médio da carreira dos técnico-administrativos do Plano de Carreira dos Cargos Técnico-Administrativos em Educação poderão ser nomeados ao cargo de Pró-Reitor, desde que possuam nível superior. III. Possuir a partir de 5 (cinco) anos de efetivo exercício em instituição federal de educação profissional e tecnológica. IV. Servidores ocupantes de cargo efetivo da carreira docente não poderão ser nomeados ao cargo de Pró-Reitor. Está INCORRETO o que se afirma em","opcoes":["I, apenas.","I, II e III, apenas.","III e IV, apenas.","IV, apenas."],"correta":3,"explicacao":"Gabarito: <strong>IV, apenas.</strong>.","banca":"IF-SP","ano":2018,"temas_relacionados":["lei_11892_2008"]},{"id":906794,"enunciado":"Considere as seguintes assertivas a respeito da Lei nº 11.892/2008: I. Os Institutos Federais possuem a natureza jurídica de autarquia, exceto o Colégio Pedro II. II. Os Institutos Federais não possuem autonomia para registrar diplomas dos cursos por eles oferecidos. III. Estimular o empreendedorismo é uma das finalidades e características dos Institutos Federais. IV. O Colégio de Dirigentes e o Conselho Superior são órgãos superiores dos Institutos Federais, e ambos possuem o caráter consultivo e deliberativo. Está correto o que se afirma APENAS em:","opcoes":["I.","III.","III e IV.","II e IV"],"correta":1,"explicacao":"Gabarito: <strong>III.</strong>.","banca":"IF-SP","ano":2018,"temas_relacionados":["lei_11892_2008"]},{"id":906844,"enunciado":"A Lei 11.892, de 29 de dezembro de 2008, institui a Rede Federal de Educação Profissional, Científica e Tecnológica e cria os Institutos Federais de Educação, Ciência e Tecnologia. Consoante a referida lei, assinale a alternativa correta.","opcoes":["Os Institutos Federais possuem natureza jurídica de fundação pública, detentoras de autonomia administrativa, patrimonial, didático-pedagógica e disciplinar e autonomia financeira.","Os Institutos Federais terão autonomia para criar e extinguir cursos, nos limites de sua área de atuação territorial, bem como para registrar diplomas dos cursos por eles oferecidos, mediante autorização do seu Colégio de Dirigentes, aplicando-se, no caso da oferta de cursos a distância, a legislação específica.","Os Institutos Federais são instituições de educação superior, básica e profissional, pluricurriculares e multicampi, especializados na oferta de educação profissional e tecnológica nas diferentes modalidades de ensino, com base na conjugação de conhecimentos técnicos e tecnológicos com as suas práticas pedagógicas.","Para efeito da incidência das disposições que regem a regulação, avaliação e supervisão das instituições e dos cursos de educação superior, os Institutos Federais são equiparados às universidades federais, estaduais e municipais."],"correta":2,"explicacao":"Gabarito: <strong>Os Institutos Federais são instituições de educação superior, básica e profissional, pluricurriculares e multicampi, especializados na oferta de educação profissional e tecnológica nas diferentes modalidades de ensino, com base na conjugação de conhecimentos técnicos e tecnológicos com as suas práticas pedagógicas.</strong>.","banca":"IF-SP","ano":2018,"temas_relacionados":["lei_11892_2008"]},{"id":906847,"enunciado":"O PDI, ou Plano de Desenvolvimento Institucional, é o documento elaborado por uma instituição de ensino superior que deverá apontar sua missão e ações para os próximos cinco anos. O IFSP – Instituto Federal de São Paulo encontra-se na fase de elaboração do respectivo PDI para o período de 2019 a 2023. Na sua elaboração a comissão responsável deverá, com base na Lei nº 11.892, de 29 de dezembro de 2008, (Lei de Criação dos Institutos Federais), atentar-se para alguns balizadores que devem ser contemplados. Desta forma, das alternativas abaixo, assinale aquela que apresenta um dos balizadores relacionados à oferta de vagas que deverá ser contemplada no PDI do IFSP.","opcoes":["Ofertar o mínimo de 50% (cinquenta por cento) em outros tipos de cursos, tais como os tecnológicos, os bacharelados e as engenharias.","Ofertar o mínimo de 50% (cinquenta por cento) de suas vagas para atender os cursos de licenciatura.","Ofertar o mínimo de 50% (cinquenta por cento) de suas vagas para atender os cursos de pós-graduação stricto sensu de mestrado e doutorado.","Ofertar o mínimo de 50% (cinquenta por cento) de suas vagas para atender educação profissional técnica de nível médio."],"correta":3,"explicacao":"Gabarito: <strong>Ofertar o mínimo de 50% (cinquenta por cento) de suas vagas para atender educação profissional técnica de nível médio.</strong>.","banca":"IF-SP","ano":2018,"temas_relacionados":["lei_11892_2008"]},{"id":920601,"enunciado":"Demétrio, Bacharel em Engenharia Civil, ocupante do cargo efetivo de Auxiliar em Administração, Nível C desde 25 de novembro de 2011, é nomeado como Pró-reitor de Administração em 12 de fevereiro de 2018, pela Reitora do Instituto Federal de Brasília. Considerando o disposto na Lei n.º 11.892/08, essa nomeação é considerada:","opcoes":["Inválida, pois apenas poderão ser nomeados Pró-Reitores os servidores ocupantes de cargo efetivo da Carreira docente, desde que possuam o mínimo de 5 (cinco) anos de efetivo exercício em instituição federal de educação profissional e tecnológica.","Válida, pois Demétrio é servidor ocupante de cargo efetivo de nível superior da carreira dos técnico-administrativos do Plano de Carreira dos Cargos Técnico-Administrativos em Educação, possuindo mais de 5 (cinco) anos de efetivo exercício em instituição federal de educação profissional e tecnológica","Inválida, pois Demétrio não é servidor ocupante do cargo efetivo de docente pertencente ao Quadro de Pessoal Ativo Permanente de qualquer dos campi que integram o Instituto Federal, ou possui o mínimo de 5 (cinco) anos de efetivo exercício em instituição federal de educação profissional e tecnológica e cumulativamente não atende a, pelo menos, um dos seguintes requisitos: possuir o título de doutor; ou estar posicionado nas Classes DIV ou DV da Carreira do Magistério do Ensino Básico, Técnico e Tecnológico, ou na Classe de Professor Associado da Carreira do Magistério Superior.","Válida, pois Demétrio é servidor ocupante de cargo efetivo com nível superior da Carreira dos técnico-administrativos do Plano de Carreira dos Cargos Técnico-Administrativos em Educação, possuindo mais de 5 (cinco) anos de efetivo exercício em instituição federal de educação profissional e tecnológica.","Válida, pois se trata de Cargo ad nutum, preenchido com base em confiança, sendo chamados de cargos em comissão, de livre preenchimento e exoneração, portanto, prescinde de pré-requisito para nomeação."],"correta":3,"explicacao":"Gabarito: <strong>Válida, pois Demétrio é servidor ocupante de cargo efetivo com nível superior da Carreira dos técnico-administrativos do Plano de Carreira dos Cargos Técnico-Administrativos em Educação, possuindo mais de 5 (cinco) anos de efetivo exercício em instituição federal de educação profissional e tecnológica.</strong>.","banca":"IF-TO","ano":2018,"temas_relacionados":["lei_11892_2008"]},{"id":920612,"enunciado":"Nos termos da Lei n.° 11.892, de 29 de dezembro de 2008, que institui a Rede Federal de Educação Profissional, Científica e Tecnológica e cria os Institutos Federais de Educação, Ciência e Tecnologia, assinale a alternativa correta:","opcoes":["A administração dos Institutos Federais terá como órgãos superiores o Colégio de Dirigentes, de caráter deliberativo e o Conselho Superior, de caráter consultivo e deliberativo.","Uma das finalidades e características dos Institutos Federais é ofertar educação profissional e tecnológica, em todos os seus níveis e somente nas modalidades de Educação de Jovens e Adultos e Educação à Distância, formando e qualificando cidadãos, com vistas na atuação profissional nos diversos setores da economia, com ênfase no desenvolvimento socioeconômico local, regional e nacional.","Os Institutos Federais terão como órgão executivo o Conselho Superior.","Os Institutos Federais não terão autonomia para criar ou extinguir cursos, cabendo ao Ministério da Educação esta decisão.","Um dos objetivos dos Institutos Federais é ministrar cursos de formação inicial e continuada de trabalhadores, objetivando a capacitação, o aperfeiçoamento, a especialização e a atualização de profissionais, em todos os níveis de escolaridade, nas áreas da educação profissional e tecnológica."],"correta":4,"explicacao":"Gabarito: <strong>Um dos objetivos dos Institutos Federais é ministrar cursos de formação inicial e continuada de trabalhadores, objetivando a capacitação, o aperfeiçoamento, a especialização e a atualização de profissionais, em todos os níveis de escolaridade, nas áreas da educação profissional e tecnológica.</strong>.","banca":"IF-TO","ano":2018,"temas_relacionados":["lei_11892_2008"]},{"id":921732,"enunciado":"De acordo com a Lei Federal nº 11.892, de 29 de dezembro de 2008, é CORRETO afirmar que:","opcoes":["A administração dos Institutos Federais terá como órgãos superiores o Colégio de Dirigentes e o Conselho Superior, sendo o primeiro presidido pelo Diretor-Geral de um dos campi do Instituto e o segundo por um dos Pró-Reitores.","Foram criados quatro Institutos Federais no Estado do Rio Grande do Sul.","Os Reitores dos Institutos Federais serão nomeados pelo Presidente da República, para mandato de 4 (quatro) anos, permitida uma recondução, após processo de consulta à comunidade escolar do respectivo Instituto Federal, atribuindo-se o peso de 1/3 (um terço) para a manifestação do corpo docente, de 1/3 (um terço) para a manifestação dos servidores técnico-administrativos e de 1/3 (um terço) para a manifestação do corpo discente.","Todas as instituições que compõem a Rede Federal de Educação Profissional, Científica e Tecnológica possuem natureza jurídica de autarquia, sendo detentoras de autonomia administrativa, patrimonial, financeira, didático-pedagógica e disciplinar.","No âmbito do ensino superior de pós-graduação, somente os cursos stricto sensu podem ser ofertados pelos Institutos Federais."],"correta":2,"explicacao":"Gabarito: <strong>Os Reitores dos Institutos Federais serão nomeados pelo Presidente da República, para mandato de 4 (quatro) anos, permitida uma recondução, após processo de consulta à comunidade escolar do respectivo Instituto Federal, atribuindo-se o peso de 1/3 (um terço) para a manifestação do corpo docente, de 1/3 (um terço) para a manifestação dos servidores técnico-administrativos e de 1/3 (um terço) para a manifestação do corpo discente.</strong>.","banca":"IF-RS","ano":2018,"temas_relacionados":["lei_11892_2008"]},{"id":921767,"enunciado":"Tendo por base as disposições contidas na Lei nº 11.892/2008, que cria os Institutos Federais de Educação, Ciência e Tecnologia, assinale a alternativa que contém a sequência CORRETA de preenchimento das lacunas, na ordem em que aparecem. “A administração dos Institutos Federais terá como órgãos superiores o Conselho Superior e o ______________, sendo seus Reitores nomeados pelo ________________, para mandato de ________ anos, ______________ recondução.”","opcoes":["Conselho Nacional de Educação – Presidente da República – 4 (quatro) anos – vedada","Conselho Acadêmico – Ministro da Educação – 5 (cinco) anos – permitida uma","Colégio de Dirigentes – Presidente da República – 4 (quatro) anos – permitida uma","Conselho Nacional de Educação – Ministro da Educação – 5 (cinco) anos – vedada","Colégio de Dirigentes – Presidente da República – 5 (cinco) anos - vedada"],"correta":2,"explicacao":"Gabarito: <strong>Colégio de Dirigentes – Presidente da República – 4 (quatro) anos – permitida uma</strong>.","banca":"IF-RS","ano":2018,"temas_relacionados":["lei_11892_2008"]},{"id":926976,"enunciado":"A Lei nº 11.892/2008 instituiu a Rede Federal de Educação Profissional, Científica e Tecnológica. De acordo com seus dispositivos, é correto afirmar que","opcoes":["o Colégio Pedro II é instituição federal de ensino, pluricurricular e multicampi, vinculada ao Ministério da Educação e especializada na oferta de educação básica e de licenciaturas.","para efeito da incidência das disposições que regem a regulação, avaliação e supervisão das instituições e dos cursos de educação superior, os Institutos Federais são equiparados às antigas Escolas Técnicas.","no âmbito de sua atuação, os Institutos Federais exercerão o papel de instituições acreditadoras, mas não poderão exercer a função de certificadoras de competências profissionais, atribuição exclusiva das universidades.","o Colégio Pedro II é equiparado às universidades federais para efeito de incidência das disposições que regem a autonomia e a utilização dos instrumentos de gestão do quadro de pessoal e de ações de regulação, avaliação e supervisão das instituições."],"correta":0,"explicacao":"Gabarito: <strong>o Colégio Pedro II é instituição federal de ensino, pluricurricular e multicampi, vinculada ao Ministério da Educação e especializada na oferta de educação básica e de licenciaturas.</strong>.","banca":"Colégio Pedro II","ano":2017,"temas_relacionados":["lei_11892_2008"]},{"id":931470,"enunciado":"Conforme dispõe a lei que instituiu a Rede Federal de Educação Profissional, Científica e Tecnológica (Lei nº 11.892/2008), os Institutos Federais se definem, por sua natureza jurídica, como","opcoes":["autarquias, sem autonomia administrativa, patrimonial, financeira, didático -pedagógica e disciplinar.","autarquias, detentoras de autonomia administrativa, patrimonial, financeira, didático - pedagógica e disciplinar.","fundações, detentoras de autonomia administrativa, patrimonial, financeira, didático - pedagógica e disciplinar.","fundações, sem autonomia administrativa, patrimonial, financeira, didático -pedagógica e disciplinar."],"correta":1,"explicacao":"Gabarito: <strong>autarquias, detentoras de autonomia administrativa, patrimonial, financeira, didático - pedagógica e disciplinar.</strong>.","banca":"COMPERVE - UFRN","ano":2017,"temas_relacionados":["lei_11892_2008"]},{"id":931471,"enunciado":"De acordo com o disposto na lei que instituiu a Rede Federal de Educação Profissional, Científica e Tecnológica (Lei nº 11.892/2008), é objetivo dos Institutos Federais","opcoes":["estimular e apoiar processos educativos que levem à geração de trabalho e renda e à emancipação do cidadão, na perspectiva do desenvolvimento socioeconômico local e regional.","desenvolver atividades de ensino, pesquisa e extensão de acordo com os princípios e as finalidades da educação profissional e técnica, em articulação com o mundo do traba lho e a iniciativa privada, e com ênfase na produção, no desenvolvimento e na difusão de conhecimentos científicos e culturais.","estimular e apoiar processos econômicos e produtivos que levem à geração de trabalho e renda e à emancipação do cidadão, na perspectiva do desenvolvimento sociocultural nacional.","desenvolver atividades de ensino, pesquisa e extensão de acordo com os princípios e as finalidades da educação básica e tecnológica, em articulação com o mundo do trabalho e os segmentos sociais, e com ênfase na produção, desenvolvimento e difusão de conhecimentos econômicos e culturais."],"correta":0,"explicacao":"Gabarito: <strong>estimular e apoiar processos educativos que levem à geração de trabalho e renda e à emancipação do cidadão, na perspectiva do desenvolvimento socioeconômico local e regional.</strong>.","banca":"COMPERVE - UFRN","ano":2017,"temas_relacionados":["lei_11892_2008"]},{"id":931575,"enunciado":"Conforme o disposto na lei que instituiu a Rede Federal de Educação Profissional, Científica e Tecnológica (Lei nº 11.892/2008), os Institutos Federais são instituições de educação","opcoes":["superior, básica e profissional, unicurriculares e pluricampi, especializados na oferta de educação profissional e técnica nas diferentes modalidades de ensino a distância, com base na conjugação de conhecimentos técnicos e teóricos com as suas práticas pedagógicas.","básica e profissional, unicurriculares e multicampi, especializados na oferta de educação profissional e tecnológica nas diferentes modalidades de ensino a distância, com base na conjugação de conhecimentos técnicos e teóricos com as suas práticas pedagógicas.","básica e profissional, multicurriculares e pluricampi, especializados na oferta de educação profissional e técnica nas diferentes modalidades de ensino, com base na conjugação de conhecimentos técnicos e tecnológicos com as suas práticas pedagógicas.","superior, básica e profissional, pluricurriculares e multicampi, especializados na oferta de educação profissional e tecnológica nas diferentes modalidades de ensino, com base na conjugação de conhecimentos técnicos e tecnológicos com as suas práticas pedagógicas."],"correta":3,"explicacao":"Gabarito: <strong>superior, básica e profissional, pluricurriculares e multicampi, especializados na oferta de educação profissional e tecnológica nas diferentes modalidades de ensino, com base na conjugação de conhecimentos técnicos e tecnológicos com as suas práticas pedagógicas.</strong>.","banca":"COMPERVE - UFRN","ano":2017,"temas_relacionados":["lei_11892_2008"]},{"id":931576,"enunciado":"Nos termos da lei que instituiu a Rede Federal de Educação Profissional, Científica e Tecnológica (Lei nº 11.892/2008), é finalidade dos Institutos Federais","opcoes":["ofertar programas de ensino, pesquisa e extensão e de divulgação científica e cultural.","realizar e estimular a pesquisa aplicada, a produção cultural, o empreendedorismo, o cooperativismo e o desenvolvimento científico e tecnológico.","promover a produção, o desenvolvimento e a transferência de tecnologias culturais, notadamente as voltadas ao comércio e às atividades industriais.","fomentar atividades com vistas à atuação profissional nos diversos setores da economia."],"correta":1,"explicacao":"Gabarito: <strong>realizar e estimular a pesquisa aplicada, a produção cultural, o empreendedorismo, o cooperativismo e o desenvolvimento científico e tecnológico.</strong>.","banca":"COMPERVE - UFRN","ano":2017,"temas_relacionados":["lei_11892_2008"]},{"id":933908,"enunciado":"Tendo por base a legislação e as práticas relativas à licitação, julgue o item subsequente.\n\n\nOs serviços de publicidade no âmbito dos diversos entes da Federação serão prestados necessariamente por intermédio de agências de propaganda.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":943843,"enunciado":"Luiz Antonio é Doutor em Filosofia e Professor do quadro de pessoal ativo permanente do IFRS, posicionado na Classe D III da Carreira do Magistério do Ensino Básico, Técnico e Tecnológico, contando com 6 (seis) anos de efetivo exercício na Instituição. A par das informações, com base na Lei de criação dos Institutos Federais nº 11.892/2008, assinale a alternativa CORRETA:","opcoes":["Considerando que ainda não alcançou a Classe DIV da Carreira do Magistério do Ensino Básico, Técnico e Tecnológico, Luiz Antonio não está apto a candidatar-se ao cargo de Reitor.","Luiz Antonio preenche o(s) requisito(s) legal(is) para candidatar-se ao cargo de Reitor do IFRS.","Luiz Antonio não poderá candidatar-se ao cargo em razão de ainda não ter alcançado a Classe DV da Carreira do Magistério do Ensino Básico, Técnico e Tecnológico.","Muito embora atenda aos requisitos de titulação e posicionamento na carreira, Luiz Antonio ainda não possui o tempo mínimo de efetivo exercício necessário à candidatura.","Para candidatar-se ao cargo de Reitor, Luiz Antonio deverá atender cumulativamente a dois requisitos: possuir o título de Doutor e estar posicionado na Classe DIV da Carreira do Magistério do Ensino Básico, Técnico e Tecnológico."],"correta":1,"explicacao":"Gabarito: <strong>Luiz Antonio preenche o(s) requisito(s) legal(is) para candidatar-se ao cargo de Reitor do IFRS.</strong>.","banca":"IF-RS","ano":2018,"temas_relacionados":["lei_11892_2008"]},{"id":945320,"enunciado":"De acordo com o disposto nos artigos 7º e 8º da Lei nº 11.892 de 29 de dezembro de 2008 - Institui a Rede Federal de Educação Profissional, Científica e Tecnológica, cria os Institutos Federais de Educação, Ciência e Tecnologia, e dá outras providências, o Instituto Federal, em cada exercício, deverá garantir o mínimo de: I. 30% (trinta por cento) de suas vagas para atender à educação profissional técnica de nível médio, prioritariamente na forma de cursos integrados, para os concluintes do ensino fundamental e para o público da educação de jovens e adultos. II. 50% (cinquenta por cento) de suas vagas para atender à educação profissional técnica de nível médio, prioritariamente na forma de cursos integrados, para os concluintes do ensino fundamental e para o público da educação de jovens e adultos. III. 20% (vinte por cento) de suas vagas para atender aos cursos de licenciatura, bem como programas especiais de formação pedagógica, com vistas na formação de professores para a educação básica, sobretudo nas áreas de ciências e matemática, e para a educação profissional. IV. 20% (vinte por cento) de suas vagas para atender aos cursos superiores de tecnologia visando à formação de profissionais para os diferentes setores da economia. Das afirmativas propostas:","opcoes":["Estão corretas I e III.","Estão corretas I e IV.","Estão corretas II e III.","Estão corretas II e IV."],"correta":2,"explicacao":"Gabarito: <strong>Estão corretas II e III.</strong>.","banca":"IF-SP","ano":2018,"temas_relacionados":["lei_11892_2008"]},{"id":946231,"enunciado":"De acordo com a Lei nº 11.892/2008, que instituiu a Rede Federal de Educação Profissional, Científica e Tecnológica, é correto afirmar que","opcoes":["o Colégio Pedro II terá a mesma estrutura e organização dos Institutos Federais de Educação, Ciência e Tecnologia.","os Institutos Federais terão como órgãos executivos a Procuradoria e a Reitoria, sendo esta composta por 1 (um) Reitor e 6 (seis) Pró-Reitores.","os Reitores serão nomeados pelo Ministro da Educação, para mandato de 2 (dois) anos, permitida uma recondução, após processo de consulta à comunidade escolar do respectivo Instituto Federal","a reitoria, por se tratar de órgão de administração central, deverá ser instalada no espaço físico de qualquer dos campi que integram o Instituto Federal, desde que previsto em seu estatuto e aprovado pelo Conselho Superior."],"correta":0,"explicacao":"Gabarito: <strong>o Colégio Pedro II terá a mesma estrutura e organização dos Institutos Federais de Educação, Ciência e Tecnologia.</strong>.","banca":"Colégio Pedro II","ano":2017,"temas_relacionados":["lei_11892_2008"]},{"id":947335,"enunciado":"A Lei de criação dos Institutos Federais (Lei nº 11.892, de 29 de dezembro de 2008) dispõe sobre diversos aspectos dessas organizações, inclusive do Instituto Federal de Educação, Ciência e Tecnologia de São Paulo (IFSP). Sobre a estrutura organizacional dos Institutos, é possível afirmar que:","opcoes":["O Colégio de Dirigentes, de caráter consultivo, será composto pelo Reitor, pelos Pró-Reitores e pelo Diretor-Geral de cada um dos campi que integram o Instituto Federal.","O Conselho Superior, de caráter consultivo, será composto por representantes dos docentes, dos estudantes, dos servidores técnico-administrativos, dos egressos da instituição, da sociedade civil, do Ministério da Educação e do Colégio de Dirigentes do Instituto Federal, assegurando-se a representação paritária dos segmentos que compõem a comunidade acadêmica.","A reitoria, como órgão de administração central, deverá ser instalada em espaço físico distinto de qualquer dos campi que integram o Instituto Federal.","Poderão ser nomeados Pró-Reitores apenas os servidores ocupantes de cargo efetivo da carreira docente, desde que possuam o mínimo de 5 (cinco) anos de efetivo exercício em instituição federal de educação profissional e tecnológica."],"correta":0,"explicacao":"Gabarito: <strong>O Colégio de Dirigentes, de caráter consultivo, será composto pelo Reitor, pelos Pró-Reitores e pelo Diretor-Geral de cada um dos campi que integram o Instituto Federal.</strong>.","banca":"IF-SP","ano":2018,"temas_relacionados":["lei_11892_2008"]},{"id":961567,"enunciado":"De acordo com a Lei nº 11.892/2008, uma das finalidades dos Institutos Federais é","opcoes":["promover a horizontalização da educação básica com a educação profissional e a educação superior, otimizando exclusivamente a infraestrutura física e os quadros de pessoal.","orientar sua formação em benefício do fortalecimento dos arranjos produtivos, com perspectiva prioritária de lucro para empresas e cooperativas locais.","constituir-se em centro de excelência na oferta do ensino de ciências, em geral, e de matemática e língua portuguesa, em particular.","desenvolver programas de pesquisa pura e aplicada, de extensão e de divulgação científica e tecnológica, além de serviços remunerados.","promover a produção, o desenvolvimento e a transferência de tecnologias sociais, notadamente as voltadas à preservação do meio ambiente."],"correta":4,"explicacao":"Gabarito: <strong>promover a produção, o desenvolvimento e a transferência de tecnologias sociais, notadamente as voltadas à preservação do meio ambiente.</strong>.","banca":"FADESP","ano":2018,"temas_relacionados":["lei_11892_2008"]},{"id":963654,"enunciado":"A Lei nº 11.892, de 29 de dezembro de 2008, institui a Rede Federal de Educação Profissional, Científica e Tecnológica e cria os Institutos Federais de Educação, Ciência e Tecnologia. Segundo o que dispõe o referido diploma legal, marque a assertiva CORRETA.","opcoes":["Suponha que determinado Instituto Federal a que se refere a Lei n° 11.892/08, em nível de educação superior, ministre 10% dos seus cursos em licenciatura, bem como programas especiais de formação pedagógica. Nessa situação hipotética, o referido percentual atende aos limites mínimos previstos no diploma legal ora citado.","É lícita a nomeação para o cargo de Reitor do Instituto Federal de Mato Grosso do Sul o Servidor da Carreira dos Cargos Técnico-Administrativos em Educação que possua título de doutor e o mínimo de 5 (cinco) anos de efetivo exercício na instituição.","Um dos objetivos dos Institutos Federais é o de ministrar preponderantemente a educação superior e de forma secundária a educação profissional técnica de nível médio, cujo percentual de cursos não poderá exceder a 50% de suas vagas.","Os Institutos Federais têm por finalidade desenvolver a educação profissional e tecnológica como processo educativo e investigativo de geração e adaptação de soluções técnicas e tecnológicas às demandas sociais e peculiaridades regionais, bem como promover a integração e a verticalização da educação básica à educação profissional e educação superior, otimizando a infraestrutura física, os quadros de pessoal e os recursos de gestão.","Os Institutos Federais têm por finalidade a promoção do ensino médio, prioritariamente na forma de cursos integrados. Por esse motivo, as instituições que compõem a Rede Federal a que se refere a Lei nº 11.892/08 devem se abster de realizar e estimular a pesquisa aplicada."],"correta":3,"explicacao":"Gabarito: <strong>Os Institutos Federais têm por finalidade desenvolver a educação profissional e tecnológica como processo educativo e investigativo de geração e adaptação de soluções técnicas e tecnológicas às demandas sociais e peculiaridades regionais, bem como promover a integração e a verticalização da educação básica à educação profissional e educação superior, otimizando a infraestrutura física, os quadros de pessoal e os recursos de gestão.</strong>.","banca":"IF-MS","ano":2019,"temas_relacionados":["lei_11892_2008"]},{"id":963704,"enunciado":"A Lei nº 11.892/2008, além de instituir a Rede Federal de Educação Profissional, Científica e Tecnológica, criou os Institutos Federais de Educação, Ciência e Tecnologia. Com base no disposto na Lei nº 11.892/2008, assinale a alternativa CORRETA:","opcoes":["Os Reitores serão nomeados pelo Presidente da República, para mandato de 5 (cinco) anos, vedada a recondução.","A candidatura aos cargos de Reitor e de Diretor-Geral é restrita aos servidores ocupantes de cargo efetivo da carreira docente.","A administração dos Institutos Federais terá como órgãos superiores o Conselho Superior e a Assembleia de Diretores.","O Instituto Federal de Mato Grosso do Sul foi criado mediante integração da Escola Técnica Federal de Mato Grosso do Sul e da Escola Agrotécnica Federal de Nova Andradina.","Os Institutos Federais terão como órgão executivo a reitoria, composta por 1 (um) Reitor, 1 (um) Vice-Reitor e 5 (cinco) Pró-Reitores."],"correta":3,"explicacao":"Gabarito: <strong>O Instituto Federal de Mato Grosso do Sul foi criado mediante integração da Escola Técnica Federal de Mato Grosso do Sul e da Escola Agrotécnica Federal de Nova Andradina.</strong>.","banca":"IF-MS","ano":2019,"temas_relacionados":["lei_11892_2008"]},{"id":964738,"enunciado":"De acordo com a Lei de Criação dos Institutos Federais (Lei nº 11.892, de 29 de dezembro de 2008), analise as assertivas abaixo no tocante aos objetivos, finalidades, características e estrutura organizacional dos Institutos Federais: I – desenvolver a educação profissional e tecnológica como processo educativo e investigativo de geração e adaptação de soluções técnicas e tecnológicas às demandas sociais e peculiaridades regionais. II – promover a interiorização e a horizontalização da educação básica à educação profissional e educação superior, otimizando a infraestrutura física, os quadros de pessoal e os recursos de gestão. III – realizar e estimular a pesquisa aplicada, a produção cultural, o empreendedorismo, o cooperativismo e o desenvolvimento científico e tecnológico. IV – desenvolver programas de extensão e de divulgação científica e tecnológica. Marque a alternativa que apresenta somente assertiva(s) CORRETA(S).","opcoes":["Apenas I.","Apenas II.","Apenas I e III.","Apenas II e III.","Apenas I, III e IV."],"correta":4,"explicacao":"Gabarito: <strong>Apenas I, III e IV.</strong>.","banca":"IF-ES","ano":2019,"temas_relacionados":["lei_11892_2008"]},{"id":964789,"enunciado":"De acordo com a Lei nº 11.892/2008, que institui a Rede Federal de Educação Profissional, Científica e Tecnológica, que cria os Institutos Federais de Educação, Ciência e Tecnologia, assinale a alternativa INCORRETA:","opcoes":["Os Reitores serão nomeados pelo Ministro de Educação, para mandato de 5 (cinco) anos, permitida uma recondução, após processo de consulta à comunidade escolar do respectivo Instituto Federal, atribuindo-se o peso de 1/3 (um terço) para a manifestação do corpo docente, de 1/3 (um terço) para a manifestação dos servidores técnico-administrativos e de 1/3 (um terço) para a manifestação do corpo discente.","Cada Instituto Federal é organizado em estrutura multicampi, com proposta orçamentária anual identificada para cada campus e a reitoria, exceto no que diz respeito a pessoal, encargos sociais e benefícios aos servidores.","A administração dos Institutos Federais terá como órgãos superiores o Colégio de Dirigentes e o Conselho Superior, cujas presidências serão exercidas pelo Reitor do Instituto Federal.","Poderão ser nomeados Pró-Reitores os servidores ocupantes de cargo efetivo da Carreira docente ou de cargo efetivo com nível superior da Carreira dos técnico-administrativos do Plano de Carreira dos Cargos Técnico-Administrativos em Educação, desde que possuam o mínimo de 5 (cinco) anos de efetivo exercício em instituição federal de educação profissional e tecnológica.","Constituir-se em centro de excelência na oferta do ensino de ciências, em geral, e de ciências aplicadas, em particular, estimulando o desenvolvimento de espírito crítico, voltado à investigação empírica, é uma das finalidades e características dos Institutos Federais."],"correta":0,"explicacao":"Gabarito: <strong>Os Reitores serão nomeados pelo Ministro de Educação, para mandato de 5 (cinco) anos, permitida uma recondução, após processo de consulta à comunidade escolar do respectivo Instituto Federal, atribuindo-se o peso de 1/3 (um terço) para a manifestação do corpo docente, de 1/3 (um terço) para a manifestação dos servidores técnico-administrativos e de 1/3 (um terço) para a manifestação do corpo discente.</strong>.","banca":"IF-ES","ano":2019,"temas_relacionados":["lei_11892_2008"]},{"id":965068,"enunciado":"Após processo de consulta à comunidade do IFSP, a servidora Carla foi quem obteve o maior índice de votos dentre todos os candidatos para o cargo de Diretor Geral do Campus Itapetininga. Carla possui título de doutora e é Professora do Ensino Básico, Técnico e Tecnológico do quadro permanente do IFSP há cinco anos, tendo exercido cargo de gestão de Diretora Educacional do Câmpus Itapetininga nos últimos dois anos. Nessas condições, a nomeação de Carla para o cargo de Diretora Geral do câmpus Itapetinga:","opcoes":["Cumpre todos os requisitos estabelecidos na lei nº 11.892/2008, podendo Carla ser nomeada por ato do Reitor.","Não cumpre o período mínimo de três anos em cargo de gestão na Instituição, razão pela qual Carla não poderá ser nomeada para o cargo.","Não poderá ser nomeada para o cargo de Diretora Geral do Câmpus, por ter ocupado cargo de gestão no último ano.","Deverá ser referendada pelo Conselho Superior do IFSP, podendo este negar-se a realizar a nomeação."],"correta":0,"explicacao":"Gabarito: <strong>Cumpre todos os requisitos estabelecidos na lei nº 11.892/2008, podendo Carla ser nomeada por ato do Reitor.</strong>.","banca":"IF-SP","ano":2019,"temas_relacionados":["lei_11892_2008"]},{"id":965069,"enunciado":"Com base na lei nº 11.892/2008, escolha a alternativa que preencha corretamente as lacunas da afirmação abaixo: No desenvolvimento da sua ação acadêmica, o Instituto Federal, em cada exercício, deverá garantir o mínimo de ______ de suas vagas para a educação profissional técnica de nível médio, prioritariamente na forma de cursos integrados, para os concluintes do ensino fundamental e para o público da educação de jovens e adultos e o mínimo de 20% de suas vagas para cursos de____________.","opcoes":["20% (vinte por cento) / bacharelado e engenharia, visando à formação de profissionais para os diferentes setores da economia e áreas do conhecimento.","50% (cinquenta por cento) / bacharelado e engenharia, visando à formação de profissionais para os diferentes setores da economia e áreas do conhecimento.","30% (trinta por cento) / licenciatura, bem como programas especiais de formação pedagógica, com vistas na formação de professores para a educação básica, sobretudo nas áreas de ciências e matemática, e para a educação profissional.","50% (cinquenta por cento) / licenciatura, bem como programas especiais de formação pedagógica, com vistas na formação de professores para a educação básica, sobretudo nas áreas de ciências e matemática, e para a educação profissional."],"correta":3,"explicacao":"Gabarito: <strong>50% (cinquenta por cento) / licenciatura, bem como programas especiais de formação pedagógica, com vistas na formação de professores para a educação básica, sobretudo nas áreas de ciências e matemática, e para a educação profissional.</strong>.","banca":"IF-SP","ano":2019,"temas_relacionados":["lei_11892_2008"]},{"id":970660,"enunciado":"Com base na Lei nº. 11.892/08, a qual dispõe sobre a criação dos Institutos Federais de Educação, Ciência e Tecnologia, julgue os itens a seguir. I - Os Institutos Federais têm como uma de suas finalidades e características, ministrar cursos de formação inicial e continuada de trabalhadores, objetivando a capacitação, o aperfeiçoamento, a especialização e a atualização de profissionais, em todos os níveis de escolaridade, nas áreas da educação profissional e tecnológica. II - Os Institutos Federais possuem como um de seus objetivos, orientar sua oferta formativa em benefício da consolidação e fortalecimento dos arranjos produtivos, sociais e culturais locais, identificados com base no mapeamento das potencialidades de desenvolvimento socioeconômico e cultural no âmbito de atuação do Instituto Federal. III - Os Reitores serão nomeados pelo Presidente da República, para mandato de 4 (quatro) anos, permitida uma recondução, após processo de consulta à comunidade escolar do respectivo Instituto Federal, atribuindo-se o peso de 1/3(um terço) para a manifestação do corpo docente, de 1/3 (um terço) para a manifestação dos servidores técnicos-administrativos e de 1/3 (um terço) para a manifestação do corpo discente. IV - Poderão ser nomeados Pró-Reitores os servidores ocupantes de cargos efetivo da Carreira docente ou de cargo efetivo com nível superior da Carreira dos técnico-administrativos do Plano de Carreira dos Cargos Técnico-Administrativos em Educação, desde que possuam o mínimo de 4 (quatro) anos de efetivo exercício em instituição federal de educação profissional e tecnológica. A quantidade de itens INCORRETOS é igual a:","opcoes":["0.","1.","2.","3.","4."],"correta":3,"explicacao":"Gabarito: <strong>3.</strong>.","banca":"IF-PA","ano":2019,"temas_relacionados":["lei_11892_2008"]},{"id":972194,"enunciado":"Quanto à Lei n.º 4.769/1965, julgue o item\n\n\n\n\nOs Conselhos Regionais aplicarão penalidades aos infratores, podendo ser, entre outras, a de multa de 5% a 50% do maior salário mínimo vigente no País.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":972195,"enunciado":"Quanto à Lei n.º 4.769/1965, julgue o item\n\n\n\n\nA falta do registro não torna ilegal o exercício da profissão de técnico de administração.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":993794,"enunciado":"Com relação aos Institutos Federais, analise as assertivas abaixo: I. Os Institutos Federais, para efeito da incidência das disposições que regem a regulação, avaliação e supervisão das instituições e dos cursos de educação superior, são equiparados às universidades federais. II. Os Institutos Federais são organizados em estrutura multicampi, com proposta orçamentária anual identificada para cada campus e a reitoria, exceto no que diz respeito a pessoal, encargos sociais e benefícios aos servidores. III. O Colégio de Dirigentes, de caráter deliberativo, será composto pelo Reitor, pelos Pró-Reitores e pelo Diretor-Geral de cada um dos campi que integram o Instituto Federal. IV. Os Institutos Federais terão como órgão executivo a reitoria, composta por 1 (um) Reitor e 6 (seis) Pró-Reitores. Estão corretas apenas as afirmativas","opcoes":["I e II.","II e IV.","II e III.","I e IV."],"correta":0,"explicacao":"Gabarito: <strong>I e II.</strong>.","banca":"IF Sul Rio-Grandense","ano":2019,"temas_relacionados":["lei_11892_2008"]},{"id":995654,"enunciado":"Conforme dispõe a Lei nº 11.892/2008, que instituiu a Rede Federal de Educação Profissional, Científica e Tecnológica, a administração dos Institutos Federais terá como órgãos superiores","opcoes":["a Ouvidoria e a Corregedoria.","o Conselho Superior e a Reitoria.","o Colégio de Dirigentes e a Reitoria.","o Colégio de Dirigentes e o Conselho Superior."],"correta":3,"explicacao":"Gabarito: <strong>o Colégio de Dirigentes e o Conselho Superior.</strong>.","banca":"Colégio Pedro II","ano":2017,"temas_relacionados":["lei_11892_2008"]},{"id":997465,"enunciado":"Segundo a Lei nº 11.892/2008, que institui a Rede Federal de Educação Profissional, Científica e Tecnológica e cria os Institutos Federais de Educação, Ciência e Tecnologia, no que se refere aos objetivos dos Institutos Federais, marque a alternativa incorreta:","opcoes":["O Colégio Pedro II terá a mesma estrutura e organização dos Institutos Federais de Educação, Ciência e Tecnologia.","A administração dos Institutos Federais terá como órgãos superiores o Colégio de Dirigentes e o Conselho Superior.","Os Institutos Federais têm por finalidades e características desenvolver a educação profissional e tecnológica como processo educativo e investigativo de geração e adaptação de soluções técnicas e tecnológicas às demandas sociais e peculiaridades regionais.","As presidências do Colégio de Dirigentes e do Conselho Superior serão exercidas pelo Pró-Reitor de Ensino do Instituto Federal.","Os Institutos Federais terão como órgão executivo a Reitoria, composta por 1 (um) Reitor e 5 (cinco) Pró-Reitores."],"correta":3,"explicacao":"Gabarito: <strong>As presidências do Colégio de Dirigentes e do Conselho Superior serão exercidas pelo Pró-Reitor de Ensino do Instituto Federal.</strong>.","banca":"IF-TO","ano":2019,"temas_relacionados":["lei_11892_2008"]},{"id":997575,"enunciado":"Segundo a Lei nº 11.892/2008, que institui a Rede Federal de Educação Profissional, Científica e Tecnológica e cria os Institutos Federais de Educação, Ciência e Tecnologia, no que se refere aos objetivos dos Institutos Federais, julgue os itens a seguir: I. Constitui objetivo realizar pesquisas aplicadas, estimulando o desenvolvimento de soluções técnicas e tecnológicas, estendendo seus benefícios à comunidade. II. Constitui objetivo estimular e apoiar processos educativos que levem à geração de trabalho e renda e à emancipação do cidadão na perspectiva do desenvolvimento socioeconômico local e regional. III. Constitui objetivo ministrar, em nível de educação superior, cursos superiores de tecnologia, visando à formação de profissionais para os diferentes setores da economia. IV. Constitui objetivo desenvolver atividades de extensão de acordo com os princípios e finalidades da educação profissional e tecnológica, em articulação com o mundo do trabalho e os segmentos sociais, e com ênfase na produção, desenvolvimento e difusão de conhecimentos científicos e tecnológicos.","opcoes":["Apenas o item IV está correto.","Apenas o item I está correto.","Apenas os itens I, II e IV estão corretos.","Apenas o item II e III estão corretos.","Todas os itens estão corretos."],"correta":4,"explicacao":"Gabarito: <strong>Todas os itens estão corretos.</strong>.","banca":"IF-TO","ano":2019,"temas_relacionados":["lei_11892_2008"]},{"id":999179,"enunciado":"A respeito dos Institutos Federais (Lei 11.892/2008), assinale a alternativa correta.","opcoes":["Os Reitores serão nomeados pelo Presidente da República, para mandato de dois anos, permitida uma recondução.","Cada Instituto Federal é organizado em estrutura multicampi, com proposta orçamentária anual identificada para cada campus e a Reitoria, inclusive no que diz respeito a pessoal, encargos sociais e benefícios aos servidores.","Os Institutos Federais terão como órgãos superiores a Reitoria e o Colégio de Docentes.","Os Reitores serão nomeados pelo Presidente da República, para mandato de quatro anos, vedada a recondução.","Os bens e direitos do Instituto Federal serão utilizados ou aplicados, exclusivamente, para a consecução de seus objetivos, não podendo ser alienados a não ser nos casos e condições permitidos em lei."],"correta":4,"explicacao":"Gabarito: <strong>Os bens e direitos do Instituto Federal serão utilizados ou aplicados, exclusivamente, para a consecução de seus objetivos, não podendo ser alienados a não ser nos casos e condições permitidos em lei.</strong>.","banca":"IDECAN","ano":2019,"temas_relacionados":["lei_11892_2008"]},{"id":999181,"enunciado":"Com base na Lei 11.892/2008, que instituiu a Rede Federal de Educação Profissional, Científica e Tecnológica, assinale a afirmativa incorreta.","opcoes":["A Rede Federal de Educação Profissional, Científica e Tecnológica não é vinculada ao Ministério da Economia.","Os Institutos Federais não poderão exercer o papel de instituições acreditadoras e certificadoras de competências profissionais.","Os Institutos Federais terão autonomia para criar e extinguir cursos, nos limites de sua área de atuação territorial, bem como para registrar diplomas dos cursos por eles oferecidos, mediante autorização do seu Conselho Superior.","Os Institutos Federais são instituições de educação superior, básica e profissional, pluricurriculares e multicampi.","É possível a oferta de cursos a distância pelos Institutos Federais."],"correta":1,"explicacao":"Gabarito: <strong>Os Institutos Federais não poderão exercer o papel de instituições acreditadoras e certificadoras de competências profissionais.</strong>.","banca":"IDECAN","ano":2019,"temas_relacionados":["lei_11892_2008"]},{"id":1018370,"enunciado":"Conforme o Plano de Desenvolvimento Institucional (PDI) 2015/2019 do IFSC, sabe-se que a Instituição busca “Promover a inclusão e formar cidadãos, por meio da educação profissional, científica e tecnológica, gerando, difundindo e aplicando conhecimento e inovação, contribuindo para o desenvolvimento socioeconômico e cultural” (IFSC, 2017, 1.6). Este trecho corresponde a: IFSC. Plano de desenvolvimento Institucional 2015-2019. Florianópolis, 2017.","opcoes":["Missão do IFSC.","Valores do IFSC.","Visão do IFSC.","Finalidades do IFSC.","Objetivos do IFSC."],"correta":0,"explicacao":"Gabarito: <strong>Missão do IFSC.</strong>.","banca":"IF-SC","ano":2019,"temas_relacionados":["lei_11892_2008"]},{"id":1027590,"enunciado":"De acordo com a Lei 11.892/2008, assinale a alternativa INCORRETA. Algumas das finalidades e características dos Institutos Federais são:","opcoes":["Ofertar educação profissional e tecnológica, em todos os seus níveis e modalidades, formando e qualificando cidadãos com vistas à atuação profissional nos diversos setores da economia, com ênfase somente no desenvolvimento socioeconômico local.","Desenvolver a educação profissional e tecnológica como processo educativo e investigativo de geração e adaptação de soluções técnicas e tecnológicas às demandas sociais e peculiaridades regionais.","Promover a integração e a verticalização da educação básica à educação profissional e educação superior, otimizando a infraestrutura física, os quadros de pessoal e os recursos de gestão.","Orientar sua oferta formativa em benefício da consolidação e fortalecimento dos arranjos produtivos, sociais e culturais locais, identificados com base no mapeamento das potencialidades de desenvolvimento socioeconômico e cultural no âmbito de atuação do Instituto Federal.","Constituir-se em centro de excelência na oferta do ensino de ciências, em geral, e de ciências aplicadas, em particular, estimulando o desenvolvimento de espírito crítico, voltado à investigação empírica."],"correta":0,"explicacao":"Gabarito: <strong>Ofertar educação profissional e tecnológica, em todos os seus níveis e modalidades, formando e qualificando cidadãos com vistas à atuação profissional nos diversos setores da economia, com ênfase somente no desenvolvimento socioeconômico local.</strong>.","banca":"IF-MT","ano":2019,"temas_relacionados":["lei_11892_2008"]},{"id":1030923,"enunciado":"Em relação à administração direta e indireta, julgue o item.\n\n\n\n\nSociedade de economia mista é a entidade criada por lei para a exploração de atividade econômica, sob a forma de sociedade anônima, cujas ações com direito a voto pertençam, em sua maioria, à União ou à entidade da administração indireta.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1033866,"enunciado":"A partir da Lei Federal n.º 3.268/1957 e do Decreto n.º 44.045/1958, julgue o item.\n\n\n\n\nOs Conselhos Regionais de Medicina são associações civis sem fins lucrativos, com autonomia administrativa e financeira.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1033867,"enunciado":"A partir da Lei Federal n.º 3.268/1957 e do Decreto n.º 44.045/1958, julgue o item.\n\n\n\n\nA Diretoria do Conselho Regional é composta de presidente, vice‐presidente, primeiro e segundo secretários e tesoureiro.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1033868,"enunciado":"A partir da Lei Federal n.º 3.268/1957 e do Decreto n.º 44.045/1958, julgue o item.\n\n\n\n\nO pedido de inscrição do médico deverá ser dirigido ao presidente do competente Conselho Regional de Medicina, com declaração da faculdade de medicina na qual se formou, sendo obrigatório o reconhecimento da firma do requerente.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1033869,"enunciado":"A partir da Lei Federal n.º 3.268/1957 e do Decreto n.º 44.045/1958, julgue o item.\n\n\n\n\nAs penas disciplinares aplicáveis aos infratores da ética profissional são advertência confidencial ou pública, suspensão do exercício profissional e cassação do exercício profissional.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1033870,"enunciado":"A partir da Lei Federal n.º 3.268/1957 e do Decreto n.º 44.045/1958, julgue o item.\n\n\n\n\nO recurso ex‐officio será obrigatório nas decisões de que resultar cassação da autorização para o exercício profissional.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1038311,"enunciado":"Julgue o próximo item, com base na Lei n.º 11.419/2006.\n\n\n\n\nA referida lei está alinhada com os princípios de segurança da informação denominados disponibilidade, confidencialidade e integridade, na medida em que estabelece que os autos dos processos eletrônicos devem ser protegidos por meio de sistemas de segurança de acesso e armazenados em meio que garanta a preservação e integridade dos dados.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2019,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1038312,"enunciado":"Julgue o próximo item, com base na Lei n.º 11.419/2006.\n\n\n\n\nOs autos de processos devem ser conservados exclusivamente em meio eletrônico, eliminando-se toda documentação impressa e, consequentemente, a necessidade de armazenamento físico.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2019,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1038313,"enunciado":"Julgue o próximo item, com base na Lei n.º 11.419/2006.\n\n\n\n\nOs órgãos do Poder Judiciário devem utilizar apenas redes internas (intranets) para acesso aos processos eletrônicos, por questões de sigilo e segurança.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2019,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1038314,"enunciado":"Julgue o próximo item, com base na Lei n.º 11.419/2006.\n\n\n\n\nQuando for inviável realizar citação, intimação ou notificação por meio eletrônico, deve-se obedecer às regras ordinárias aplicáveis aos documentos físicos, devendo-se digitalizá-los e posteriormente destruí-los.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2019,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1055720,"enunciado":"No que se refere aos ministérios, julgue o iten.\n\nA criação e a extinção de ministérios, órgãos e autarquias deverá ocorrer mediante lei de iniciativa privativa do presidente da República e aprovada pelo Congresso Nacional.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1055721,"enunciado":"No que se refere aos ministérios, julgue o iten.\n\nA administração direta compreende as competências e os serviços integrados na estrutura administrativa da presidência da República e dos ministérios, assim como os órgãos dos Poderes Legislativo e Judiciário e do Ministério Público da União.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1055932,"enunciado":"A Lei nº 11.892, de 29 de dezembro de 2008, institui, no âmbito do Sistema Federal de Ensino, a Rede Federal de Educação Profissional, Científica e Tecnológica, vinculada ao Ministério da Educação. Compõem essa rede as seguintes instituições: I - Institutos Federais de Educação, Ciência e Tecnologia; II - Universidade Tecnológica Federal do Paraná – UTFPR; III - Centros Federais de Educação Tecnológica Celso Suckow da Fonseca - CEFET-RJ e de Minas Gerais - CEFET-MG; IV - Escolas Técnicas Vinculadas às Universidades Federais; e V - Colégio Pedro II. Especificamente sobre os Institutos Federais de Educação, Ciência e Tecnologia, é CORRETO afirmar que:","opcoes":["são instituições de educação superior, básica e profissional, pluricurriculares e multicampi, especializadas na oferta de educação profissional e tecnológica nas diferentes modalidades de ensino, com base na conjugação de conhecimentos técnicos e tecnológicos com as suas práticas pedagógicas, nos termos da legislação.","são entidades autárquicas vinculadas ao Ministério da Educação, configurando-se como instituições de ensino superior de currículo integral, especializadas na oferta de educação tecnológica nos diferentes níveis e modalidades de ensino, caracterizando-se pela atuação prioritária na área tecnológica, na forma da legislação.","configuram-se como escola técnica e universidade especializada, nos termos do parágrafo único do art. 52 da Lei no 9.394, de 20 de dezembro de 1996, regendo-se pelos princípios, finalidades e objetivos constantes da Lei no 11.184, de 7 de outubro de 2005.","possuem uma relação de Escolas Técnicas Vinculadas às Universidades Federais, organizadas regionalmente e aprovadas pelos conselhos municipais de educação.","não possuem, por serem vinculadas às Universidades Federais, natureza jurídica de autarquia, nem detenção de autonomia administrativa, patrimonial e financeira, ficando a seu cargo apenas as autonomias didático-pedagógica e disciplinar."],"correta":0,"explicacao":"Gabarito: <strong>são instituições de educação superior, básica e profissional, pluricurriculares e multicampi, especializadas na oferta de educação profissional e tecnológica nas diferentes modalidades de ensino, com base na conjugação de conhecimentos técnicos e tecnológicos com as suas práticas pedagógicas, nos termos da legislação.</strong>.","banca":"IF-PE","ano":2019,"temas_relacionados":["lei_11892_2008"]},{"id":1059183,"enunciado":"O Instituto Federal de Educação, Ciência e Tecnologia de Pernambuco (IFPE), em observância à Lei nº 11.892, de 29 de dezembro de 2008, a partir da Organização Acadêmica Institucional, nas modalidades presencial ou a distância, pode ministrar: I. Educação Profissional Técnica de Nível Médio. II. Educação Especial. III. Cursos de Formação Inicial e Continuada ou Qualificação Profissional. IV. Educação Superior em Tecnologia, Licenciatura e Bacharelado. V. Pós-Graduação Lato Sensu e Stricto Sensu de Mestrado e Doutorado. Estão CORRETAS, apenas, as afirmativas","opcoes":["I, III, IV e V.","I, II, III e IV.","III, IV e V.","I e II.","I e IV."],"correta":0,"explicacao":"Gabarito: <strong>I, III, IV e V.</strong>.","banca":"IF-PE","ano":2019,"temas_relacionados":["lei_11892_2008"]},{"id":1059191,"enunciado":"Sobre os níveis e modalidades de educação e ensino ministrados pelo Instituto Federal de Educação, Ciência e Tecnologia de Pernambuco (IFPE), em observância à Lei nº 11.892, de 29 de dezembro de 2008, analise as afirmativas a seguir. I O IFPE poderá ministrar Educação Profissional Técnica de Nível Médio, prioritariamente na forma de cursos integrados, para os concluintes do Ensino Fundamental e para o público da Educação de Jovens e Adultos. II O IFPE poderá ministrar Educação Profissional Técnica de Nível Médio, prioritariamente na forma de cursos subsequentes, para os concluintes do Ensino Fundamental e para o público da Educação de Jovens e Adultos. III O IFPE poderá ministrar cursos de Formação Inicial e Continuada ou Qualificação Profissional, objetivando a capacitação, o aperfeiçoamento, a especialização, a atualização de profissionais, em todos os níveis de escolaridade, nas áreas da Educação Profissional e Tecnológica. IV O IFPE poderá ministrar, em nível superior, cursos de: Tecnologia; Licenciatura e Programas de Formação Pedagógica; Bacharelado; Pós-Graduação Lato Sensu de Aperfeiçoamento e Especialização; Pós-Graduação Stricto Sensu de Mestrado e Doutorado. V O IFPE poderá ministrar Educação Profissional e Tecnológica, prioritariamente na forma de cursos inseridos nas atividades de Extensão, para os concluintes do Ensino Fundamental e para o público da Educação de Jovens e Adultos. Está(ão) CORRETA(S) apenas a(s) afirmativa(s)","opcoes":["I, III e IV.","I, II, III.","II, III, IV e V.","I.","III."],"correta":0,"explicacao":"Gabarito: <strong>I, III e IV.</strong>.","banca":"IF-PE","ano":2019,"temas_relacionados":["lei_11892_2008"]},{"id":1115276,"enunciado":"Lei nº 11.892, de 29/12/2008, que institui a Rede Federal de Educação Profissional, Científica e Tecnológica, cria os Institutos Federais de Educação, Ciência e Tecnologia, e dá outras providências, indica que os Institutos Federais têm por finalidades e características, dentre outras: I. promover a horizontalização da educação básica, dividindo-a em educação profissional, educação técnica e educação superior. II. realizar e estimular a pesquisa aplicada, a produção cultural, o empreendedorismo, o cooperativismo e o desenvolvimento científico e tecnológico. III. desenvolver programas de extensão e de divulgação científica e tecnológica. Está correto o que se afirma em:","opcoes":["I, II e III.","I e II, apenas.","II, apenas.","I e III, apenas.","II e III, apenas."],"correta":4,"explicacao":"Gabarito: <strong>II e III, apenas.</strong>.","banca":"IBADE","ano":2019,"temas_relacionados":["lei_11892_2008"]},{"id":1116482,"enunciado":"A Rede Federal de Educação Profissional foi criada pela Lei nº 11 .892, de 29/12/2008. A rede é composta por:","opcoes":["instituições que conjugam saberes técnicos, tecnológicos e pedagógicos.","instituições especializadas na oferta de educação a distância.","instituições de educação básica, sem oferta de educação superior.","instituições de educação superior, sem oferta de educação básica.","instituições vocacionados aos estudos de pós-graduação."],"correta":0,"explicacao":"Gabarito: <strong>instituições que conjugam saberes técnicos, tecnológicos e pedagógicos.</strong>.","banca":"IBADE","ano":2019,"temas_relacionados":["lei_11892_2008"]},{"id":1119299,"enunciado":"São finalidades e características dos Institutos Federais","opcoes":["promover a produção, o desenvolvimento e a transferência de tecnologias sociais, notadamente as voltadas à preservação da cultura e desporto.","ofertar educação profissional e tecnológica, em todos os seus níveis e modalidades, formando e qualificando cidadãos com vistas na atuação profissional nos diversos setores da economia, com ênfase apenas no desenvolvimento socioeconômico local e regional.","realizar e estimular a pesquisa aplicada, a produção cultural, o desenvolvimento científico e tecnológico, exceto o empreendedorismo e o cooperativismo.","promover a integração e a verticalização da educação básica à educação profissional e educação de nível médio, otimizando a infraestrutura física, os quadros de pessoal e os recursos de gestão.","desenvolver programas de extensão e de divulgação científica e tecnológica."],"correta":4,"explicacao":"Gabarito: <strong>desenvolver programas de extensão e de divulgação científica e tecnológica.</strong>.","banca":"IF Baiano","ano":2019,"temas_relacionados":["lei_11892_2008"]},{"id":1125151,"enunciado":"Com base nos dispositivos da Lei nº 11.892/2008, é correto afirmar que","opcoes":["a administração dos Institutos Federais terá como órgãos superiores a Reitoria e o Conselho Superior.","o Colégio Pedro II terá como órgãos executivos a Reitoria, composta por 1 (um) Reitor e 5 (cinco) Pró-Reitores; a Corregedoria; e a Procuradoria Federal.","o estatuto do Instituto Federal disporá sobre a estruturação, as competências e as normas de funcionamento do Colégio de Dirigentes e do Conselho Superior.","o Conselho Superior, de caráter consultivo, será composto pelo Reitor, pelos Pró-Reitores e pelo Diretor-Geral de cada um dos campi que integram o Instituto Federal."],"correta":2,"explicacao":"Gabarito: <strong>o estatuto do Instituto Federal disporá sobre a estruturação, as competências e as normas de funcionamento do Colégio de Dirigentes e do Conselho Superior.</strong>.","banca":"Colégio Pedro II","ano":2019,"temas_relacionados":["lei_11892_2008"]},{"id":1125909,"enunciado":"A Lei nº 11.892/2008 institui a Rede Federal de Educação Profissional, Científica e Tecnológica, cria os Institutos Federais de Educação, Ciência e Tecnologia, e dá outras providências. Após sofrer alterações no seu texto, a referida lei passou a estabelecer que “O Colégio Pedro II terá a mesma estrutura e organização dos Institutos Federais de Educação, Ciência e Tecnologia”. No que se refere aos seus dispositivos, é correto afirmar que","opcoes":["cada Instituto Federal é organizado em estrutura multicampi, com proposta orçamentária anual centralizada na Reitoria, inclusive no que diz respeito a pessoal, encargos sociais e benefícios aos servidores.","a administração dos Institutos Federais terá como órgãos superiores o Colégio de Dirigentes e o Conselho Superior, sendo este último composto pelo Reitor e pelo Diretor-Geral de cada um dos campi.","os Reitores serão nomeados pelo Presidente da República, para mandato de 4 (quatro) anos, permitida uma recondução, após processo de consulta à comunidade escolar do respectivo Instituto Federal.","os campi serão dirigidos por Diretores-Gerais, nomeados pelo Ministro da Educação para mandato de 2 (dois) anos, permitida uma recondução, após processo de consulta à comunidade escolar."],"correta":2,"explicacao":"Gabarito: <strong>os Reitores serão nomeados pelo Presidente da República, para mandato de 4 (quatro) anos, permitida uma recondução, após processo de consulta à comunidade escolar do respectivo Instituto Federal.</strong>.","banca":"Colégio Pedro II","ano":2019,"temas_relacionados":["lei_11892_2008"]},{"id":1126015,"enunciado":"A Lei nº 11.892/2008 institui a Rede Federal de Educação Profissional, Científica e Tecnológica, cria os Institutos Federais de Educação, Ciência e Tecnologia, e dá outras providências. No que se refere aos seus dispositivos, foram feitas as seguintes afirmativas: I. O Colégio Pedro II é equiparado aos Institutos Federais para efeito de incidência das disposições que regem a autonomia e a utilização dos instrumentos de gestão do quadro de pessoal e de ações de regulação, avaliação e supervisão das instituições e dos cursos de educação profissional e superior. II. Os Institutos Federais terão autonomia para criar e extinguir cursos, nos limites de sua área de atuação territorial, bem como para registrar diplomas dos cursos por eles oferecidos, mediante autorização do Ministério da Educação. III. O Colégio Pedro II é instituição federal de ensino, pluricurricular e multicampi, vinculada ao Ministério da Educação e especializada na oferta de educação básica e de licenciaturas. IV. No âmbito de sua atuação, as Universidades Federais exercerão o papel de instituições acreditadoras e certificadoras de competências profissionais. Estão corretas","opcoes":["I e II.","I e III.","II e III.","II e IV."],"correta":1,"explicacao":"Gabarito: <strong>I e III.</strong>.","banca":"Colégio Pedro II","ano":2019,"temas_relacionados":["lei_11892_2008"]},{"id":1145351,"enunciado":"De acordo com a Lei 11.892/2008, que criou os Institutos Federais, assinale a afirmativa incorreta.","opcoes":["É objetivo dos Institutos Federais, entre outros, realizar pesquisas aplicadas, estimulando o desenvolvimento de soluções técnicas e tecnológicas, estendendo seus benefícios à comunidade.","O Colégio Pedro II terá a mesma estrutura e organização dos Institutos Federais de Educação, Ciência e Tecnologia.","Poderão ser nomeados Pró-Reitores os servidores ocupantes de cargo efetivo da Carreira docente ou de cargo efetivo com nível superior da Carreira dos técnico-administrativos do Plano de Carreira dos Cargos Técnico-Administrativos em Educação, desde que possuam o mínimo de 5 (cinco) anos de efetivo exercício em instituição federal de educação profissional e tecnológica.","É necessário o título de mestre ou doutor para poder se candidatar ao cargo de Reitor.","É objetivo dos Institutos Federais, entre outros, estimular e apoiar processos educativos que levem à geração de trabalho e renda e à emancipação do cidadão na perspectiva do desenvolvimento socioeconômico local e regional."],"correta":3,"explicacao":"Gabarito: <strong>É necessário o título de mestre ou doutor para poder se candidatar ao cargo de Reitor.</strong>.","banca":"IDECAN","ano":2019,"temas_relacionados":["lei_11892_2008"]},{"id":1167530,"enunciado":"Segundo a Lei 11.892/08, são finalidades e características dos Institutos Federais, exceto","opcoes":["desenvolver programas de extensão e de divulgação científica e tecnológica.","realizar e estimular a pesquisa aplicada, a produção cultural, o empreendedorismo, o cooperativismo e o desenvolvimento científico e tecnológico.","ofertar educação profissional e tecnológica, em todos os seus níveis e modalidades, formando e qualificando cidadãos com vistas na atuação profissional nos diversos setores da economia, com ênfase apenas no desenvolvimento socioeconômico local e regional.","promover a produção, o desenvolvimento e a transferência de tecnologias sociais, notadamente as voltadas à preservação do meio ambiente.","promover a integração e a verticalização da educação básica à educação profissional e educação superior, otimizando a infraestrutura física, os quadros de pessoal e os recursos de gestão."],"correta":2,"explicacao":"Gabarito: <strong>ofertar educação profissional e tecnológica, em todos os seus níveis e modalidades, formando e qualificando cidadãos com vistas na atuação profissional nos diversos setores da economia, com ênfase apenas no desenvolvimento socioeconômico local e regional.</strong>.","banca":"IDECAN","ano":2019,"temas_relacionados":["lei_11892_2008"]},{"id":1177857,"enunciado":"Acerca dos ministérios e de suas áreas de competência e dos poderes e deveres do administrador público, julgue o item .\n\n\n\n\nAs unidades de planejamento e orçamento integrantes da estrutura do Poder Executivo são subordinadas ao Ministério do Planejamento do ponto de vista hierárquico e funcional.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1177859,"enunciado":"Acerca dos ministérios e de suas áreas de competência e dos poderes e deveres do administrador público, julgue o item .\n\n\n\n\nSe determinado Ministério pretender realizar operação de crédito externa, só poderá fazê‐lo após a manifestação da Comissão de Financiamentos Externos do Ministério da Economia.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1177862,"enunciado":"Acerca dos ministérios e de suas áreas de competência e dos poderes e deveres do administrador público, julgue o item .\n\n\n\n\nOs dirigentes dos órgãos integrantes dos sistemas de planejamento, de orçamentos, de contabilidade federal e de controle interno são proibidos de exercer profissão liberal.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1178365,"enunciado":"No que se refere aos ministérios e às respectivas áreas de competência, julgue o item .\n\n\n\n\nAs políticas sobre drogas, quanto à educação, à informação e à capacitação para a ação efetiva para a redução do uso indevido de drogas lícitas e ilícitas, estão a cargo do Ministério da Justiça.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1178366,"enunciado":"No que se refere aos ministérios e às respectivas áreas de competência, julgue o item .\n\n\n\n\nA regulação profissional e a fiscalização do trabalho estão a cargo do Ministério da Economia.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1262122,"enunciado":"Preencha corretamente as lacunas das frases a seguir com base nos dispositivos legais da Lei nº 11.892/2008, que institui a Rede Federal de Educação Profissional, Científica e Tecnológica e cria os Institutos Federais de Educação, Ciência e Tecnologia. O(A) _________________, de caráter consultivo, será composto(a) pelo Reitor, pelos Pró-Reitores e pelo Diretor-Geral de cada um dos campi que integram o Instituto Federal. O(A) _________________, de caráter consultivo e deliberativo, será composto(a) por representantes dos docentes, dos estudantes, dos servidores técnico-administrativos, dos egressos da instituição, da sociedade civil, do Ministério da Educação e do(a) _________________ do Instituto Federal, assegurando-se a representação paritária dos segmentos que compõem a comunidade acadêmica. A sequência que preenche corretamente as lacunas das frases é","opcoes":["Colégio de Dirigentes / Conselho Superior / Colégio de Dirigentes","Conselho Superior / Colégio de Dirigentes / Conselho Superior","Reitoria / Conselho Superior / Colégio de Dirigentes","Colégio de Dirigentes / Conselho Superior / Reitoria","Reitoria / Colégio de Dirigentes / Reitoria"],"correta":0,"explicacao":"Gabarito: <strong>Colégio de Dirigentes / Conselho Superior / Colégio de Dirigentes</strong>.","banca":"FCM","ano":2019,"temas_relacionados":["lei_11892_2008"]},{"id":1281361,"enunciado":"A estrutura organizacional dos institutos federais, de acordo com a Lei nº 11.892/2008, prevê que a administração dos mencionados institutos terá como órgãos superiores o Colégio de Dirigentes e o(a):","opcoes":["Secretaria de Educação Estadual.","Conselho Superior.","Poder Judiciário.","Ministério Público.","Secretaria de Desenvolvimento Humano."],"correta":1,"explicacao":"Gabarito: <strong>Conselho Superior.</strong>.","banca":"FUNDATEC","ano":2019,"temas_relacionados":["lei_11892_2008"]},{"id":1281362,"enunciado":"A Lei nº 11.892/2008 determina que são objetivos dos Institutos Federais: I. Ministrar educação profissional técnica de nível médio, prioritariamente na forma de cursos integrados, para os concluintes do ensino fundamental e para o público da educação de jovens e adultos. II. Ministrar cursos de formação inicial e continuada de trabalhadores, objetivando a capacitação, o aperfeiçoamento, a especialização e a atualização de profissionais, em todos os níveis de escolaridade, nas áreas da educação profissional e tecnológica. III. Ministrar, em nível de educação superior, cursos de pós-graduação stricto sensu de mestrado e doutorado, que contribuam para promover o estabelecimento de bases sólidas em educação, ciência e tecnologia, com vistas ao processo de geração e inovação tecnológica. Quais estão corretas?","opcoes":["Apenas I.","Apenas II.","Apenas I e II.","Apenas II e III.","I, II e III."],"correta":4,"explicacao":"Gabarito: <strong>I, II e III.</strong>.","banca":"FUNDATEC","ano":2019,"temas_relacionados":["lei_11892_2008"]},{"id":1281411,"enunciado":"A Lei nº 11.892/2008 determina que os institutos federais têm por finalidade e características realizar e estimular a ______________________, a produção cultural, o empreendedorismo, o cooperativismo e o desenvolvimento científico e tecnológico. Assinale a alternativa que preenche corretamente a lacuna do trecho acima.","opcoes":["transformação","inovação","criatividade","proatividade","pesquisa aplicada"],"correta":4,"explicacao":"Gabarito: <strong>pesquisa aplicada</strong>.","banca":"FUNDATEC","ano":2019,"temas_relacionados":["lei_11892_2008"]},{"id":1281412,"enunciado":"A Lei nº 11.892/2008 determina que os Institutos Federais terão órgão executivo, que será composto por:","opcoes":["Um conselho superior.","Uma reitoria geral, somente.","Um reitor e cinco pró-reitores.","Uma diretoria administrativa e fiscal.","Um diretor geral e secretarias administrativas."],"correta":2,"explicacao":"Gabarito: <strong>Um reitor e cinco pró-reitores.</strong>.","banca":"FUNDATEC","ano":2019,"temas_relacionados":["lei_11892_2008"]},{"id":1376919,"enunciado":"Nos termos da lei que instituiu a Rede Federal de Educação Profissional, Científica e Tecnológica (Lei nº 11.892/2008), analise as seguintes afirmativas acerca dos Institutos Federais: I No âmbito de sua atuação, os Institutos Federais exercerão o papel de instituições acreditadoras e certificadoras de competências profissionais. II Para efeito da incidência das disposições que regem a regulação, a avaliação e a supervisão das instituições e dos cursos de educação superior, os Institutos Federais são equiparados às universidades federais. III Os Institutos Federais terão autonomia para criar e extinguir cursos, mesmo fora dos limites de sua área de atuação territorial. IV Os Institutos Federais poderão conceder bolsas de ensino, desenvolvimento, educação e intercâmbio a alunos e pesquisadores vinculados a empresas públicas. Dentre as afirmativas, estão corretas","opcoes":["III e IV.","II e III.","I e IV.","I e II."],"correta":3,"explicacao":"Gabarito: <strong>I e II.</strong>.","banca":"COMPERVE - UFRN","ano":2017,"temas_relacionados":["lei_11892_2008"]},{"id":1377560,"enunciado":"Tendo como parâmetro o disposto na lei que instituiu a Rede Federal de Educação Profissional, Científica e Tecnológica (Lei nº 11.892/2008), os Institutos Federais","opcoes":["qualificam-se como centro de referência no apoio à oferta do ensino de ciências sociais nas instituições públicas de ensino, oferecendo capacitação técnica e atualização pedagógica aos docentes da rede privada de ensino.","qualificam-se como centro local de referência no apoio à oferta do ensino de ciências nas instituições públicas de ensino, oferecendo capacitação técnica e atualização pedagógica aos docentes das redes pública e privada de ensino.","constituem-se em centro local de excelência na oferta do ensino de ciências sociais, em geral, e de ciências aplicadas, em particular, estimulando o desenvolvimento de espírito crítico voltado à investigação técnica.","constituem-se em centro de excelência na oferta do ensino de ciências, em geral, e de ciências aplicadas, em particular, estimulando o desenvolvimento de espírito crítico voltado à investigação empírica."],"correta":3,"explicacao":"Gabarito: <strong>constituem-se em centro de excelência na oferta do ensino de ciências, em geral, e de ciências aplicadas, em particular, estimulando o desenvolvimento de espírito crítico voltado à investigação empírica.</strong>.","banca":"COMPERVE - UFRN","ano":2017,"temas_relacionados":["lei_11892_2008"]},{"id":1377561,"enunciado":"A Lei nº 11.892/2008 trata da estrutura organizacional dos Institutos Federais, dispondo que","opcoes":["os Institutos Federais terão como órgão consultivo a reitoria, composta por um Reitor e dez Pró-Reitores.","a administração central dos Institutos Federais terá como órgãos superiores o Conselho de Dirigentes e o Colégio Superior.","a reitoria poderá ser instalada em espaço físico distinto de qualquer dos campi que integram o Instituto Federal, mesmo que não previsto em seu estatuto ou aprovado pelo Ministério da Educação.","os Institutos Federais são organizados em estrutura multicampi, com proposta orçamentária anual identificada para cada campus e para a reitoria, exceto no que diz respeito a pessoal, encargos sociais e benefícios aos servidores."],"correta":3,"explicacao":"Gabarito: <strong>os Institutos Federais são organizados em estrutura multicampi, com proposta orçamentária anual identificada para cada campus e para a reitoria, exceto no que diz respeito a pessoal, encargos sociais e benefícios aos servidores.</strong>.","banca":"COMPERVE - UFRN","ano":2017,"temas_relacionados":["lei_11892_2008"]},{"id":1406227,"enunciado":"A Lei 11.892/2008, que institui a Rede Federal de Educação Profissional, Científica e Tecnológica e cria os Institutos Federais de Educação, Ciência e Tecnologia, estabelece, entre outros, os objetivos dos Institutos Federais. Marque abaixo qual das opções não é um objetivo dos Institutos Federais:","opcoes":["Ministrar educação profissional técnica de nível médio, prioritariamente na forma de cursos propedêuticos, para os concluintes do ensino fundamental e para o público da educação de jovens e adultos.","Ministrar cursos de formação inicial e continuada de trabalhadores, objetivando a capacitação, o aperfeiçoamento, a especialização e a atualização de profissionais, em todos os níveis de escolaridade, nas áreas da educação profissional e tecnológica.","Realizar pesquisas aplicadas, estimulando o desenvolvimento de soluções técnicas e tecnológicas, estendendo seus benefícios à comunidade.","Estimular e apoiar processos educativos que levem à geração de trabalho e renda e à emancipação do cidadão na perspectiva do desenvolvimento socioeconômico local e regional.","Ministrar em nível de educação superior: I) cursos superiores de tecnologia, visando à formação de profissionais para os diferentes setores da economia; II) cursos de licenciatura, bem como programas especiais de formação pedagógica, com vistas na formação de professores para a educação básica, sobretudo nas áreas de ciências e matemática, e para a educação profissional; III) cursos de bacharelado e engenharia, visando à formação de profissionais para os diferentes setores da economia e áreas do conhecimento."],"correta":0,"explicacao":"Gabarito: <strong>Ministrar educação profissional técnica de nível médio, prioritariamente na forma de cursos propedêuticos, para os concluintes do ensino fundamental e para o público da educação de jovens e adultos.</strong>.","banca":"IF-MT","ano":2020,"temas_relacionados":["lei_11892_2008"]},{"id":1612155,"enunciado":"Considerando a Lei nº 11.892/2008 e a história do IFSC analise as assertivas abaixo: I – é finalidade do IFSC ministrar educação profissional técnica de nível médio, prioritariamente na forma de cursos integrados, para os concluintes do ensino fundamental e para o público da educação de jovens e adultos; II – também é finalidade dos Institutos Federais ministrar cursos em nível de educação superior, incluindo cursos superiores de tecnologia, cursos de licenciatura, bacharelados e engenharias além de cursos de pós-graduação lato e stricto sensu; III – além de realizar pesquisas aplicadas, o IFSC deve desenvolver atividades de extensão de acordo com os princípios e finalidades da educação profissional e tecnológica, em articulação com as associações comerciais e industriais locais e movimentos sociais com ênfase na produção, desenvolvimento e comercialização de soluções científicas e tecnológicas; IV – as Escolas de Aprendizes Artífices, criadas em 1909, foram implementadas para oferta de cursos de formação inicial e continuada de nível técnico e de nível superior para os trabalhadores e filhos dos desfavorecidos da fortuna; V – O IFSC, ao longo de sua história, já teve as seguintes nomenclaturas e institucionalidades: CEFET-SC (década de 2000), ETF-SC (década de 1990) e UTF-SC (década de 1980). Está CORRETA a alternativa:","opcoes":["As assertivas I, III e V estão incorretas.","Somente I e V estão corretas.","Todas as assertivas estão corretas.","Todas as assertivas estão incorretas.","Somente I e II estão corretas."],"correta":4,"explicacao":"Gabarito: <strong>Somente I e II estão corretas.</strong>.","banca":"IF-SC","ano":2019,"temas_relacionados":["lei_11892_2008"]},{"id":1618816,"enunciado":"Considera-se objetivo dos Institutos Federais:","opcoes":["Desenvolver a educação profissional e tecnológica como processo educativo e investigativo.","Desenvolver programas de extensão e de divulgação científica e tecnológica.","Promover a produção, o desenvolvimento e a transferência de tecnologias sociais.","Orientar sua oferta formativa em benefício da consolidação e fortalecimento dos arranjos produtivos.","Realizar pesquisas aplicadas, estimulando o desenvolvimento de soluções técnicas e tecnológicas, estendendo seus benefícios à comunidade."],"correta":4,"explicacao":"Gabarito: <strong>Realizar pesquisas aplicadas, estimulando o desenvolvimento de soluções técnicas e tecnológicas, estendendo seus benefícios à comunidade.</strong>.","banca":"FAU","ano":2019,"temas_relacionados":["lei_11892_2008"]},{"id":1621250,"enunciado":"A lei n° 11.892/08 instituiu a Rede Federal de Educação Profissional, Científica e Tecnológica e criou os institutos Federais de Educação, Ciência e Tecnologia. Os Institutos Federais têm por finalidades e características","opcoes":["ofertar educação profissional e tecnológica, em todos os seus níveis e modalidades, formando e qualificando cidadãos com vistas à atuação profissional nos diversos setores da economia, com ênfase no desenvolvimento socioeconômico local, regional e nacional.","desenvolver a educação profissional e tecnológica como processo educativo e investigativo de geração e adaptação de soluções técnicas e tecnológicas às demandas sociais e peculiaridades nacionais e locais.","promover a interiorização da educação básica à educação profissional e educação superior, otimizando a infra estrutura física, os quadros de pessoal e os recursos de gestão.","orientar sua oferta formativa em benefício da consolidação e fortalecimento dos arranjos produtivos, sociais e culturais locais, identificados com base no mapeamento das potencialidades de desenvolvimento socioeconômico e cultura! no âmbito de atuação da lei de diretrizes da educação.","constituir-se em centro de excelência na oferta do ensino de engenharias, em geral, e de ciências aplicadas, em particular, estimulando o desenvolvimento do espírito crítico, voltado à investigação empírica."],"correta":0,"explicacao":"Gabarito: <strong>ofertar educação profissional e tecnológica, em todos os seus níveis e modalidades, formando e qualificando cidadãos com vistas à atuação profissional nos diversos setores da economia, com ênfase no desenvolvimento socioeconômico local, regional e nacional.</strong>.","banca":"IF-PI","ano":2019,"temas_relacionados":["lei_11892_2008"]},{"id":1621254,"enunciado":"Poderão candidatar-se ao cargo de Diretor-Geral do campus os servidores ocupantes de cargo efetivo da carreira docente ou de cargo efetivo de nível superior da carreira do servidor técnico-administrativo do Plano de Carreira dos Cargos Técnico-Administrativos em Educação, desde que possuam o mínimo de 5 (cinco) anos de efetivo exercício em instituição federal de educação profissional e tecnológica e que se enquadrem, em pelo menos, uma das seguintes situações:","opcoes":["preencher os requisitos exigidos para a candidatura ao cargo de Reitor do Instituto Federal.","possuir o mínimo de 3 (três) anos de exercício em cargo ou função de gestão na instituição.","ter concluído, com aproveitamento, curso de formação para o exercício de cargo ou função de liderança em instituições da administração pública","ter a qualificação de doutor ou mestre em administração pública.","ter sido promovido pelo menos uma vez num período de 5 anos."],"correta":0,"explicacao":"Gabarito: <strong>preencher os requisitos exigidos para a candidatura ao cargo de Reitor do Instituto Federal.</strong>.","banca":"IF-PI","ano":2019,"temas_relacionados":["lei_11892_2008"]},{"id":1621934,"enunciado":"A lei n° 11.892/2008 que institui a Rede Federal de Educação Profissional, Científica e Tecnológica e cria os Institutos Federais de Educação, Ciência e Tecnologia, apresenta a finalidade e as características dos Institutos Federais. Assinale a alternativa que não apresenta finalidade ou característica dos Institutos Federais:","opcoes":["realizar e estimular a pesquisa aplicada, a produção cultural, o empreendedorismo, o cooperativismo e o desenvolvimento científico e tecnológico;","ministrar cursos de formação inicial e continuada de trabalhadores, objetivando a capacitação, o aperfeiçoamento, a especialização e a atualização de profissionais, em todos os níveis de escolaridade, nas áreas da educação profissional e tecnológica;","desenvolver a educação profissional e tecnológica como processo educativo e investigativo de geração e adaptação de soluções técnicas e tecnológicas às demandas sociais e peculiaridades regionais;","promover a integração e a verticalização da educação básica à educação profissional e educação superior, otimizando a infraestrutura física, os quadros de pessoal e os recursos de gestão;","constituir-se em centro de excelência na oferta do ensino de ciências, em geral, e de ciências aplicadas, em particular, estimulando o desenvolvimento do espírito crítico, voltado à investigação empírica;"],"correta":1,"explicacao":"Gabarito: <strong>ministrar cursos de formação inicial e continuada de trabalhadores, objetivando a capacitação, o aperfeiçoamento, a especialização e a atualização de profissionais, em todos os níveis de escolaridade, nas áreas da educação profissional e tecnológica;</strong>.","banca":"IF-PI","ano":2019,"temas_relacionados":["lei_11892_2008"]},{"id":1621935,"enunciado":"Sobre a estrutura organizacional dos Institutos Federais, assinale a alternativa correta:","opcoes":["A administração dos Institutos Federais terá como órgãos superiores o Colégio de Dirigentes, o Conselho Superior e o Conselho Fiscal.","As presidências do Colégio de Dirigentes e do Conselho Superior serão exercidas pelo Reitor e vice-reitor do Instituto Federal, respectivamente.","Os Institutos Federais terão como órgão executivo a reitoria, composta por 1 (um) Reitor e 5 (cinco) Pró-Reitores.","Poderão ser nomeados Pró-Reitores os servidores ocupantes de cargo efetivo da Carreira docente, desde que possuam o mínimo de 2 (dois) anos de efetivo exercício em instituição federal de educação profissional e tecnológica.","Poderão candidatar-se ao cargo de Reitor os docentes pertencentes ao Quadro de Pessoal Ativo Permanente de qualquer dos campi que integram o Instituto Federal, desde que, necessariamente, possuam o título de doutor."],"correta":2,"explicacao":"Gabarito: <strong>Os Institutos Federais terão como órgão executivo a reitoria, composta por 1 (um) Reitor e 5 (cinco) Pró-Reitores.</strong>.","banca":"IF-PI","ano":2019,"temas_relacionados":["lei_11892_2008"]},{"id":1682810,"enunciado":"Partido político que obtenha doação proveniente de desvio de dinheiro público poderá sofrer as sanções da referida lei pela conduta lesiva à administração pública, como sujeito ativo, por constituir pessoa jurídica de direito privado.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2020,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1682811,"enunciado":"De acordo com a lei em questão, são independentes as responsabilidades da pessoa jurídica e da pessoa natural, de modo que é possível a responsabilização da pessoa jurídica por ato ilícito praticado, mesmo que nenhuma pessoa natural o seja.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2020,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1682812,"enunciado":"O acordo de leniência poderá ser celebrado com pessoa jurídica que cometa ato lesivo contra a administração pública, desde que da colaboração resulte a identificação de outros envolvidos no ato de corrupção ou, opcionalmente, a obtenção de informações que comprovem o ilícito sob apuração.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2020,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1682878,"enunciado":"Carla foi contratada pelo estado de Rondônia em 3/3/1986 para o cargo de professora. Em 1988, ela fez concurso e passou a ser estatutária. Em 2000, ela pediu exoneração e mudou-se para o Paraná, onde até hoje exerce o cargo de professora estadual. Nessa situação, Carla possui requisitos para optar pela transposição assegurada na Lei n.º 13.681/2018.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2020,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1682879,"enunciado":"Ângela encontrava-se no exercício de suas funções, prestando serviço à administração pública do ex-território do Amapá, na data em que este foi transformado em estado e, oportunamente, optou por incorporar-se aos quadros da União. Em 2013, ela foi afastada por motivos de saúde e, em 2015, aposentou-se por invalidez. Nessa situação, Ângela faz jus à inclusão nos quadros em extinção assegurados pela Lei n.º 13.681/2018.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2020,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1682880,"enunciado":"João foi contratado pelo estado de Rondônia em 15/2/1987, pelo regime celetista, e foi exonerado no ano de 2000, por decreto do governador, em razão de adequação das despesas de pessoal da administração pública estadual. Nessa situação, João tem direito à transposição assegurada na Lei n.º 13.681/2018, mas se aplicará a supressão de vantagem concedida por decisão judicial, ainda que transitada em julgado.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2020,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1682882,"enunciado":"Leda, servidora pública efetiva do Ministério Público do Estado de Roraima, encontrava-se no exercício regular de suas funções, prestando serviço a esse ex-território federal, na data em que ele foi transformado em estado. Nessa situação, Leda poderá optar pela sua inclusão nos quadros em extinção da União.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2020,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1682883,"enunciado":"A lei prevê o ingresso, nos quadros em extinção da União, de pessoas que comprovem que tiveram vínculo empregatício ou de trabalho, ainda que precário, com o governo dos estados e respectivos municípios dos ex-territórios federais de Roraima, Amapá e de Rondônia, no período estabelecido na lei, mesmo que tais pessoas não tenham mais vínculo com nenhum desses estados ou seus municípios.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2020,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1682884,"enunciado":"Os servidores e empregados pertencentes ao quadro em extinção da União e oriundos dos ex-territórios federais do Amapá, Rondônia e Roraima, bem como de seus municípios, poderão ser cedidos para outros entes federativos e para entidades da administração pública federal indireta, porém, nessa hipótese, permanecerão lotados no quadro em extinção da União, não podendo seus cargos e empregos ser redistribuídos para outros órgãos da União, dos estados, do Distrito Federal ou dos municípios, cujas vagas terão fim após sua vacância ou rescisão do contrato de trabalho.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2020,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1682885,"enunciado":"Empregado do estado de Rondônia admitido em quadro da União e enquadrado em cargo e função equivalentes àqueles que ocupava na estrutura estadual, com remuneração e plano de cargos competentes para o referido cargo, deve ser submetido ao regime jurídico disciplinado pela Consolidação das Leis do Trabalho.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2020,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1682886,"enunciado":"Servidores e empregados dos antigos territórios federais do Amapá e de Roraima que possuíam vínculos empregatícios com empresas de direito privado contratadas pela União e que optarem pela inclusão farão parte de quadro em extinção, cujas vagas terão fim após sua aposentadoria.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2020,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1682887,"enunciado":"O direito de opção pela inclusão nos quadros em extinção da União, nos termos do citado decreto, é ato personalíssimo, logo só pode ser exercido pelo próprio interessado.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2020,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1682888,"enunciado":"A Emenda Constitucional n.º 60/2009, que regulamenta direitos dos servidores e empregados do estado de Rondônia, não permite que aposentados e pensionistas sejam optantes da transposição, no entanto, com a publicação da Emenda Constitucional n.º 79/2014, dispôs-se que os proventos das aposentadorias, pensões, reformas e reservas remuneradas passassem a ser mantidos pela União.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2020,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1682889,"enunciado":"A estrutura da CEEXT constitui-se de duas câmaras de julgamento e uma recursal para cada ex-território, cada qual composta por quatro membros, todas instaladas na estrutura do Ministério da Economia.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2020,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1682890,"enunciado":"As câmaras de julgamento da CEEXT não possuem discricionariedade em sua competência para analisar requerimentos de opção e documentação apresentados por servidores e empregados dos ex-territórios, porém podem agir de ofício, por exemplo, no reexame de requerimentos que tenham sido indeferidos até a data de publicação do Decreto n.º 9.823/2019, mas cujos fundamentos tenham sido alterados.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2020,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1682891,"enunciado":"O presidente geral da CEEXT e seu substituto são escolhidos e designados pelo secretário especial de desburocratização, gestão e governo digital do Ministério da Economia, enquanto os presidentes de cada câmara da CEEXT e seus substitutos são escolhidos por eleição entre seus pares.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2020,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1682892,"enunciado":"Servidor público federal em exercício no Distrito Federal que seja escolhido e designado como membro da CEEXT se dedicará integralmente às atividades dessa comissão enquanto a integrar, sendo sua participação considerada prestação de serviço público relevante, não remunerada","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2020,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1688336,"enunciado":"Segundo a Lei n.º 9.784/1999 e o Decreto n.º 9.830/2019, julgue o item.\n\n\n\n\nNão cabe responsabilização se o agente público cometer erro grosseiro no desempenho de suas funções.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1688337,"enunciado":"Segundo a Lei n.º 9.784/1999 e o Decreto n.º 9.830/2019, julgue o item.\n\n\n\n\nÉ permitido invalidar situação plenamente constituída quando ocorrer mudança posterior de orientação geral.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1688338,"enunciado":"Segundo a Lei n.º 9.784/1999 e o Decreto n.º 9.830/2019, julgue o item.\n\n\n\n\nA motivação da decisão indicará as normas, a interpretação jurídica, a jurisprudência ou a doutrina que a embasaram.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1688396,"enunciado":"No que diz respeito ao exercício da profissão de técnico industrial, julgue o item.\n\nA qualificação de técnico industrial poderá ser acrescida apenas à denominação de pessoa jurídica fundada por profissionais possuidores de tais títulos, ainda que seja composta por profissionais de outras áreas.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1688401,"enunciado":"No que diz respeito ao exercício da profissão de técnico industrial, julgue o item.\n\nOs técnicos industriais cujos diplomas estejam em fase de registro não poderão exercer a profissão.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1688404,"enunciado":"Quanto ao Conselho Federal dos Técnicos Industriais e aos Conselhos Regionais dos Técnicos Industriais, julgue o item.\n\nO diretor financeiro do Conselho Federal dos Técnicos Industriais não integrará a Diretoria Executiva do órgão.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1688405,"enunciado":"Quanto ao Conselho Federal dos Técnicos Industriais e aos Conselhos Regionais dos Técnicos Industriais, julgue o item.\n\nO Plenário do Conselho Federal dos Técnicos Industriais será composto por nove conselheiros federais.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1688407,"enunciado":"Quanto ao Conselho Federal dos Técnicos Industriais e aos Conselhos Regionais dos Técnicos Industriais, julgue o item.\n\nAs atividades dos Conselhos Federal e Regionais dos Técnicos Industriais serão custeadas exclusivamente por renda própria.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1702255,"enunciado":"No que diz respeito ao exercício da profissão de técnico industrial, julgue o item.\n\n\n\n\nOs técnicos industriais poderão orientar e coordenar a execução dos serviços de manutenção de equipamentos e instalações.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1702256,"enunciado":"No que diz respeito ao exercício da profissão de técnico industrial, julgue o item.\n\n\n\n\nO técnico industrial de qualquer área poderá projetar e dirigir edificações, de até 80 m² de área construída, que não constituam conjuntos residenciais, realizar reformas, desde que não impliquem em estruturas de concreto armado ou metálicas, e exercer a atividade de desenhista de sua especialidade.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1702257,"enunciado":"No que diz respeito ao exercício da profissão de técnico industrial, julgue o item.\n\n\n\n\nO técnico industrial de qualquer área terá atribuições para a medição, a demarcação e o levantamento topográfico, bem como para projetar, conduzir e dirigir trabalhos topográficos, funcionar como perito em vistorias e arbitramentos relativos à agrimensura e exercer a atividade de desenhista de sua especialidade.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1702259,"enunciado":"No que diz respeito ao exercício da profissão de técnico industrial, julgue o item.\n\n\n\n\nNos trabalhos executados por técnicos industriais, é obrigatória, além da assinatura, a menção explícita do título e do número da carteira profissional do responsável.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1702260,"enunciado":"No que diz respeito ao exercício da profissão de técnico industrial, julgue o item.\n\n\n\n\nA fiscalização do exercício da profissão de técnico industrial será exercida pelo respectivo conselho profissional.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1702261,"enunciado":"No que diz respeito ao exercício da profissão de técnico industrial, julgue o item.\n\n\n\n\nO técnico industrial somente poderá exercer a profissão após o registro no respectivo conselho profissional da jurisdição de exercício de sua atividade.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1702262,"enunciado":"No que diz respeito ao exercício da profissão de técnico industrial, julgue o item.\n\n\n\n\nAo profissional registrado em conselho de fiscalização do exercício profissional será expedida carteira profissional de técnico, a qual não substituirá o diploma, mas valerá como documento de identidade.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1702264,"enunciado":"No que diz respeito ao exercício da profissão de técnico industrial, julgue o item.\n\n\n\n\n\n\n\nO profissional, a firma ou a organização registrados em qualquer conselho profissional, quando exercerem atividades em região diferente daquela em que se encontram registrados, obrigam-se ao visto do registro na nova região.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1702265,"enunciado":"Quanto ao Conselho Federal dos Técnicos Industriais e aos Conselhos Regionais dos Técnicos Industriais, julgue o item.\nO Conselho Federal dos Técnicos Industriais deve possuir estrutura e funcionamento definidos em regimento interno próprio, aprovado somente pela maioria absoluta de seus conselheiros.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1702268,"enunciado":"Quanto ao Conselho Federal dos Técnicos Industriais e aos Conselhos Regionais dos Técnicos Industriais, julgue o item.\n\n\n\n\nCompete aos Conselhos Regionais dos Técnicos Industriais elaborar seus próprios regimentos internos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1764844,"enunciado":"A respeito das atividades dos representantes comerciais autônomos, julgue o item, considerando a Lei n.º 4.886/1965.\nA representação comercial é exercida por pessoa física ou jurídica que desempenhe, em caráter eventual, por conta de uma ou mais pessoas, a mediação para a realização de negócios mercantis.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1764845,"enunciado":"A respeito das atividades dos representantes comerciais autônomos, julgue o item, considerando a Lei n.º 4.886/1965.\n\nO fato de uma pessoa não poder ser comerciante não a impede de ser representante comercial.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1764847,"enunciado":"A respeito das atividades dos representantes comerciais autônomos, julgue o item, considerando a Lei n.º 4.886/1965.\nOs Conselhos Regionais dos Representantes Comerciais poderão aplicar as penalidades de advertência e suspensão aos representantes comerciais que cometam irregularidades.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1764848,"enunciado":"A respeito das atividades dos representantes comerciais autônomos, julgue o item, considerando a Lei n.º 4.886/1965.\nO representante poderá rescindir, por motivo justo, o contrato de representação comercial caso ocorra, por parte do representado, a quebra indireta da exclusividade prevista no contrato.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1764851,"enunciado":"Com relação ao Conselho Regional dos Representantes Comerciais do Estado do Tocantins, julgue o item de acordo com seu Regimento Interno.\nDeverá enviar mensalmente 20% da sua renda bruta ao Conselho Federal dos Representantes Comerciais.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1817232,"enunciado":"A respeito dos objetivos e da estrutura dos Institutos Federais (Lei 11.892/2008), assinale a alternativa correta.","opcoes":["É objetivo dos Institutos Federais, entre outros, ministrar, em nível de educação superior, cursos de licenciatura, bem como programas especiais de formação pedagógica, com vistas na formação de professores para a educação básica, sobretudo nas áreas de ciências e matemática, e para a educação profissional.","Os Institutos Federais não podem oferecer cursos de pós-graduação stricto sensu de mestrado e doutorado.","Somente os cursos superiores de tecnologia poderão ser ofertados pelos Institutos Federais.","Os Institutos Federais não podem oferecer cursos de pós-graduação lato sensu de aperfeiçoamento e especialização.","Os campi serão dirigidos pelo Reitor, nomeado pelo Presidente da República para mandato de 4 (quatro) anos, permitida uma recondução."],"correta":0,"explicacao":"Gabarito: <strong>É objetivo dos Institutos Federais, entre outros, ministrar, em nível de educação superior, cursos de licenciatura, bem como programas especiais de formação pedagógica, com vistas na formação de professores para a educação básica, sobretudo nas áreas de ciências e matemática, e para a educação profissional.</strong>.","banca":"IDECAN","ano":2019,"temas_relacionados":["lei_11892_2008"]},{"id":1844400,"enunciado":"À luz do Decreto n.º 9.830/2019, que institui a Lei de Introdução às Normas do Direito Brasileiro, julgue o item.\nAs decisões da Administração Pública prescindem de fundamentação.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1844420,"enunciado":"Quanto à organização administrativa da União, julgue o item. \n\n\n\n\nCompete ao ministro de Estado, chefe da Secretaria de Planejamento, auxiliar diretamente o presidente da República na coordenação, na revisão e na consolidação dos programas setoriais e regionais e na elaboração da programação geral do governo.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1844456,"enunciado":"Conforme a Lei n.º 5.524/1968, que dispõe sobre o exercício da profissão de técnico industrial, julgue o item.\nA atividade consistente na prestação de assistência técnica na compra, na venda e na utilização de produtos e equipamentos especializados é um campo de atuação do técnico industrial de nível médio.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1844457,"enunciado":"Conforme a Lei n.º 5.524/1968, que dispõe sobre o exercício da profissão de técnico industrial, julgue o item.  \nOs cargos de técnico industrial de nível médio, no serviço público federal, estadual ou municipal, prescindem de profissionais legalmente habilitados.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1844458,"enunciado":"Conforme a Lei n.º 5.524/1968, que dispõe sobre o exercício da profissão de técnico industrial, julgue o item.\nO exercício da profissão de técnico industrial de nível médio é privativo de quem tenha sido diplomado por escola oficial autorizada no Brasil, sendo vedado, em quaisquer hipóteses, o exercício da profissão por aqueles que tenham sido diplomados por escola ou instituto técnico industrial estrangeiro.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1844459,"enunciado":"Segundo o Decreto n.º 90.922/1985, que dispõe sobre o exercício da profissão de técnico industrial, julgue o item.  \nOs técnicos de 2.º grau das áreas de arquitetura e de engenharia civil, na modalidade edificações, poderão projetar e dirigir edificações de até 80 m2 de área construída, que não constituam conjuntos residenciais, realizar reformas, desde que não impliquem em estruturas de concreto armado ou metálicas, e exercer a atividade de desenhista de sua especialidade.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1844460,"enunciado":"Segundo o Decreto n.º 90.922/1985, que dispõe sobre o exercício da profissão de técnico industrial, julgue o item. \nPara exercer a sua profissão, os técnicos industriais estão facultados a proceder ao registro perante os conselhos profissionais da jurisdição de exercício de sua atividade.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1844461,"enunciado":"No que se refere à Lei n.º 13.639/2018, que cria o Conselho Federal e os Conselhos Regionais dos Técnicos Industriais, julgue o item.\nO Conselho Federal dos Técnicos Industriais terá sede e jurisdição no estado onde tenha o maior número de profissionais nele registrados.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1844462,"enunciado":"No que se refere à Lei n.º 13.639/2018, que cria o Conselho Federal e os Conselhos Regionais dos Técnicos Industriais, julgue o item.\nO Plenário dos conselhos federais será composto por, no mínimo, doze e, no máximo, 27 conselheiros federais, acrescido esse número dos membros da Diretoria Executiva.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1844463,"enunciado":"No que se refere à Lei n.º 13.639/2018, que cria o Conselho Federal e os Conselhos Regionais dos Técnicos Industriais, julgue o item.\nA criação de colegiados com finalidades e funções específicas é uma competência atribuída tanto aos Conselhos Regionais quanto ao Conselho Federal dos Técnicos Industriais.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1845518,"enunciado":"Em atenção à estrutura organizacional dos Institutos Federais, contida na Lei nº 11.892/08, assinale a alternativa incorreta.","opcoes":["A administração dos Institutos Federais terá como órgãos superiores o Colégio de Dirigentes e o Conselho Superior.","Os Reitores serão nomeados pelo Presidente da República, para mandato de 4 (quatro) anos, vedada a recondução, podendo candidatar-se ao referido cargo apenas os docentes com o mínimo de três anos de efetivo exercício.","Os Institutos Federais terão como órgão executivo a reitoria, composta por 1 (um) Reitor e 5 (cinco) Pró-Reitores.","A reitoria, como órgão de administração central, poderá ser instalada em espaço físico distinto de qualquer dos campi que integram o Instituto Federal, desde que previsto em seu estatuto e aprovado pelo Ministério da Educação.","Cada Instituto Federal é organizado em estrutura multicampi, com proposta orçamentária anual identificada para cada campus e a reitoria, exceto no que diz respeito a pessoal, encargos sociais e benefícios aos servidores."],"correta":1,"explicacao":"Gabarito: <strong>Os Reitores serão nomeados pelo Presidente da República, para mandato de 4 (quatro) anos, vedada a recondução, podendo candidatar-se ao referido cargo apenas os docentes com o mínimo de três anos de efetivo exercício.</strong>.","banca":"IF-TO","ano":2021,"temas_relacionados":["lei_11892_2008"]},{"id":1858043,"enunciado":"Com base na Lei 11.892/2008, analise as afirmativas a seguir: I. As presidências do Colégio de Dirigentes e do Conselho Superior serão exercidas pelo Reitor do Instituto Federal. II. O Colégio de Dirigentes, de caráter consultivo, será composto pelo Reitor, pelos Pró-Reitores e pelo Diretor-Geral de cada um dos campi que integram o Instituto Federal. III. O Conselho Superior, de caráter consultivo e deliberativo, será composto por representantes dos docentes, dos estudantes, dos servidores técnico-administrativos, dos egressos da instituição, da sociedade civil, do Ministério da Educação e do Colégio de Dirigentes do Instituto Federal, assegurando-se a representação paritária dos segmentos que compõem a comunidade acadêmica. Assinale","opcoes":["se apenas as afirmativas I e II estiverem corretas.","se apenas as afirmativas I e III estiverem corretas.","se apenas as afirmativas II e III estiverem corretas.","se todas as afirmativas estiverem corretas."],"correta":3,"explicacao":"Gabarito: <strong>se todas as afirmativas estiverem corretas.</strong>.","banca":"IDECAN","ano":2021,"temas_relacionados":["lei_11892_2008"]},{"id":1858046,"enunciado":"De acordo com a Lei 11.892/2008, é objetivo dos Institutos Federais","opcoes":["ofertar educação profissional e tecnológica, em todos os seus níveis e modalidades, formando e qualificando cidadãos com vistas na atuação profissional nos diversos setores da economia, com ênfase no desenvolvimento socioeconômico local, regional e nacional.","desenvolver a educação profissional e tecnológica como processo educativo e investigativo de geração e adaptação de soluções técnicas e tecnológicas às demandas sociais e peculiaridades regionais.","estimular e apoiar processos educativos que levem à geração de trabalho e renda e à emancipação do cidadão na perspectiva do desenvolvimento socioeconômico local e regional.","promover a integração e a verticalização da educação básica à educação profissional e educação superior, otimizando a infraestrutura física, os quadros de pessoal e os recursos de gestão"],"correta":2,"explicacao":"Gabarito: <strong>estimular e apoiar processos educativos que levem à geração de trabalho e renda e à emancipação do cidadão na perspectiva do desenvolvimento socioeconômico local e regional.</strong>.","banca":"IDECAN","ano":2021,"temas_relacionados":["lei_11892_2008"]},{"id":1865469,"enunciado":"O exercício da atividade profissional de farmacêutico dispensa registro no Conselho Regional em cuja jurisdição o profissional desempenhe suas atividades.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1907594,"enunciado":"De acordo com o Estatuto e o Regimento Geral da Universidade de Brasília, julgue o item a seguir.\n\n\n\n\nA Prefeitura e a Procuradoria Jurídica da Universidade de Brasília compõem a Reitoria da Universidade de Brasília.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1907595,"enunciado":"De acordo com o Estatuto e o Regimento Geral da Universidade de Brasília, julgue o item a seguir.\n\n\n\n\nNo âmbito da Administração Superior da Universidade de Brasília, a Reitoria é o órgão executivo e o Conselho Comunitário é o órgão deliberativo e normativo.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1907596,"enunciado":"De acordo com a Instrução Normativa n.º 65/2020, do Ministério da Economia, que implementou o Programa de Gestão, julgue o item subsequente.\n\n\n\n\nNo âmbito do Programa de Gestão, será concedida ajuda de custo ao participante mesmo quando não houver mudança de domicílio em caráter permanente, tendo em vista o objetivo do programa de atrair e manter novos talentos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1907597,"enunciado":"De acordo com a Instrução Normativa n.º 65/2020, do Ministério da Economia, que implementou o Programa de Gestão, julgue o item subsequente.\n\n\n\n\nUm dos objetivos do Programa de Gestão é contribuir com a redução de custos no poder público.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1923945,"enunciado":"Com referência na Lei nº 11.892/2008, que institui a Rede Federal de Educação Profissional, Científica e Tecnológica, e cria os Institutos Federais de Educação, Ciência e Tecnologia, são objetivos dos Institutos Federais: I. Ministrar cursos de formação inicial e continuada de trabalhadores, objetivando a capacitação, o aperfeiçoamento, a especialização e a atualização de profissionais, em todos os níveis de escolaridade, nas áreas da educação profissional e tecnológica. II. Ministrar educação profissional técnica de nível médio, prioritariamente na forma de cursos integrados, para os concluintes do ensino fundamental e para o público da educação de jovens e adultos. III. Ministrar em nível de educação superior, cursos superiores de tecnologia visando à formação de profissionais para os diferentes setores da economia. Quais estão corretos?","opcoes":["Apenas III.","Apenas I e II.","Apenas I e III.","Apenas II e III.","I, II e III."],"correta":4,"explicacao":"Gabarito: <strong>I, II e III.</strong>.","banca":"FUNDATEC","ano":2022,"temas_relacionados":["lei_11892_2008"]},{"id":1926318,"enunciado":"À luz do Decreto n.º 9.830/2019, julgue o item.\n\n\n\n\nToda decisão será fundamentada, sendo vedada a motivação por declaração de concordância com o conteúdo de notas técnicas, pareceres, informações, decisões ou propostas que precederam a decisão.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1926319,"enunciado":"À luz do Decreto n.º 9.830/2019, julgue o item.\n\n\n\n\nA responsabilização pela opinião técnica não se estende de forma automática ao decisor que a adotou como fundamento de decidir e somente configurar-se-á se estiverem presentes elementos suficientes para o decisor aferir o dolo ou o erro grosseiro da opinião técnica ou se houver conluio entre os agentes.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1926804,"enunciado":"À luz do que dispõe a Lei nº 11.892/2008, que institui a Rede Federal de Educação Profissional, Científica e Tecnológica e cria os Institutos Federais de Educação, Ciência e Tecnologia, é correto afirmar que","opcoes":["as Universidades são instituições de educação superior, básica e profissional, pluricurricular, especializada na oferta de educação profissional e tecnológica.","no âmbito de sua atuação, as Universidades Federais exercerão o papel de instituições acreditadoras e certificadoras de competências profissionais.","o Colégio Pedro II integra a Rede Federal de Educação Profissional, Científica e Tecnológica, que se vincula ao Ministério da Educação.","para efeito da incidência das disposições que regem a regulação das instituições, o Colégio Pedro II é equiparado às Universidades Federais."],"correta":2,"explicacao":"Gabarito: <strong>o Colégio Pedro II integra a Rede Federal de Educação Profissional, Científica e Tecnológica, que se vincula ao Ministério da Educação.</strong>.","banca":"Colégio Pedro II","ano":2022,"temas_relacionados":["lei_11892_2008"]},{"id":1941925,"enunciado":"Os Institutos Federais terão como órgão executivo a reitoria, a qual, de acordo com a Lei n° 11.892/08, é composta por:","opcoes":["2 (dois) Reitores e 4 (quatro) Pró-Reitores.","1 (um) Reitor e 5 (cinco) Pró-Reitores.","1 (um) Reitor e 3 (três) Pró-Reitores.","2 (dois) Reitores e 6 (seis) Pró-Reitores."],"correta":1,"explicacao":"Gabarito: <strong>1 (um) Reitor e 5 (cinco) Pró-Reitores.</strong>.","banca":"IDECAN","ano":2022,"temas_relacionados":["lei_11892_2008"]},{"id":1964061,"enunciado":"Segundo a Lei nº 11.892, de 29 de dezembro de 2008, NÃO é objetivo dos Institutos Federais de Educação, Ciência e Tecnologia:","opcoes":["Estimular e apoiar processos educativos que levem à geração de trabalho e renda e à emancipação do cidadão na perspectiva do desenvolvimento socioeconômico local e regional.","Ministrar educação profissional técnica de nível médio, prioritariamente na forma de cursos integrados, para os concluintes do ensino fundamental e para o público da educação de jovens e adultos.","Ministrar, em nível de educação superior, cursos de pós-graduação stricto sensu de mestrado e doutorado, que contribuam para promover o estabelecimento de bases sólidas em educação, ciência e tecnologia, com vistas no processo de geração e inovação tecnológica.","Realizar e estimular prioritariamente a pesquisa básica, a produção cultural, o empreendedorismo, o cooperativismo e o desenvolvimento científico e tecnológico.","Realizar pesquisas aplicadas, estimulando o desenvolvimento de soluções técnicas e tecnológicas, estendendo seus benefícios à comunidade."],"correta":3,"explicacao":"Gabarito: <strong>Realizar e estimular prioritariamente a pesquisa básica, a produção cultural, o empreendedorismo, o cooperativismo e o desenvolvimento científico e tecnológico.</strong>.","banca":"IF-PI","ano":2022,"temas_relacionados":["lei_11892_2008"]},{"id":1973826,"enunciado":"Com relação à Lei n.º 9.394/1996 e suas alterações, julgue o item a seguir.\n\n\n\n\nNa educação de surdos, a educação bilíngue deve ser ofertada a partir do ensino fundamental e se estender ao longo da vida.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1973827,"enunciado":"Com relação à Lei n.º 9.394/1996 e suas alterações, julgue o item a seguir.\n\n\n\n\nAs instituições de ensino superior mantidas pela iniciativa privada fazem parte do sistema federal ou estadual do ensino, a depender do ato autorizativo de implementação.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1976675,"enunciado":"Considerando o teor do Decreto n.º 9.830/2019, julgue o item.\n\nNos processos administrativos, a autoridade pública não poderá exigir compensação por benefícios indevidamente fruídos pelo particular.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1976676,"enunciado":"Considerando o teor do Decreto n.º 9.830/2019, julgue o item.\n\nNa hipótese de ocorrência de dano ao erário provocado por agentes públicos mediante dolo ou erro grosseiro, não poderá ser celebrado termo de ajustamento de gestão.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1976677,"enunciado":"Considerando o teor do Decreto n.º 9.830/2019, julgue o item.\n\nO nexo de causalidade constitui elemento a ser considerado na decisão que impuser sanção ao agente público.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1978460,"enunciado":"Tendo como referência as diretrizes estabelecidas no Decreto n.º 9.830/2019, julgue o item.\n\nConsidera-se erro grosseiro aquele manifesto, evidente e inescusável praticado com culpa grave e caracterizado por ação ou omissão com elevado grau de negligência, imprudência ou imperícia.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1978461,"enunciado":"Tendo como referência as diretrizes estabelecidas no Decreto n.º 9.830/2019, julgue o item.\n\nA decisão que se baseia exclusivamente em valores jurídicos abstratos independe de análise dos fundamentos de mérito e jurídicos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1978462,"enunciado":"Tendo como referência as diretrizes estabelecidas no Decreto n.º 9.830/2019, julgue o item.\n\nAs circunstâncias agravantes ou atenuantes devem ser consideradas na decisão que impuser sanção ao agente público.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1982061,"enunciado":"Julgue o item, referentes ao teor do Decreto n.º 9.830/2019. \n\nNa interpretação das normas sobre gestão pública, deverão ser considerados, sem prejuízo dos direitos dos administrados, os obstáculos, as dificuldades reais do agente público e as exigências das políticas públicas a seu cargo.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1982062,"enunciado":"Julgue o item, referentes ao teor do Decreto n.º 9.830/2019. \n\nO agente público somente poderá ser responsabilizado por suas decisões ou por suas opiniões técnicas se agir ou se omitir com dolo, direto ou eventual, no desempenho de suas funções, ou, ainda, se cometer erro grosseiro, isto é, o erro manifesto, evidente e inescusável praticado com culpa grave, caracterizado por ação ou omissão com elevado grau de negligência, imprudência ou imperícia.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1996127,"enunciado":"A gestão dos cargos do Plano de Carreira dos Cargos Técnico-Administrativos em Educação, no âmbito das Instituições Federais de Ensino vinculadas ao Ministério da Educação, deve observar, entre outros, o reconhecimento do saber não instituído resultante da atuação profissional na dinâmica de ensino, de pesquisa e de extensão.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"IDECAN","ano":2022,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":1996133,"enunciado":"De acordo com o Decreto nº 9.830, que regulamenta o disposto nos art. 20 ao art. 30 do Decreto-Lei nº 4.657, de 4 de setembro de 1942, que institui a Lei de Introdução às Normas do Direito Brasileiro, na decisão sobre a regularidade de conduta ou a validade de atos, contratos, ajustes, processos ou normas administrativas, serão consideradas as circunstâncias práticas que impuseram, limitaram ou condicionaram a ação do agente público.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"IDECAN","ano":2022,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2007783,"enunciado":"A Lei n° 11892, de 29 de dezembro de 2008, institui a Rede Federal de Educação Profissional, Científica e Tecnológica e cria os Institutos Federais de Educação, Ciência e Tecnologia. De acordo com esta lei, indique qual das alternativas abaixo está CORRETA.","opcoes":["Fica instituída, no âmbito do sistema federal de ensino, a Rede Federal de Educação Profissional, Científica e Tecnológica, vinculada ao Ministério da Educação e constituída pelas seguintes instituições: Institutos Federais de Educação, Ciência e Tecnologia - Institutos Federais; Universidade Tecnológica Federal do Paraná - UTFPR; Centros Federais de Educação Tecnológica Celso Suckow da Fonseca - CEFET-RJ e de Minas Gerais - CEFET-MG e Colégio Pedro II.","No desenvolvimento da sua ação acadêmica, o Instituto Federal, em cada exercício, deverá garantir o mínimo de 50% (cinquenta por cento) de suas vagas para atender à educação profissional técnica de nível médio, prioritariamente na forma de cursos integrados, para os concluintes do ensino fundamental e para o público da educação de jovens e adultos e o mínimo de 20% (vinte por cento) de suas vagas para atender aos cursos de licenciatura, bem como programas especiais de formação pedagógica, com vistas à formação de professores para a educação básica, sobretudo nas áreas de ciências e matemática.","Os Reitores serão nomeados pelo Presidente da República, para mandato de 4 (quatro) anos, permitida uma recondução, após processo de consulta à comunidade escolar do respectivo Instituto Federal, atribuindo-se o peso de 1/3 (um terço) para a manifestação do corpo docente, de 1/3 (um terço) para a manifestação dos servidores técnico-administrativos e de 1/3 (um terço) para a manifestação do corpo discente. Poderão candidatar-se ao cargo de Reitor os servidores pertencentes ao Quadro de Pessoal Ativo Permanente de qualquer dos campi que integram o Instituto Federal, desde que possuam o mínimo de 5 (cinco) anos de efetivo exercício em instituição federal de educação profissional e tecnológica.","Os Institutos Federais têm por finalidade, exclusivamente, ofertar educação profissional e tecnológica, em todos os seus níveis e modalidades, formando e qualificando cidadãos com vistas à atuação profissional nos diversos setores da economia, com ênfase no desenvolvimento socioeconômico local, regional e nacional."],"correta":1,"explicacao":"Gabarito: <strong>No desenvolvimento da sua ação acadêmica, o Instituto Federal, em cada exercício, deverá garantir o mínimo de 50% (cinquenta por cento) de suas vagas para atender à educação profissional técnica de nível médio, prioritariamente na forma de cursos integrados, para os concluintes do ensino fundamental e para o público da educação de jovens e adultos e o mínimo de 20% (vinte por cento) de suas vagas para atender aos cursos de licenciatura, bem como programas especiais de formação pedagógica, com vistas à formação de professores para a educação básica, sobretudo nas áreas de ciências e matemática.</strong>.","banca":"IF-GO","ano":2018,"temas_relacionados":["lei_11892_2008"]},{"id":2017428,"enunciado":"À luz do Decreto n.° 9.830/2019, julgue o item.\n\n\n\n\nA decisão que decretar invalidação de normas administrativas poderá ser imotivada, quando convirja com o interesse dos interessados.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2017429,"enunciado":"À luz do Decreto n.° 9.830/2019, julgue o item.\n\n\n\n\nO compromisso buscará solução proporcional, equânime, eficiente e compatível com os interesses gerais.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2017430,"enunciado":"À luz do Decreto n.° 9.830/2019, julgue o item.\n\n\n\n\nNa hipótese de ocorrência de dano ao erário praticado por agentes públicos que agirem com erro grosseiro, não será celebrado termo de ajustamento de gestão.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2017476,"enunciado":"À luz das disposições da Lei n.° 5.524/1968 e do Decreto n.° 90.922/1985, julgue o item.\n\n\n\n\nOs cargos de técnico industrial de nível médio, no serviço público, somente serão exercidos por profissionais legalmente habilitados.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2017477,"enunciado":"À luz das disposições da Lei n.° 5.524/1968 e do Decreto n.° 90.922/1985, julgue o item.\n\n\n\n\nOs técnicos em eletrotécnica poderão projetar e dirigir instalações elétricas com demanda de energia de até 800 kva, bem como exercer a atividade de desenhista de sua especialidade.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2017478,"enunciado":"À luz das disposições da Lei n.° 5.524/1968 e do Decreto n.° 90.922/1985, julgue o item.\n\n\n\n\nO exercício da atividade profissional do técnico em região diferente daquela em que se encontre registrado independe de visto do registro na nova região.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2017479,"enunciado":"À luz das disposições da Lei n.° 5.524/1968 e do Decreto n.° 90.922/1985, julgue o item.\n\n\n\n\nA carteira profissional conterá, obrigatoriamente, o número do registro e o nome da profissão, além da respectiva modalidade.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2017480,"enunciado":"À luz das disposições da Lei n.° 5.524/1968 e do Decreto n.° 90.922/1985, julgue o item.\n\n\n\n\nAs qualificações de técnico industrial de 2.° grau poderão ser acrescidas à denominação de pessoa jurídica quando composta, em sua maioria, de profissionais possuidores de tais títulos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2017481,"enunciado":"Com base na Lei n.° 13.639/2018, julgue o item.\n\n\n\n\nO Conselho Federal dos Técnicos Industriais, com sede e foro em Brasília, será integrado por brasileiros, natos ou naturalizados.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2017482,"enunciado":"Com base na Lei n.° 13.639/2018, julgue o item.\n\n\n\n\nO mandato dos membros do Conselho Federal dos Técnicos Industriais terá duração de quatro anos, admitida uma reeleição.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2017483,"enunciado":"Com base na Lei n.° 13.639/2018, julgue o item.\n\n\n\n\nA Diretoria Executiva do Conselho Federal dos Técnicos Industriais será composta, exclusivamente, pelo presidente, pelo vice-presidente e pelo diretor administrativo.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2017484,"enunciado":"Com base na Lei n.° 13.639/2018, julgue o item.\n\n\n\n\nCada unidade federativa do País será representada no plenário do Conselho Federal por três conselheiros.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2017485,"enunciado":"Com base na Lei n.° 13.639/2018, julgue o item.\n\n\n\n\nO Conselho Federal dos Técnicos Industriais será composto pela diretoria executiva e pelo plenário deliberativo.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2017486,"enunciado":"Com base na Lei n.° 13.639/2018, julgue o item.\n\n\n\n\nOs membros da diretoria executiva dos Conselhos Regionais serão eleitos, por meio de voto direto e secreto, pelos profissionais aptos a votar.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2017487,"enunciado":"Com base na Lei n.° 13.639/2018, julgue o item.\n\n\n\n\nNo caso de vacância do cargo de diretor de fiscalização e normas do Conselho Regional, a assembleia geral dos profissionais escolherá o novo diretor.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2017488,"enunciado":"Com base na Lei n.° 13.639/2018, julgue o item.\n\n\n\n\nOs Conselhos Regionais poderão criar colegiados com finalidades e funções específicas.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2017489,"enunciado":"Com base na Lei n.° 13.639/2018, julgue o item.\n\n\n\n\nCaberá ao Conselho Federal dos Técnicos Industriais cobrar as anuidades e multas que lhe são devidas pelos profissionais sujeitos a sua jurisdição.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2017490,"enunciado":"Com base na Lei n.° 13.639/2018, julgue o item.\n\n\n\n\nO plenário dos Conselhos Regionais será composto por, no mínimo, 12 e, no máximo, 28 conselheiros.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2017491,"enunciado":"Com base na Lei n.° 13.639/2018, julgue o item.\n\n\n\n\nO número de conselheiros de cada Conselho Regional será definido em resolução aprovada pelo Conselho Federal.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2017492,"enunciado":"Com base na Lei n.° 13.639/2018, julgue o item.\n\n\n\n\nAs atividades do Conselho Federal dos Técnicos Industriais e dos Conselhos Regionais serão custeadas por renda própria.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2017493,"enunciado":"Com base na Lei n.° 13.639/2018, julgue o item.\n\n\n\n\nO trabalho de atuação compartilhada com outras profissões regulamentadas será objeto de termo de responsabilidade técnica.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2017494,"enunciado":"Com base na Lei n.° 13.639/2018, julgue o item.\n\n\n\n\nO termo de responsabilidade técnica independe do pagamento de taxas.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2017495,"enunciado":"Com base na Lei n.° 13.639/2018, julgue o item.\n\n\n\n\nCompete ao Conselho Federal dos Técnicos Industriais adotar medidas para assegurar o funcionamento regular dos Conselhos Regionais.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2026930,"enunciado":"À luz da Lei nº 11.892/08, que institui a Rede Federal de Educação Profissional, Científica e Tecnológica e cria os Institutos Federais de Educação, Ciência e Tecnologia, julgue as assertivas abaixo: I. O Instituto Federal de Mato Grosso foi criado mediante a integração dos Centros Federais de Educação Tecnológica de Mato Grosso e de Cáceres, e da Escola Agrotécnica Federal de São Vicente. lI. A unidade de ensino que compõe a estrutura organizacional de instituição transformada ou integrada em Instituto Federal passa de forma automática, independentemente de qualquer formalidade, à condição de campus da nova instituição. IlI. A Sede da Reitoria do Instituto Federal de Mato Grosso está localizada na cidade de Cuiabá. IV. O Instituto Federal de Mato Grosso, a Universidade Federal de Mato Grosso e a Universidade Federal de Rondonópolis fazem parte da Rede Federal de Educação Profissional, Científica e Tecnológica. Está(ão) CORRETA(S) apena(s) a(s) assertiva(s):","opcoes":["I e IlI.","lI e IlI.","IlI e IV.","I e IV.","Todas estão corretas."],"correta":1,"explicacao":"Gabarito: <strong>lI e IlI.</strong>.","banca":"IF-MT","ano":2023,"temas_relacionados":["lei_11892_2008"]},{"id":2036716,"enunciado":"Dados os itens, I. Administração do seu patrimônio, dos seus recursos, licitações e contratos. II. Resultados de auditorias realizadas por órgãos de controle interno ou externo. III. Metas e indicadores propostos para implantação, acompanhamento e resultados de programas e projetos. verifica-se que, dentro da perspectiva de transparência no setor público, é(são) informação(ões) que as Instituições Federais de Ensino Superior (IFES) deve(m) disponibilizar","opcoes":["I, II e III.","II e III, apenas.","I e II, apenas.","III, apenas.","I, apenas."],"correta":0,"explicacao":"Gabarito: <strong>I, II e III.</strong>.","banca":"COPEVE-UFAL","ano":2016,"temas_relacionados":["lei_11892_2008"]},{"id":2046663,"enunciado":"De acordo com a Lei nº 11.892, de 29 de dezembro de 2008, que criou os Institutos Federais, analise as assertivas abaixo: I – É objetivo dos Institutos Federais estimular e apoiar processos educativos que levem à geração de trabalho e renda e à emancipação do cidadão na perspectiva do desenvolvimento socioeconômico local e regional. II – Os Institutos Federais têm por finalidades e características promover a produção, o desenvolvimento e a transferência de tecnologias sociais, notadamente as voltadas à preservação do meio ambiente. III – A administração dos Institutos Federais terá como órgãos superiores o Colégio de Dirigentes e o Conselho Superior, ambos de caráter deliberativo. IV – Os Institutos Federais terão como órgão executivo a reitoria, composta por 1 (um) Reitor e 5 (cinco) Pró-Reitores. Marque a alternativa que apresenta somente assertiva(s) CORRETA(S).","opcoes":["I, II, III e IV.","I, II e III.","II, III e IV.","I e IV.","I, II e IV."],"correta":4,"explicacao":"Gabarito: <strong>I, II e IV.</strong>.","banca":"IF-ES","ano":2019,"temas_relacionados":["lei_11892_2008"]},{"id":2062105,"enunciado":"Quanto à Estrutura Organizacional dos Institutos Federais, disciplinada pela Lei nº 11.892/2008, é correto afirmar:","opcoes":["As presidências do Conselho Curador e do Conselho Diretor serão exercidas pelo Reitor do Instituto Federal.","A administração dos Institutos Federais terá como órgãos superiores o Conselho Curador e o Conselho Diretor.","Os Reitores serão nomeados pelo Presidente da República, para mandato de 2 (dois) anos, permitida a recondução.","Poderão candidatar-se ao cargo de Reitor os docentes e técnicos pertencentes ao Quadro de Pessoal Ativo Permanente de qualquer dos campi que integram o Instituto Federal.","Cada Instituto Federal é organizado em estrutura multicampi, com proposta orçamentária anual identificada para cada campus e a reitoria, exceto no que diz respeito a pessoal, encargos sociais e benefícios aos servidores."],"correta":4,"explicacao":"Gabarito: <strong>Cada Instituto Federal é organizado em estrutura multicampi, com proposta orçamentária anual identificada para cada campus e a reitoria, exceto no que diz respeito a pessoal, encargos sociais e benefícios aos servidores.</strong>.","banca":"FCM","ano":2023,"temas_relacionados":["lei_11892_2008"]},{"id":2062255,"enunciado":"De acordo com a Lei nº 11.892/2008, que institui a Rede Federal de Educação Profissional, Científica e Tecnológica, cria os Institutos Federais de Educação, Ciência e Tecnologia, os Institutos Federais possuem a natureza jurídica de","opcoes":["autarquia.","empresa pública.","fundação pública.","fundação privada.","sociedade de economia mista."],"correta":0,"explicacao":"Gabarito: <strong>autarquia.</strong>.","banca":"FCM","ano":2023,"temas_relacionados":["lei_11892_2008"]},{"id":2066852,"enunciado":"De acordo com a Lei nº 11.892/2008, que institui a Rede Federal de Educação Profissional, Científica e Tecnológica e cria os Institutos Federais de Educação, Ciência e Tecnologia, analise as afirmações a seguir: I - Os Institutos Federais de Educação, Ciência e Tecnologia possuem natureza jurídica de autarquia, detentoras de autonomia administrativa, patrimonial, financeira, didático-pedagógica e disciplinar. II - Os Institutos Federais terão autonomia para criar e extinguir cursos, nos limites de sua área de atuação territorial, bem como para registrar diplomas dos cursos por eles oferecidos, mediante autorização do seu Conselho Superior, aplicando-se, no caso da oferta de cursos a distância, a legislação específica. III - Os Institutos Federais são instituições de educação superior, básica e profissional, pluricurriculares e multicampi, especializados na oferta de educação profissional e tecnológica nas diferentes modalidades de ensino, com base na conjugação de conhecimentos técnicos e tecnológicos com as suas práticas pedagógicas. Está correto apenas o que se afirma em","opcoes":["I, II e III.","I e II.","II e III.","I.","III."],"correta":0,"explicacao":"Gabarito: <strong>I, II e III.</strong>.","banca":"FCM","ano":2023,"temas_relacionados":["lei_11892_2008"]},{"id":2077776,"enunciado":"Com base no Decreto n.º 9.830/2019, que instituiu a Lei de Introdução às Normas do Direito brasileiro, julgue o item.\n\nA motivação das decisões judiciais indicará as normas, a interpretação jurídica e a jurisprudência ou a doutrina que a embasaram.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2077777,"enunciado":"Com base no Decreto n.º 9.830/2019, que instituiu a Lei de Introdução às Normas do Direito brasileiro, julgue o item.\n\nNa declaração de invalidade de atos administrativos, o decisor poderá restringir os efeitos da declaração, mas não decidir que a sua eficácia se iniciará em momento posteriormente definido.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2077778,"enunciado":"Com base no Decreto n.º 9.830/2019, que instituiu a Lei de Introdução às Normas do Direito brasileiro, julgue o item.\n\nO compromisso firmado com os interessados para eliminar irregularidade, incerteza jurídica ou situações contenciosas na aplicação do direito público produz efeitos a partir da sua celebração, dispensando a sua publicação para produzir efeitos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2077779,"enunciado":"Com base no Decreto n.º 9.830/2019, que instituiu a Lei de Introdução às Normas do Direito brasileiro, julgue o item.\n\nA responsabilização do agente público por suas decisões ou opiniões técnicas somente ocorrerá se ele agir ou se omitir com dolo, direto ou eventual, ou cometer erro grosseiro, quando do desempenho de suas funções.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2077780,"enunciado":"Com base no Decreto n.º 9.830/2019, que instituiu a Lei de Introdução às Normas do Direito brasileiro, julgue o item.\n\nA autoridade máxima de órgão ou entidade da Administração Pública poderá editar enunciados, os quais vinculam o próprio órgão ou a entidade, mas não os seus órgãos subordinados, caso o ato não seja expresso nesse sentido.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2077781,"enunciado":"À luz da Lei n.º 8.159/1991, que dispõe sobre a política nacional de arquivos públicos e privados, julgue o item.\n\nA violação do sigilo com relação às informações dos cidadãos gera o direito a danos materiais ou morais, o que afasta as ações penais e administrativas decorrentes daquele abuso de direito.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2077782,"enunciado":"À luz da Lei n.º 8.159/1991, que dispõe sobre a política nacional de arquivos públicos e privados, julgue o item.\n\nSão considerados arquivos públicos os documentos produzidos e recebidos por entidades privadas encarregadas da gestão de serviços públicos, no exercício de suas atividades.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2077783,"enunciado":"À luz da Lei n.º 8.159/1991, que dispõe sobre a política nacional de arquivos públicos e privados, julgue o item.\n\nConsideram-se documentos públicos intermediários aqueles em curso ou que, mesmo sem movimentação, constituam objeto de consultas frequentes.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2082090,"enunciado":"O Instituto Federal de Alagoas (IFAL) foi criado pela Lei n° 11.892, de 29 de dezembro de 2008, e compõe a Rede Federal de Educação Profissional, Científica e Tecnológica. Na estrutura administrativa federal, é considerado uma ________________ e faz parte da administração pública ________________. Assinale a alternativa que completa corretamente as lacunas do texto.","opcoes":["autarquia; direta","autarquia; indireta","fundação pública; direta","fundação pública; indireta","empresa pública; indireta"],"correta":1,"explicacao":"Gabarito: <strong>autarquia; indireta</strong>.","banca":"COPEVE-UFAL","ano":2023,"temas_relacionados":["lei_11892_2008"]},{"id":2134022,"enunciado":"Segundo a Lei nº 11.892/2008, que institui a Rede Federal de Educação Profissional, Científica e Tecnológica e cria os Institutos Federais de Educação, Ciência e Tecnologia, no que se refere aos objetivos dos Institutos Federais, julgue os itens a seguir. I - É objetivo do Instituto Federal ministrar, em nível de educação superior, cursos de pós-graduação lato sensu de aperfeiçoamento e especialização, visando à formação de especialistas nas diferentes áreas do conhecimento. II - É objetivo do Instituto Federal ministrar educação profissional técnica de nível médio, prioritariamente na forma de cursos integrados, para os concluintes do ensino fundamental e para o público da educação de jovens e adultos. III - É objetivo do Instituto Federal ministrar cursos de formação inicial e continuada de trabalhadores, objetivando a capacitação, o aperfeiçoamento, a especialização e a atualização de profissionais, em todos os níveis de escolaridade, nas áreas da educação profissional e tecnológica. Está correto apenas o que se afirma em","opcoes":["I.","II.","III.","I e III.","I, II e III."],"correta":4,"explicacao":"Gabarito: <strong>I, II e III.</strong>.","banca":"FCM","ano":2023,"temas_relacionados":["lei_11892_2008"]},{"id":2134023,"enunciado":"Segundo a Lei nº 11.892/2008, que institui a Rede Federal de Educação Profissional, Científica e Tecnológica e cria os Institutos Federais de Educação, Ciência e Tecnologia, no que se refere aos objetivos dos Institutos Federais, quanto às finalidades e características dos Institutos Federais, preencha as lacunas do texto a seguir, com os exatos termos da legislação. Os Institutos Federais têm por finalidades e características ofertar educação ___________ e tecnológica, em todos os seus níveis e modalidades, formando e qualificando ___________ com vistas na atuação profissional nos diversos setores da economia, com ênfase no desenvolvimento socioeconômico local, regional e ___________.","opcoes":["técnica / cidadãos / sulamericano","superior / estudantes / nacional","profissional / trabalhadores / internacional","profissional / cidadãos / nacional","superior / estudantes / internacional"],"correta":3,"explicacao":"Gabarito: <strong>profissional / cidadãos / nacional</strong>.","banca":"FCM","ano":2023,"temas_relacionados":["lei_11892_2008"]},{"id":2134750,"enunciado":"Em razão do disposto no Decreto n.º 9.830/2019, julgue o item.\n\n\n\n\nA decisão de celebrar o compromisso independe de oitiva do órgão jurídico.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2134751,"enunciado":"Em razão do disposto no Decreto n.º 9.830/2019, julgue o item.\n\n\n\n\nA culpabilidade do agente será considerada na decisão que impuser sanção ao agente público.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2161768,"enunciado":"Mévio, servidor público federal, exerce o cargo de docente no Instituto Federal do Estado do Pará e, de acordo com a legislação vigente, foi nomeado Reitor daquela instituição. De acordo com a Lei nº 11.892/2008 e a Resolução nº 120/2020 – CONSUP, NÃO é atribuição de Mévio:","opcoes":["Presidir o Conselho Superior.","Presidir o Colégio de Dirigentes.","Representar o Instituto Federal em juízo ou fora dele.","Definir a Política de Desenvolvimento e Gestão de Pessoas alinhada à estratégia organizacional."],"correta":3,"explicacao":"Gabarito: <strong>Definir a Política de Desenvolvimento e Gestão de Pessoas alinhada à estratégia organizacional.</strong>.","banca":"Instituto Consulplan","ano":2023,"temas_relacionados":["lei_11892_2008"]},{"id":2163996,"enunciado":"Em relação à Lei que institui a Rede Federal de Educação Profissional, Científica e Tecnológica; e cria os Institutos Federais de Educação, Ciência e Tecnologia, assinale a afirmativa correta.","opcoes":["Os referidos Institutos Federais possuem a atribuição acreditadora e certificadora de competências profissionais, sendo equiparados às universidades federais para fins de regulação, avaliação e supervisão.","A autonomia didático-pedagógica autoriza os Institutos Federais a criar e extinguir cursos, à exceção de curso a distância que possui regulamentação específica, só podendo ser criado ou extinto pelo Ministério da Educação.","Os Institutos Federais podem ministrar educação profissional de nível médio, desde que na forma de cursos integrados, para os alunos que concluírem o ensino fundamental e para a continuidade de educação de jovens e adultos.","Para fins de fiscalização e supervisão ministerial, os Institutos Federais equiparam-se às empresas estatais federais, no que tange à obrigatoriedade de regime contábil e financeiro com registro de movimentações financeiras em livro próprio e fiscalização direta pelo Ministério Público."],"correta":0,"explicacao":"Gabarito: <strong>Os referidos Institutos Federais possuem a atribuição acreditadora e certificadora de competências profissionais, sendo equiparados às universidades federais para fins de regulação, avaliação e supervisão.</strong>.","banca":"Instituto Consulplan","ano":2023,"temas_relacionados":["lei_11892_2008"]},{"id":2174958,"enunciado":"Segundo a Lei nº 11.892/2008, que institui a Rede Federal de Educação Profissional, Científica e Tecnológica, é INCORRETO afirmar que os Institutos Federais têm por finalidade e característica:","opcoes":["Restringir a produção, o desenvolvimento e a transferência de tecnologias sociais.","Realizar e estimular a pesquisa aplicada, a produção cultural e o empreendedorismo.","Desenvolver programas de extensão e de divulgação científica e tecnológica.","Promover a integração da educação básica à educação profissional e à educação superior.","Ofertar educação profissional e tecnológica em todos os seus níveis e modalidades."],"correta":0,"explicacao":"Gabarito: <strong>Restringir a produção, o desenvolvimento e a transferência de tecnologias sociais.</strong>.","banca":"FUNDATEC","ano":2023,"temas_relacionados":["lei_11892_2008"]},{"id":2174967,"enunciado":"Com referência na Lei nº 11.892/2008, os Institutos Federais têm por finalidade e característica ofertar educação profissional e tecnológica, em todos os seus níveis e modalidades, formando e qualificando cidadãos com vistas à atuação profissional nos diversos setores da economia, com ênfase no desenvolvimento socioeconômico: I. Internacional. II. Regional. III. Local. Quais estão corretas?","opcoes":["Apenas II.","Apenas I e II.","Apenas I e III.","Apenas II e III.","I, II e III."],"correta":3,"explicacao":"Gabarito: <strong>Apenas II e III.</strong>.","banca":"FUNDATEC","ano":2023,"temas_relacionados":["lei_11892_2008"]},{"id":2175058,"enunciado":"Segundo a Lei nº 11.892/2008, que institui a Rede Federal de Educação Profissional, Científica e Tecnológica, os Institutos Federais poderão conceder bolsas de pesquisa, desenvolvimento, inovação e intercâmbio a alunos, docentes e pesquisadores externos ou de empresas, a serem regulamentadas por órgão técnico competente do(a):","opcoes":["Secretaria do meio ambiente.","Ministério da Educação.","Serviço Social.","Defensoria pública.","Ministério público."],"correta":1,"explicacao":"Gabarito: <strong>Ministério da Educação.</strong>.","banca":"FUNDATEC","ano":2023,"temas_relacionados":["lei_11892_2008"]},{"id":2175064,"enunciado":"Segundo a Lei nº 11.892/2008, que institui a Rede Federal de Educação Profissional, Científica e Tecnológica, é correto afirmar que para efeito da incidência das disposições que regem a regulação, avaliação e supervisão das instituições e dos cursos de educação superior, os Institutos Federais são equiparados às:","opcoes":["Universidades privadas.","Escolas particulares.","Instituições estaduais.","Universidades federais.","Escolas públicas."],"correta":3,"explicacao":"Gabarito: <strong>Universidades federais.</strong>.","banca":"FUNDATEC","ano":2023,"temas_relacionados":["lei_11892_2008"]},{"id":2182358,"enunciado":"Em conformidade com o Art. 7.º da Lei n.º 11.892/2008, são objetivos dos Institutos Federais: “I - ministrar educação profissional técnica de nível médio, prioritariamente na forma de cursos integrados, para os concluintes do ensino fundamental e para o público da educação de jovens e adultos; [...] VI - ministrar em nível de educação superior: a) cursos superiores de tecnologia visando à formação de profissionais para os diferentes setores da economia; b) cursos de licenciatura, bem como programas especiais de formação pedagógica, com vistas na formação de professores para a educação básica, sobretudo nas áreas de ciências e matemática, e para a educação profissional; c) cursos de bacharelado e engenharia, visando à formação de profissionais para os diferentes setores da economia e áreas do conhecimento; d) cursos de pós-graduação lato sensu de aperfeiçoamento e especialização, visando à formação de especialistas nas diferentes áreas do conhecimento; e","opcoes":["cursos de pós-graduação stricto sensu de mestrado e doutorado, que contribuam para promover o estabelecimento de bases sólidas em educação, ciência e tecnologia, com vistas no processo de geração e inovação tecnológica.”","25% e 15%.","30% e 25%.","40% e 30%.","50% e 20%.","60% e 25%."],"correta":4,"explicacao":"Gabarito: <strong>50% e 20%.</strong>.","banca":"UFPR","ano":2023,"temas_relacionados":["lei_11892_2008"]},{"id":2186611,"enunciado":"A Lei n.º 11.892/2008 institui a Rede Federal de Educação Profissional, Científica e Tecnológica, cria os Institutos Federais de Educação, Ciência e Tecnologia, e dá outras providências. Sobre o tema, é correto afirmar que:","opcoes":["entre os objetivos dos Institutos Federais, consta o de ofertar educação básica em todos os seus níveis e modalidades.","a administração dos Institutos Federais terá como órgãos superiores o Colégio de Discentes e o Conselho de Diretores.","os Institutos Federais poderão ter estrutura de campus único, sendo que, nesse caso, a Reitoria deverá ser sediada nas dependências desse campus.","o cargo de Reitor de Instituto Federal é passível de ser ocupado por servidor técnico-administrativo que seja eleito para tal cargo pela comunidade escolar.","os Institutos Federais poderão ministrar cursos de pós-graduação lato sensu de aperfeiçoamento e especialização, e cursos de pós-graduação stricto sensu de mestrado e doutorado."],"correta":4,"explicacao":"Gabarito: <strong>os Institutos Federais poderão ministrar cursos de pós-graduação lato sensu de aperfeiçoamento e especialização, e cursos de pós-graduação stricto sensu de mestrado e doutorado.</strong>.","banca":"UFPR","ano":2023,"temas_relacionados":["lei_11892_2008"]},{"id":2209741,"enunciado":"Segundo a Lei nº 11.892/2008, que institui a Rede Federal de Educação Profissional, Científica e Tecnológica e cria os Institutos Federais de Educação, Ciência e Tecnologia, analise as assertivas abaixo e assinale a alternativa correta. I. A finalidade dos Institutos Federais é promover exclusivamente a educação em nível superior que esteja relacionada à preservação ao meio ambiente. II. Os Institutos Federais são equiparados às escolas públicas municipais. III. O Colégio Pedro II é instituição federal de ensino, pluricurricular e multicampi, vinculada ao Ministério da Educação e especializada na oferta de educação básica e de licenciaturas.","opcoes":["Todas estão corretas.","Todas estão incorretas.","Apenas I está correta.","Apenas III está correta.","Apenas I e II estão corretas."],"correta":3,"explicacao":"Gabarito: <strong>Apenas III está correta.</strong>.","banca":"FUNDATEC","ano":2023,"temas_relacionados":["lei_11892_2008"]},{"id":2209747,"enunciado":"De acordo com a Lei nº 11.892/2008, os Institutos Federais são instituições de educação superior, básica e profissional, pluricurriculares e multicampi, especializados na oferta de educação profissional e tecnológica nas diferentes modalidades de ensino, com base na conjugação de conhecimentos técnicos e tecnológicos com as suas práticas pedagógicas. São objetivos dos Institutos Federais, EXCETO:","opcoes":["Ministrar cursos de formação inicial e continuada de trabalhadores, objetivando a capacitação, o aperfeiçoamento, a especialização e a atualização de profissionais, em todos os níveis de escolaridade, nas áreas da educação profissional e tecnológica.","Realizar pesquisas aplicadas, estimulando o desenvolvimento de soluções técnicas e tecnológicas, estendendo seus benefícios à comunidade.","Ministrar em nível de educação superior cursos superiores de tecnologia visando à formação de profissionais para os diferentes setores da economia.","Estimular na educação superior cursos de educação cívica e bom comportamento.","Estimular e apoiar processos educativos que levem à geração de trabalho e renda e à emancipação do cidadão na perspectiva do desenvolvimento socioeconômico local e regional."],"correta":3,"explicacao":"Gabarito: <strong>Estimular na educação superior cursos de educação cívica e bom comportamento.</strong>.","banca":"FUNDATEC","ano":2023,"temas_relacionados":["lei_11892_2008"]},{"id":2210253,"enunciado":"A Lei nº 11.892/2008 foi responsável por criar os Institutos Federais de Educação, Ciência e Tecnologia. Assinale a alternativa que apresenta um dos objetivos dos Institutos Federais mencionados na referida lei.","opcoes":["Ampliar o acesso apenas à educação superior no país.","Descentralizar a gestão das universidades federais.","Ofertar educação profissional e tecnológica, em todos os seus níveis e modalidades.","Criar novas universidades privadas em regiões carentes.","Transformar todas as escolas estaduais em institutos federais."],"correta":2,"explicacao":"Gabarito: <strong>Ofertar educação profissional e tecnológica, em todos os seus níveis e modalidades.</strong>.","banca":"FUNDATEC","ano":2023,"temas_relacionados":["lei_11892_2008"]},{"id":2211816,"enunciado":"Analise as assertivas abaixo, assinalando V, se verdadeiras, ou F, se falsas, a partir dos princípios previstos na Lei Federal nº 11.892/2008, que institui a Rede Federal de Educação Profissional, Científica e Tecnológica, cria os Institutos Federais de Educação, Ciência e Tecnologia. ( ) Os Institutos Federais têm por finalidade realizar e estimular a pesquisa aplicada, a produção cultural, o empreendedorismo, o cooperativismo e o desenvolvimento científico e tecnológico. ( ) Os Institutos Federais têm por característica constituir-se em centro de excelência na oferta do ensino de ciências, em geral, e de ciências aplicadas, em particular, estimulando o desenvolvimento de espírito crítico, voltado à investigação teórica. ( ) Os Institutos Federais possuem como principal objetivo fomentar a educação infantil em todos os Estados e Distrito Federal. A ordem correta de preenchimento dos parênteses, de cima para baixo, é:","opcoes":["F – V – V.","V – F – V.","F – F – F.","F – V – F.","V – F – F."],"correta":4,"explicacao":"Gabarito: <strong>V – F – F.</strong>.","banca":"FUNDATEC","ano":2023,"temas_relacionados":["lei_11892_2008"]},{"id":2219882,"enunciado":"Nos termos da Lei nº 11.892/2008, que institui a Rede Federal de Educação Profissional, Científica e Tecnológica, cria os Institutos Federais de Educação, Ciência e Tecnologia, e dá outras providências, assinale a alternativa que NÃO constitui um dos objetivos dos Institutos Federais.","opcoes":["Realizar pesquisas aplicadas, estimulando o desenvolvimento de soluções técnicas e tecnológicas, estendendo seus benefícios à comunidade.","Estimular e apoiar processos educativos que levem à geração de trabalho e renda e à emancipação do cidadão na perspectiva do desenvolvimento socioeconômico local e regional.","Ministrar educação lúdica para o nível infantil, prioritariamente na forma de jogos tecnológicos.","Ministrar cursos de formação inicial e continuada de trabalhadores, objetivando a capacitação, o aperfeiçoamento, a especialização e a atualização de profissionais, em todos os níveis de escolaridade, nas áreas da educação profissional e tecnológica.","Ministrar, em nível de educação superior, cursos superiores de tecnologia visando à formação de profissionais para os diferentes setores da economia."],"correta":2,"explicacao":"Gabarito: <strong>Ministrar educação lúdica para o nível infantil, prioritariamente na forma de jogos tecnológicos.</strong>.","banca":"FUNDATEC","ano":2023,"temas_relacionados":["lei_11892_2008"]},{"id":2226001,"enunciado":"Em relação aos Institutos Federais de Educação, Ciência e Tecnologia, assinale a alternativa correta segundo a Lei Federal nº 11.892/2008.","opcoes":["Possuem natureza jurídica de empresa pública.","São instituições de educação superior, básica e profissional, pluricurriculares e multicampi, especializados na oferta de educação profissional e tecnológica nas diferentes modalidades de ensino, com base na conjugação de conhecimentos técnicos e tecnológicos com as suas práticas pedagógicas.","Têm como órgão executivo o Conselho Superior.","São equiparados às universidades estaduais para efeito da incidência das disposições que regem a regulação, avaliação e supervisão das instituições e dos cursos de educação superior.","Possuem natureza jurídica de fundação."],"correta":1,"explicacao":"Gabarito: <strong>São instituições de educação superior, básica e profissional, pluricurriculares e multicampi, especializados na oferta de educação profissional e tecnológica nas diferentes modalidades de ensino, com base na conjugação de conhecimentos técnicos e tecnológicos com as suas práticas pedagógicas.</strong>.","banca":"INSTITUTO AOCP","ano":2023,"temas_relacionados":["lei_11892_2008"]},{"id":2226221,"enunciado":"De acordo com a Lei Federal nº 11.892/2008, que instituiu a Rede Federal de Educação Profissional, Científica e Tecnológica, assinale a alternativa correta.","opcoes":["Os Institutos Federais possuem natureza jurídica de fundação pública e configuram-se como universidades especializadas.","Os Institutos Federais, as Universidades Federais e o Colégio Pedro II integram a Rede Federal de Educação Profissional, Científica e Tecnológica.","A Universidade Federal do Maranhão é instituição de educação superior, básica e profissional, pluricurricular e multicampi, especializada na oferta de educação profissional e tecnológica nas diferentes modalidades de ensino, com base na conjugação de conhecimentos técnicos e tecnológicos com as suas práticas pedagógicas.","O Instituto Federal do Maranhão possui natureza jurídica de autarquia e detém autonomia administrativa, patrimonial, financeira, didáticopedagógica e disciplinar.","O Colégio Pedro II é instituição especializada na oferta de educação básica, profissional e tecnológica nas diferentes modalidades de ensino."],"correta":3,"explicacao":"Gabarito: <strong>O Instituto Federal do Maranhão possui natureza jurídica de autarquia e detém autonomia administrativa, patrimonial, financeira, didáticopedagógica e disciplinar.</strong>.","banca":"INSTITUTO AOCP","ano":2023,"temas_relacionados":["lei_11892_2008"]},{"id":2238449,"enunciado":"Segundo os termos da Lei nº 11.892/2008, que institui a Rede Federal de Educação Profissional, Científica e Tecnológica, no âmbito de sua atuação, os Institutos Federais exercerão o papel de instituições __________ de competências profissionais. Assinale a alternativa que preenche corretamente a lacuna do trecho acima.","opcoes":["acreditadoras e certificadoras","certificadoras e repressoras","repressoras e educadoras","educadoras e autoritárias","autoritárias e acreditadoras"],"correta":0,"explicacao":"Gabarito: <strong>acreditadoras e certificadoras</strong>.","banca":"FUNDATEC","ano":2023,"temas_relacionados":["lei_11892_2008"]},{"id":2238728,"enunciado":"Em relação aos Institutos Federais de Educação, Ciência e Tecnologia, assinale a alternativa INCORRETA segundo a Lei Federal nº 11.892/2008.","opcoes":["Têm por objetivo ministrar educação profissional técnica de nível médio, prioritariamente na forma de cursos integrados, para os concluintes do ensino fundamental e para o público da educação de jovens e adultos.","No âmbito em que atuam, exercem o papel de instituições acreditadoras e certificadoras de competências profissionais.","Caracterizam-se como universidade especializada na oferta de educação básica e de licenciaturas.","Têm por objetivo ministrar, em nível de educação superior, cursos superiores de tecnologia visando à formação de profissionais para os diferentes setores da economia.","Têm por finalidade e característica desenvolver a educação profissional e tecnológica como processo educativo e investigativo de geração e adaptação de soluções técnicas e tecnológicas às demandas sociais e peculiaridades regionais."],"correta":2,"explicacao":"Gabarito: <strong>Caracterizam-se como universidade especializada na oferta de educação básica e de licenciaturas.</strong>.","banca":"INSTITUTO AOCP","ano":2023,"temas_relacionados":["lei_11892_2008"]},{"id":2253342,"enunciado":"Leia, analise as assertivas abaixo e depois responda à questão. O Instituto Federal, no desenvolvimento da sua ação acadêmica, deverá: I - Garantir o mínimo de 50% (cinquenta por cento) de suas vagas para atender a educação profissional técnica de nível médio, prioritariamente na forma de cursos integrados, para os concluintes do ensino fundamental e para o público da educação de jovens e adultos. II - Garantir o mínimo de 50% (cinquenta por cento) de suas vagas para atender aos cursos superiores de tecnologia, visando à formação de profissionais para os diferentes setores da economia. III - Garantir o mínimo de 50% (cinquenta por cento) de suas vagas para atender aos cursos de pós-graduação lato sensu de aperfeiçoamento e especialização, visando à formação de especialistas nas diferentes áreas do conhecimento. IV - Garantir o mínimo de 20% (vinte por cento) de suas vagas para atender aos cursos de licenciatura, bem como programas especiais de formação pedagógica, com vistas à formação de professores para a educação básica, sobretudo nas áreas de ciências e matemática. V - Garantir o mínimo de 20% (vinte por cento) de suas vagas para atender aos cursos de bacharelado e engenharia, visando à formação de profissionais para os diferentes setores da economia e áreas do conhecimento. VI - Garantir o mínimo de 20% (vinte por cento) de suas vagas para atender aos cursos de pós-graduação stricto sensu de mestrado e doutorado, que contribuam para promover o estabelecimento de bases sólidas em educação, ciência e tecnologia, com vistas ao processo de geração e inovação tecnológica. Conforme a Lei n.º 11.892/08, a alternativa CORRETA é:","opcoes":["Somente as assertivas I e III estão corretas.","Somente as assertivas I e IV estão corretas.","Somente as assertivas II e V estão corretas.","Somente as assertivas II e VI estão corretas.","Nenhuma das assertivas está correta."],"correta":1,"explicacao":"Gabarito: <strong>Somente as assertivas I e IV estão corretas.</strong>.","banca":"IF-MG","ano":2023,"temas_relacionados":["lei_11892_2008"]},{"id":2253721,"enunciado":"Leia as afirmações sobre os Institutos Federais de Educação, Ciência e Tecnologia (Institutos Federais) e depois responda à questão: I - Os Institutos Federais são instituições de educação superior, básica e profissional, pluricurriculares e multicampi. II - Os Institutos Federais são instituições que possuem natureza jurídica autárquica e são detentores de autonomia administrativa, patrimonial, financeira, didático-pedagógica e disciplinar. III - Os Institutos Federais exercem o papel de instituições acreditadoras e certificadoras de competências profissionais. IV - Os Institutos Federais têm autonomia para criar e extinguir cursos, nos limites de sua área de atuação territorial. V - Os Institutos Federais podem registrar diplomas dos cursos por eles oferecidos, mediante autorização do seu Conselho Superior, aplicando-se, no caso da oferta de cursos à distância, a legislação específica. Após ler as afirmações, a alternativa CORRETA é:","opcoes":["Somente I, III e V estão corretas.","Somente II e IV estão corretas.","Somente III e IV estão corretas.","Somente V está correta.","Todas as alternativas estão corretas."],"correta":4,"explicacao":"Gabarito: <strong>Todas as alternativas estão corretas.</strong>.","banca":"IF-MG","ano":2023,"temas_relacionados":["lei_11892_2008"]},{"id":2281026,"enunciado":"A Lei nº 11.892/08 institui a Rede Federal de Educação Profissional, Científica e Tecnológica e cria os Institutos Federais de Educação, Ciência e Tecnologia. Considerando as finalidades e características dos Institutos Federais, analise as assertivas a seguir e assinale a alternativa correta: I. Ofertar educação profissional e tecnológica, em todos os seus níveis e modalidades, formando e qualificando cidadãos com vistas na atuação profissional nos diversos setores da economia, com ênfase no desenvolvimento socioeconômico local, regional e nacional. II. Orientar sua oferta formativa em benefício da consolidação e fortalecimento dos arranjos produtivos, sociais e culturais locais, identificados com base no mapeamento das potencialidades de desenvolvimento socioeconômico e cultural no âmbito de atuação do Instituto Federal. III. Constituir-se em centro de excelência na oferta do ensino de ciências, em geral, e de ciências aplicadas, em particular, estimulando o desenvolvimento de espírito crítico, voltado à investigação empírica.","opcoes":["Apenas a assertiva II está correta.","Apenas a assertiva III está correta.","Todas as assertivas estão corretas.","Nenhuma das assertivas está correta."],"correta":2,"explicacao":"Gabarito: <strong>Todas as assertivas estão corretas.</strong>.","banca":"IF-SP","ano":2023,"temas_relacionados":["lei_11892_2008"]},{"id":2289764,"enunciado":"Sobre a Administração Pública dos Institutos Federais, assinale a alternativa correta:","opcoes":["Os Institutos Federais são autarquias dotadas de autonomia, patrimônio e receita próprias, estando subordinadas ao Ministério da Educação.","Os atos de improbidade administrativa são constituídos por atos dolosos ou culposos que atentam contra os princípios da administração pública, geram enriquecimento ilícito e causam dano ao erário.","O processo administrativo inicia-se somente pelo requerimento do interessado.","A administração dos Institutos Federais tem como órgãos superiores o Colégio de Dirigentes e o Conselho Superior, tendo este último caráter consultivo e deliberativo e aquele, apenas caráter consultivo."],"correta":3,"explicacao":"Gabarito: <strong>A administração dos Institutos Federais tem como órgãos superiores o Colégio de Dirigentes e o Conselho Superior, tendo este último caráter consultivo e deliberativo e aquele, apenas caráter consultivo.</strong>.","banca":"IF SUL - MG","ano":2023,"temas_relacionados":["lei_11892_2008"]},{"id":2295109,"enunciado":"De acordo com a Lei nº 11.892/2008, que institui a Rede Federal de Educação Profissional, Científica e Tecnológica, cria os Institutos Federais de Educação, Ciência e Tecnologia, e dá outras providências, analise as assertivas abaixo e assinale a alternativa correta. I. Os Institutos Federais têm como finalidade o desenvolvimento de atividades exclusivamente econômicas que irão auxiliar os usuários em seu ingresso no mercado financeiro. II. A Lei nº 11.892/2008 estabelece que os Institutos Federais são responsáveis apenas pela implementação e desenvolvimento do ensino fundamental, para que o aluno saia da escola capacitado a exercer qualquer tipo de profissão. III. São objetivos dos Institutos Federais realizar pesquisas aplicadas, estimulando o desenvolvimento de soluções técnicas e tecnológicas, estendendo seus benefícios à comunidade.","opcoes":["Todas as assertivas estão corretas.","Todas as assertivas estão incorretas.","Apenas a assertiva I está correta.","Apenas a assertiva III está correta.","Apenas as assertivas I e II estão corretas."],"correta":3,"explicacao":"Gabarito: <strong>Apenas a assertiva III está correta.</strong>.","banca":"FUNDATEC","ano":2023,"temas_relacionados":["lei_11892_2008"]},{"id":2310217,"enunciado":"O Ifes tem como objetivo principal promover a formação profissional e tecnológica dos estudantes, por meio de cursos técnicos, tecnológicos e superiores. Eles devem oferecer ensino de qualidade, atualizado e alinhado com as demandas do mercado de trabalho. Para tanto, é necessária uma boa gestão. Segundo a Lei nº 11.892/2008, poderão ser nomeados Pró-Reitores no Ifes:","opcoes":["Os servidores ocupantes de cargo efetivo da Carreira docente ou de cargo efetivo com nível superior da Carreira dos técnico-administrativos do Plano de Carreira dos Cargos Técnico-administrativos em Educação, desde que possuam o mínimo de 5 (cinco) anos de efetivo exercício em instituição federal de educação profissional e tecnológica.","Apenas os servidores ocupantes de cargo efetivo da Carreira docente desde que possuam o mínimo de 5 (cinco) anos de efetivo exercício em instituição federal de educação profissional e tecnológica.","Os servidores ocupantes de cargo efetivo da Carreira docente desde que possuam o mínimo de 2 (dois) anos de efetivo exercício em instituição federal de educação profissional e tecnológica.","os servidores ocupantes de cargo efetivo da Carreira docente ou de cargo efetivo com nível médio ou superior da Carreira dos técnico-administrativos do Plano de Carreira dos Cargos Técnico-administrativos em Educação, desde que possuam o mínimo de 4 (anos) anos de efetivo exercício em instituição federal de educação profissional e tecnológica.","Qualquer servidor, visto que se trata de cargo de livre nomeação."],"correta":0,"explicacao":"Gabarito: <strong>Os servidores ocupantes de cargo efetivo da Carreira docente ou de cargo efetivo com nível superior da Carreira dos técnico-administrativos do Plano de Carreira dos Cargos Técnico-administrativos em Educação, desde que possuam o mínimo de 5 (cinco) anos de efetivo exercício em instituição federal de educação profissional e tecnológica.</strong>.","banca":"IF-ES","ano":2023,"temas_relacionados":["lei_11892_2008"]},{"id":2320439,"enunciado":"No que concerne ao Decreto n.º 9.830/2019, que regulamentou o disposto nos artigos 20 a 30 da Lei de Introdução às Normas do Direito Brasileiro, julgue o item a seguir.\n\nA decisão nas esferas administrativa, controladora ou judicial somente necessita de motivação quando for fundamentada em valores jurídicos abstratos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2320440,"enunciado":"No que concerne ao Decreto n.º 9.830/2019, que regulamentou o disposto nos artigos 20 a 30 da Lei de Introdução às Normas do Direito Brasileiro, julgue o item a seguir.\n\nA responsabilidade do agente público é afastada quando este age com dolo na prática de atos administrativos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2320441,"enunciado":"No que concerne ao Decreto n.º 9.830/2019, que regulamentou o disposto nos artigos 20 a 30 da Lei de Introdução às Normas do Direito Brasileiro, julgue o item a seguir.\n\nA decisão que impuser sanção ao agente público deverá levar em conta a dosimetria das demais sanções da mesma natureza e relativas ao mesmo fato.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2335326,"enunciado":"Considerando-se como verdadeiras as informações constantes do curriculo hipotético apresentado, nos termos da Lei 11.892/08 e da Lei 11.091/05, julgue as assertivas abaixo: I. Fulano de Tal podera ser nomeado pré-reitor, visto que é ocupante de cargo efetivo com nivel superior da carreira dos técnicos administrativos do Plano de Carreira dos Cargos Técnico-Administrativos em Educagéo. II. Fulano de Tal ndo podera ser nomeado pro-reitor, visto que não é ocupante de cargo efetivo da carreira docente. III. Fulano de Tal podera ser nomeado pro-reitor, visto que possui o minimo de 5 (cinco) anos de efetivo exercicio em instituicdo federal de educação profissional e tecnoldgica. IV. Fulano de Tal ndo poderá ser nomeado pré-reitor, visto que ndo possui o minimo de 10 (dez) anos de efetivo exercicio em instituição federal de educação profissional e tecnolégica. Esté correto o que se afirma em:","opcoes":["I e II.","II e III.","III e IV.","II e IV.","I e III."],"correta":4,"explicacao":"Gabarito: <strong>I e III.</strong>.","banca":"IF-MT","ano":2023,"temas_relacionados":["lei_11892_2008"]},{"id":2345718,"enunciado":"À luz da Lei nº. 13.639/2018, julgue o item.\n\n\n\n\n\n\n\nO Conselho Federal dos Técnicos Industriais (CFT) e os Conselhos Regionais dos Técnicos Industriais (CRTs) são fundações públicas com autonomia administrativa e financeira e estrutura federativa.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2345719,"enunciado":"À luz da Lei nº. 13.639/2018, julgue o item.\n\nO CFT e os CRTs terão sua estrutura e seu funcionamento definidos em regimento interno próprio, aprovado pela maioria absoluta de seus conselheiros.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2345720,"enunciado":"À luz da Lei nº. 13.639/2018, julgue o item.\n\nO CFT e os CRTs  serão integrados, exclusivamente, por brasileiros natos cujos diplomas profissionais estejam registrados de acordo com a legislação em vigor.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2345721,"enunciado":"À luz da Lei nº. 13.639/2018, julgue o item.\n\nO CFT é composto da diretoria executiva, da secretaria-geral e da tesouraria.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2345722,"enunciado":"À luz da Lei nº. 13.639/2018, julgue o item.\n\nO mandato dos membros dos Conselhos Federais terá duração de quatro anos, admitida uma reeleição.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2345723,"enunciado":"À luz da Lei nº. 13.639/2018, julgue o item.\n\nO plenário dos Conselhos Regionais será composto de, no mínimo, doze e, no máximo, 48 conselheiros regionais, acrescido dos membros da diretoria executiva, observado o quantitativo de profissionais inscritos em cada Conselho.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2345724,"enunciado":"À luz da Lei nº. 13.639/2018, julgue o item.\n\nNão será efetuado termo de responsabilidade técnica sem o prévio recolhimento da taxa do termo de responsabilidade técnica pela pessoa física do profissional ou pela pessoa jurídica responsável.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2345725,"enunciado":"À luz da Lei nº. 13.639/2018, julgue o item.\n\nO processo disciplinar no âmbito do CFT e dos CRTs somente poderá ser instaurado de ofício.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2345726,"enunciado":"À luz da Lei nº. 13.639/2018, julgue o item.\n\nCabe a cada Conselho Regional a emissão do registro da carteira de identificação para o exercício das atividades do técnico industrial que estabelecer domicílio profissional no respectivo território, prevalecendo o domicílio da pessoa física.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2345727,"enunciado":"À luz da Lei nº. 13.639/2018, julgue o item.\n\nO CFT e os CRTs serão auditados anualmente por auditoria independente e os resultados serão divulgados para conhecimento público.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2345728,"enunciado":"De acordo com o Código de Ética e Disciplina do Técnico Industrial, julgue o item.\n\n\n\n\n\n\n\nO técnico industrial é um profissional liberal, o qual exerce atividades intelectuais de interesse público e alcance social mediante complexa relação de trabalho, devendo deter, por formação, um conjunto sistematizado de conhecimentos das artes, das ciências e das técnicas, assim como das teorias e práticas específicas de técnico em sua área de formação.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2345729,"enunciado":"De acordo com o Código de Ética e Disciplina do Técnico Industrial, julgue o item.\n\nOs técnicos industriais devem manter e desenvolver seus conhecimentos preservando independência, parcialidade, integridade e competência profissional, de modo a contribuir para a categoria por meio do desempenho de suas atribuições específicas.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2345730,"enunciado":"De acordo com o Código de Ética e Disciplina do Técnico Industrial, julgue o item.\n\nOs técnicos industriais devem defender os direitos fundamentais da pessoa humana, expressos na Constituição brasileira e em acordos internacionais.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2345731,"enunciado":"De acordo com o Código de Ética e Disciplina do Técnico Industrial, julgue o item.\n\nO técnico industrial é autorizado a assumir responsabilidades profissionais que extrapolem os limites de suas atribuições, habilidades e competências, em seus respectivos campos de atuação, desde que seja em regime de urgência.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2345732,"enunciado":"De acordo com o Código de Ética e Disciplina do Técnico Industrial, julgue o item.\n\nOs técnicos industriais devem, no exercício das atividades profissionais, zelar pela conservação e preservação do patrimônio público e privado.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2345733,"enunciado":"De acordo com o Código de Ética e Disciplina do Técnico Industrial, julgue o item.\n\nO técnico industrial autor de projeto ou responsável pela execução de serviço ou obra deve resguardar o sigilo a respeito da atividade realizada, somente a identificando mediante autorização judicial.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2345734,"enunciado":"De acordo com o Código de Ética e Disciplina do Técnico Industrial, julgue o item.\n\nOs técnicos industriais devem empregar esforços para assegurar o atendimento das necessidades humanas referentes à funcionalidade, à economicidade, à durabilidade, ao conforto, à higiene e à acessibilidade das obras e dos serviços prestados.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2345735,"enunciado":"De acordo com o Código de Ética e Disciplina do Técnico Industrial, julgue o item.\n\nNas relações contratuais, o técnico industrial deve exercer suas atividades profissionais de maneira parcial, de acordo com as vontades e determinações do contratante, respeitando as leis, os contratos e as normas técnicas estabelecidas.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2345736,"enunciado":"De acordo com o Código de Ética e Disciplina do Técnico Industrial, julgue o item.\n\nOs técnicos industriais devem considerar a profissão como uma atividade mercantil com fins privados.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2345737,"enunciado":"De acordo com o Código de Ética e Disciplina do Técnico Industrial, julgue o item.\n\nConstitui‑se infração ética todo ato cometido pelo profissional que atente contra os princípios éticos, descumpra os deveres do ofício, pratique condutas expressamente vedadas ou lese direitos reconhecidos de outrem.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2353894,"enunciado":"De acordo com a Lei N.º 11.892, de 29 de dezembro de 2008, que criou a Rede Federal de Educação Profissional, Científica e Tecnológica, os Institutos Federais são instituições","opcoes":["de educação básica e profissional, multicurriculares e multicampi, especializados na oferta de educação técnica e tecnológica, prioritariamente no ensino médio.","de educação básica e superior, com arranjos curriculares sistêmicos e intercampi, focados na oferta de ensino técnico e tecnológico, em modalidades presenciais ou à distância.","de educação superior, básica e profissional, pluricurriculares e multicampi, especializados na oferta de educação profissional e tecnológica nas diferentes modalidades de ensino.","de educação superior, básica, técnica e tecnológica, com currículos multiculturais e descentralização por meio de campus, especializados na oferta de educação profissional, nas diferentes modalidades de ensino."],"correta":2,"explicacao":"Gabarito: <strong>de educação superior, básica e profissional, pluricurriculares e multicampi, especializados na oferta de educação profissional e tecnológica nas diferentes modalidades de ensino.</strong>.","banca":"FUNCERN","ano":2024,"temas_relacionados":["lei_11892_2008"]},{"id":2353896,"enunciado":"Maria da Luz é assistente de aluno no campus do IFRN, em João Câmara. Certo dia, um de seus familiares indagou se ela trabalhava em uma universidade ou em uma escola técnica. A essa indagação, a resposta correta da servidora seria afirmar que os Institutos Federais","opcoes":["possuem uma identidade híbrida e, portanto, devem ser considerados como escolas técnicas superiores, pois priorizam a oferta de cursos superiores de tecnologia (tecnólogos), apesar de ofertarem cursos técnicos não superiores.","são instituições de nível superior, estruturadas a partir do ensino técnico e da pesquisa aplicada. Estão vinculados às Universidades Federais, com autonomia universitária e estrutura organizacional semelhante, incluindo reitoria e pró-reitorias.","possuem uma institucionalidade singular e, para efeito da incidência das disposições que regem a regulação, a avaliação e a supervisão das instituições e dos cursos de educação superior, são equiparados às universidades federais.","podem ser considerados escolas técnicas, pois pelo menos cinquenta por cento de suas vagas devem ser destinados à oferta de vagas em cursos técnicos de nível médio. Sendo assim, apesar de também oferecer cursos superiores, o foco é a educação profissional, que são os cursos de qualificação profissional e os cursos técnicos."],"correta":2,"explicacao":"Gabarito: <strong>possuem uma institucionalidade singular e, para efeito da incidência das disposições que regem a regulação, a avaliação e a supervisão das instituições e dos cursos de educação superior, são equiparados às universidades federais.</strong>.","banca":"FUNCERN","ano":2024,"temas_relacionados":["lei_11892_2008"]},{"id":2354280,"enunciado":"Tendo em consideração as disposições contidas na Lei nº 11.892/2009, que institui a Rede Federal de Educação Profissional, Científica e Tecnológica, cria os Institutos Federais de Educação, Ciência e Tecnologia, analise as assertivas abaixo e assinale a alternativa correta. I. O Colégio Pedro II é parte da Rede Federal de Educação Profissional, Científica e Tecnológica.   II. Embora sejam dotados de ampla capacidade organizativa, os Institutos Federais não têm autonomia para criar ou extinguir cursos, tampouco para registrar diplomas dos cursos por eles oferecidos. III. Entre as finalidades e características dos Institutos Federais está a de realizar e estimular a pesquisa aplicada, a produção cultural, o empreendedorismo, o cooperativismo e o desenvolvimento científico e tecnológico.","opcoes":["Todas as assertivas estão corretas.","Todas as assertivas estão incorretas.","Apenas a assertiva I está correta.","Apenas a assertiva II está correta","Apenas as assertivas I e III estão corretas."],"correta":4,"explicacao":"Gabarito: <strong>Apenas as assertivas I e III estão corretas.</strong>.","banca":"FUNDATEC","ano":2023,"temas_relacionados":["lei_11892_2008"]},{"id":2356044,"enunciado":"Os Institutos Federais de Educação, Ciência e Tecnologia, criados pela Lei n.º 11.892/2008, têm como órgão executivo a reitoria, composta por 1 Reitor e 5 Pró-Reitores. De acordo com as disposições do citado diploma legal, os Reitores serão nomeados pelo Presidente da República, para mandato de","opcoes":["4 anos, vedada a recondução.","2 anos, vedada a recondução.","2 anos, permitida uma recondução, após processo de consulta à comunidade escolar do respectivo Instituto Federal.","4 anos, permitida uma recondução, após processo de consulta à comunidade escolar do respectivo Instituto Federal."],"correta":3,"explicacao":"Gabarito: <strong>4 anos, permitida uma recondução, após processo de consulta à comunidade escolar do respectivo Instituto Federal.</strong>.","banca":"FUNCERN","ano":2024,"temas_relacionados":["lei_11892_2008"]},{"id":2356059,"enunciado":"O Instituto Federal de Educação, Ciência e Tecnologia - (IF), como organização educativa, foi criada no Brasil pela Lei nº 11.8921, de 29 de dezembro de 2008. Com base na supracitada lei, sobre os Institutos Federais é correto afirmar:","opcoes":["É uma entidade da administração direta, com natureza jurídica de autarquia, detentora de autonomia didático-pedagógica, disciplinar, administrativa, patrimonial e financeira.","O campus é uma escola funcionando com autonomia de gestão administrativa e financeira, a quem cabe desenvolver as ações acadêmicas (ensino, pesquisa e extensão), delineadas em Projeto Político-Pedagógico (PPP) e Plano de Desenvolvimento Institucional (PDI) construído no âmbito de cada campus.","A institucionalização dar-se-á de forma decorrente de estruturas acadêmicas multiníveis, pluricurricular e multicampi, especializada na oferta de educação profissional e tecnológica nas diferentes modalidades de ensino, no contexto da organização pública brasileira.","A institucionalização dos IFs, no que concerne ao ensino dar-se-á mediante a oferta de vagas em cada exercício e em cada campus, assim distribuídas: no mínimo 50% (cinquenta por cento) para educação profissional técnica de nível médio, prioritariamente, na forma integrada, e de no máximo, 10% (dez por cento) para a formação de professores, e os demais percentuais até a totalidade da capacidade de cada campus distribuídas nas demais formas de oferta educacional."],"correta":2,"explicacao":"Gabarito: <strong>A institucionalização dar-se-á de forma decorrente de estruturas acadêmicas multiníveis, pluricurricular e multicampi, especializada na oferta de educação profissional e tecnológica nas diferentes modalidades de ensino, no contexto da organização pública brasileira.</strong>.","banca":"FUNCERN","ano":2024,"temas_relacionados":["lei_11892_2008"]},{"id":2356060,"enunciado":"Sobre os documentos institucionais definidos no corpo da Lei nº 11.892/2008, como Plano de Desenvolvimento Institucional (PDI) e no Projeto Político-Pedagógico (PPP), é correto afirmar que:","opcoes":["São documentos unificados de caráter oficial, de identidade, com abrangência para toda a jurisdição de um Instituto Federal de Educação, Ciência e Tecnologia, devidamente instituído.","São documentos que possuem, simultaneamente, uma racionalidade administrativa e pedagógica, com semelhantes processos de regulação.","São documentos de caráter oficial, de abrangência de cada campus que pertence ao IF, que contribui no processo de regulação, avaliação e supervisão da Instituição e dos cursos pelo campus ofertado.","São documentos complementares à gestão, uma vez que, o Estatuto e o Regimento Interno do Instituto Federal de Educação, Ciência e Tecnologia (IF) devidamente, instituído, se constituem em normativos basilares em que os objetivos, funções e metas institucionais encontram-se definidos."],"correta":0,"explicacao":"Gabarito: <strong>São documentos unificados de caráter oficial, de identidade, com abrangência para toda a jurisdição de um Instituto Federal de Educação, Ciência e Tecnologia, devidamente instituído.</strong>.","banca":"FUNCERN","ano":2024,"temas_relacionados":["lei_11892_2008"]},{"id":2356062,"enunciado":"De acordo com o Art. 178 da Organização Didática do Instituto Federal de Educação, Ciência e Tecnologia do Rio Grande do Norte, aprovada pela Resolução 38/2012-CONSUP/IFRN, as ações de acompanhamento da frequência e do desempenho acadêmico dos estudantes devem ser desenvolvidas","opcoes":["de forma periódica e sistematizada, sob a coordenação do Coordenador de Curso, em conjunto com os professores e a equipe técnico-pedagógica.","por meio de estratégias de acompanhamento devidamente coordenadas pela equipe técnicopedagógica com a finalidade de garantir aos estudantes a permanência com êxito e a conclusão do curso.","de forma semestral, sistematizada sob a coordenação da Direção Acadêmica, em conjunto com a equipe técnico-pedagógica.","por meio da equipe técnico-pedagógica, profissionais da assistência estudantil e os professores, utilizando-se de estratégias que sistematizam as dificuldades com relação a permanência do estudante."],"correta":0,"explicacao":"Gabarito: <strong>de forma periódica e sistematizada, sob a coordenação do Coordenador de Curso, em conjunto com os professores e a equipe técnico-pedagógica.</strong>.","banca":"FUNCERN","ano":2024,"temas_relacionados":["lei_11892_2008"]},{"id":2356063,"enunciado":"Considerando o atual Projeto Político Pedagógico do IFRN (2012), bem como a Organização Didática do IFRN (2012), o ensino, a pesquisa e a extensão são atividades","opcoes":["indissociáveis, articuladas na formação acadêmica-profissional, exclusiva, das ofertas do ensino superior.","indissociáveis, articuladoras da formação acadêmico-profissional com a educação integrada.","indissociáveis, porém independentes, pois as prioridades na formação acadêmico-profissional, devem se coadunar aos arranjos produtivos locais relacionados a cada campus.","indissociáveis e se ajustam aos cursos e programas ofertados, em que as prioridades são definidas por modalidade de ensino, priorizando a pesquisa na educação superior."],"correta":1,"explicacao":"Gabarito: <strong>indissociáveis, articuladoras da formação acadêmico-profissional com a educação integrada.</strong>.","banca":"FUNCERN","ano":2024,"temas_relacionados":["lei_11892_2008"]},{"id":2356419,"enunciado":"No âmbito do sistema federal de ensino, os Institutos Federais de Educação, Ciência e Tecnologia, criados com a Lei nº 11.892/2008, fazem parte das instituições que compõem a Rede Federal de Educação Profissional, Científica e Tecnológica. Em conformidade com a referida Lei, é correto afirmar que o Instituto Federal de Educação, Ciência e Tecnologia do Rio Grande do Norte deve","opcoes":["ofertar educação profissional e tecnológica, em todos os seus níveis e modalidades, formando e qualificando cidadãos com vistas à atuação profissional nos diversos setores da economia, com ênfase no desenvolvimento socioeconômico local, regional e nacional, como uma das suas finalidades e características.","promover a integração e a verticalização da educação básica à educação profissional e à educação superior, otimizando a infraestrutura física, os quadros de pessoal e os recursos de gestão, como um dos seus objetivos.","ministrar educação profissional técnica de nível médio, prioritariamente na forma de cursos integrados, para os concluintes do ensino fundamental e para o público da educação de jovens e adultos, como uma das suas finalidades e características.","constituir-se em centro de excelência na oferta do ensino de ciências, em geral, e de ciências aplicadas, em particular, estimulando o desenvolvimento de espírito crítico, voltado à investigação empírica, como um dos seus objetivos."],"correta":0,"explicacao":"Gabarito: <strong>ofertar educação profissional e tecnológica, em todos os seus níveis e modalidades, formando e qualificando cidadãos com vistas à atuação profissional nos diversos setores da economia, com ênfase no desenvolvimento socioeconômico local, regional e nacional, como uma das suas finalidades e características.</strong>.","banca":"FUNCERN","ano":2024,"temas_relacionados":["lei_11892_2008"]},{"id":2356420,"enunciado":"Com a transformação do Centro Federal de Educação Tecnológica do Rio Grande do Norte (CEFET-RN) em Instituto Federal de Educação, Ciência e Tecnologia do Rio Grande do Norte (IFRN), houve a necessidade da reelaboração de diversos documentos regulatórios da instituição, demandando, portanto, a revisão e a reconstrução de documentos que conduziam as ações institucionais. Entre eles, compreendido como o planejamento global de todas as ações da instituição, encontra-se o","opcoes":["Projeto Político Pedagógico do IFRN, que sistematiza concepções, princípios e diretrizes norteadoras dos programas e projetos educativos, em âmbito regional, e constitui-se em um processo e em um documento de caráter normativo.","Plano de Desenvolvimento Institucional do IFRN, que delineia a cultura da instituição, traçando direcionamentos pedagógicos, administrativos e financeiros, em âmbito nacional, e constitui-se em um processo e em um documento de caráter identitário","Projeto Político Pedagógico do IFRN, que sistematiza concepções, princípios e diretrizes norteadoras das práticas e das políticas educativas, em âmbito local, e constitui-se em um processo e em um documento de caráter identitário.","Plano de Desenvolvimento Institucional do IFRN, considerado um instrumento de gestão democrática que oportuniza o processo de reflexão crítica e contínua a respeito das práticas, dos métodos e da identidade institucional."],"correta":2,"explicacao":"Gabarito: <strong>Projeto Político Pedagógico do IFRN, que sistematiza concepções, princípios e diretrizes norteadoras das práticas e das políticas educativas, em âmbito local, e constitui-se em um processo e em um documento de caráter identitário.</strong>.","banca":"FUNCERN","ano":2024,"temas_relacionados":["lei_11892_2008"]},{"id":2356421,"enunciado":"A nova institucionalidade do IFRN, dada pela Lei nº 11.892, de 29 de dezembro de 2008, atribuída a uma instituição centenária, está alicerçada em valores, tradições, práticas, inter-relações sociais, funções sociais, áreas de atuação, públicos-alvo, prestígio social e inserção no projeto microssocial e macrossocial. Nesse sentido, entende-se que o ideal pedagógico da instituição encontra-se representado na função social, nos compromissos pedagógicos e nos valores culturais. No contexto atual, o IFRN tem como função social","opcoes":["contribuir com o aumento da capacidade de (re)inserção sociolaboral de longa duração dos seus egressos, com a extensão de ofertas de boa qualidade aos coletivos mais desfavorecidos, do ponto de vista socioeconômico, para que, uma vez beneficiados pela educação profissional (EP), possam atuar, de forma competente e ética, como agentes de mudanças orientadas à satisfação das necessidades coletivas.","ofertar educação profissional e tecnológica – de qualidade referenciada socialmente e de arquitetura político-pedagógica capaz de articular ciência, cultura, trabalho e tecnologia – comprometida com a formação humana integral, com o exercício da cidadania e com a produção e a socialização do conhecimento, visando, sobretudo, à transformação da realidade na perspectiva da igualdade e da justiça social.","contribuir para uma formação profissional e tecnológica que favoreça, nos mais variados âmbitos, o (re)dimensionamento de ofertas de boa qualidade aos coletivos mais desfavorecidos, comprometida com a formação para o mercado de trabalho, com a produção e a socialização do conhecimento, visando à transformação da realidade na perspectiva da igualdade e da ascensão social.","ofertar educação profissional e tecnológica – de qualidade referenciada socialmente - capaz de articular cultura, trabalho e tecnologia, comprometida com a formação humana integral, com o exercício da cidadania e com a produção e a socialização do conhecimento, visando, sobretudo, à transformação da realidade na perspectiva da igualdade e da ascensão social."],"correta":1,"explicacao":"Gabarito: <strong>ofertar educação profissional e tecnológica – de qualidade referenciada socialmente e de arquitetura político-pedagógica capaz de articular ciência, cultura, trabalho e tecnologia – comprometida com a formação humana integral, com o exercício da cidadania e com a produção e a socialização do conhecimento, visando, sobretudo, à transformação da realidade na perspectiva da igualdade e da justiça social.</strong>.","banca":"FUNCERN","ano":2024,"temas_relacionados":["lei_11892_2008"]},{"id":2356425,"enunciado":"O Art. 6º da Lei nº 11.892/2008, que cria os Institutos Federais de Educação, Ciência e Tecnologia (IFs), apresenta as suas finalidades e características. O inciso II desse artigo afirma que uma das missões dos IFs é desenvolver a educação profissional e tecnológica como processo educativo e investigativo de geração e adaptação de soluções técnicas e tecnológicas às demandas sociais e peculiaridades regionais. Esse inciso","opcoes":["aborda a questão da integração curricular da educação básica com a profissional, bem como da oferta dentro do mesmo projeto pedagógico de cursos nos níveis educacionais: educação básica e superior.","retoma a questão da educação profissional e tecnológica e do desenvolvimento do território, enfatizando o apoio enraizado nas estruturas socioculturais locais, a partir do diagnóstico das oportunidades de desenvolvimento.","determina, como uma das finalidades dos Institutos, o ensino de ciências, ressaltando que tais instituições, ou os profissionais por ela formados ou em formação, devem se ocupar, particularmente, com a aplicabilidade dos conhecimentos científicos.","traz a concepção da pesquisa enquanto princípio educativo, entendendo-a como o trabalho de produção do conhecimento e como atividade instigadora do educando, no sentido de procurar respostas às questões postas pelo mundo do trabalho."],"correta":3,"explicacao":"Gabarito: <strong>traz a concepção da pesquisa enquanto princípio educativo, entendendo-a como o trabalho de produção do conhecimento e como atividade instigadora do educando, no sentido de procurar respostas às questões postas pelo mundo do trabalho.</strong>.","banca":"FUNCERN","ano":2024,"temas_relacionados":["lei_11892_2008"]},{"id":2358335,"enunciado":"Considerando a Lei n.° 12.527/2011 e o Decreto n.° 9.830/2019, julgue o item.\n\n\n\n\nO agente público somente poderá ser responsabilizado por suas decisões ou opiniões técnicas se agir com culpa ou cometer erro grosseiro no desempenho de suas funções.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2385514,"enunciado":"Considerando o Decreto n.º 9.830/2019, julgue o item.\n\n\n\n\nO agente público, quando entender conveniente para eliminar irregularidade, incerteza jurídica ou situações contenciosas na aplicação do direito público, poderá celebrar compromisso com os interessados, na forma da legislação pertinente.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2385515,"enunciado":"Considerando o Decreto n.º 9.830/2019, julgue o item.\n\n\n\n\nA culpabilidade será considerada na decisão que impuser sanção ao agente público.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2385516,"enunciado":"Considerando o Decreto n.º 9.830/2019, julgue o item.\n\n\n\n\nAo proferir a decisão pela convocação de consulta pública, a autoridade decisora será obrigada a considerar individualmente todas as manifestações apresentadas pelos interessados.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2415284,"enunciado":"De acordo com as Leis n.º 8.112/1990, n.º 8.429/1992 e n.º 12.846/2013, julgue o item a seguir. \n\n\n\n\nConforme a Lei n.º 12.846/2013, a responsabilidade da pessoa jurídica pela prática de atos contra a administração pública é mantida ainda que haja alteração contratual, transformação, incorporação, fusão ou cisão societária.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2417546,"enunciado":"João da Silva, professor efetivo pertencente ao quadro de servidores do IFSULDEMINAS, pretende se candidatar ao cargo de Reitor nas próximas eleições. De acordo com a Lei nº. 11.892/2008, para que seja possível a sua candidatura, deverão ser cumpridas, simultaneamente, as seguintes exigências:","opcoes":["Estar posicionado na Classe DIII da Carreira do Magistério do Ensino Básico, Técnico e Tecnológico; e titularidade de mestre.","Possuir o mínimo de 05 (cinco) anos de efetivo exercício docente em instituição federal de educação profissional e tecnológica; e titularidade de doutor.","Possuir o mínimo de 2 (dois) anos de exercício em cargo de gestão na instituição; e titularidade de mestre.","Ter concluído, com aproveitamento, curso de formação para o exercício de cargo de gestão; e titularidade de doutor."],"correta":1,"explicacao":"Gabarito: <strong>Possuir o mínimo de 05 (cinco) anos de efetivo exercício docente em instituição federal de educação profissional e tecnológica; e titularidade de doutor.</strong>.","banca":"IF SUL - MG","ano":2024,"temas_relacionados":["lei_11892_2008"]},{"id":2421872,"enunciado":"A lei nº 11.892 de 2008, que criou os Institutos Federais de Educação, Ciência e Tecnologia, nos artigos 6º e 7º, definiu finalidades, características e objetivos dessas instituições. A respeito dos objetivos, descritos no artigo 7º, afirma-se que","opcoes":["os Institutos Federais devem ministrar educação profissional técnica de nível médio, unicamente na forma de cursos integrados, para os concluintes do ensino fundamental e para jovens e adultos fora da idade escolar.","a essas instituições de ensino cabe a oferta somente de cursos de formação inicial e continuada de trabalhadores, visando à capacitação, ao aperfeiçoamento, à especialização e à atualização de profissionais, em todas as áreas da educação profissional e tecnológica.","os Institutos Federais têm por objetivo realizar pesquisas aplicadas e desenvolver atividades de extensão de acordo com os princípios e finalidades da educação profissional e tecnológica.","os Institutos Federais, quanto ao ensino superior, devem ministrar preferencialmente cursos superiores de tecnologia, visando à formação de profissionais para os diferentes setores da economia, e cursos de pós-graduação stricto sensu de mestrado e doutorado."],"correta":2,"explicacao":"Gabarito: <strong>os Institutos Federais têm por objetivo realizar pesquisas aplicadas e desenvolver atividades de extensão de acordo com os princípios e finalidades da educação profissional e tecnológica.</strong>.","banca":"IF Sul Rio-Grandense","ano":2021,"temas_relacionados":["lei_11892_2008"]},{"id":2421873,"enunciado":"Leia o texto a seguir, completando as lacunas. Os Institutos Federais são instituições de ___________, _________ e ___________, pluricurriculares e multicampi, especializados na oferta de educação profissional e tecnológica nas diferentes modalidades de ensino, com base na conjugação de - ______________ e _________ com as suas práticas pedagógicas, nos termos desta Lei. Do artigo 2º da Lei nº 11.892/08, foram extraídos 5 (cinco) termos. Qual sequência abaixo completa, correta e respectivamente, as lacunas?","opcoes":["Ensino técnico – básico – superior - reconhecimento de saberes - competências","Ensino básico – tecnológico – superior - conhecimentos técnicos - práticos","Educação superior – básica – profissional - conhecimentos técnicos - tecnológicos","Educação profissional – técnica – superior - conhecimentos técnicos - tecnológicos"],"correta":2,"explicacao":"Gabarito: <strong>Educação superior – básica – profissional - conhecimentos técnicos - tecnológicos</strong>.","banca":"IF Sul Rio-Grandense","ano":2021,"temas_relacionados":["lei_11892_2008"]},{"id":2432731,"enunciado":"De acordo com a Lei nº 11 .892/08, qual das instituições abaixo NÃO compõe a Rede Federal de Educação Profissional, Científica e Tecnológica?","opcoes":["Instituto Federal de Educação, Ciência e Tecnologia de Mato Grosso.","Universidade Tecnológica Federal do Paraná.","Centro Federal de Educação Tecnológica Celso Suckow da Fonseca.","Universidade Federal de Rondonópolis.","Colégio Pedro II."],"correta":3,"explicacao":"Gabarito: <strong>Universidade Federal de Rondonópolis.</strong>.","banca":"IF-MT","ano":2023,"temas_relacionados":["lei_11892_2008"]},{"id":2432732,"enunciado":"À luz da Lei nº 11.892/08, julgue as assertivas abaixo: I. Os Reitores serão nomeados pelo Presidente da República. II. Os Pró-Reitores são nomeados pelo Ministro da Educação, nos termos da legislação aplicável à nomeação de cargos de direção. III. Poderão candidatar-se ao cargo de Reitor os docentes e técnicos-administrativos pertencentes ao Quadro de Pessoal Ativo Permanente de qualquer dos campi que integram o Instituto Federal. IV. Os campi serão dirigidos por Diretores-Gerais, nomeados pelo Reitor para mandato de 4 (quatro) anos. Está(ão) CORRETA(S) apena(s) a(s) assertiva(s):","opcoes":["I e II.","II e III.","III e IV.","I e IV.","Todas estão corretas."],"correta":3,"explicacao":"Gabarito: <strong>I e IV.</strong>.","banca":"IF-MT","ano":2023,"temas_relacionados":["lei_11892_2008"]},{"id":2448209,"enunciado":"A Lei n° 11.892/2008 institui a Rede Federal de Educação Profissional, Científica e Tecnológica e cria os Institutos Federais de Educação, Ciência e Tecnologia. Nos termos do art. 11 da referida lei, os Institutos Federais terão como órgão executivo a reitoria, composta por","opcoes":["um reitor e quatro gerentes administrativos setoriais.","um reitor e dois pró-reitores.","um diretor-geral e três reitores.","um reitor e cinco pró-reitores."],"correta":3,"explicacao":"Gabarito: <strong>um reitor e cinco pró-reitores.</strong>.","banca":"IV - UFG","ano":2024,"temas_relacionados":["lei_11892_2008"]},{"id":2452125,"enunciado":"A Lei n° 11.892/2008 institui a Rede Federal de Educação Profissional, Científica e Tecnológica e cria os Institutos Federais de Educação, Ciência e Tecnologia. Nos termos do art. 11 da referida lei, os Institutos Federais terão como órgão executivo a reitoria, composta por um reitor e cinco pró-reitores. Quanto aos requisitos para candidatar-se ao cargo de reitor, o art. 12 dispõe que é necessário possuir o mínimo de","opcoes":["quatro anos de magistério superior em instituto federal de educação ou universidade federal.","cinco anos de magistério superior em instituição de educação profissional, pública ou privada.","quatro anos de efetivo exercício em instituição de educação superior, pública ou privada.","cinco anos de efetivo exercício em instituição federal de educação profissional e tecnológica."],"correta":3,"explicacao":"Gabarito: <strong>cinco anos de efetivo exercício em instituição federal de educação profissional e tecnológica.</strong>.","banca":"IV - UFG","ano":2024,"temas_relacionados":["lei_11892_2008"]},{"id":2467837,"enunciado":"Com base na Lei n.º 12.197/2010 e na Lei n.º 11.788/2008, julgue o item.\n\n\n\n\nAs atividades de extensão, de monitorias e de iniciação científica na educação superior, desenvolvidas pelo estudante, somente poderão ser equiparadas ao estágio em caso de previsão no projeto pedagógico do curso.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2469110,"enunciado":"Considerando a Lei n.º 10.973/2004, julgue o item.\n\n\n\n\nAo inventor independente que comprove depósito de pedido de patente é vedado solicitar a adoção de sua criação por ICT pública.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2469111,"enunciado":"Considerando a Lei n.º 10.973/2004, julgue o item.\n\n\n\n\nA União, os estados, o Distrito Federal, os municípios e suas respectivas agências de fomento poderão estimular e apoiar a constituição de alianças estratégicas e o desenvolvimento de projetos de cooperação envolvendo empresas, ICTs e entidades privadas sem fins lucrativos voltados para atividades de pesquisa e desenvolvimento, que objetivem a geração de produtos, de processos e de serviços inovadores e a transferência e a difusão de tecnologia.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2469112,"enunciado":"Considerando a Lei n.º 10.973/2004, julgue o item.\n\n\n\n\nA União e os demais entes federativos e suas entidades são autorizados a participar minoritariamente do capital social de empresas, com o propósito de desenvolver produtos ou processos inovadores que estejam de acordo com as diretrizes e as prioridades definidas nas políticas de ciência, tecnologia, inovação e de desenvolvimento industrial de cada esfera de governo.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2469113,"enunciado":"Considerando a Lei n.º 10.973/2004, julgue o item.\n\n\n\n\nÉ vedado à ICT pública celebrar contrato de transferência de tecnologia e de licenciamento para outorga de direito de uso ou de exploração de criação por ela desenvolvida isoladamente ou por meio de parceria.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2489892,"enunciado":"A Rede Federal de Educação Profissional, Científica e Tecnológica funciona no âmbito do sistema federal de ensino e está vinculada ao Ministério da Educação. Os Institutos Federais que a constituem têm por finalidade:","opcoes":["realizar pesquisas aplicadas, estimulando o desenvolvimento de soluções técnicas e tecnológicas, estendendo seus benefícios à comunidade","ministrar educação profissional técnica de nível médio, prioritariamente na forma de cursos integrados, para os concluintes do ensino fundamental","estimular e apoiar processos educativos que levem à geração de trabalho e renda e à emancipação do cidadão na perspectiva do desenvolvimento local e regional","realizar e estimular a pesquisa aplicada, a produção cultural, o empreendedorismo, o cooperativismo e o desenvolvimento científico e tecnológico"],"correta":3,"explicacao":"Gabarito: <strong>realizar e estimular a pesquisa aplicada, a produção cultural, o empreendedorismo, o cooperativismo e o desenvolvimento científico e tecnológico</strong>.","banca":"SELECON","ano":2024,"temas_relacionados":["lei_11892_2008"]},{"id":2501269,"enunciado":"Acerca dos sites de busca e pesquisa na Internet, das noções de vírus, worms e pragas virtuais e do Sistema Eletrônico de Informações (SEI), julgue o item subsequente.\n\n\n\n\nQuanto ao arquivamento de documentos digitalizados no SEI, define‑se tipo de localizador como sendo a informação do endereço do arquivo.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2501270,"enunciado":"Acerca dos sites de busca e pesquisa na Internet, das noções de vírus, worms e pragas virtuais e do Sistema Eletrônico de Informações (SEI), julgue o item subsequente.\n\n\n\n\nUm dos benefícios do SEI é que ele gerencia o acesso de usuários externos a documentos e processos dos quais são interessados.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2501906,"enunciado":"De acordo com o que normatiza a Lei nº 11.892/2008, assinale a alternativa correta em relação às finalidades e características dos Institutos Federais.","opcoes":["Ofertar educação profissional e tecnológica, em todos os seus níveis e modalidades, formando e qualificando cidadãos com vistas na atuação profissional nos diversos setores da economia, com ênfase no desenvolvimento socioeconômico local, regional e nacional.","Orientar sua oferta formativa em benefício da construção e desenvolvimento dos processos produtivos, sociais e culturais nacionais, identificados com base no mapeamento das potencialidades de desenvolvimento socioeconômico e cultural no âmbito de atuação do Instituto Federal.","Promover a produção, o desenvolvimento e a transferência de tecnologias de ponta e atuais, notadamente as voltadas ao desenvolvimento do meio ambiente empresarial e social.","Desenvolver a educação profissional e tecnológica como processo educativo e criador de soluções técnicas e digitais às demandas empresariais e peculiaridades nacionais.","Promover a integração e a horizontalização da educação básica à educação profissional e educação superior, fornecendo infraestrutura física e os recursos de gestão."],"correta":0,"explicacao":"Gabarito: <strong>Ofertar educação profissional e tecnológica, em todos os seus níveis e modalidades, formando e qualificando cidadãos com vistas na atuação profissional nos diversos setores da economia, com ênfase no desenvolvimento socioeconômico local, regional e nacional.</strong>.","banca":"IDECAN","ano":2024,"temas_relacionados":["lei_11892_2008"]},{"id":2501907,"enunciado":"De acordo com o que preconiza a Lei nº 11.892/2008, cada Instituto Federal é organizado em estrutura multicampi, com proposta orçamentária anual identificada para cada campus e a reitoria, exceto no que diz respeito a pessoal, encargos sociais e benefícios aos servidores. Sobre as Estruturas Organizacionais dos Institutos Federais, assinale a alternativa correta.","opcoes":["Os Institutos Federais terão como órgão executivo a reitoria, composta por 1 (um) Reitor e 4 (quatro) Pró-Reitores.","O Colégio de Dirigentes, de caráter normativo, será composto pelo Reitor, pelos Pró-Reitores e pelo Diretor-Geral de cada um dos campi que integram o Instituto Federal.","O Conselho Superior, de caráter normativo e deliberativo, será composto por representantes dos docentes, dos estudantes, dos servidores técnico-administrativos, dos egressos da instituição, da sociedade civil, do Ministério da Educação e do Colégio de Dirigentes do Instituto Federal, assegurando-se a representação majoritária dos docentes e estudantes.","Poderão ser nomeados Pró-Reitores os servidores ocupantes de cargo efetivo da Carreira docente ou de cargo efetivo com nível superior da Carreira dos técnico-administrativos do Plano de Carreira dos Cargos Técnico-Administrativos em Educação, desde que possuam o mínimo de 5 (cinco) anos de efetivo exercício em instituição federal de educação profissional e tecnológica.","Os Reitores serão nomeados pelo Presidente da República, para mandato de 4 (quatro) anos, permitidas reconduções, após processo de consulta à comunidade escolar do respectivo Instituto Federal, atribuindo-se o peso de 1/3 (um terço) para a manifestação do corpo docente, de 1/3 (um terço) para a manifestação dos servidores técnicoadministrativos e de 1/3 (um terço) para a manifestação do corpo discente."],"correta":3,"explicacao":"Gabarito: <strong>Poderão ser nomeados Pró-Reitores os servidores ocupantes de cargo efetivo da Carreira docente ou de cargo efetivo com nível superior da Carreira dos técnico-administrativos do Plano de Carreira dos Cargos Técnico-Administrativos em Educação, desde que possuam o mínimo de 5 (cinco) anos de efetivo exercício em instituição federal de educação profissional e tecnológica.</strong>.","banca":"IDECAN","ano":2024,"temas_relacionados":["lei_11892_2008"]},{"id":2520036,"enunciado":"Quanto aos conceitos de redes de computadores, ao programa de correio eletrônico Microsoft Outlook 2019 e ao Sistema Eletrônico de Informações (SEI), julgue o item abaixo.\n\n\n\n\nO SEI permite que um texto recorrente na unidade possa ser utilizado como um conteúdo padrão para documentos. Assim, para a inclusão de um texto padrão, o usuário deverá clicar no menu Textos Padrão, selecionar a opção Incluir, digitar o texto e clicar em Criar.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2520037,"enunciado":"Quanto aos conceitos de redes de computadores, ao programa de correio eletrônico Microsoft Outlook 2019 e ao Sistema Eletrônico de Informações (SEI), julgue o item abaixo.\n\n\n\n\nNo SEI, a inserção de controle de prazo em processo é um procedimento que somente poderá ser executado em um processo por vez, já que o SEI não possui um recurso para inserir esse controle em lote (vários processos de uma vez).","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2528822,"enunciado":"Em relação ao Decreto nº 9.830/2019, julgue o item abaixo. \n\n\n\n\nAs súmulas, os enunciados e as respostas a consultas terão caráter vinculante em relação ao órgão ou à entidade da Administração Pública a que se destinarem, até ulterior revisão.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2528823,"enunciado":"Em relação ao Decreto nº 9.830/2019, julgue o item abaixo. \n\n\n\n\nO nexo de causalidade entre a conduta e o resultado danoso deverá ser observado na decisão que impuser sanção ao agente público.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2560695,"enunciado":"Com base na Lei nº 11.892/2008, que institui a Rede Federal de Educação Profissional, Científica e Tecnológica e cria os Institutos Federais, estes têm por finalidades e características: I. Desenvolver jovens aptos para a pesquisa científica voltada ao serviço militar. II. Estimular o empreendedorismo internacional com foco no Mercosul e América Latina. III. Constituir-se em centro de excelência na oferta do ensino de ciências, em geral, e de ciências aplicadas, em particular, estimulando o desenvolvimento de espírito crítico, voltado à investigação empírica. IV. Desenvolver programas de extensão e de divulgação científica e tecnológica. Quais estão corretas?","opcoes":["Apenas I e II.","Apenas II e III.","Apenas II e IV.","Apenas III e IV.","Apenas I, III e IV."],"correta":3,"explicacao":"Gabarito: <strong>Apenas III e IV.</strong>.","banca":"FUNDATEC","ano":2024,"temas_relacionados":["lei_11892_2008"]},{"id":2562096,"enunciado":"Segundo a Lei nº 11.892/2008, dentro da estrutura organizacional dos Institutos Federais, o órgão consultivo composto pelo Reitor, pelos Pró-Reitores e pelo Diretor-Geral de cada um dos campi que integram o Instituto Federal é o","opcoes":["Conselho Superior.","Conselho da Presidência.","Colégio de Dirigentes.","Colégio de Reitores.","Colégio de Presidentes."],"correta":2,"explicacao":"Gabarito: <strong>Colégio de Dirigentes.</strong>.","banca":"IV - UFG","ano":2024,"temas_relacionados":["lei_11892_2008"]},{"id":2574529,"enunciado":"Julgue o item que se segue.\n\nAo se referir ao quilombo e às pessoas que o compõem, podemos dizer que a presunção de ancestralidade negra estabelecida pela Instrução Normativa do INCRA auxilia nos processos de reconhecimento e titulação de terras quilombolas.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"IGEDUC","ano":2024,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2574530,"enunciado":"Julgue o item que se segue.\n\nO processo de certificação e titulação das terras quilombolas no Brasil é marcado por uma série de desafios, incluindo a burocracia estatal, a sobreposição de títulos de propriedade e a resistência de setores políticos contrários aos direitos territoriais das comunidades quilombolas. Esses entraves comprometem a segurança jurídica das terras e dificultam a implementação de políticas voltadas para o desenvolvimento sustentável dessas comunidades.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"IGEDUC","ano":2024,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2583928,"enunciado":"Segundo a Lei Federal 11.892/2008 (Lei de Criação dos Institutos Federais), desenvolver programas de extensão e de divulgação científica e tecnológica constitui:","opcoes":["Um dos valores dos Institutos Federais.","Uma das finalidades e características dos Institutos Federais.","Uma das visões dos Institutos Federais.","Um dos objetivos dos Institutos Federais.","Nenhuma das respostas anteriores."],"correta":1,"explicacao":"Gabarito: <strong>Uma das finalidades e características dos Institutos Federais.</strong>.","banca":"IF-MT","ano":2024,"temas_relacionados":["lei_11892_2008"]},{"id":2583977,"enunciado":"Nos termos da Lei 11.892/2008, julgue as assertivas abaixo: I- Os Institutos Federais terão como órgão executivo a Reitoria, composta por 1 (um) reitor, 1 (um) vice-reitor e 6 (seis) pró-reitores. Il- Os Institutos Federais terão como órgão executivo a Reitoria, composta por 1 (um) reitor e 5 (cinco) pró-reitores. IlI - A Reitoria, como órgão de administração central, poderá ser instalada em espaço físico distinto de qualquer dos campi que integram o Instituto Federal, desde que previsto em seu estatuto e aprovado pelo Ministério da Educação. IV- A Reitoria, como órgão de administração setorial, deverá ser instalada em espaço físico distinto de qualquer dos campi que integram o Instituto Federal. Está correto o que se afirma em:","opcoes":["l e ll, somente.","Il e lIl, somente.","Il e IV, somente.","l e IV, somente.","l e lll, somente."],"correta":1,"explicacao":"Gabarito: <strong>Il e lIl, somente.</strong>.","banca":"IF-MT","ano":2024,"temas_relacionados":["lei_11892_2008"]},{"id":2639262,"enunciado":"À luz da Lei nº 11.892/08, que institui a Rede Federal de Educação Profissional, Científica e Tecnológica e cria os Institutos Federais de Educação, Ciência e Tecnologia, julgue as assertivas abaixo: l. O instituto Federal de Mato Grosso foi criado mediante a integração dos Centros Federais de Educação Tecnológica de Mato Grosso e de Cáceres, e da Escola Agro técnica Federal de São Vicente. II. A unidade de ensino que compõe a estrutura organizacional de instituição transformada ou integrada em Instituto Federal passa de forma automática, independentemente de qualquer formalidade, à condição de campus da nova instituição. III. A Sede da Reitoria do Instituto Federal de Mato Grosso está localizada na cidade de Cuiabá. IV. O Instituto Federal de Mato Grosso, a Universidade Federal de Mato Grosso e a Universidade Federal de Rondonópolis fazem parte da Rede Federal de Educação Profissional, Científica e Tecnológica. Está(ão) CORRETA(S) apena(s) a(s) assertiva(s):","opcoes":["l e III.","II e III.","III e IV.","I e IV.","Todas estão corretas."],"correta":1,"explicacao":"Gabarito: <strong>II e III.</strong>.","banca":"IF-MT","ano":2023,"temas_relacionados":["lei_11892_2008"]},{"id":2658248,"enunciado":"Segundo a lei de criação dos Institutos Federais {Lei Federal nº 11.892/2008), seus bens e direitos serão utilizados ou aplicados, exclusivamente, para a consecução de seus objetivos, não podendo ser alienados a não ser nos casos e condições permitidos em lei. Com efeito, de acordo com o que consta expressamente na referida lei, o patrimônio de cada um dos novos Institutos Federais será constituído. EXCETO:","opcoes":["Por incorporações que resultem de serviços por ele realizado.","Pelas doações ou legados que receber.","Pelos bens e direitos que vier a adquirir.","Pelos materiais de consumo de terceiros.","Pelos bens e direitos que compõem o patrimônio de cada uma das instituições que o integram, os quais ficam automaticamente transferidos, sem reservas ou condições, ao novo ente."],"correta":3,"explicacao":"Gabarito: <strong>Pelos materiais de consumo de terceiros.</strong>.","banca":"IF-MT","ano":2023,"temas_relacionados":["lei_11892_2008"]},{"id":2665198,"enunciado":"Quanto ao programa de navegação Mozilla Firefox, em sua versão mais recente, aos conceitos de organização e de gerenciamento de arquivos e pastas e ao Sistema Eletrônico de Informações (SEI), julgue o item seguinte. \n\nNa barra de ferramentas do SEI, a funcionalidade  possibilita busca rápida por meio do número de processo ou de documento.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2665199,"enunciado":"Quanto ao programa de navegação Mozilla Firefox, em sua versão mais recente, aos conceitos de organização e de gerenciamento de arquivos e pastas e ao Sistema Eletrônico de Informações (SEI), julgue o item seguinte. \n\nNo SEI, o NUP é um código numérico oficial para cadastro, utilizado no controle dos documentos, avulsos ou processos, produzidos ou recebidos pelos órgãos e pelas entidades da Administração Pública Federal.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2665275,"enunciado":"À luz do Decreto nº 85.877/1981, julgue o item a seguir. \n\nAs disposições desse Decreto abrangem o exercício da profissão de químico apenas nas entidades particulares.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2665276,"enunciado":"À luz do Decreto nº 85.877/1981, julgue o item a seguir. \n\nO exercício da profissão de químico compreende ensaios e pesquisas em geral, pesquisa e desenvolvimento de métodos e produtos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2665277,"enunciado":"À luz do Decreto nº 85.877/1981, julgue o item a seguir. \n\nAs dúvidas provenientes do exercício de atividades afins com outras profissões regulamentadas serão resolvidas pelo CFQ.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2665278,"enunciado":"À luz do Decreto nº 85.877/1981, julgue o item a seguir. \n\nCompete aos profissionais de química, privativamente, o controle de qualidade de águas potáveis, de águas de piscina, de praias e balneários.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2665279,"enunciado":"À luz do Decreto nº 85.877/1981, julgue o item a seguir. \n\nAs atividades de estudo, planejamento, projeto e especificações de equipamentos e instalações industriais, na área de química, são privativas dos profissionais com currículo da engenharia química.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":2693288,"enunciado":"A lei nº 11.892/2008 que institui a Rede Federal de Educação Profissional, Científica e Tecnológica e cria os Institutos Federais de Educação, Ciência e Tecnologia, apresenta a finalidade e as características dos Institutos Federais. Assinale a alternativa que não apresenta finalidade ou característica dos Institutos Federais:","opcoes":["realizar e estimular a pesquisa aplicada, a produção cultural, o empreendedorismo,o cooperativismo e o desenvolvimento científico e tecnológico;","ministrar cursos de formação inicial e continuada de trabalhadores, objetivando a capacitação, o aperfeiçoamento, a especialização e a atualização de profissionais, em todos os níveis de escolaridade, nas áreas da educação profissional e tecnológica;","desenvolver a educação profissional e tecnológica como processo educativo e investigativo de geração e adaptação de soluções técnicas e tecnológicas às demandas sociais e peculiaridades regionais;","promover a integração e a verticalização da educação básica à educação profissional e educação superior, otimizando a infra­estrutura física, os quadros de pessoal e os recursos de gestão;","constituir-se em centro de excelência na oferta do ensino de ciências, em geral, e de ciências aplicadas, em particular, estimulando o desenvolvimento do espírito crítico, voltado à investigação empírica;"],"correta":1,"explicacao":"Gabarito: <strong>ministrar cursos de formação inicial e continuada de trabalhadores, objetivando a capacitação, o aperfeiçoamento, a especialização e a atualização de profissionais, em todos os níveis de escolaridade, nas áreas da educação profissional e tecnológica;</strong>.","banca":"IF-PI","ano":2019,"temas_relacionados":["lei_11892_2008"]},{"id":2722503,"enunciado":"No Artigo segundo da Lei 11.892, está expresso: “§ 2º No âmbito de sua atuação, os Institutos Federais exercerão o papel de instituições acreditadoras e certificadoras de competências profissionais.” Acreditação e certificação, referem-se respectivamente a:","opcoes":["Credenciar outras escolas e certificar seus próprios alunos","Registrar os diplomas de outras instituições e emitir diplomas e certificado de seus próprios cursos","Reconhecer a formação de outras instituições e registrar seus diplomas e certificados","Apostilar diplomas de outras instituições e registrar seus próprios diplomas","Emitir e registrar seus diplomas e certificados"],"correta":2,"explicacao":"Gabarito: <strong>Reconhecer a formação de outras instituições e registrar seus diplomas e certificados</strong>.","banca":"IF-SC","ano":2017,"temas_relacionados":["lei_11892_2008"]},{"id":2726278,"enunciado":"Na Lei N° 11.892 de 2008, no §2° do Artigo 2o está expresso: “§ 2- No âmbito de sua atuação, os Institutos Federais exercerão o papel de instituições acreditadoras e certificadoras de competências profissionais.” Acreditação e certificação, referem-se respectivamente a:","opcoes":["Credenciar outras escolas e certificar seus próprios alunos.","Registrar os diplomas de outras instituições e emitir diplomas e certificados de seus próprios cursos.","Reconhecer a formação de outras instituições e registrar seus diplomas e certificados.","Apostilar diplomas de outras instituições e registrar seus próprios diplomas.","Emitir e registrar seus diplomas e certificados."],"correta":2,"explicacao":"Gabarito: <strong>Reconhecer a formação de outras instituições e registrar seus diplomas e certificados.</strong>.","banca":"IF-SC","ano":2017,"temas_relacionados":["lei_11892_2008"]},{"id":2743239,"enunciado":"De acordo com o Capítulo I da Lei N° 11.892/2008, que dispõe sobre a Rede Federal de Educação Profissional, Científica e Tecnológica, é correto afirmar:","opcoes":["No âmbito de sua atuação, os Institutos Federais exercerão o papel de instituições acreditadoras e certificadoras de competências profissionais.","Os diplomas dos cursos oferecidos pelos Institutos Federais deverão ser encaminhados ao órgão técnico competente do Ministério da Educação para serem devidamente registrados.","Os reitores dos Institutos Federais terão autonomia para criar cursos, nos limites de sua área de atuação, mediante autorização do seu Colégio de Dirigentes.","Para efeito da avaliação e regulamentação das instituições e dos cursos de educação de nível médio, os Institutos Federais se equiparam aos Centros Universitários."],"correta":0,"explicacao":"Gabarito: <strong>No âmbito de sua atuação, os Institutos Federais exercerão o papel de instituições acreditadoras e certificadoras de competências profissionais.</strong>.","banca":"FUNDEP (Gestão de Concursos)","ano":2016,"temas_relacionados":["lei_11892_2008"]},{"id":2743240,"enunciado":"Considerando dispositivos da Lei N° 11.892/2008, assinale a alternativa que apresenta corretamente uma das finalidades e características dos Institutos Federais.","opcoes":["Estimular a pesquisa social e a cultura popular, bem como ofertar cursos nas áreas de cooperativismo e de empreendedorismo.","Estimular o desenvolvimento de soluções técnicas e tecnológicas em parceria com os arranjos produtivos locais, estendendo seus benefícios à comunidade.","Promover a integração e a verticalização da educação básica à educação superior, otimizando as plataformas virtuais e os recursos pedagógicos.","Promover a produção, o desenvolvimento e a transferência de tecnologias sociais, notadamente as voltadas à preservação do meio ambiente."],"correta":3,"explicacao":"Gabarito: <strong>Promover a produção, o desenvolvimento e a transferência de tecnologias sociais, notadamente as voltadas à preservação do meio ambiente.</strong>.","banca":"FUNDEP (Gestão de Concursos)","ano":2016,"temas_relacionados":["lei_11892_2008"]},{"id":2743241,"enunciado":"Analise estas afirmativas sobre o conteúdo dos capítulos que integram os Títulos III e IV do Estatuto do Instituto Federal de Educação, Ciência e Tecnologia do Norte de Minas Gerais, assinalando com V as verdadeiras e com F as falsas. ( ) As ações de pesquisa, pós-graduação e inovação constituem um processo educativo, cultural e científico que articula o ensino e a pesquisa de forma indissociável, para viabilizar uma relação transformadora entre o Instituto Federal de Educação, Ciência e Tecnologia do Norte de Minas Gerais e a sociedade. ( ) As ofertas educacionais do Instituto Federal de Educação, Ciência e Tecnologia do Norte de Minas Gerais estão organizadas através da formação inicial e continuada de trabalhadores, da educação profissional técnica de nível médio e da educação superior de graduação. ( ) O regime disciplinar do corpo docente e técnico- administrativo do Instituto Federal de Educação, Ciência e Tecnologia do Norte de Minas Gerais é estabelecido em regulamento próprio aprovado pelo Conselho Superior. ( ) Os alunos em regime de matrícula especial farão jus a diploma ou certificado na forma e nas condições previstas na organização didática. Assinale a sequência CORRETA.","opcoes":["V F V F","V F V V","F V F F","F V F V"],"correta":2,"explicacao":"Gabarito: <strong>F V F F</strong>.","banca":"FUNDEP (Gestão de Concursos)","ano":2016,"temas_relacionados":["lei_11892_2008"]},{"id":2781018,"enunciado":"Considere as afirmativas I, II e III a respeito dos objetivos estipulados pela Lei nº 11.892/08 aos Institutos Federais e assinale a alternativa que contém a(s) afirmativa(s) CORRETA(S). I) Realizar pesquisas aplicadas, estimulando o desenvolvimento de soluções técnicas e tecnológicas, estendendo seus benefícios à comunidade. II) Ministrar em nível de educação superior apenas os cursos de bacharelado e engenharia que não são ofertados por universidades, visando à formação de profissionais para os diferentes setores da economia e áreas do conhecimento. III) Ministrar educação profissional técnica de nível médio, prioritariamente na forma de cursos integrados, para os concluintes do ensino fundamental e para o público da educação de jovens e adultos.","opcoes":["Apenas I","Apenas I e II","Apenas I e III","Apenas II e III","I, II e III"],"correta":2,"explicacao":"Gabarito: <strong>Apenas I e III</strong>.","banca":"IFB","ano":2016,"temas_relacionados":["lei_11892_2008"]},{"id":2909689,"enunciado":"Leia os trechos do retângulo abaixo, sobre dispositivos da Lei nº 11.892/2008, que instituiu a Rede Federal de Educação Profissional e Tecnológica e criou os Institutos Federais de Educação, Ciência e Tecnologia: Considerando os dispositivos legais acima referidos, analise as afirmativas abaixo sobre a natureza jurídica e as formas de constituição do patrimônio do Instituto Federal de Educação, Ciência e Tecnologia do Piauí (IFPI): I O IFPI é uma autarquia federal, vinculada ao Ministério da Educação (MEC). II O patrimônio do IFPI é constituído, também, pelos bens e direitos que compunham o patrimônio do antigo CEFET-PI, os quais ficaram automaticamente transferidos com reservas ou condições ao IFPI. III O patrimônio do IFPI é constituído, também, pelos bens e direitos que o IFPI vier a adquirir. IV O IFPI é uma empresa pública federal, vinculada ao Ministério da Educação, Ciência e Tecnologia (MEC). V O patrimônio do IFPI é constituído apenas pelos bens e direitos que compunham o patrimônio do antigo CEFET-PI e pelas doações ou legados que receber. VI O IFPI tem natureza jurídica de fundação pública federal, vinculada ao Ministério da Educação (MEC). VII O patrimônio do IFPI é constituído, também, por incorporações que resultem de serviços por ele realizado. VIII O patrimônio do IFPI é constituído, ainda, pelos bens e direitos obtidos a partir dos recursos adquiridos após a alienação de bens móveis e imóveis inservíveis, sendo vedado o recebimento de legados. Está correto o que se afirma em:","opcoes":["I, II e VI, apenas.","I, III e VII, apenas.","II, III, IV e VII, apenas.","II, IV, V e VIII, apenas.","III, V, VII e VIII, apenas."],"correta":1,"explicacao":"Gabarito: <strong>I, III e VII, apenas.</strong>.","banca":"IF-PI","ano":2012,"temas_relacionados":["lei_11892_2008"]},{"id":3011376,"enunciado":"De acordo com a Lei nº 11.892/2008, que institui a Rede Federal de Educação Profissional, Científica e Tecnológica, cria os Institutos Federais de Educação, Ciência e Tecnologia, e dá outras providências, analise as assertivas abaixo e assinale a alternativa correta. I. Os Institutos Federais devem priorizar a formação de profissionais para atuar em grandes centros urbanos, visando à competitividade no mercado global. II. Os Institutos Federais devem concentrar seus esforços em áreas do conhecimento específicas, como engenharia e tecnologia da informação. III. Uma das finalidades dos Institutos Federais é desenvolver programas de extensão e de divulgação científica e tecnológica.","opcoes":["Todas as assertivas estão corretas.","Todas as assertivas estão incorretas.","Apenas a assertiva II está correta.","Apenas a assertiva III está correta.","Apenas as assertivas I e II estão corretas."],"correta":3,"explicacao":"Gabarito: <strong>Apenas a assertiva III está correta.</strong>.","banca":"FUNDATEC","ano":2024,"temas_relacionados":["lei_11892_2008"]},{"id":3011377,"enunciado":"De acordo com o Plano de Desenvolvimento Institucional do Instituto Federal de Educação, Ciência e Tecnologia de Santa Catarina 2020-2024 (PDI-IFSC), o órgão máximo do IFSC, de caráter consultivo e deliberativo, é composto por representantes da comunidade interna (docentes, discentes, técnico-administrativos e diretores-gerais dos campi), eleitos por seus pares, e de segmentos ligados à educação profissional e tecnológica (sociedade civil, Secretaria de Estado da Educação, Fundação de Pesquisa do Estado de Santa Catarina e Ministério da Educação), tendo o Reitor como seu presidente. O trecho refere-se ao:","opcoes":["Colégio de Dirigentes (CODIR).","Conselho Superior (CONSUP).","Gabinete do Reitor.","Colegiado de Desenvolvimento de Pessoas.","Comitê Permanente de Acompanhamento do Desenvolvimento Institucional (COPADIN)."],"correta":1,"explicacao":"Gabarito: <strong>Conselho Superior (CONSUP).</strong>.","banca":"FUNDATEC","ano":2024,"temas_relacionados":["lei_11892_2008"]},{"id":3011380,"enunciado":"De acordo com a Lei nº 11.892/2008, analise as assertivas abaixo e assinale a alternativa correta. I. Um dos objetivos dos Institutos Federais é fomentar a Educação Infantil. II. Uma das finalidades dos Institutos Federais é realizar e estimular a pesquisa aplicada, a produção cultural, o empreendedorismo, o cooperativismo e o desenvolvimento científico e tecnológico. III. Os Institutos Federais são equiparados às universidades federais para efeito da incidência das disposições que regem a regulação, avaliação e supervisão das instituições e dos cursos de Educação Superior.","opcoes":["Todas as assertivas estão corretas.","Todas as assertivas estão incorretas.","Apenas a assertiva I está correta.","Apenas as assertivas I e III estão corretas.","Apenas as assertivas II e III estão corretas."],"correta":4,"explicacao":"Gabarito: <strong>Apenas as assertivas II e III estão corretas.</strong>.","banca":"FUNDATEC","ano":2024,"temas_relacionados":["lei_11892_2008"]},{"id":3028252,"enunciado":"O Decreto nº. 9.830/2019 estabelece instrumentos que os órgãos de controle interno da administração pública e os agentes púbicos poderão firmar com a finalidade de corrigir falhas apontadas em ações de controle, aprimorar procedimentos, assegurar a continuidade da execução do objeto, sempre que possível, e garantir o atendimento do interesse geral. Tal instrumento denomina-se:","opcoes":["termo de ajustamento de conduta.","termo de ajustamento de gestão.","termo de responsabilidade.","termo de compromisso.","termo de consentimento."],"correta":1,"explicacao":"Gabarito: <strong>termo de ajustamento de gestão.</strong>.","banca":"IBADE","ano":2024,"temas_relacionados":["lei_11892_2008"]},{"id":3028253,"enunciado":"De acordo com o Decreto nº 9.830/2019, na declaração de invalidade de atos, contratos, ajustes, processos ou normas administrativos, o decisor poderá, consideradas as consequências jurídicas e administrativas da decisão para a administração pública e para o administrado, modular os efeitos da decisão. Sobre o tema, assinale a alternativa correta.","opcoes":["Não poderá restringir os efeitos da declaração nem decidir que sua eficácia se iniciará em momento posteriormente definido.","Poderá restringir os efeitos da declaração, entretanto, não poderá decidir que sua eficácia se iniciará em momento posteriormente definido.","Não poderá restringir os efeitos da declaração, entretanto, poderá decidir que sua eficácia se iniciará em momento posteriormente definido.","Poderá restringir os efeitos da declaração ou decidir que sua eficácia se iniciará em momento posteriormente definido.","Poderá ampliar os efeitos da declaração e decidir que sua eficácia se iniciará em momento posteriormente definido."],"correta":3,"explicacao":"Gabarito: <strong>Poderá restringir os efeitos da declaração ou decidir que sua eficácia se iniciará em momento posteriormente definido.</strong>.","banca":"IBADE","ano":2024,"temas_relacionados":["lei_11892_2008"]},{"id":3028299,"enunciado":"Considerando a Lei nº 12.514/2011, julgue as sentenças abaixo como VERDADEIRAS ou FALSAS. 1.( ) O inadimplemento das anuidades por mais de 6 (seis) meses ensejará a suspensão permanente do registro profissional. 2.( ) Ao médico-residente é assegurado bolsa no valor de R$ 2.384,82 (dois mil, trezentos e oitenta e quatro reais e oitenta e dois centavos), em regime especial de treinamento em serviço de 60 (sessenta) horas semanais. 3.( ) O fato gerador das anuidades é a existência de inscrição no conselho, ainda que por tempo limitado, ao longo do exercício. A sequência correta é:","opcoes":["1.V, 2.V, 3. F.","1.F, 2.V, 3. V.","1.V, 2.V, 3. V.","1.V, 2.F, 3. V.","1.V, 2.F, 3. F."],"correta":1,"explicacao":"Gabarito: <strong>1.F, 2.V, 3. V.</strong>.","banca":"IBADE","ano":2024,"temas_relacionados":["lei_11892_2008"]},{"id":3028300,"enunciado":"De acordo com a Lei nº 6.830/1980, o instrumento legal utilizado para a cobrança judicial da Dívida Ativa da Fazenda Pública é o(a):","opcoes":["ação ordinária.","mandado de segurança.","execução fiscal.","recurso extraordinário.","ação de cobrança."],"correta":2,"explicacao":"Gabarito: <strong>execução fiscal.</strong>.","banca":"IBADE","ano":2024,"temas_relacionados":["lei_11892_2008"]},{"id":3028303,"enunciado":"Considere um processo contra um contribuinte para a cobrança de Dívida Ativa. Durante o curso do processo, o contribuinte veio a falecer antes de liquidar o débito. Considerando as disposições da Lei nº 6.830/1980, contra quem deve prosseguir a execução fiscal para garantir o pagamento da dívida, levando em conta a continuidade do procedimento legal?","opcoes":["Herdeiros individualmente.","Cônjuge sobrevivente.","Espólio.","Inventariante.","Tribunal de Justiça."],"correta":2,"explicacao":"Gabarito: <strong>Espólio.</strong>.","banca":"IBADE","ano":2024,"temas_relacionados":["lei_11892_2008"]},{"id":3028306,"enunciado":"De acordo com a Lei nº 6.830/1980, caso o devedor não pague a dívida nem garanta a execução dentro do prazo legal, qual medida pode ser tomada pelo juiz para assegurar o pagamento da dívida?","opcoes":["Extinção do processo.","Conversão da dívida em pena criminal.","Decretação da prisão do devedor.","Penhora de bens do devedor.","Arquivamento do processo."],"correta":3,"explicacao":"Gabarito: <strong>Penhora de bens do devedor.</strong>.","banca":"IBADE","ano":2024,"temas_relacionados":["lei_11892_2008"]},{"id":3045429,"enunciado":"De acordo com a Lei n. 11.892/2008 (Lei que Institui a Rede Federal de Educação Profissional, Científica e Tecnológica, cria os Institutos Federais de Educação, Ciência e Tecnologia, e dá outras providências.), a administração dos Institutos Federais possui os seguintes órgãos superiores:","opcoes":["O Colégio de Dirigentes e o Conselho Superior.","O Grupo de Dirigentes e o Conselho Fiscal.","O Conselho Superior e o Conselho Fiscal.","O Grupo de Pró-Reitores e o Conselho Administrativo."],"correta":0,"explicacao":"Gabarito: <strong>O Colégio de Dirigentes e o Conselho Superior.</strong>.","banca":"IF-SP","ano":2024,"temas_relacionados":["lei_11892_2008"]},{"id":3059954,"enunciado":"Acerca dos conceitos de redes de computadores, do programa de correio eletrônico Microsoft Outlook 2016 e do Sistema Eletrônico de Informações (SEI), julgue o item seguinte.\n\n\n\n\nDevido ao fato de ser um sistema oficial, o SEI não permite que um texto recorrente na unidade possa ser utilizado como um conteúdo padrão para documentos. Esse é um recurso muito importante, cujo objetivo é evitar o plágio.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":3059955,"enunciado":"Acerca dos conceitos de redes de computadores, do programa de correio eletrônico Microsoft Outlook 2016 e do Sistema Eletrônico de Informações (SEI), julgue o item seguinte.\n\n\n\n\nNo SEI, cada vez que uma edição de documento for salva, será gerada uma nova versão dele no sistema.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":3069627,"enunciado":"A Lei nº 11.892, de 29 dezembro de 2008, dispõe sobre a Rede Federal de Educação Profissional, Científica e Tecnológica e a criação dos Institutos Federais de Educação, Ciência e Tecnologia. Sobre a lei citada, assinale a alternativa INCORRETA:","opcoes":["Para efeito da incidência das disposições que regem a regulação, avaliação e supervisão das instituições e dos cursos de educação superior, os Institutos Federais são equiparados às universidades federais.","O Colégio de Dirigentes, de caráter consultivo, será composto pelo Reitor, pelos Pró-Reitores e pelo Diretor-Geral de cada um dos campi que integram o Instituto Federal.","Os Institutos Federais são instituições de educação superior, básica e profissional, pluricurriculares e multicampi, especializados na oferta de educação profissional e tecnológica nas diferentes modalidades de ensino, com base na conjugação de conhecimentos técnicos e tecnológicos com as suas práticas pedagógicas.","Cada Instituto Federal é organizado em estrutura multicampi, com proposta orçamentária anual identificada para cada campus e a reitoria, incluindo no que diz respeito a pessoal, encargos sociais e benefícios aos servidores.","Os Institutos Federais terão autonomia para criar e extinguir cursos, nos limites de sua área de atuação territorial, bem como para registrar diplomas dos cursos por eles oferecidos, mediante autorização do seu Conselho Superior, aplicando-se, no caso da oferta de cursos a distância, a legislação específica."],"correta":3,"explicacao":"Gabarito: <strong>Cada Instituto Federal é organizado em estrutura multicampi, com proposta orçamentária anual identificada para cada campus e a reitoria, incluindo no que diz respeito a pessoal, encargos sociais e benefícios aos servidores.</strong>.","banca":"IF-TO","ano":2024,"temas_relacionados":["lei_11892_2008"]},{"id":3069644,"enunciado":"A Lei nº 11.892/2008 estabelece objetivos para os Institutos Federais de Educação, Ciência e Tecnologia. A partir dessa legislação, qual é o papel dos Institutos Federais na promoção da verticalização do ensino, e como essa verticalização contribui para a integração das diferentes modalidades de ensino oferecidas pelas instituições? Assinale a alternativa CORRETA.","opcoes":["A verticalização do ensino nos Institutos Federais visa a restringir a oferta de cursos técnicos e tecnológicos, focando exclusivamente na educação superior","A verticalização do ensino nos Institutos Federais é entendida como a oferta simultânea de diferentes níveis e modalidades de ensino, desde o ensino técnico até a pós-graduação, permitindo a formação continuada do estudante dentro da mesma instituição.","A verticalização do ensino propicia a integração dos alunos apenas entre cursos de nível técnico, sem impacto significativo na formação superior.","A verticalização do ensino se refere à oferta de cursos até a pós-graduação lato sensu.","Estimular e apoiar processos educativos que levem à geração de trabalho e renda sob uma perspectiva pragmática visando uma liberdade utilitarista."],"correta":1,"explicacao":"Gabarito: <strong>A verticalização do ensino nos Institutos Federais é entendida como a oferta simultânea de diferentes níveis e modalidades de ensino, desde o ensino técnico até a pós-graduação, permitindo a formação continuada do estudante dentro da mesma instituição.</strong>.","banca":"IF-TO","ano":2024,"temas_relacionados":["lei_11892_2008"]},{"id":3073063,"enunciado":"Nos termos da Lei nº 11.892/08, que instituiu a Rede Federal de Educação Profissional, Científica e Tecnológica, assinale a alternativa INCORRETA.","opcoes":["Os Institutos Federais de Educação, Ciência e Tecnologia possuem natureza jurídica de autarquia, detentoras de autonomia administrativa, patrimonial, financeira, didático pedagógica e disciplinar.","Os Institutos Federais são instituições de educação superior, básica e profissional, pluricurriculares e multicampi, especializados na oferta de educação profissional e tecnológica nas diferentes modalidades de ensino, com base na conjugação de conhecimentos técnicos e tecnológicos com as suas práticas pedagógicas, nos termos desta Lei.","Para efeito da incidência das disposições que regem a regulação, avaliação e supervisão das instituições e dos cursos de educação superior, os Institutos Federais são equiparados às universidades federais.","No âmbito de sua atuação, os Institutos Federais exercerão o papel de instituições acreditadoras e certificadoras de competências profissionais.","Os Institutos Federais terão autonomia para criar e extinguir cursos, nos limites de sua área de atuação territorial, exceto para registrar diplomas dos cursos por eles oferecidos."],"correta":4,"explicacao":"Gabarito: <strong>Os Institutos Federais terão autonomia para criar e extinguir cursos, nos limites de sua área de atuação territorial, exceto para registrar diplomas dos cursos por eles oferecidos.</strong>.","banca":"FACTO","ano":2022,"temas_relacionados":["lei_11892_2008"]},{"id":3073347,"enunciado":"Nos termos da Lei nº 11.892/08, no desenvolvimento da sua ação acadêmica, o Instituto Federal, em cada exercício, deverá garantir:","opcoes":["o mínimo de 50% (cinquenta por cento) de suas vagas para ministrar educação profissional técnica de nível médio, prioritariamente na forma de cursos integrados, para os concluintes do ensino fundamental e para o público da educação de jovens e adultos; e o mínimo de 20% (vinte por cento) de suas vagas para ministrar em nível de educação superior cursos de licenciatura, bem como programas especiais de formação pedagógica, com vistas na formação de professores para a educação básica, sobretudo nas áreas de ciências e matemática, e para a educação profissional.","o mínimo de 50% (cinquenta por cento) de suas vagas para ministrar educação profissional técnica de nível médio, prioritariamente na forma de cursos integrados, para os concluintes do ensino fundamental e para o público da educação de jovens e adultos; e o mínimo de 20% (vinte por cento) de suas vagas para ministrar em nível de educação superior cursos superiores de tecnologia visando à formação de profissionais para os diferentes setores da economia.","o mínimo de 50% (cinquenta por cento) de suas vagas para ministrar cursos de formação inicial e continuada de trabalhadores, objetivando a capacitação, o aperfeiçoamento, a especialização e a atualização de profissionais, em todos os níveis de escolaridade, nas áreas da educação profissional e tecnológica; e o mínimo de 20% (vinte por cento) de suas vagas para ministrar em nível de educação superior cursos de bacharelado e engenharia, visando à formação de profissionais para os diferentes setores da economia e áreas do conhecimento.","o mínimo de 50% (cinquenta por cento) de suas vagas para ministrar em nível de educação superior cursos de bacharelado e engenharia, visando à formação de profissionais para os diferentes setores da economia e áreas do conhecimento; e o mínimo de 20% (vinte por cento) de suas vagas para ministrar em nível de educação superior cursos de pós-graduação lato sensu de aperfeiçoamento e especialização, visando à formação de especialistas nas diferentes áreas do conhecimento.","o mínimo de 50% (cinquenta por cento) de suas vagas para ministrar em nível de educação superior cursos de licenciatura, bem como programas especiais de formação pedagógica, com vistas na formação de professores para a educação básica, sobretudo nas áreas de ciências e matemática, e para a educação profissional; e o mínimo de 20% (vinte por cento) de suas vagas para ministrar em nível de educação superior cursos de pós-graduação stricto sensu de mestrado e doutorado, que contribuam para promover o estabelecimento de bases sólidas em educação, ciência e tecnologia, com vistas no processo de geração e inovação tecnológica."],"correta":0,"explicacao":"Gabarito: <strong>o mínimo de 50% (cinquenta por cento) de suas vagas para ministrar educação profissional técnica de nível médio, prioritariamente na forma de cursos integrados, para os concluintes do ensino fundamental e para o público da educação de jovens e adultos; e o mínimo de 20% (vinte por cento) de suas vagas para ministrar em nível de educação superior cursos de licenciatura, bem como programas especiais de formação pedagógica, com vistas na formação de professores para a educação básica, sobretudo nas áreas de ciências e matemática, e para a educação profissional.</strong>.","banca":"FACTO","ano":2022,"temas_relacionados":["lei_11892_2008"]},{"id":3074428,"enunciado":"Nos termos da Lei nº 11.892/08, no que diz respeito a estrutura organizacional dos Institutos Federais, assinale a alternativa CORRETA.","opcoes":["Cada Instituto Federal é organizado em estrutura multicampi, com proposta orçamentária anual identificada para cada campus e a reitoria, inclusive no que diz respeito a pessoal, encargos sociais e benefícios aos servidores.","A administração dos Institutos Federais terá como órgãos superiores a Reitoria, o Colégio de Dirigentes e o Conselho Superior.","O Colégio de Dirigentes, de caráter deliberativo, será composto pelo Reitor, pelos Pró Reitores e pelo Diretor-Geral de cada um dos campi que integram o Instituto Federal.","O Conselho Superior, de caráter consultivo e deliberativo, será composto por representantes dos docentes, dos estudantes, dos servidores técnico-administrativos, dos egressos da instituição, da sociedade civil, do Ministério da Educação e do Colégio de Dirigentes do Instituto Federal, assegurando-se a representação paritária dos segmentos que compõem a comunidade acadêmica.","A reitoria, como órgão de administração central, deverá ser instalada em espaço físico distinto de qualquer dos campi que integram o Instituto Federal."],"correta":3,"explicacao":"Gabarito: <strong>O Conselho Superior, de caráter consultivo e deliberativo, será composto por representantes dos docentes, dos estudantes, dos servidores técnico-administrativos, dos egressos da instituição, da sociedade civil, do Ministério da Educação e do Colégio de Dirigentes do Instituto Federal, assegurando-se a representação paritária dos segmentos que compõem a comunidade acadêmica.</strong>.","banca":"FACTO","ano":2022,"temas_relacionados":["lei_11892_2008"]},{"id":3084469,"enunciado":"Observada a Lei Federal nº 11.892/2008, é correto afirmar que o IFSULDEMINAS foi criado mediante a integração:","opcoes":["Dos Centros Federais de Educação Tecnológica de Ouro Preto e de Bambuí, e da Escola Agrotécnica Federal de São João Evangelista.","Do Centro Federal de Educação Tecnológica de Januária e da Escola Agrotécnica Federal de Salinas.","Do Centro Federal de Educação Tecnológica de Rio Pomba e da Escola Agrotécnica Federal de Barbacena.","Das Escolas Agrotécnicas Federais de Inconfidentes, de Machado e de Muzambinho.","Do Centro Federal de Educação Tecnológica de Uberaba e da Escola Agrotécnica Federal de Uberlândia."],"correta":3,"explicacao":"Gabarito: <strong>Das Escolas Agrotécnicas Federais de Inconfidentes, de Machado e de Muzambinho.</strong>.","banca":"FUNDATEC","ano":2024,"temas_relacionados":["lei_11892_2008"]},{"id":3155492,"enunciado":"Acerca da Região Integrada de Desenvolvimento do Distrito Federal e Entorno (RIDE), julgue o item subsequente. \n\n\n\n\nAlgumas das causas da falta de acesso a bens materiais por parte da população dos municípios da RIDE remontam ao período colonial do Brasil.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":3155493,"enunciado":"Acerca da Região Integrada de Desenvolvimento do Distrito Federal e Entorno (RIDE), julgue o item subsequente. \n\n\n\n\nOs planos diretores de ordenamento territorial e urbano dos integrantes da RIDE foram constituídos mediante uma integração das respectivas legislações urbanísticas, edilícias e ambientais.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":3155494,"enunciado":"Acerca da Região Integrada de Desenvolvimento do Distrito Federal e Entorno (RIDE), julgue o item subsequente. \n\n\n\n\nOs serviços públicos específicos do Distrito Federal, como os de geração de empregos, são considerados de interesse dos integrantes da RIDE.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":3155495,"enunciado":"Acerca da Região Integrada de Desenvolvimento do Distrito Federal e Entorno (RIDE), julgue o item subsequente. \n\n\n\n\nCom a criação da RIDE, as desigualdades entre os municípios que fazem parte dessa região foram amenizadas devido à promoção de condições mais igualitárias de distribuição de bens de uso e de consumo.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":3210748,"enunciado":"Em relação à regulação, às agências reguladoras, à liberdade econômica, à análise de impacto regulatório e à Estratégia Nacional de Melhoria Regulatória (Decreto n.º 12.150/2024), julgue o item que se segue.\n\n\n\n\nO tempo e os recursos investidos no processo regulatório devem ser alocados conforme o custo unitário estimado da medida em análise, com foco em soluções que atendam às demandas da sociedade.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":3210749,"enunciado":"Em relação à regulação, às agências reguladoras, à liberdade econômica, à análise de impacto regulatório e à Estratégia Nacional de Melhoria Regulatória (Decreto n.º 12.150/2024), julgue o item que se segue.\n\n\n\n\nEm processos de privatização de serviços de utilidade pública, o Estado abdica de suas funções regulatórias, dando ensejo a processos de desregulamentação.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":3210750,"enunciado":"Em relação à regulação, às agências reguladoras, à liberdade econômica, à análise de impacto regulatório e à Estratégia Nacional de Melhoria Regulatória (Decreto n.º 12.150/2024), julgue o item que se segue.\n\n\n\n\nO Decreto n.º 10.411/2020 define os custos regulatórios e indica metodologias preferenciais para a realização de suas estimativas.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":3210751,"enunciado":"Em relação à regulação, às agências reguladoras, à liberdade econômica, à análise de impacto regulatório e à Estratégia Nacional de Melhoria Regulatória (Decreto n.º 12.150/2024), julgue o item que se segue.\n\n\n\n\nSob um regime de regulação por incentivos, o regulador não está voltado a monitorar os custos incorridos no passado pela entidade regulada.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":3210752,"enunciado":"Em relação à regulação, às agências reguladoras, à liberdade econômica, à análise de impacto regulatório e à Estratégia Nacional de Melhoria Regulatória (Decreto n.º 12.150/2024), julgue o item que se segue.\n\n\n\n\nA lei que institui a declaração de direitos de liberdade econômica garante ao particular o direito de ser informado sobre o prazo máximo para análise de sua solicitação de ato público de liberação de atividade econômica; passado esse prazo, o silêncio da autoridade será interpretado como aprovação, exceto em casos específicos previstos em lei.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":3210756,"enunciado":"De acordo com a Lei n.º 13.848/2019, julgue o item seguinte.\n\n\n\n\nO regimento interno da ANM deve dispor sobre a operacionalização da análise de impacto regulatório (AIR) em seu âmbito de atuação.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":3210757,"enunciado":"De acordo com a Lei n.º 13.848/2019, julgue o item seguinte.\n\n\n\n\nAinda que entenda pela não edição de determinado ato normativo, a ANM deverá indicar os pressupostos de fato e de direito que determinam a sua decisão.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":3212532,"enunciado":"Os Institutos Federais são instituições que ofertam cursos de Educação Profissional e Tecnológica, em todos os seus níveis e modalidades, atuando desde a formação inicial e continuada até cursos de Pós-graduação. Observadas as finalidades e características dessas instituições está correto afirmar que a Lei n° 11.892/2008 define como objetivos dos Institutos Federais, EXCETO:","opcoes":["Ministrar Educação Profissional Técnica de nível médio, prioritariamente na forma de cursos integrados, para os concluintes do Ensino Fundamental e para o público da educação de jovens e adultos.","Ministrar cursos de formação inicial e continuada de trabalhadores, objetivando a capacitação, o aperfeiçoamento, a especialização e a atualização de profissionais, em todos os níveis de escolaridade, nas áreas da Educação Profissional e Tecnológica.","Realizar pesquisas aplicadas, estimulando o desenvolvimento de soluções técnicas e tecnológicas, estendendo seus benefícios à comunidade.","Desenvolver atividades de extensão de acordo com os princípios e finalidades da Educação Profissional e Tecnológica, em articulação com o mundo do trabalho e os segmentos sociais, e com ênfase na produção, no desenvolvimento e na difusão de conhecimentos científicos e tecnológicos.","Estimular a inovação industrial por meio de educação, consultoria, pesquisa aplicada e serviços técnicos e tecnológicos que são decisivos para a competitividade das empresas do Estado e do Brasil."],"correta":4,"explicacao":"Gabarito: <strong>Estimular a inovação industrial por meio de educação, consultoria, pesquisa aplicada e serviços técnicos e tecnológicos que são decisivos para a competitividade das empresas do Estado e do Brasil.</strong>.","banca":"IF-ES","ano":2025,"temas_relacionados":["lei_11892_2008"]},{"id":3212533,"enunciado":"Os Institutos Federais de Educação, Ciência e Tecnologia são instituições de educação de oferta verticalizada especializados na oferta de Educação Profissional e Tecnológica nas diferentes modalidades de ensino. A respeito dessas instituições, e com base na Lei nº 11.892/2008, está correto afirmar, EXCETO:","opcoes":["Os Institutos Federais possuem natureza jurídica de autarquia, detentoras de autonomia administrativa, patrimonial, financeira, didático-pedagógica e disciplinar.","Trata-se de instituições que possuem autonomia para criar e extinguir cursos, bem como para registrar diplomas dos cursos oferecidos por eles ou por outras instituições de Educação Profissional, mediante autorização do seu Conselho Superior.","Cada Instituto Federal é organizado em estrutura multicampi, com proposta orçamentária anual identificada para cada campus e a reitoria, exceto no que diz respeito a pessoal, encargos sociais e benefícios aos servidores.","Os Institutos Federais têm como órgão executivo a reitoria, composta por 1 (um) Reitor e 5 (cinco) Pró-Reitores.","Para efeito da incidência das disposições que regem a regulação, avaliação e supervisão das instituições e dos cursos de educação superior, os Institutos Federais são equiparados às universidades federais."],"correta":1,"explicacao":"Gabarito: <strong>Trata-se de instituições que possuem autonomia para criar e extinguir cursos, bem como para registrar diplomas dos cursos oferecidos por eles ou por outras instituições de Educação Profissional, mediante autorização do seu Conselho Superior.</strong>.","banca":"IF-ES","ano":2025,"temas_relacionados":["lei_11892_2008"]},{"id":3219672,"enunciado":"Analise as seguintes asserções e a relação proposta entre elas, conforme a Lei nº 11.892/2008, que institui a Rede Federal de Educação Profissional, Científica e Tecnológica, cria os Institutos Federais de Educação, Ciência e Tecnologia, além de outras providências: I. A Lei cria o Instituto Federal Farroupilha, mediante integração do Centro Federal de Educação Tecnológica de São Vicente do Sul e da Escola Agrotécnica Federal de Alegrete. PORQUE II. Os Institutos Federais terão autonomia para criar e extinguir cursos, nos limites de sua área de atuação territorial, bem como para registrar diplomas dos cursos por eles oferecidos, mediante autorização do seu Conselho Superior, aplicando-se, no caso da oferta de cursos à distância, a legislação específica. A respeito dessas asserções, assinale a alternativa correta.","opcoes":["As asserções I e II são proposições verdadeiras, e a II é uma justificativa da I.","As asserções I e II são proposições verdadeiras, mas a II não é uma justificativa da I.","A asserção I é uma proposição verdadeira, e a II é uma proposição falsa.","A asserção I é uma proposição falsa, e a II é uma proposição verdadeira.","As asserções I e II são proposições falsas."],"correta":1,"explicacao":"Gabarito: <strong>As asserções I e II são proposições verdadeiras, mas a II não é uma justificativa da I.</strong>.","banca":"FUNDATEC","ano":2025,"temas_relacionados":["lei_11892_2008"]},{"id":3255962,"enunciado":"Um dos principais instrumentos normativos que regulamenta a Administração Pública Federal no Brasil é o Decreto-Lei nº 200, de 25 de fevereiro de 1967. O Instituto Federal de Educação, Ciência e Tecnologia de Mato Grosso (IFMT), por sua vez, enquanto instituição integrante da Administração Pública Federal, é regulamentado pela Lei nº 11.892, de 29 de dezembro de 2008. À luz dessas legislações, julgue as assertivas abaixo, marcando V para as assertivas verdadeiras e F para as falsas. ( ) O IFMT faz parte da chamada Administração Direta, que se constitui dos serviços integrados na estrutura administrativa da Presidência da República e dos Ministérios. ( ) O IFMT apresenta natureza jurídica de Fundação Pública, sendo uma entidade dotada de personalidade jurídica de direito privado, sem fins lucrativos, criada em virtude de autorização legislativa para o desenvolvimento de atividades que não exijam execução por órgãos ou entidades de direito público, com autonomia administrativa, patrimônio próprio gerido pelos respectivos órgãos de direção e funcionamento custeado por recursos da União e de outras fontes. ( ) O IFMT apresenta natureza jurídica de Autarquia, sendo um serviço autônomo, criado por lei, com personalidade jurídica, patrimônio e receita próprios, para executar atividades típicas da Administração Pública que requeiram, para seu melhor funcionamento, gestão administrativa e financeira descentralizada. ( ) Como instituição integrante da Administração Federal, o IFMT está sujeito à supervisão do Ministério da Educação. Assinale a sequência CORRETA.","opcoes":["V, F, F, V.","F, F, V, V.","F, V, F, V.","V, V, F, F.","V, V, V, V."],"correta":1,"explicacao":"Gabarito: <strong>F, F, V, V.</strong>.","banca":"IF-MT","ano":2023,"temas_relacionados":["lei_11892_2008"]},{"id":3262998,"enunciado":"Assinale a alternativa correta segundo a Lei nº 11.892/2008, que institui a Rede Federal de Educação Profissional, Científica e Tecnológica e cria os Institutos Federais de Educação, Ciência e Tecnologia.","opcoes":["Escolas Técnicas vinculadas às Universidades Federais fazem parte da Rede Federal de Educação Profissional, Científica e Tecnológica.","Diversos organismos de âmbito federal possuem por função precípua a realização e o estímulo da produção cultural, o que, por força de lei, não ocorre nos Institutos Federais.","A realização de pesquisas aplicadas, em razão da especificidade, não é desenvolvida por Institutos Federais, ficando a cargo das Universidades Federais e instituições privadas de Ensino Superior.","As Reitorias, órgãos deliberativos dos Institutos Federais, são compostas por três Pró-Reitores.","Por imposição legal, visto se tratar de instituições públicas federais, doações ou legados que os Institutos Federais vierem a receber não integrarão seu patrimônio, sob pena de improbidade administrativa."],"correta":0,"explicacao":"Gabarito: <strong>Escolas Técnicas vinculadas às Universidades Federais fazem parte da Rede Federal de Educação Profissional, Científica e Tecnológica.</strong>.","banca":"FUNDATEC","ano":2025,"temas_relacionados":["lei_11892_2008"]},{"id":3262999,"enunciado":"Sobre a estrutura organizacional dos Institutos Federais e outras disposições da Lei Federal nº 11.892/2008, analise as assertivas abaixo e assinale a alternativa correta. I. Os Institutos Federais terão como órgão executivo a reitoria, composta por um Reitor e cinco Pró-Reitores. Os Reitores serão nomeados pelo Governador do Estado em que se localiza o Instituto, após a indicação do corpo docente, para mandato de quatro anos, sendo vedada recondução. II. A Lei determina que o Colégio Pedro II tenha a mesma estrutura e organização dos Institutos Federais de Educação, Ciência e Tecnologia. III. O Colégio de Dirigentes é órgão superior e tem caráter consultivo, sendo composto por docentes pertencentes ao Quadro de Pessoal Ativo e presidido por um representante eleito pelo corpo docente para este fim.","opcoes":["Todas as assertivas estão corretas.","Todas as assertivas estão incorretas.","Apenas a assertiva I está correta.","Apenas a assertiva II está correta.","Apenas a assertiva III está correta."],"correta":3,"explicacao":"Gabarito: <strong>Apenas a assertiva II está correta.</strong>.","banca":"FUNDATEC","ano":2025,"temas_relacionados":["lei_11892_2008"]},{"id":3263647,"enunciado":"De acordo com a Lei Federal nº 11.892/2008, que institui a Rede Federal de Educação Profissional, Científica e Tecnológica, e cria os Institutos Federais de Educação, Ciência e Tecnologia, analise as assertivas abaixo e assinale a alternativa correta. I. A administração dos Institutos Federais terá como órgãos superiores o Colégio de Dirigentes e o Conselho Superior. II. Os Institutos Federais terão como órgão executivo a Reitoria, composta por um Reitor e dez Pró-Reitores. III. Os reitores são nomeados pelo Conselho Superior para um mandato de 6 anos.","opcoes":["Todas as assertivas estão corretas.","Todas as assertivas estão incorretas.","Apenas a assertiva I está correta.","Apenas a assertiva II está correta.","Apenas as assertivas I e III estão corretas."],"correta":2,"explicacao":"Gabarito: <strong>Apenas a assertiva I está correta.</strong>.","banca":"FUNDATEC","ano":2025,"temas_relacionados":["lei_11892_2008"]},{"id":3274460,"enunciado":"De acordo com o Decreto nº 9.830/2019, julgue o item seguinte. \n\n\n\n\nA decisão que determinar a revisão da validade de atos, cujos efeitos ainda estejam em curso, levará em consideração as orientações vigentes, caso as anteriores tenham sido expressamente revogadas.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":3274461,"enunciado":"De acordo com o Decreto nº 9.830/2019, julgue o item seguinte. \n\n\n\n\nO compromisso é um instrumento destinado a eliminar irregularidade, incerteza jurídica ou situações contenciosas na aplicação do direito público. Contudo, ele não poderá conferir desoneração permanente de dever ou condicionamento de direito reconhecido por orientação geral.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":3274462,"enunciado":"De acordo com o Decreto nº 9.830/2019, julgue o item seguinte. \n\n\n\n\nO dano ao erário, ainda que expressivo, não poderá, por si só, ser elemento para caracterizar o erro grosseiro ou o dolo.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":3327831,"enunciado":"De acordo com a Lei n. 11.892/2008, os Institutos Federais têm como objetivos, exceto:","opcoes":["Promover o desenvolvimento de programas de extensão com foco prioritário no intercâmbio internacional, buscando parcerias com instituições estrangeiras para capacitação de alunos e servidores, sem a obrigatoriedade de retorno direto das atividades desenvolvidas à comunidade.","Ministrar cursos de formação inicial e continuada de trabalhadores, objetivando a capacitação, o aperfeiçoamento, a especialização e a atualização de profissionais, em todos os níveis de escolaridade nas áreas de educação profissional e tecnológica.","Realizar pesquisas aplicadas, estimulando o desenvolvimento de soluções técnicas e tecnológicas, estendendo seus benefícios à comunidade.","Ministrar educação profissional técnica de nível médio, prioritariamente na forma de cursos integrados, com os concluintes do ensino fundamental e para o público da educação de jovens e adultos.","Estimular e apoiar processos educativos que levem à geração de trabalho e renda e à emancipação do cidadão na perspectiva do desenvolvimento socioeconômico local e regional."],"correta":0,"explicacao":"Gabarito: <strong>Promover o desenvolvimento de programas de extensão com foco prioritário no intercâmbio internacional, buscando parcerias com instituições estrangeiras para capacitação de alunos e servidores, sem a obrigatoriedade de retorno direto das atividades desenvolvidas à comunidade.</strong>.","banca":"IF-MG","ano":2024,"temas_relacionados":["lei_11892_2008"]},{"id":3367958,"enunciado":"O artigo 6º da Lei nº 11.892/2008 apresenta as finalidades e características dos Institutos Federais de Educação, Ciência e Tecnologia. Com base no citado dispositivo legal, marque a alternativa que apresenta de forma correta uma finalidade/característica destas instituições.","opcoes":["Desenvolver a educação profissional e tecnológica como processo educativo e investigativo de geração e adaptação de soluções técnicas e tecnológicas às demandas sociais e peculiaridades regionais.","Ofertar educação profissional e tecnológica, apenas no nívelsuperior, formando e qualificando cidadãos com vistas à atuação profissional nos diversos setores da economia, com ênfase no desenvolvimento socioeconômico local, regional e nacional.","Desenvolver a educação profissional e tecnológica como processo educativo e investigativo de geração e adaptação de soluções técnicas e tecnológicas às demandas sociais, não devendo observar peculiaridades regionais.","Qualificar-se como centro de referência no apoio à oferta do ensino de ciências nas instituições públicas de ensino, oferecendo capacitação técnica e atualização pedagógica aos docentes das redes privadas de ensino.","Promover a integração e a verticalização da educação básica à educação profissional apenas, excluindo a educação superior, otimizando a infraestrutura física, os quadros de pessoal e os recursos de gestão."],"correta":0,"explicacao":"Gabarito: <strong>Desenvolver a educação profissional e tecnológica como processo educativo e investigativo de geração e adaptação de soluções técnicas e tecnológicas às demandas sociais e peculiaridades regionais.</strong>.","banca":"IF-PI","ano":2022,"temas_relacionados":["lei_11892_2008"]},{"id":3368496,"enunciado":"Com base na Lei nº 11.892, de 29 de dezembro de 2008, analise as assertivas a seguir. I. Um dos objetivos dos Institutos Federais é estimular e apoiar processos educativos que levem à geração de trabalho e renda e à emancipação do cidadão na perspectiva do desenvolvimento socioeconômico local e regional. II. A administração dos Institutos Federais terá como órgãos superiores o Colégio de Dirigentes e o Conselho Superior. As presidências do Colégio de Dirigentes e do Conselho Superior serão exercidas pelo Reitor do Instituto Federal. III. O Colégio de Dirigentes, de caráter consultivo, será composto exclusivamente pelo Reitor e pelo DiretorGeral de cada um dos campi que integram o Instituto Federal. IV. O Colégio Pedro II é equiparado aos institutos federais para efeito de incidência das disposições que regem a autonomia e a utilização dos instrumentos de gestão do quadro de pessoal e de ações de regulação, avaliação e supervisão das instituições e dos cursos de educação profissional e superior. Está correto o que se apresenta em:","opcoes":["I, II e III, apenas.","I, III e IV, apenas.","II, III e IV, apenas.","I, II e IV, apenas.","I, II, III e IV."],"correta":3,"explicacao":"Gabarito: <strong>I, II e IV, apenas.</strong>.","banca":"Nosso Rumo","ano":2024,"temas_relacionados":["lei_11892_2008"]},{"id":3369121,"enunciado":"Conforme disposto na Lei nº 11.892/2008, os Institutos Federais têm por finalidade e característica, entre outros:","opcoes":["realizar pesquisas aplicadas, estimulando o desenvolvimento de soluções técnicas e tecnológicas, estendendo seus benefícios à comunidade.","qualificar-se como centro de referência no apoio à oferta do ensino de ciências nas instituições públicas e privadas de ensino, oferecendo capacitação técnica e atualização pedagógica aos docentes de todas as redes de ensino que assim desejarem.","promover a integração e a verticalização da educação básica à educação profissional e educação superior, otimizando a infraestrutura física, os quadros de pessoal e os recursos de gestão.","promover a produção, o desenvolvimento e a transferência de tecnologias sociais, notadamente as voltadas ao desenvolvimento econômico.","ministrar em nível de educação superior cursos superiores de tecnologia visando à formação de profissionais para os diferentes setores da economia."],"correta":2,"explicacao":"Gabarito: <strong>promover a integração e a verticalização da educação básica à educação profissional e educação superior, otimizando a infraestrutura física, os quadros de pessoal e os recursos de gestão.</strong>.","banca":"Nosso Rumo","ano":2024,"temas_relacionados":["lei_11892_2008"]},{"id":3371507,"enunciado":"Assinale a alternativa correta a respeito da Estrutura Organizacional dos Institutos Federais, conforme a Lei nº 11.892/2008.","opcoes":["Os Institutos Federais terão como órgão executivo a reitoria, composta por 1 (um) Reitor e 2 (dois) Pró-Reitores.","O mandato de Reitor extingue-se pelo decurso do prazo ou, antes desse prazo, somente pela renúncia.","A reitoria, como órgão de administração central, não poderá ser instalada em espaço físico distinto de qualquer dos campi que integram o Instituto Federal.","A administração dos Institutos Federais terá como órgão superior o Ministério da Educação.","Cada Instituto Federal é organizado em estrutura multicampi, com proposta orçamentária anual identificada para cada campus e a reitoria, exceto no que diz respeito a pessoal, encargos sociais e benefícios aos servidores."],"correta":4,"explicacao":"Gabarito: <strong>Cada Instituto Federal é organizado em estrutura multicampi, com proposta orçamentária anual identificada para cada campus e a reitoria, exceto no que diz respeito a pessoal, encargos sociais e benefícios aos servidores.</strong>.","banca":"Nosso Rumo","ano":2024,"temas_relacionados":["lei_11892_2008"]},{"id":3448604,"enunciado":"A Lei nº 12.813/13 dispõe sobre o conflito de interesses no exercício de cargo ou emprego do Poder Executivo federal e impedimentos posteriores ao exercício do cargo ou emprego. Desse modo, analise o item a seguir. \n\n\n\n\nAtuar, ainda que informalmente, como procurador, consultor, assessor ou intermediário de interesses privados nos órgãos ou entidades da administração pública direta ou indireta de qualquer dos Poderes da União, dos Estados, do Distrito Federal e dos Municípios, configura conflito de interesses no exercício de cargo ou emprego no âmbito do Poder Executivo federal.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Qconcursos","ano":2025,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":3448609,"enunciado":"A respeito dos conflitos de interesses previstos na Lei nº 12.813/13, julgue o item seguinte.\n\n\n\n\nConfigura conflito de interesses após o exercício de cargo ou emprego no âmbito do Poder Executivo federal a qualquer tempo, divulgar ou fazer uso de informação privilegiada obtida em razão das atividades exercidas.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Qconcursos","ano":2025,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":3448680,"enunciado":"A Portaria Conjunta MGI/MF/CGU nº 33/2023 estabelece normas aplicáveis à celebração, execução e prestação de contas de convênios e instrumentos congêneres no âmbito da Administração Pública Federal.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Qconcursos","ano":2025,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":3448684,"enunciado":"A IN nº 5/2017 orienta que a fiscalização de contratos seja realizada com base em plano de fiscalização previamente estabelecido, compatível com a complexidade do objeto contratado.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Qconcursos","ano":2025,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":3448693,"enunciado":"Durante uma investigação sobre crime de extorsão mediante sequestro, o delegado titular do caso requisitou diretamente à instituição bancária os dados e informações cadastrais do investigado, sem necessidade de autorização judicial, fundamentando a medida no interesse da apuração dos fatos.\n\n\n\n\nNessa situação, o delegado de polícia agiu dentro dos limites legais conferidos pela Lei nº 12.830/2013.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Qconcursos","ano":2025,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":3448694,"enunciado":"João, delegado de polícia responsável por uma unidade especializada, foi removido de ofício para outra delegacia sem qualquer justificativa formal. A remoção ocorreu por conveniência administrativa, sem despacho fundamentado. Conforme a Lei nº 12.830/2013, a remoção do delegado de polícia pode ocorrer por conveniência da Administração, independentemente de fundamentação.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Qconcursos","ano":2025,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":3448695,"enunciado":"De acordo com a Lei nº 12.830/2013, as funções de polícia judiciária e a apuração de infrações penais exercidas pelo delegado de polícia são de natureza jurídica, essenciais e exclusivas de Estado.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Qconcursos","ano":2025,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":3504104,"enunciado":"Como parte das iniciativas governamentais da política nacional voltada à educação profissional nos anos 2000, a Lei nº 11.892, de 29 de dezembro de 2008, instituiu a Rede Federal de Educação Profissional, Científica e Tecnológica, vinculada ao Ministério da Educação, conforme dispõe o seu Art. 1º. Dentre as instituições da Rede Federal, cabe aos Institutos Federais, entre outras obrigações, ofertar","opcoes":["educação profissional técnica de nível médio, na forma de cursos integrados, subsequentes e concomitantes; cursos de formação inicial e continuada de trabalhadores, nas áreas e eixos da educação profissional e tecnológica; realizar pesquisas aplicadas, estendendo os seus benefícios à comunidade; atividades de extensão, em articulação com o mundo do trabalho e os segmentos sociais, e com ênfase na produção, desenvolvimento e difusão de conhecimentos científicos e tecnológicos; estimular e apoiar processos educativos que levem à geração de emprego e renda e à emancipação do cidadão na perspectiva do desenvolvimento socioeconômico local e regional; e ministrar cursos em nível de educação superior.","educação profissional técnica de nível médio, na forma de cursos integrados, subsequentes e concomitantes; cursos de formação inicial e continuada de trabalhadores, nas áreas e eixos da educação profissional e tecnológica; realizar pesquisas aplicadas, estendendo os seus benefícios à comunidade; atividades de extensão, em articulação com o mercado do trabalho e os segmentos sociais, e com ênfase na produção, desenvolvimento e difusão de conhecimentos tecnológicos; estimular e apoiar processos educativos que levem à geração de emprego e renda e à emancipação do cidadão na perspectiva do desenvolvimento socioeconômico local e regional; e ministrar cursos de graduação, exclusivamente com foco tecnológico.","educação profissional técnica de nível médio, na forma de cursos integrados, subsequentes e regulares; cursos de formação inicial e continuada de pessoas desempregadas, nas áreas e eixos da educação profissional e tecnológica; realizar pesquisas aplicadas, estendendo os seus benefícios à comunidade científica; atividades de extensão, em articulação com o mercado de trabalho e os segmentos sociais, e com ênfase na produção, desenvolvimento e difusão de conhecimentos científicos e tecnológicos; estimular e apoiar processos educativos que levem à geração de emprego e renda e à profissionalização do cidadão na sua respectiva região.","educação profissional técnica de nível médio, na forma de cursos integrados, subsequentes e concomitantes; cursos de qualificação e de aperfeiçoamento para jovens e adultos trabalhadores, nas áreas e eixos da educação profissional e tecnológica; realizar pesquisas acadêmicas, estendendo os seus benefícios à comunidade; atividades de extensão, em articulação com o mundo do trabalho e os segmentos sociais, e com ênfase na produção, desenvolvimento e difusão de conhecimentos científicos e tecnológicos; estimular e apoiar processos educativos que levem à geração de emprego e renda e à emancipação do cidadão."],"correta":0,"explicacao":"Gabarito: <strong>educação profissional técnica de nível médio, na forma de cursos integrados, subsequentes e concomitantes; cursos de formação inicial e continuada de trabalhadores, nas áreas e eixos da educação profissional e tecnológica; realizar pesquisas aplicadas, estendendo os seus benefícios à comunidade; atividades de extensão, em articulação com o mundo do trabalho e os segmentos sociais, e com ênfase na produção, desenvolvimento e difusão de conhecimentos científicos e tecnológicos; estimular e apoiar processos educativos que levem à geração de emprego e renda e à emancipação do cidadão na perspectiva do desenvolvimento socioeconômico local e regional; e ministrar cursos em nível de educação superior.</strong>.","banca":"FUNCERN","ano":2025,"temas_relacionados":["lei_11892_2008"]},{"id":3514981,"enunciado":"Conforme definido na Lei Federal nº 11.892/2008, o Instituto Federal de Mato Grosso foi criado mediante:","opcoes":["A integração da Escola Técnica Federal de Cuiabá e das Escolas Agrotécnicas Federais de São Vicente e de Cáceres.","A integração dos Centros Federais de Educação Tecnológica de Mato Grosso e de São Vicente e da Escola Agrotécnica Federal de Cáceres.","A integração dos Centros Federais de Educação Tecnológica de Mato Grosso e de Cuiabá e da Escola Agrotécnica Federal de Cáceres.","A integração da Escola Técnica Federal de Mato Grosso e das Escolas Agrotécnicas Federais de Cuiabá e de Cáceres.","A integração da Escola Técnica Federal de Mato Grosso e das Escolas Agrotécnicas Federais de São Vicente e de Cáceres."],"correta":2,"explicacao":"Gabarito: <strong>A integração dos Centros Federais de Educação Tecnológica de Mato Grosso e de Cuiabá e da Escola Agrotécnica Federal de Cáceres.</strong>.","banca":"IF-MT","ano":2024,"temas_relacionados":["lei_11892_2008"]},{"id":3518261,"enunciado":"Nos termos da Lei nº 11.892/2008, julgue as assertivas abaixо: I. Nos campi em processo de implantação, os cargos de Diretor-Geral serão providos em caráter pro tempore, por nomeação do Ministro da Educação, até que seja possível identificar candidatos que atendam aos requisitos previstos na Lei nº 11.892/2008. II. Nos campi em processo de implantação, os cargos de Diretor-Geral serão providos em caráter pro tempore, por nomeação do Reitor do Instituto Federal, até que seja possível identificar candidatos que atendam aos requisitos previstos na Lei nº 11.892/2008. III.O Diretor-Geral nomeado para o cargo de Reitor Pro-Tempore do Instituto Federal, ou de Diretor-Geral ProTempore do Campus, não poderá candidatar-se a um novo mandato, desde que já se encontre no exercício do segundo mandato, em observância ao limite máximo de investidura permitida, que são de 2 (dois) mandatos consecutivos. IV.O Diretor-Geral nomeado para o cargo de Reitor Pro-Tempore do Instituto Federal, ou de Diretor-Geral ProTempore do Campus, poderá candidatar-se a um novo mandato, mesmo que já se encontre no exercício do segundo mandato, em observância ao limite máximo de investidura permitida, que são de 3 (três) mandatos consecutivos. Está(ão) CORRETA(S) apenas a(s) assertiva(s):","opcoes":["Ie II.","II e III.","II e IV.","I e IV.","Todas estão corretas."],"correta":1,"explicacao":"Gabarito: <strong>II e III.</strong>.","banca":"IF-MT","ano":2024,"temas_relacionados":["lei_11892_2008"]},{"id":3539771,"enunciado":"Conforme determina a Lei n° 11.892/2008, no desenvolvimento da sua ação académica, o Instituto Federal, em cada exercício, deverá garantir o mínimo de                         de suas vagas para atender a educação profissional técnica de nível médio, prioritariamente na forma de cursos integrados, para os concluintes do ensino fundamental e para o publico da educação de jovens e adultos. O Instituto Federal deverá garantir também o mínimo de                         de suas vagas para atender aos cursos de licenciatura, bem como programas especiais de formação pedagógica, com vistas a formação de professores para a educação básica, sobretudo nas areas de ciências e Matematica, e para a educação profissional. Assinale a alternativa que preenche CORRETAMENTE as lacunas:","opcoes":["20% (vinte por cento); 5% (cinco por cento).","30% (trinta por cento); 10% (dez por cento).","40% (quarenta por cento); 15% (quinze por cento).","50% (cinquenta por cento); 20% (vinte por cento).","60% (sessenta por cento); 25% (vinte e cinco por cento)."],"correta":3,"explicacao":"Gabarito: <strong>50% (cinquenta por cento); 20% (vinte por cento).</strong>.","banca":"IF-MT","ano":2024,"temas_relacionados":["lei_11892_2008"]},{"id":3539876,"enunciado":"Conforme a Lei Federal nº 11.892/2008, que institui a rede federal de educação profissional, científica e tecnológica, são objetivos dos institutos federais ministrar em nível de educação superior: I. cursos de formação inicial e continuada de trabalhadores, objetivando a capacitação, o aperfeiçoamento, a especialização e a atualização de profissionais jovens e adultos; II. cursos de licenciatura, bem como programas especiais de formação pedagógica, com vistas à formação de professores para a educação básica, sobretudo nas áreas de ciências e matemática, e para a educação profissional; III. cursos de bacharelado e engenharia, visando à formação de profissionais para os diferentes setores da economia e áreas do conhecimento; IV. cursos de pós-graduação lato sensu de aperfeiçoamento e especialização, visando à formação de especialistas nas diferentes áreas do conhecimento. Estão corretos","opcoes":["apenas II, III e IV.","apenas I e IV.","apenas I, III e IV.","apenas II e III.","apenas I, II e III."],"correta":0,"explicacao":"Gabarito: <strong>apenas II, III e IV.</strong>.","banca":"INSTITUTO AOCP","ano":2025,"temas_relacionados":["lei_11892_2008"]},{"id":3540000,"enunciado":"Marta é secretária especial do Ministério da Educação, com a função de fiscalizar e avaliar a rede federal de educação. Para exercer seu ofício, Marta teve que interpretar a Lei Federal nº 11.892/2008, que criou os institutos federais, para compreender que","opcoes":["os Institutos Federais terão como órgão executivo a reitoria, composta por 1 (um) Reitor e 2 (dois) Pró-Reitores.","a administração dos Institutos Federais terá como órgão superior o Ministério da Educação.","a reitoria, como órgão de administração central, deverá ser instalada em espaço físico coincidente com qualquer dos campi que integram o Instituto Federal.","os Reitores serão nomeados pelo Presidente da República, para mandato de 3 (três) anos, vedada a recondução.","os campi serão dirigidos por Diretores-Gerais, nomeados pelo Reitor para mandato de 4 (quatro) anos, permitida uma recondução, após processo de consulta à comunidade do respectivo campus, atribuindo-se o peso de 1/3 (um terço) para a manifestação do corpo docente, de 1/3 (um terço) para a manifestação dos servidores técnico-administrativos e de 1/3 (um terço) para a manifestação do corpo discente."],"correta":4,"explicacao":"Gabarito: <strong>os campi serão dirigidos por Diretores-Gerais, nomeados pelo Reitor para mandato de 4 (quatro) anos, permitida uma recondução, após processo de consulta à comunidade do respectivo campus, atribuindo-se o peso de 1/3 (um terço) para a manifestação do corpo docente, de 1/3 (um terço) para a manifestação dos servidores técnico-administrativos e de 1/3 (um terço) para a manifestação do corpo discente.</strong>.","banca":"INSTITUTO AOCP","ano":2025,"temas_relacionados":["lei_11892_2008"]},{"id":3540001,"enunciado":"Com base na Lei Federal nº 11.892/2008, que institui a Rede Federal de Educação Profissional, Científica e Tecnológica, cria os Institutos Federais de Educação, Ciência e Tecnologia, e dá outras providências, no âmbito de sua atuação, os Institutos Federais exercerão o papel de instituições acreditadoras e certificadoras de","opcoes":["comportamento probo.","qualidade social.","competências profissionais.","diplomação.","higidez intelectual."],"correta":2,"explicacao":"Gabarito: <strong>competências profissionais.</strong>.","banca":"INSTITUTO AOCP","ano":2025,"temas_relacionados":["lei_11892_2008"]},{"id":3540257,"enunciado":"A Lei nº 11.892/2008 institui a Rede Federal de Educação Profissional, Científica e Tecnológica e cria os Institutos Federais de Educação, Ciência e Tecnologia. Com base nessa lei, assinale a alternativa INCORRETA.","opcoes":["Cada Instituto Federal é organizado em estrutura multicampi, com proposta orçamentária semestral identificada para cada campus e a reitoria, inclusive no que diz respeito a pessoal, encargos sociais e benefícios aos servidores","No âmbito de sua atuação, os Institutos Federais exercerão o papel de instituições acreditadoras e certificadoras de competências profissionais.","Os Institutos Federais têm por finalidades e características, dentre outras, promover a integração e a verticalização da educação básica à educação profissional e à educação superior, otimizando a infraestrutura física, os quadros de pessoal e os recursos de gestão.","A administração dos Institutos Federais terá como órgãos superiores o Colégio de Dirigentes e o Conselho Superior.","Dentre outros requisitos, para candidatar-se ao cargo de Reitor, os docentes pertencentes ao Quadro de Pessoal Ativo Permanente de qualquer dos campi que integram o Instituto Federal devem possuir o mínimo de 5 (cinco) anos de efetivo exercício em instituição federal de educação profissional e tecnológica."],"correta":0,"explicacao":"Gabarito: <strong>Cada Instituto Federal é organizado em estrutura multicampi, com proposta orçamentária semestral identificada para cada campus e a reitoria, inclusive no que diz respeito a pessoal, encargos sociais e benefícios aos servidores</strong>.","banca":"INSTITUTO AOCP","ano":2025,"temas_relacionados":["lei_11892_2008"]},{"id":3548325,"enunciado":"Conforme a Lei Federal nº 11.892/2008, os Institutos Federais de Educação, Ciência e Tecnologia","opcoes":["têm por finalidade e característica ofertar educação profissional e tecnológica, em todos os seus níveis e modalidades, formando e qualificando cidadãos com vistas na atuação profissional nos diversos setores da economia, com ênfase no desenvolvimento socioeconômico local, regional e nacional.","têm por objetivo realizar pesquisas aplicadas, estimulando o desenvolvimento de soluções técnicas e tecnológicas, estendendo seus benefícios à comunidade, embora possuam regulamentação e estrutura organizacional impeditivas ao desenvolvimento de programas de extensão.","são impedidos de conceder bolsas de pesquisa a docentes, a ocupantes de cargo público efetivo, a detentores de função ou de emprego público e a pesquisadores externos ou de empresas.","têm como órgão executivo a reitoria, composta por 1 (um) Reitor, eleito por voto direto da comunidade escolar do respectivo Instituto Federal, e 5 (cinco) Pró-Reitores.","possuem natureza jurídica de empresa pública e são instituições detentoras de autonomia administrativa, patrimonial, financeira, didático-pedagógica e disciplinar."],"correta":0,"explicacao":"Gabarito: <strong>têm por finalidade e característica ofertar educação profissional e tecnológica, em todos os seus níveis e modalidades, formando e qualificando cidadãos com vistas na atuação profissional nos diversos setores da economia, com ênfase no desenvolvimento socioeconômico local, regional e nacional.</strong>.","banca":"INSTITUTO AOCP","ano":2025,"temas_relacionados":["lei_11892_2008"]},{"id":3563832,"enunciado":"A Lei nº 11.892/2008 foi um marco na consolidação da EPCT no Brasil. A partir dessa legislação, foram criados os Institutos Federais de Educação, Ciência e Tecnologia, com uma missão específica. Assinale a alternativa que melhor descreve essa missão institucional.","opcoes":["Oferecer cursos técnicos de nível médio voltados ao setor industrial.","Promover a Educação Básica em tempo integral, com foco em atividades culturais e esportivas.","Oferecer Educação Profissional e Tecnológica articulada com pesquisa aplicada, extensão e desenvolvimento local.","Formar profissionais para atuar preferencialmente no Ensino Superior, com foco em pesquisa acadêmica tradicional.","Desenvolver programas de alfabetização para jovens e adultos em parceria com municípios."],"correta":2,"explicacao":"Gabarito: <strong>Oferecer Educação Profissional e Tecnológica articulada com pesquisa aplicada, extensão e desenvolvimento local.</strong>.","banca":"FUNDATEC","ano":2025,"temas_relacionados":["lei_11892_2008"]},{"id":3563841,"enunciado":"Com base na Lei nº 11.892/2008, que institui a Rede Federal de Educação Profissional, Científica e Tecnológica e cria os Institutos Federais de Educação, Ciência e Tecnologia, assinale a alternativa INCORRETA.","opcoes":["Os Institutos Federais são instituições de educação pluricurriculares, multicampi, com autonomia para criar e extinguir cursos em sua área de atuação territorial, inclusive à distância, desde que autorizados por seu Conselho Superior.","Para efeito da regulação, avaliação e supervisão de instituições e cursos de educação superior, os Institutos Federais são equiparados às Universidades Federais.","Os Institutos Federais devem garantir, anualmente, no mínimo 50% das vagas para cursos técnicos integrados ao ensino médio e pelo menos 30% das vagas para cursos de licenciatura e bacharelado, visando à formação de profissionais para os diferentes setores da economia e áreas do conhecimento.","Os Institutos Federais têm por finalidades e características, dentre outras, constituir-se em centro de excelência na oferta do ensino de ciências, em geral, e de ciências aplicadas, em particular, estimulando o desenvolvimento de espírito crítico, voltado à investigação empírica.","Os Institutos Federais podem atuar no desenvolvimento de programas de extensão e de divulgação científica e tecnológica, mesmo sem fins de exploração econômica."],"correta":2,"explicacao":"Gabarito: <strong>Os Institutos Federais devem garantir, anualmente, no mínimo 50% das vagas para cursos técnicos integrados ao ensino médio e pelo menos 30% das vagas para cursos de licenciatura e bacharelado, visando à formação de profissionais para os diferentes setores da economia e áreas do conhecimento.</strong>.","banca":"FUNDATEC","ano":2025,"temas_relacionados":["lei_11892_2008"]},{"id":3564392,"enunciado":"Segundo a Lei nº 11.892/2008, que cria os Institutos Federais de Educação, Ciência e Tecnologia, analise as assertivas abaixo e assinale V, se verdadeiras, ou F, se falsas. ( ) Os Institutos Federais têm por finalidade ofertar educação profissional em todos os níveis e modalidades, integrando ensino, pesquisa e extensão. ( ) A Lei estabelece como prioridade a formação de trabalhadores para os setores de base tecnológica e industrial, desconsiderando aspectos regionais. ( ) Os órgãos superiores dos Institutos Federais incluem o Conselho Superior e o Colégio de Dirigentes. ( ) O Conselho Superior é composto por Reitor, Pró-Reitores e representantes dos docentes. A ordem correta de preenchimento dos parênteses, de cima para baixo, é:","opcoes":["V – F – V – F.","V – V – F – F.","F – V – F – V.","F – F – V – V.","V – V – F – V."],"correta":0,"explicacao":"Gabarito: <strong>V – F – V – F.</strong>.","banca":"FUNDATEC","ano":2025,"temas_relacionados":["lei_11892_2008"]},{"id":3565188,"enunciado":"Em um instituto federal, está em andamento o processo de consulta à comunidade escolar para a escolha do reitor. Os diferentes segmentos da comunidade participam ativamente da manifestação, cientes de que a Lei Federal nº 11.892/2008 estabelece critérios para a ponderação de seus votos. Com base na referida Lei, sobre o processo de consulta à comunidade escolar para a nomeação do reitor dos institutos federais, assinale a alternativa correta.","opcoes":["Qualquer cidadão da região de atuação do instituto federal pode participar do processo de consulta, dada a vocação regional da instituição.","Os reitores são eleitos diretamente pela comunidade escolar, sem necessidade de nomeação presidencial.","O mandato do reitor é de 2 anos, permitida uma recondução.","A manifestação de cada um dos três segmentos (docente, técnico-administrativo e discente) tem o peso de 1/3.","A consulta pública para escolha do reitor é facultativa e não influencia a nomeação oficial."],"correta":3,"explicacao":"Gabarito: <strong>A manifestação de cada um dos três segmentos (docente, técnico-administrativo e discente) tem o peso de 1/3.</strong>.","banca":"FUNDATEC","ano":2025,"temas_relacionados":["lei_11892_2008"]},{"id":3574419,"enunciado":"Com base na Lei nº 11.892, de 29 de dezembro de 2008, que institui a Rede Federal de Educação Profissional, Científica e Tecnológica e cria os Institutos Federais de Educação, Ciência e Tecnologia, analise as assertivas a seguir quanto aos objetivos dessas instituições: a) Ministrar, em nível de educação superior, prioritariamente na forma de cursos integrados, para concluintes do ensino fundamental e para o público da educação de jovens e adultos, cursos superiores de tecnologia visando à formação de profissionais para o mercado de trabalho. b) Ministrar cursos de formação inicial e continuada de trabalhadores, objetivando a capacitação, o aperfeiçoamento, a especialização e a atualização de profissionais, em todos os níveis de escolaridade, nas áreas da educação profissional e tecnológica. c) Realizar pesquisa básica, estimulando o desenvolvimento de soluções elementares, cujos benefícios devem ser exclusivamente destinados à própria Instituição. d) Desenvolver atividades de extensão em consonância com os princípios e finalidades da educação profissional e tecnológica, articuladas com o mundo do trabalho e os segmentos sociais, com ênfase na produção, no desenvolvimento e na difusão de conhecimentos científicos e tecnológicos.","opcoes":["Estimular e apoiar processos educativos voltados à geração de trabalho e renda, promovendo a emancipação cidadã, com foco no desenvolvimento socioeconômico local e regional.","V – F – F – V – F","F – F – V – V – V","F – V – F – V – V","F – V – V – F – V","V – V – F – F – F"],"correta":3,"explicacao":"Gabarito: <strong>F – V – F – V – V</strong>.","banca":"IF-MG","ano":2025,"temas_relacionados":["lei_11892_2008"]},{"id":3574499,"enunciado":"Com base na Lei nº 11.892, de 29 de dezembro de 2008, que institui a Rede Federal de Educação Profissional, Científica e Tecnológica e cria os Institutos Federais de Educação, Ciência e Tecnologia, é correto afirmar que NÃO constitui uma das finalidades ou características dos Institutos Federais, como o IFMG:","opcoes":["Promover a integração e a verticalização da educação básica, profissional e superior, otimizando a infraestrutura, os quadros de pessoal e os recursos de gestão.","Direcionar sua oferta educacional ao fortalecimento dos arranjos produtivos, sociais e culturais locais, com base em diagnósticos das potencialidades regionais.","Ofertar obrigatoriamente 50% das vagas para programas de pós-graduação stricto sensu, em todas as áreas do conhecimento.","Realizar e estimular a pesquisa aplicada, o empreendedorismo, o cooperativismo e o desenvolvimento científico e tecnológico.","Desenvolver e transferir tecnologias sociais, notadamente as voltadas à preservação do meio ambiente."],"correta":2,"explicacao":"Gabarito: <strong>Ofertar obrigatoriamente 50% das vagas para programas de pós-graduação stricto sensu, em todas as áreas do conhecimento.</strong>.","banca":"IF-MG","ano":2025,"temas_relacionados":["lei_11892_2008"]},{"id":3610509,"enunciado":"De acordo com a Lei nº 12.846/2013 – Lei Anticorrupção –, julgue o item a seguir.\n\n\n\n\nA incidência da Lei Anticorrupção é restrita aos atos praticados por agentes públicos no exercício das atividades públicas, estabelecendo formas de reparação aos danos causados ao erário.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":3610510,"enunciado":"De acordo com a Lei nº 12.846/2013 – Lei Anticorrupção –, julgue o item a seguir.\n\n\n\n\nA responsabilidade da pessoa jurídica por atos lesivos contra a Administração Pública independe da comprovação da existência de dolo ou culpa.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":3610511,"enunciado":"De acordo com a Lei nº 12.846/2013 – Lei Anticorrupção –, julgue o item a seguir.\n\n\n\n\nNa responsabilização administrativa da pessoa jurídica, a imposição de multa – no valor de 0,1% a 20% do faturamento bruto do último exercício anterior ao da instauração do processo administrativo, excluídos os tributos – que nunca será inferior à vantagem auferida, quando for possível a sua estimação, constitui espécie de sanção que pode ser aplicada às pessoas jurídicas.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":3610512,"enunciado":"De acordo com a Lei nº 12.846/2013 – Lei Anticorrupção –, julgue o item a seguir.\n\n\n\n\nA imposição de penalidade administrativa exclui a obrigação de reparação integral do dano causado pela pessoa jurídica.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":3610513,"enunciado":"De acordo com a Lei nº 12.846/2013 – Lei Anticorrupção –, julgue o item a seguir.\n\n\n\n\nAs sanções aplicadas às pessoas jurídicas serão aplicadas isoladamente, com a finalidade de preservar o nome e as atividades da pessoa jurídica.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":3632508,"enunciado":"Quanto à legislação e ética na Administração Pública, julgue o item a seguir. \n\nDe acordo com a legislação que regulamenta a responsabilização administrativa e civil de pessoas jurídicas pela prática de atos lesivos contra a Administração Pública, o programa de integridade da pessoa jurídica busca fomentar e manter uma cultura de integridade no ambiente organizacional.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":3632509,"enunciado":"Quanto à legislação e ética na Administração Pública, julgue o item a seguir. \n\nAcerca da legislação que regulamenta a responsabilização administrativa e civil de pessoas jurídicas pela prática de atos lesivos contra a administração pública, a avaliação do programa de integridade da pessoa jurídica levará em consideração os treinamentos e as ações de comunicação periódicos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":3632510,"enunciado":"Quanto à legislação e ética na Administração Pública, julgue o item a seguir. \n\nA apuração da responsabilidade administrativa de pessoa jurídica, decorrente do exercício do poder sancionador da Administração Pública, será efetuada exclusivamente por meio de processo administrativo de responsabilização.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":3632529,"enunciado":"À luz da Legislação Anticorrupção, julgue o item seguinte. \n\nSubsiste a responsabilidade da pessoa jurídica na hipótese de alteração contratual, transformação, incorporação, fusão ou cisão societária.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":3632530,"enunciado":"À luz da Legislação Anticorrupção, julgue o item seguinte. \n\nA responsabilização da pessoa jurídica exclui a responsabilidade individual dos seus dirigentes ou de qualquer pessoa natural coautora do ato ilícito.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":3632531,"enunciado":"À luz da Legislação Anticorrupção, julgue o item seguinte. \n\nConstitui ato lesivo à Administração Pública a manipulação do equilíbrio econômico‑financeiro dos contratos celebrados com a Administração Pública.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":3632532,"enunciado":"À luz da Legislação Anticorrupção, julgue o item seguinte. \n\nA instauração de processo administrativo específico de reparação integral do dano prejudica a aplicação imediata das sanções estabelecidas na Lei Anticorrupção.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":3632533,"enunciado":"À luz da Legislação Anticorrupção, julgue o item seguinte. \n\nNa esfera administrativa, a responsabilidade da pessoa jurídica afasta a possibilidade da sua responsabilização na esfera judicial.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":3632534,"enunciado":"À luz da Legislação Anticorrupção, julgue o item seguinte. \n\nNas penas aplicadas às pessoas jurídicas responsabilizadas por atos lesivos, previstos na Lei Anticorrupção, não se admite considerar a situação econômica do infrator.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":3638127,"enunciado":"A respeito da Lei nº 12.846/2013 – Lei Anticorrupção –, julgue o item seguinte.\n\n\n\n\nA fusão ou cisão societária da pessoa jurídica constitui hipótese de exclusão da responsabilidade da própria pessoa jurídica, que passará a recair exclusivamente sobre os sócios.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":3638128,"enunciado":"A respeito da Lei nº 12.846/2013 – Lei Anticorrupção –, julgue o item seguinte.\n\n\n\n\nO efeito negativo produzido pela infração é um dos elementos que será levado em consideração na aplicação das sanções às pessoas jurídicas.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":3638129,"enunciado":"A respeito da Lei nº 12.846/2013 – Lei Anticorrupção –, julgue o item seguinte.\n\n\n\n\nO processo administrativo para a apuração da responsabilidade de pessoa jurídica será conduzido por comissão designada pela autoridade instauradora e composta de dois ou mais servidores estáveis.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":3638130,"enunciado":"A respeito da Lei nº 12.846/2013 – Lei Anticorrupção –, julgue o item seguinte.\n\n\n\n\nA celebração do acordo de leniência suspende o prazo prescricional dos atos ilícitos praticados pela pessoa jurídica.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":3638131,"enunciado":"A respeito da Lei nº 12.846/2013 – Lei Anticorrupção –, julgue o item seguinte.\n\n\n\n\nNa esfera administrativa, a responsabilidade da pessoa jurídica não afasta a possibilidade de sua responsabilização na esfera judicial.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":3648752,"enunciado":"No âmbito da Rede Federal de Educação Profissional, Científica e Tecnológica, a Lei nº 11.892/2008 estabelece as finalidades e características que devem orientar a atuação dos Institutos Federais de Educação, Ciência e Tecnologia. Nesse contexto, tendo em vista os objetivos institucionais previstos na legislação, assinale a afirmativa correta.","opcoes":["Os Institutos Federais têm por finalidade prioritária a formação de profissionais voltados exclusivamente ao atendimento de demandas de nível nacional, devendo priorizar a integração com grandes centros industriais, em detrimento das demandas locais e regionais.","Os Institutos Federais devem restringir-se ao desenvolvimento de atividades de ensino técnico de nível médio, sendo vedada a atuação simultânea no ensino superior, na extensão e na pesquisa aplicada.","Os Institutos Federais devem promover a integração e a verticalização da educação básica, da educação profissional e da educação superior, de forma a otimizar os recursos físicos, humanos e de gestão, ampliando as possibilidades formativas.","Os Institutos Federais devem direcionar a sua oferta formativa exclusivamente para a área das ciências aplicadas, sendo proibida a inclusão de disciplinas voltadas ao desenvolvimento de espírito crítico e à investigação científica.","Os Institutos Federais devem desenvolver programas de extensão e pesquisa apenas quando diretamente vinculados a arranjos produtivos locais e regionais, sendo vedada a atuação em temas que não tenham aplicação econômica imediata."],"correta":2,"explicacao":"Gabarito: <strong>Os Institutos Federais devem promover a integração e a verticalização da educação básica, da educação profissional e da educação superior, de forma a otimizar os recursos físicos, humanos e de gestão, ampliando as possibilidades formativas.</strong>.","banca":"IDECAN","ano":2025,"temas_relacionados":["lei_11892_2008"]},{"id":3672931,"enunciado":"A Lei nº 11.892/2008 instituiu a Rede Federal de Educação Profissional, Científica e Tecnológica e criou os Institutos Federais de Educação, Ciência e Tecnologia (IFs). Considerando sua definição identitária, os IFs se constituem em instituições","opcoes":["interdisciplinares e multicampi, voltadas exclusivamente à formação técnica de nível médio em diferentes modalidades de ensino.","multicampi e pluricurriculares, especializadas na oferta de educação profissional e tecnológica em diferentes níveis e modalidades de ensino.","multidisciplinares e pluricurriculares, especializadas em cursos técnicos e superiores de tecnologia, com organização curricular voltada à formação para o mercado de trabalho.","multicampi e interdisciplinares, voltadas para a pesquisa acadêmica e para as formações técnicas e de pós-graduação stricto sensu.","pluricurriculares de ensino superior, com foco na formação profissional, podendo atuar na forma conveniada do ensino básico integrado ao profissional."],"correta":1,"explicacao":"Gabarito: <strong>multicampi e pluricurriculares, especializadas na oferta de educação profissional e tecnológica em diferentes níveis e modalidades de ensino.</strong>.","banca":"FUNCERN","ano":2025,"temas_relacionados":["lei_11892_2008"]},{"id":3689583,"enunciado":"Conforme a Lei Federal nº 11.892/2008, a escolha dos Diretores-Gerais dos campi dos Institutos Federais ocorre por meio de consulta à comunidade do respectivo campus. A participação dos segmentos da comunidade (corpo docente, servidores técnico-administrativos e corpo discente) no processo de consulta terá um","opcoes":["peso de 70% para docentes e 30% para técnicos e discentes.","peso proporcional ao número de membros de cada segmento na instituição.","peso igualitário de 1/3 para cada segmento.","peso de 50% para servidores (docentes e técnicos) e 50% para discentes.","peso definido de forma autônoma pelo Conselho Superior de cada Instituto Federal."],"correta":2,"explicacao":"Gabarito: <strong>peso igualitário de 1/3 para cada segmento.</strong>.","banca":"FUNCERN","ano":2025,"temas_relacionados":["lei_11892_2008"]},{"id":3697329,"enunciado":"Conforme a Lei nº 11.892/2008, o mandato do(a) Reitor(a) dos Institutos Federais será de ______ anos, _________________ recondução. Assinale a alternativa que preenche, correta e respectivamente, as lacunas do trecho acima.","opcoes":["2 – admitida","4 – admitida","5 – vedada","6 – admitida","4 – vedada"],"correta":1,"explicacao":"Gabarito: <strong>4 – admitida</strong>.","banca":"FUNDATEC","ano":2025,"temas_relacionados":["lei_11892_2008"]},{"id":3724344,"enunciado":"No que se refere à Lei nº 11.892/2008, que instituiu a Rede Federal de Educação Profissional, Científica e Tecnológica e criou os Institutos Federais de Educação, Ciência e Tecnologia, julgue as afirmativas abaixo como Verdadeiras (V) ou Falsas (F). ( ) Os Institutos Federais são instituições de educação superior, básica e profissional, pluricurriculares e multicampi, especializadas na oferta de educação profissional e tecnológica nas diferentes modalidades de ensino, com o objetivo de articular a educação profissional, científica e tecnológica com a formação de cidadãos. ( ) É obrigatório que os Institutos Federais tenham pelo menos 50% de suas matrículas destinadas à educação profissional técnica de nível médio, com o mínimo de 20% do total de vagas de seus cursos de graduação e pós-graduação sendo reservadas para a formação de professores para a educação básica. ( ) Os Institutos Federais de Educação, Ciência e Tecnologia possuem natureza jurídica de autarquia, são vinculados ao Ministério da Educação e Cultura e têm autonomia didático-pedagógica e financeira, mas dependem de aprovação externa para a criação de novos cursos. ( ) As matrículas nos cursos de pós-graduação stricto sensu, como mestrado e doutorado, devem ser destinadas, em sua totalidade, a estudos e pesquisas aplicados voltados para a inovação e o desenvolvimento de produtos, processos e serviços em áreas de conhecimento estratégicas. ( ) Entre as finalidades e características dos Institutos Federais, destaca-se a de ofertar educação profissional e tecnológica em todos os seus níveis e modalidades, formando e qualificando cidadãos com vistas à sua atuação profissional nos diversos setores da economia e com forte ênfase no desenvolvimento local e regional. A sequência correta é:","opcoes":["V, V, V, V, V.","V, V, F, F, V.","F, V, F, V, F.","F, F, V, V, F.","F, V, V, V, V."],"correta":1,"explicacao":"Gabarito: <strong>V, V, F, F, V.</strong>.","banca":"FUNDAÇÃO SOUSÂNDRADE","ano":2025,"temas_relacionados":["lei_11892_2008"]},{"id":3737946,"enunciado":"Os Institutos Federais de Educação, Ciência e Tecnologia, dentre eles o IFPA, foram criados pela Lei Federal nº 11.892 de 29 de dezembro de 2008. Considerando os objetivos dessas Instituições, é correto afirmar que:","opcoes":["Os Institutos Federais têm dentre seus objetivos a oferta de cursos em vários níveis de ensino, desde o Ensino Médio/Técnico até a Pós-graduação em nível de Mestrado Profissional, não tendo os IFs autorização legal para a oferta de cursos em nível de Doutorado;","Os Institutos Federais têm dentre seus objetivos a oferta em cada exercício, de no mínimo 15% (quinze por cento) de suas vagas, para cursos de licenciatura, bem como programas especiais de formação pedagógica;","Os Institutos Federais têm dentre seus objetivos a realização de pesquisa científica básica, estimulando o desenvolvimento de soluções técnicas e tecnológicas, estendendo seus benefícios à comunidade;","Os Institutos Federais têm dentre seus objetivos o desenvolvimento de programas de extensão e de divulgação científica e tecnológica;","Os Institutos Federais têm dentre seus objetivos a oferta de cursos de bacharelado e engenharia, visando à formação de profissionais para os diferentes setores da economia e áreas do conhecimento"],"correta":4,"explicacao":"Gabarito: <strong>Os Institutos Federais têm dentre seus objetivos a oferta de cursos de bacharelado e engenharia, visando à formação de profissionais para os diferentes setores da economia e áreas do conhecimento</strong>.","banca":"IF-PA","ano":2022,"temas_relacionados":["lei_11892_2008"]},{"id":3753151,"enunciado":"A Rede Federal de Educação Profissional, Científica e Tecnológica, instituída pela Lei Federal nº 11.892/2008, está presente em todos os estados do país, atendendo a diversos de seus municípios com educação pública, gratuita e de qualidade. Com base na referida legislação, essa rede educacional integra:","opcoes":["Os sistemas federal e estadual de ensino.","O sistema municipal de ensino.","Os sistemas federal, estadual e municipal de ensino.","O sistema estadual de ensino.","O sistema federal de ensino."],"correta":4,"explicacao":"Gabarito: <strong>O sistema federal de ensino.</strong>.","banca":"IF-MT","ano":2025,"temas_relacionados":["lei_11892_2008"]},{"id":3760811,"enunciado":"Nos termos da Lei n° 11.892/08, a mudança de lotação de servidores entre diferentes campi de um mesmo Instituto Federal deverá observar o instituto da  __________. Assinale a alternativa que preenche CORRETAMENTE a lacuna:","opcoes":["redistribuição.","remoção.","recondução.","readaptação.","promoção."],"correta":1,"explicacao":"Gabarito: <strong>remoção.</strong>.","banca":"IF-MT","ano":2023,"temas_relacionados":["lei_11892_2008"]},{"id":3771959,"enunciado":"Com base na Lei 11.892/2008, analise as afirmativas a seguir: I. A reitoria, como órgão de administração central, poderá ser instalada em espaço físico distinto de qualquer dos campi que integram o Instituto Federal, desde que previsto em seu estatuto e aprovado pelo Ministério da Educação. II. O estatuto do Instituto Federal disporá sobre a estruturação, as competências e as normas de funcionamento do Colégio de Dirigentes e do Conselho Superior. III. Poderão ser nomeados Pró-Reitores os servidores ocupantes de cargo efetivo da Carreira docente ou de cargo efetivo com nível superior da Carreira dos técnicoadministrativos do Plano de Carreira dos Cargos TécnicoAdministrativos em Educação, desde que possuam o mínimo de 5 (cinco) anos de efetivo exercício em instituição federal de educação profissional e tecnológica. Assinale","opcoes":["se apenas as afirmativas I e II estiverem corretas","se apenas as afirmativas I e III estiverem corretas.","se apenas as afirmativas II e III estiverem corretas.","se todas as afirmativas estiverem corretas."],"correta":3,"explicacao":"Gabarito: <strong>se todas as afirmativas estiverem corretas.</strong>.","banca":"IDECAN","ano":2021,"temas_relacionados":["lei_11892_2008"]},{"id":3781665,"enunciado":"A Lei n. 11.892/2008 estabelece as diretrizes para a organização e funcionamento dos Institutos Federais de Educação, Ciência e Tecnologia. Dentre suas características, destaca-se a integração entre diferentes níveis e modalidades de ensino, visando a uma formação abrangente e contextualizada. De acordo com o documento legal, os Institutos Federais devem orientar suas ações para integração e verticalização da educação básica, profissional e superior. Assinale a alternativa que apresenta corretamente uma das formas de atuação para alcançar essa integração.","opcoes":["Priorizar a oferta de cursos de pós-graduação stricto sensu, desvinculados da educação profissional e tecnológica, para fomentar a pesquisa acadêmica pura.","Desenvolver programas de extensão e de divulgação científica e tecnológica, com foco exclusivo na comunidade acadêmica interna.","Limitar a oferta de cursos de formação inicial e continuada de trabalhadores, a fim de concentrar recursos nos cursos de graduação.","Oferecer educação profissional técnica de nível médio, prioritariamente na forma integrada, para concluintes do ensino fundamental."],"correta":3,"explicacao":"Gabarito: <strong>Oferecer educação profissional técnica de nível médio, prioritariamente na forma integrada, para concluintes do ensino fundamental.</strong>.","banca":"IF-SP","ano":2025,"temas_relacionados":["lei_11892_2008"]},{"id":3875152,"enunciado":"A Lei nº 11.892/2008 institui a Rede Federal de Educação Profissional, Científica e Tecnológica e cria os Institutos Federais de Educação, Ciência e Tecnologia. Com base no conteúdo desta Lei, é correto afirmar que os Institutos Federais","opcoes":["possuem natureza jurídica de empresa pública.","terão seus Reitores e Pró-reitores nomeados pelo Presidente da República, para mandato de 4 (quatro) anos.","detêm autonomia didático-pedagógica e disciplinar e possuem vinculação administrativa, patrimonial e financeira a outros órgãos.","têm por finalidade realizar pesquisas aplicadas, estimulando o desenvolvimento de soluções técnicas e tecnológicas, restringindo seus benefícios à Indústria e comércio.","terão autonomia para criar e extinguir cursos, nos limites de sua área de atuação territorial, bem como para registrar diplomas dos cursos por eles oferecidos, mediante autorização do seu Conselho Superior, aplicando-se, no caso da oferta de cursos a distância, a legislação específica."],"correta":4,"explicacao":"Gabarito: <strong>terão autonomia para criar e extinguir cursos, nos limites de sua área de atuação territorial, bem como para registrar diplomas dos cursos por eles oferecidos, mediante autorização do seu Conselho Superior, aplicando-se, no caso da oferta de cursos a distância, a legislação específica.</strong>.","banca":"FCM","ano":2026,"temas_relacionados":["lei_11892_2008"]},{"id":3891015,"enunciado":"No que concerne à Lei nº 11.892, de 29 de dezembro de 2008, que institui a Rede Federal de Educação Profissional, Científica e Tecnológica, analise as assertivas abaixo. I. A criação dos Institutos Federais de Educação, Ciência e Tecnologia resultou da transformação de Escolas Técnicas e Agrotécnicas Federais, bem como de Centros Federais de Educação Tecnológica, com a finalidade de constituir a nova rede federal. II. Os Institutos Federais têm por objetivo ministrar educação profissional técnica de nível médio, prioritariamente na forma de cursos integrados, mas não têm autonomia para oferecer cursos de pós-graduação stricto sensu. III. Os bens e direitos dos Institutos Federais serão utilizados ou aplicados, exclusivamente, para a consecução de seus objetivos, não podendo ser alienados, independentemente do contexto. IV. Os Institutos Federais possuem autonomia didático-pedagógica, administrativa e de gestão financeira e patrimonial. Está correto o que se afirma em:","opcoes":["II, III e IV.","I, II e III.","I e IV.","III e IV.","I, II, III e IV."],"correta":2,"explicacao":"Gabarito: <strong>I e IV.</strong>.","banca":"FUNDAÇÃO SOUSÂNDRADE","ano":2025,"temas_relacionados":["lei_11892_2008"]},{"id":3891621,"enunciado":"Considerando o que dispõe a Lei n. 11.892/2008, que Institui a Rede Federal de Edu cação Profissional, Científica e Tecnológica, cria os Institutos Federais de Educação, Ciência e Tecnologia, e dá outras providências, é correto afimar:","opcoes":["A Lei extinguiu todos os Centros Federais de Educação Tecnológica.","A Universidade Tecnológica Federal do Paraná compõe a Rede Federal de Educação Profissional, Científica e Tecnológica.","Não há previsão de Escolas Técnicas Vinculadas às Universidades Federais.","O Colégio Pedro II foi transformado em Instituto Federal com sede no Rio de Janeiro."],"correta":1,"explicacao":"Gabarito: <strong>A Universidade Tecnológica Federal do Paraná compõe a Rede Federal de Educação Profissional, Científica e Tecnológica.</strong>.","banca":"IF-SP","ano":2026,"temas_relacionados":["lei_11892_2008"]},{"id":3972349,"enunciado":"Observe os itens abaixo, que dizem respeito sobre as finalidades e características dos Institutos Federais, descritos na Lei Nº 11.892, de 29 de dezembro de 2008: I – ofertar educação profissional e tecnológica, em todos os seus níveis e modalidades, formando e qualificando profissionais com vistas na atuação profissional nos seguimento técnico e tecnológico da economia, com ênfase no desenvolvimento socioeconômico local, regional e nacional; II – desenvolver a educação profissional e tecnológica como processo educativo e investigativo de geração e adaptação de soluções técnicas e tecnológicas às demandas sociais e peculiaridades regionais; III – promover a integração e a horizontalizarão da educação básica à educação profissional e educação superior, otimizando a base de conhecimentos, os quadros de pessoal e o desenvolvimento nacional; IV – orientar sua oferta formativa em benefício da consolidação e fortalecimento dos arranjos produtivos, sociais e culturais locais, identificados com base no mapeamento das potencialidades de desenvolvimento socioeconômico e cultural no âmbito de atuação do Instituto Federal; Dos itens anteriores, aponte qual(ais) está(ão) correto(s):","opcoes":["I, II e IV.","I e IV.","I, II e III.","II e IV."],"correta":3,"explicacao":"Gabarito: <strong>II e IV.</strong>.","banca":"IF-SP","ano":2022,"temas_relacionados":["lei_11892_2008"]},{"id":3972369,"enunciado":"O Instituto Federal de Educação, Ciência e Tecnologia de São Paulo (IFSP) tem por missão “Ofertar educação profissional, científica e tecnológica orientada por uma práxis educativa que efetive a formação integral e contribua para a inclusão social, o desenvolvimento regional, a produção e a socialização do conhecimento”. Considerando a Lei nº 11.892, de 29/12/2008, que institui a Rede Federal de Educação Profissional, Científica e Tecnológica e cria os Institutos Federais de Educação, Ciência e Tecnologia, é correto o que se afirma em:","opcoes":["Os Institutos Federais são instituições de educação superior, básica e profissional, pluricurriculares e multicampi, especializados na oferta de educação profissional e tecnológica nas diferentes modalidades de ensino, com base na conjugação de conhecimentos técnicos e tecnológicos com as suas práticas pedagógicas.","Os Institutos Federais são instituições de educação básica e profissional, voltada somente a cursos técnicos.","Os Institutos Federais são instituições de educação superior, sendo ofertados somente cursos de graduação e pós-graduação.","Os Institutos Federais são instituições de educação tecnológica, voltado somente a formar tecnólogos para a indústria tecnológica."],"correta":0,"explicacao":"Gabarito: <strong>Os Institutos Federais são instituições de educação superior, básica e profissional, pluricurriculares e multicampi, especializados na oferta de educação profissional e tecnológica nas diferentes modalidades de ensino, com base na conjugação de conhecimentos técnicos e tecnológicos com as suas práticas pedagógicas.</strong>.","banca":"IF-SP","ano":2022,"temas_relacionados":["lei_11892_2008"]},{"id":3972370,"enunciado":"O Instituto Federal de Educação, Ciência e Tecnologia de São Paulo possui o Conselho Superior – CONSUP, que é um órgão colegiado que tem por finalidade analisar e regular as diretrizes de atuação do Instituto Federal de São Paulo, no âmbito acadêmico e administrativo, tendo como finalidade o processo educativo de excelência. Considerando a Lei nº 11.892, de 29/12/2008, que institui a Rede Federal de Educação Profissional, Científica e Tecnológica e designa a criação do Conselho Superior, é correto o que se afirma em:","opcoes":["O Conselho Superior é um órgão de caráter somente consultivo, será composto somente pelo Reitor, pelos Pró-Reitores e pelo Diretor-Geral de cada um dos campi que integram o Instituto Federal.","O Conselho Superior, de caráter consultivo e deliberativo, será composto por representantes dos docentes, dos estudantes, dos servidores técnico-administrativos, dos egressos da instituição, da sociedade civil, do Ministério da Educação e do Colégio de Dirigentes do Instituto Federal, assegurando-se a representação paritária dos segmentos que compõem a comunidade acadêmica.","Poderão candidatar-se a presidente do Conselho Superior os docentes pertencentes ao Quadro de Pessoal Ativo Permanente de qualquer dos campi que integram o Instituto Federal, desde que possuam o mínimo de 10 (dez) anos de efetivo exercício em instituição federal de educação profissional e tecnológica e que possuem o título de doutor.","Visando à autonomia do Conselho Superior, o reitor não poderá presidi-lo, devendo realizar uma eleição em sua comunidade para a escolha do presidente do conselho."],"correta":1,"explicacao":"Gabarito: <strong>O Conselho Superior, de caráter consultivo e deliberativo, será composto por representantes dos docentes, dos estudantes, dos servidores técnico-administrativos, dos egressos da instituição, da sociedade civil, do Ministério da Educação e do Colégio de Dirigentes do Instituto Federal, assegurando-se a representação paritária dos segmentos que compõem a comunidade acadêmica.</strong>.","banca":"IF-SP","ano":2022,"temas_relacionados":["lei_11892_2008"]},{"id":3972371,"enunciado":"Conforme a Portaria nº 2.968/2015/IFSP: “As ações de extensão são uma via de mão dupla com a sociedade, que proporciona a relação de diálogo entre conhecimentos acadêmicos e conhecimentos tradicionais, enriquecendo o processo educativo e possibilitando a formação de consciência crítica tanto da comunidade interna do IFSP (docentes, discentes e técnicos-administrativos), quanto dos diversos atores sociais envolvidos”. Considerando a Lei nº 11.892, de 29/12/2008, que institui a Rede Federal de Educação Profissional, Científica e Tecnológica, em relação aos objetivos dos Institutos Federais no que tange as atividades de extensão, é correto o que se afirma em:","opcoes":["As atividades de extensão somente poderão ser ministradas em nível de educação superior, exclusivamente para cursos de licenciatura.","Desenvolver atividades de extensão de acordo com os princípios e finalidades da educação profissional e tecnológica, em articulação com o mundo do trabalho e os segmentos sociais, e com ênfase na produção, desenvolvimento e difusão de conhecimentos científicos e tecnológicos.","As atividades de extensão somente poderão ser ministradas em cursos de pós-graduação strictu sensu e lato sensu, exclusivamente voltados a cursos tecnológicos.","Desenvolver atividades de extensão de acordo com os princípios e finalidades da educação profissional e tecnológica, em articulação com o mundo do trabalho e os segmentos sociais. Além disso, somente poderão ser ministradas em cursos técnicos."],"correta":1,"explicacao":"Gabarito: <strong>Desenvolver atividades de extensão de acordo com os princípios e finalidades da educação profissional e tecnológica, em articulação com o mundo do trabalho e os segmentos sociais, e com ênfase na produção, desenvolvimento e difusão de conhecimentos científicos e tecnológicos.</strong>.","banca":"IF-SP","ano":2022,"temas_relacionados":["lei_11892_2008"]},{"id":3972623,"enunciado":"Com base na Lei Nº 11.892, de 29 de dezembro de 2008, marque a alternativa que NÃO indica uma das finalidades da Rede Federal de Educação Profissional, Científica e Tecnológica:","opcoes":["promover a produção, o desenvolvimento e a transferência de tecnologiassociais, notadamente as voltadas à preservação do meio ambiente","constituir-se em centro de referência na produção de tecnológica, em geral, e, estimulando o desenvolvimento de espírito competitivo na formação profissional.","realizar e estimular a pesquisa aplicada, a produção cultural, o empreendedorismo, o cooperativismo e o desenvolvimento científico e tecnológico.","desenvolver programas de extensão e de divulgação científica e tecnológica."],"correta":1,"explicacao":"Gabarito: <strong>constituir-se em centro de referência na produção de tecnológica, em geral, e, estimulando o desenvolvimento de espírito competitivo na formação profissional.</strong>.","banca":"IF-SP","ano":2022,"temas_relacionados":["lei_11892_2008"]},{"id":3972697,"enunciado":"Com base na Lei Nº 11.892, de 29 de dezembro de 2008, marque a alternativa que NÂO indica uma das finalidades da Rede Federal de Educação Profissional, Científica e Tecnológica:","opcoes":["promover a produção, o desenvolvimento e a transferência de tecnologiassociais, notadamente as voltadas à preservação do meio ambiente.","constituir-se em centro de referência na produção de tecnológica, em geral, e, estimulando o desenvolvimento de espírito competitivo na formação profissional.","realizar e estimular a pesquisa aplicada, a produção cultural, o empreendedorismo, o cooperativismo e o desenvolvimento científico e tecnológico.","desenvolver programas de extensão e de divulgação científica e tecnológica."],"correta":1,"explicacao":"Gabarito: <strong>constituir-se em centro de referência na produção de tecnológica, em geral, e, estimulando o desenvolvimento de espírito competitivo na formação profissional.</strong>.","banca":"IF-SP","ano":2022,"temas_relacionados":["lei_11892_2008"]},{"id":3978565,"enunciado":"A Lei Federal nº 11.892/2008, que institui a Rede Federal de Educação Profissional, Científica e Tecnológica, define os objetivos, finalidades, características e estrutura organizacional dos Institutos Federais de Educação, Ciência e Tecnologia. No que tange ao desenvolvimento das suas ações acadêmicas, os Institutos Federais têm como objetivo:","opcoes":["Ministrar cursos de licenciatura, bem como programas especiais de formação pedagógica, com vistas à formação de professores para a Educação Básica, sobretudo nas áreas de Ciências e Matemática, e para a Educação Profissional, garantindo o mínimo de 20% (vinte por cento) de suas vagas para essa modalidade de cursos em cada exercício.","Ministrar cursos de nível superior de Tecnologia visando à formação de profissionais para os diferentes setores da economia, garantindo o mínimo de 50% (cinquenta por cento) de suas vagas para essa modalidade de cursos em cada exercício.","Ministrar Educação Profissional Técnica de Nível Médio, prioritariamente na forma de cursos integrados, para os concluintes do Ensino Fundamental e para o público da Educação de Jovens e Adultos, garantindo o mínimo de 20% (vinte por cento) de suas vagas para essa modalidade de cursos em cada exercício.","Ministrar cursos de Pós-graduação Lato Sensu, de Aperfeiçoamento e de Especialização visando à formação de especialistas nas diferentes áreas do conhecimento, garantindo o mínimo de 30% (trinta por cento) de suas vagas para essa modalidade de cursos em cada exercício."],"correta":0,"explicacao":"Gabarito: <strong>Ministrar cursos de licenciatura, bem como programas especiais de formação pedagógica, com vistas à formação de professores para a Educação Básica, sobretudo nas áreas de Ciências e Matemática, e para a Educação Profissional, garantindo o mínimo de 20% (vinte por cento) de suas vagas para essa modalidade de cursos em cada exercício.</strong>.","banca":"IF-SP","ano":2022,"temas_relacionados":["lei_11892_2008"]},{"id":3987160,"enunciado":"A respeito do Estatuto do Instituto Federal de Educação, Ciência e Tecnologia da Paraíba, informe se é verdadeiro (V) ou falso (F) o que se afirma a seguir e assinale a alternativa com a sequência correta. (   ) Para efeito da incidência das disposições que regem a regulação, a avaliação e a supervisão da instituição e dos cursos de educação superior, o IFPB não pode ser equiparado às universidades federais. (   ) São órgãos gerais e sistêmicos do IFPB o Conselho Superior, o Colégio de Dirigentes e a Reitoria. (   ) Somente os estudantes com matrícula regular ativa nos cursos técnicos de nível médio, de graduação ou de pós-graduação poderão votar e serem votados para as representações estudantis do Conselho Superior, do CEPE - IFPB e do COPAF-IFPB. (   ) O IFPB não poderá admitir, sem vínculo empregatício, estudantes de cursos nas funções de monitor.","opcoes":["V – V – F – F.","F – V – F – V.","F – V – V – F.","V – F – V – V.","F – F – F – F."],"correta":2,"explicacao":"Gabarito: <strong>F – V – V – F.</strong>.","banca":"INSTITUTO AOCP","ano":2025,"temas_relacionados":["lei_11892_2008"]},{"id":4009705,"enunciado":"No que se refere à contratação de bens e serviços, julgue o item seguinte, de acordo com a Lei n.º 14.133/2021 e a IN n.º 5/2017 da Secretaria de Gestão do Ministério do Planejamento, Desenvolvimento e Gestão. \n\n\n\n\nConforme as disposições contidas na IN n.º 5/2017, não configura ato de ingerência da administração pública exercer o poder de mando sobre os empregados da contratada quando o objeto da contratação previr a notificação direta para a execução de tarefas previamente descritas no contrato de prestação de serviços para determinada função específica, como recepção e apoio administrativo.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2026,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":4026074,"enunciado":"Considerando as disposições da Lei nº 11.892/2008, que trata da Rede Federal de Educação Profissional, Científica e Tecnológica, assinale a alternativa INCORRETA sobre os Institutos Federais.","opcoes":["São instituições de Educação Superior Básica e Profissional pluricurriculares e multicampi, especializadas na oferta de Educação Profissional e Tecnológica.","Sua administração tem como órgãos superiores o Colégio de Dirigentes e o Conselho Superior.","Uma de suas finalidades é desenvolver programas de extensão e de divulgação científica e tecnológica.","Priorizam a educação à distância para que todas as pessoas possam ter acesso ao conhecimento.","Têm como órgão executivo a Reitoria, composta por um reitor e cinco pró-reitores."],"correta":3,"explicacao":"Gabarito: <strong>Priorizam a educação à distância para que todas as pessoas possam ter acesso ao conhecimento.</strong>.","banca":"FUNDATEC","ano":2026,"temas_relacionados":["lei_11892_2008"]},{"id":4026356,"enunciado":"Nos termos da Lei nº 11.892/2008, os Reitores dos Institutos Federais serão nomeados","opcoes":["pelo Presidente do Colégio de Dirigentes, para mandato de quatro anos, permitida uma recondução.","pelo Presidente do Conselho Superior, para mandato de quatro anos, vedada a recondução.","pelo Presidente da República, para mandato de quatro anos, permitida uma recondução.","pelo Pró-Reitor, para mandato de quatro anos, permitida uma recondução.","pelo Diretor-Geral do campus, para mandato de quatro anos, vedada a recondução."],"correta":2,"explicacao":"Gabarito: <strong>pelo Presidente da República, para mandato de quatro anos, permitida uma recondução.</strong>.","banca":"INSTITUTO AOCP","ano":2026,"temas_relacionados":["lei_11892_2008"]},{"id":4026665,"enunciado":"A Lei nº 11.892/2008 conferiu aos Institutos Federais de Educação, Ciência e Tecnologia (IFs) uma identidade institucional singular no campo da educação brasileira, diferenciando-os tanto das universidades federais quanto dos Centros Federais de Educação Tecnológica (CEFETs). Um docente concursado para um IF, ao analisar o modelo institucional previsto em lei, identifica que sua instituição possui características jurídicas, administrativas e pedagógicas específicas. Considerando a natureza jurídica, a estrutura organizacional e as finalidades dos IFs estabelecidas pela Lei nº 11.892/2008, assinale a alternativa correta.","opcoes":["Os IFs possuem natureza jurídica de fundação pública de direito privado, o que lhes confere autonomia plena de gestão financeira e administrativa, desvinculando-os da supervisão do Ministério da Educação.","Por deterem autonomia didático-pedagógica equivalente à das universidades federais, os IFs podem definir livremente sua organização curricular sem necessidade de observância às Diretrizes Curriculares Nacionais para a Educação Profissional e Tecnológica.","A equivalência de tratamento entre IFs e universidades federais, prevista na Lei nº 11.892/2008, implica que os IFs devem destinar ao menos 75% de suas vagas a cursos de graduação e pós-graduação, em detrimento da oferta de educação técnica de nível médio.","Os IFs são autarquias vinculadas exclusivamente aos respectivos sistemas estaduais de ensino, cabendo ao Ministério da Educação apenas a função de financiamento, sem poderes de supervisão ou regulação sobre suas atividades acadêmicas.","Os IFs possuem natureza jurídica de autarquia federal, com autonomia administrativa, patrimonial, financeira, didático-pedagógica e disciplinar, e detêm, para fins da incidência das disposições que regem a regulação, avaliação e supervisão das instituições e dos cursos de educação superior, tratamento equivalente ao das universidades federais."],"correta":4,"explicacao":"Gabarito: <strong>Os IFs possuem natureza jurídica de autarquia federal, com autonomia administrativa, patrimonial, financeira, didático-pedagógica e disciplinar, e detêm, para fins da incidência das disposições que regem a regulação, avaliação e supervisão das instituições e dos cursos de educação superior, tratamento equivalente ao das universidades federais.</strong>.","banca":"FUNDATEC","ano":2026,"temas_relacionados":["lei_11892_2008"]},{"id":4027986,"enunciado":"Um docente EBTT de um IF, ao elaborar seu Plano Individual de Trabalho (PIT) semestral, distribui sua carga horária da seguinte forma: 80% para atividades de ensino em sala de aula, 10% para orientação de TCCs e 10% para participação em eventos científicos como ouvinte. Ao apresentar o PIT ao Departamento de Ensino, a coordenação pedagógica questiona a ausência de projetos de pesquisa e extensão formalmente cadastrados. O docente argumenta que suas atividades de ensino já incorporam elementos de pesquisa e extensão de forma implícita, tornando desnecessário o cadastramento formal. Considerando o princípio da indissociabilidade entre ensino, pesquisa e extensão nos IFs, previsto na Lei nº 11.892/2008 e nas diretrizes institucionais, assinale a alternativa correta.","opcoes":["O argumento do docente é juridicamente válido, pois a Lei nº 11.892/2008 não exige o cadastramento formal de projetos de pesquisa e extensão, bastando que o docente demonstre, no relatório anual de atividades, que desenvolveu essas dimensões de forma integrada ao ensino.","A coordenação pedagógica age corretamente ao questionar o PIT, pois a indissociabilidade entre ensino, pesquisa e extensão nos IFs pressupõe a articulação intencional e planejada dessas três dimensões, o que implica o desenvolvimento de projetos formalmente institucionalizados e registrados nos sistemas acadêmicos da instituição.","A participação em eventos científicos como ouvinte equivale ao desenvolvimento de pesquisa institucional, razão pela qual o PIT está adequadamente estruturado, atendendo ao princípio da indissociabilidade sem necessidade de ajustes.","O princípio da indissociabilidade entre ensino, pesquisa e extensão aplica-se exclusivamente aos IFs que ofertam cursos de pós-graduação stricto sensu, não sendo exigível de docentes que atuam apenas no ensino médio integrado ou na graduação tecnológica.","O PIT está adequado à legislação federal, pois a carga horária de ensino pode representar até 100% das atividades docentes nos IFs, sendo a pesquisa e a extensão atividades complementares de adesão voluntária, sem obrigatoriedade institucional."],"correta":1,"explicacao":"Gabarito: <strong>A coordenação pedagógica age corretamente ao questionar o PIT, pois a indissociabilidade entre ensino, pesquisa e extensão nos IFs pressupõe a articulação intencional e planejada dessas três dimensões, o que implica o desenvolvimento de projetos formalmente institucionalizados e registrados nos sistemas acadêmicos da instituição.</strong>.","banca":"FUNDATEC","ano":2026,"temas_relacionados":["lei_11892_2008"]},{"id":4031769,"enunciado":"Considerando a Lei nº 11.892/2008, quanto às finalidades e às características dos Institutos Federais, analise as assertivas abaixo e assinale a INCORRETA:","opcoes":["Os Institutos Federais devem ofertar educação profissional e tecnológica, em todos os seus níveis e modalidades, formando e qualificando cidadãos com vistas na atuação profissional nos diversos setores da economia, com ênfase no desenvolvimento socioeconômico local, regional e nacional.","Cabe aos Institutos Federais a promoção do desenvolvimento da educação profissional e tecnológica como processo educativo e investigativo de geração e adaptação de soluções técnicas e tecnológicas às demandas sociais e peculiaridades regionais.","Os Institutos Federais devem promover a integração e a horizontalização da educação básica, da educação profissional e da educação superior, fortalecendo o uso da infra-estrutura física, dos quadros de pessoal e dos recursos de gestão.","Cabe aos Institutos Federais orientar sua oferta formativa em benefício da consolidação e fortalecimento dos arranjos produtivos, sociais e culturais locais, identificados com base no mapeamento das potencialidades de desenvolvimento socioeconômico e cultural no âmbito de atuação do Instituto Federal.","Os Institutos Federais devem realizar e estimular a pesquisa aplicada, a produção cultural, o empreendedorismo, o cooperativismo e o desenvolvimento científico e tecnológico."],"correta":2,"explicacao":"Gabarito: <strong>Os Institutos Federais devem promover a integração e a horizontalização da educação básica, da educação profissional e da educação superior, fortalecendo o uso da infra-estrutura física, dos quadros de pessoal e dos recursos de gestão.</strong>.","banca":"IFMG","ano":2026,"temas_relacionados":["lei_11892_2008"]},{"id":4085569,"enunciado":"Considerando os Institutos Federais de Educação, Ciência e Tecnologia, parte da Rede Federal de Educação Profissional, Científica e Tecnológica, assinale a alternativa que apresenta uma de suas finalidades e características.","opcoes":["Ofertar educação profissional e tecnológica, em todos os seus níveis e modalidades, formando e qualificando cidadãos com vistas na atuação profissional nos diversos setores científicos, com ênfase no desenvolvimento técnico local, regional e nacional.","Ofertar educação profissional e tecnológica, em todos os seus níveis e modalidades, formando e qualificando cidadãos com vistas na atuação profissional nos diversos setores ligados ao empreendedorismo, com ênfase na promoção do empreendedorismo local, regional e nacional.","Ofertar educação profissional e tecnológica, em todos os seus níveis e modalidades, formando e qualificando cidadãos com vistas na atuação profissional nos diversos setores do cooperativismo, com ênfase na promoção do sistema cooperativista local, regional e nacional.","Ofertar educação profissional e tecnológica, em todos os seus níveis e modalidades, formando e qualificando cidadãos com vistas na atuação profissional nos diversos setores da cultura, com ênfase no desenvolvimento cultural local, regional e nacional.","Ofertar educação profissional e tecnológica, em todos os seus níveis e modalidades, formando e qualificando cidadãos com vistas na atuação profissional nos diversos setores da economia, com ênfase no desenvolvimento socioeconômico local, regional e nacional."],"correta":4,"explicacao":"Gabarito: <strong>Ofertar educação profissional e tecnológica, em todos os seus níveis e modalidades, formando e qualificando cidadãos com vistas na atuação profissional nos diversos setores da economia, com ênfase no desenvolvimento socioeconômico local, regional e nacional.</strong>.","banca":"INSTITUTO AOCP","ano":2026,"temas_relacionados":["lei_11892_2008"]},{"id":4085830,"enunciado":"A Lei nº 11.892/2008 institui a Rede Federal de Educação Profissional, Científica e Tecnológica, cria os Institutos Federais de Educação, Ciência e Tecnologia. Na forma da citada lei, a constituição do patrimônio de cada um dos novos Institutos Federais se dará, EXCETO","opcoes":["pelas doações que vier a receber","pelos bens e direitos que vier a adquirir.","pelas incorporações que resultem de serviços prestados pela instituição.","pela incorporação com reserva dos bens das instituições que o integram.","pelos legados que vier a receber."],"correta":3,"explicacao":"Gabarito: <strong>pela incorporação com reserva dos bens das instituições que o integram.</strong>.","banca":"INSTITUTO AOCP","ano":2026,"temas_relacionados":["lei_11892_2008"]},{"id":4085831,"enunciado":"Ivo é servidor efetivo de nível superior da carreira dos técnico-administrativos em uma instituição de ensino submetida à Lei nº 11.892/2008 e pretende se candidatar ao cargo de Diretor-Geral do campus onde atua. À luz da Lei nº 11.892/2008, é correto afirmar que","opcoes":["Ivo não poderá se candidatar, isso porque a função de Diretor-Geral é exclusiva para ocupantes do cargo de docente.","Ivo pode se candidatar se possuir no mínimo cinco anos de efetivo exercício em instituição federal de educação profissional e tecnológica e cumprir os demais requisitos legais.","Ivo não poderá se candidatar, tendo em vista que, além de restrita aos docentes, a função de DiretorGeral é suprida mediante indicação do Reitor da instituição de ensino.","Ivo poderá se candidatar, no entanto a comprovação de realização de curso de formação para o exercício de cargo ou função de gestão em instituições da administração pública é obrigatória.","Ivo poderá se candidatar, no entanto a comprovação de realização de curso de formação para o exercício de cargo ou função de gestão em instituições da administração pública é obrigatória."],"correta":1,"explicacao":"Gabarito: <strong>Ivo pode se candidatar se possuir no mínimo cinco anos de efetivo exercício em instituição federal de educação profissional e tecnológica e cumprir os demais requisitos legais.</strong>.","banca":"INSTITUTO AOCP","ano":2026,"temas_relacionados":["lei_11892_2008"]},{"id":4087842,"enunciado":"A Lei nº 11.892/2008 institui a Rede Federal de Educação Profissional, Científica e Tecnológica, cria os Institutos Federais de Educação, Ciência e Tecnologia. Na forma da citada lei, a constituição do patrimônio de cada um dos novos Institutos Federais se dará, EXCETO","opcoes":["pelas doações que vier a receber.","pelos bens e direitos que vier a adquirir.","pelas incorporações que resultem de serviços prestados pela instituição.","pela incorporação com reserva dos bens das instituições que o integram.","pelos legados que vier a receber."],"correta":3,"explicacao":"Gabarito: <strong>pela incorporação com reserva dos bens das instituições que o integram.</strong>.","banca":"INSTITUTO AOCP","ano":2026,"temas_relacionados":["lei_11892_2008"]},{"id":4087843,"enunciado":"Ivo é servidor efetivo de nível superior da carreira dos técnico-administrativos em uma instituição de ensino submetida à Lei nº 11.892/2008 e pretende se candidatar ao cargo de Diretor-Geral do campus onde atua. À luz da Lei nº 11.892/2008, é correto afirmar que","opcoes":["Ivo não poderá se candidatar, isso porque a função de Diretor-Geral é exclusiva para ocupantes do cargo de docente","Ivo pode se candidatar se possuir no mínimo cinco anos de efetivo exercício em instituição federal de educação profissional e tecnológica e cumprir os demais requisitos legais.","Ivo não poderá se candidatar, tendo em vista que, além de restrita aos docentes, a função de DiretorGeral é suprida mediante indicação do Reitor da instituição de ensino.","Ivo poderá se candidatar, no entanto a comprovação de realização de curso de formação para o exercício de cargo ou função de gestão em instituições da administração pública é obrigatória.","Ivo deverá demonstrar que possui os requisitos exigidos para candidatura ao cargo de Reitor e o exercício por no mínimo dois anos em cargo ou gestão na instituição."],"correta":1,"explicacao":"Gabarito: <strong>Ivo pode se candidatar se possuir no mínimo cinco anos de efetivo exercício em instituição federal de educação profissional e tecnológica e cumprir os demais requisitos legais.</strong>.","banca":"INSTITUTO AOCP","ano":2026,"temas_relacionados":["lei_11892_2008"]},{"id":4088955,"enunciado":"Acerca das disposições da Lei nº 11.892/2008, que institui a Rede Federal de Educação Profissional, Científica e Tecnológica, cria os Institutos Federais de Educação, Ciência e Tecnologia, assinale a alternativa correta.","opcoes":["Pode haver a concessão de bolsas de pesquisa, de desenvolvimento e de inovação, em favor dos alunos e docentes do respectivo Instituto Federal, vedada a concessão aos pesquisadores externos.","Para a concessão de bolsas de pesquisa, exige-se regulamentação editada e devidamente publicada pelo próprio Instituto Federal, através de seu conselho superior ou reitoria.","Há vedação expressa da concessão de bolsa de intercâmbio, considerando que essa modalidade não agrega valor direto ao ensino.","É discricionária a competência dos Institutos Federais para concessão de bolsas de pesquisa, de desenvolvimento e de inovação.","Veda-se expressamente a concessão de bolsas de desenvolvimento e de inovação aos detentores de emprego público, considerando que, nesses casos, o vínculo institucional é precário."],"correta":3,"explicacao":"Gabarito: <strong>É discricionária a competência dos Institutos Federais para concessão de bolsas de pesquisa, de desenvolvimento e de inovação.</strong>.","banca":"INSTITUTO AOCP","ano":2026,"temas_relacionados":["lei_11892_2008"]},{"id":4088956,"enunciado":"Considere que um Instituto Federal de determinada unidade da Federação pretende instalar a sede da reitoria em espaço físico distinto de qualquer dos campi que integram o referido Instituto Federal. A pretensão, na forma do disposto na Lei nº 11.892/2008, é","opcoes":["possível, no entanto deve haver aprovação do Ministério da Educação, sendo dispensável a previsão estatutária.","impossível, considerando que não é permitido que a reitoria, como órgão executivo, esteja sediada em espaço físico distinto de quaisquer campi.","impossível, já que a reitoria é considerada um órgão de administração central, devendo estar sediada no campus principal","impossível, considerando que não há previsão legal autorizando a sede da reitoria em espaço físico distinto de quaisquer campi.","possível, desde que haja previsão no estatuto e aprovação do Ministério da Educação."],"correta":4,"explicacao":"Gabarito: <strong>possível, desde que haja previsão no estatuto e aprovação do Ministério da Educação.</strong>.","banca":"INSTITUTO AOCP","ano":2026,"temas_relacionados":["lei_11892_2008"]},{"id":4120704,"enunciado":"Julgue o próximo item, relativo ao Microsoft Office, à Política Nacional de Educação Digital (PNED) e a redes de computadores.\n\n\n\n\nNa PNED, o eixo capacitação e especialização digital visa à capacitação da população brasileira em idade ativa para o desenvolvimento de competências digitais para a plena inserção no mundo do trabalho, sendo uma de suas estratégias prioritárias a identificação das competências digitais necessárias para a empregabilidade.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2026,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":4120780,"enunciado":"Com base na Instrução Normativa n.º 5/2017 da Secretaria de Gestão do Ministério do Planejamento, Desenvolvimento e Gestão e na Lei n.º 14.133/2021, julgue o item seguinte, referente a aspectos relacionados à situação hipotética apresentada.\n\n\n\n\nO termo de referência da contratação deve incluir a declaração do objeto, os critérios de seleção do fornecedor e os critérios de medição e pagamento.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2026,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":4120783,"enunciado":"Com base na Instrução Normativa n.º 5/2017 da Secretaria de Gestão do Ministério do Planejamento, Desenvolvimento e Gestão e na Lei n.º 14.133/2021, julgue o item seguinte, referente a aspectos relacionados à situação hipotética apresentada.\n\n\n\n\nNo contrato em questão, haja vista o objeto ser a prestação de serviços contínuos com dedicação exclusiva de mão de obra, é obrigatória a exigência de garantia contratual.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2026,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":4120791,"enunciado":"A respeito da retenção e do recolhimento de tributos incidentes sobre bens e serviços, julgue o item a seguir.\n\n\n\n\nA administração pública, ao realizar pagamentos por serviços contratados, está dispensada de efetuar retenções tributárias quando o contratado comprovar regularidade fiscal perante os órgãos competentes.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2026,"tipo":"certo_errado","temas_relacionados":["lei_11892_2008"]},{"id":4161050,"enunciado":"Selecione a alternativa correta conforme a Lei nº 11.892/2008, que criou os Institutos Federais:","opcoes":["OsInstitutos Federaistêm como objetivo ministrar em nível de educação superior: cursos superiores de tecnologia visando à formação de tecnólogos para os diferentes setores da economia.","Os Institutos Federais têm como objetivo ministrar em nível de educação superior: cursos de bacharelado, direito e engenharia, visando à formação de profissionais para os diferentes setores da economia e áreas do conhecimento.","Os Institutos Federais têm como objetivo ministrar em nível de educação superior: cursos de licenciatura, bem como programas especiais de formação pedagógica, com vistas na formação de professores para a educação básica, sobretudo nas áreas de ciências e matemática, e para a educação profissional.","Os Institutos Federais têm como objetivo ministrar em nível de educação superior: cursos de pós-graduação stricto sensu de mestrado, que contribuam para promover o estabelecimento de bases sólidas em educação, ciência e tecnologia, com vistas no processo de geração e inovação tecnológica."],"correta":2,"explicacao":"Gabarito: <strong>Os Institutos Federais têm como objetivo ministrar em nível de educação superior: cursos de licenciatura, bem como programas especiais de formação pedagógica, com vistas na formação de professores para a educação básica, sobretudo nas áreas de ciências e matemática, e para a educação profissional.</strong>.","banca":"IF-SP","ano":2022,"temas_relacionados":["lei_11892_2008"]},{"id":4198895,"enunciado":"A Resolução Normativa CFA nº 670, de 26 de junho de 2025, altera o Regula mento de Registro do Sistema CFA/CRAs, aprovado pela Resolução Normativa CFA nº 649, de 28 de maio de 2024. Segundo ela, em seu Artigo 1º, o Artigo 11 do regulamento aprovado pela Resolução Normativa passa a vigorar com uma nova redação que lista cursos de educação técnica de nível médio considerados conexos à Administração. Dentre esses, é INCORRETO considerar o curso denominado","opcoes":["Técnico em Condomínio.","Técnico em Marketing.","Técnico em Redes Sociais e Produção de Conteúdo Digital.","Técnico em Transações Imobiliárias."],"correta":2,"explicacao":"Gabarito: <strong>Técnico em Redes Sociais e Produção de Conteúdo Digital.</strong>.","banca":"FUMARC","ano":2026,"temas_relacionados":["lei_11892_2008"]},{"id":4200052,"enunciado":"A Lei Federal n. 11.892/2008 institui a Rede Federal de Educação Profissional, Científica e Tecnológica e cria os Institutos Federais de Educação, Ciência e Tecnologia (IFs). De acordo com essa lei, um dos objetivos dos desses institutos é","opcoes":["realizar pesquisas aplicadas voltadas para a educação profissional.","estimular soluções tecnológicas em benefício do instituto.","desenvolver atividades de extensão em articulação com o mundo do trabalho.","incentivar no meio industrial o uso de tecnologias consideradas inovadoras."],"correta":2,"explicacao":"Gabarito: <strong>desenvolver atividades de extensão em articulação com o mundo do trabalho.</strong>.","banca":"IV - UFG","ano":2022,"temas_relacionados":["lei_11892_2008"]},{"id":4218369,"enunciado":"De acordo com a Lei nº 11.892/2008, assinale a alternativa que corresponde a um dos objetivos dos Institutos Federais de Educação, Ciência e Tecnologia.","opcoes":["Promover educação profissional integrada, pesquisa aplicada, extensão e qualificação de trabalhadores.","Priorizar formação acadêmico-teórica desvinculada de demandas sociais e produtivas.","Ofertar ensino superior voltado à pesquisa científica básica e experimental.","Desenvolver atividades educativas articuladas com as ciências sociais e humanas.","Atuar predominantemente na educação básica por meio de ações curriculares de extensão."],"correta":0,"explicacao":"Gabarito: <strong>Promover educação profissional integrada, pesquisa aplicada, extensão e qualificação de trabalhadores.</strong>.","banca":"INSTITUTO AOCP","ano":2026,"temas_relacionados":["lei_11892_2008"]},{"id":4218386,"enunciado":"Os Institutos Federais promovem educação com base na produção de conhecimento por meio da interação com a realidade local. Nesse sentido, sua estrutura institucional é","opcoes":["multicampi.","intercampi.","intracampi.","transcampi.","unicampi."],"correta":0,"explicacao":"Gabarito: <strong>multicampi.</strong>.","banca":"INSTITUTO AOCP","ano":2026,"temas_relacionados":["lei_11892_2008"]},{"id":4218617,"enunciado":"O Conselho Superior de um Instituto Federal delibera sobre a ampliação da oferta de cursos. A proposta inclui a criação de licenciaturas, cursos técnicos integrados ao ensino médio e programas de extensão articulados à pesquisa aplicada. Um conselheiro questiona se essa ampliação está em conformidade com a natureza institucional prevista em lei. Quanto à conformidade da ampliação de cursos com a natureza institucional dos institutos federais, é correto afirmar que os institutos federais","opcoes":["possuem atuação restrita à formação técnica de nível médio, sem previsão de cursos de licenciatura ou integração com a educação superior.","destinam-se prioritariamente à formação profissional, podendo eventualmente ofertar cursos de educação básica de forma desvinculada da pesquisa e da extensão.","exercem função suplementar às universidades federais, atuando sem autonomia acadêmica própria e com foco exclusivo na formação profissional de nível médio.","ofertam educação superior apenas na modalidade tecnológica, sem possibilidade de criação de licenciaturas ou cursos de extensão.","caracterizam-se pela integração da educação básica, da formação profissional e da educação superior, articuladas com pesquisa e extensão, incluindo licenciaturas e cursos tecnológicos."],"correta":4,"explicacao":"Gabarito: <strong>caracterizam-se pela integração da educação básica, da formação profissional e da educação superior, articuladas com pesquisa e extensão, incluindo licenciaturas e cursos tecnológicos.</strong>.","banca":"INSTITUTO AOCP","ano":2026,"temas_relacionados":["lei_11892_2008"]},{"id":4218624,"enunciado":"A integração entre formação geral e formação técnica passou a orientar a organização curricular na Educação Profissional e Tecnológica. À luz da Lei nº 11.892/2008 e das alterações promovidas na LDB (Lei nº 9.394/1996), assinale a alternativa correta.","opcoes":["Na oferta integrada, a formação geral e a técnica podem ser concluídas separadamente, com certificações distintas ao longo do percurso.","A integração entre ensino médio e educação profissional ocorre por justaposição de componentes curriculares, sem reorganização do projeto pedagógico.","A organização curricular da EPT preserva a separação entre conteúdos científicos e formação profissional como princípio estruturante.","Na forma concomitante, há matrícula única institucional e certificação integrada ao final do curso.","A verticalização nos Institutos Federais envolve articulação entre níveis de ensino e integração entre formação científica e profissional."],"correta":4,"explicacao":"Gabarito: <strong>A verticalização nos Institutos Federais envolve articulação entre níveis de ensino e integração entre formação científica e profissional.</strong>.","banca":"INSTITUTO AOCP","ano":2026,"temas_relacionados":["lei_11892_2008"]},{"id":4219340,"enunciado":"Ivo é servidor efetivo de nível superior da carreira dos técnico-administrativos em uma instituição de ensino submetida à Lei nº 11.892/2008 e pretende se candidatar ao cargo de Diretor-Geral do campus onde atua. À luz da Lei nº 11.892/2008, é correto afirmar que","opcoes":["Ivo não poderá se candidatar, isso porque a função de Diretor-Geral é exclusiva para ocupantes do cargo de docente.","Ivo pode se candidatar se possuir no mínimo cinco anos de efetivo exercício em instituição federal de educação profissional e tecnológica e cumprir os demais requisitos legais.","Ivo não poderá se candidatar, tendo em vista que, além de restrita aos docentes, a função de Diretor-Geral é suprida mediante indicação do Reitor da instituição de ensino.","Ivo poderá se candidatar, no entanto, a comprovação de realização de curso de formação para o exercício de cargo ou função de gestão em instituições da administração pública é obrigatória.","Ivo deverá demonstrar que possui os requisitos exigidos para candidatura ao cargo de Reitor e o exercício por no mínimo dois anos em cargo ou gestão na instituição."],"correta":1,"explicacao":"Gabarito: <strong>Ivo pode se candidatar se possuir no mínimo cinco anos de efetivo exercício em instituição federal de educação profissional e tecnológica e cumprir os demais requisitos legais.</strong>.","banca":"INSTITUTO AOCP","ano":2026,"temas_relacionados":["lei_11892_2008"]},{"id":4223973,"enunciado":"O Instituto Federal de Educação, Ciência e Tecnologia de Goiás (IFG), criado pela Lei n. 11.892/2008, que transformou os Centros Federais de Educação Tecnológica (CEFET) em Institutos Federais de Educação, Ciência e Tecnologia (IF), é uma autarquia federal detentora de autonomia administrativa, patrimonial, financeira, didático-pedagógica e disciplinar. Essas características indicam que o IFG é uma instituição","opcoes":["de educação superior, básica e profissional, pluricurricular e multicampi.","de oferta especializada da educação profissional concomitante e subsequente.","de atendimento às crianças de 4 e 5 anos, de acordo com legislação específica","de atendimento específico dos três níveis: básico, técnico e tecnológico."],"correta":0,"explicacao":"Gabarito: <strong>de educação superior, básica e profissional, pluricurricular e multicampi.</strong>.","banca":"IV - UFG","ano":2022,"temas_relacionados":["lei_11892_2008"]}];
